import React from 'react';
import { ObserveState } from '../../utils/statemanager/ObserveState';
import { ModalManager } from '../../utils/ModalManager';

/**
 * Generic modal layer that renders all active modals
 * Supports multiple modals with priority ordering
 */
export function ModalLayer() {
  return (
    <ObserveState
      listenTo={ModalManager.Instance}
      properties={['activeModals']}
      control={() => {
        const manager = ModalManager.Instance;
        const modals = manager.activeModals;
        
        if (modals.length === 0) {
          return null;
        }
        
        return (
          <>
            {modals.map((modal, index) => (
              <div
                key={modal.id}
                style={{
                  position: 'fixed',
                  top: 0,
                  left: 0,
                  right: 0,
                  bottom: 0,
                  zIndex: 2000 + index, // Stack modals by priority order
                  pointerEvents: 'auto'
                }}
              >
                {modal.render()}
              </div>
            ))}
          </>
        );
      }}
    />
  );
}
