import { filterFunctionNames, loadFunctionsXml, type MachineType } from '../../utils/FunctionsXmlParser';

/**
 * Legacy Centroid output names enum for backward compatibility
 * @deprecated Use getCentroidOutputNames() function instead for dynamic loading from functions.xml
 */
export enum CentroidOutputName {
  // Spindle Control Outputs
  SpindleOnOutput = 'SpindleOnOutput',
  SpindleDirectionOutput = 'SpindleDirectionOutput',
  SpindleSpeedOutput = 'SpindleSpeedOutput',

  // Coolant Control Outputs
  FloodCoolantOutput = 'FloodCoolantOutput',
  MistCoolantOutput = 'MistCoolantOutput',

  // Tool Change Outputs
  ToolChangeOutput = 'ToolChangeOutput',
  DrawBarOutput = 'DrawBarOutput',
  ToolUnclampOutput = 'ToolUnclampOutput',
  ToolClampOutput = 'ToolClampOutput',

  // Machine Control Outputs
  MachineEnableOutput = 'MachineEnableOutput',
  ServoEnableOutput = 'ServoEnableOutput',

  // Lighting and Visual Outputs
  WorkLightOutput = 'WorkLightOutput',
  StatusLightRedOutput = 'StatusLightRedOutput',
  StatusLightYellowOutput = 'StatusLightYellowOutput',
  StatusLightGreenOutput = 'StatusLightGreenOutput',

  // Vacuum and Dust Collection
  VacuumOutput = 'VacuumOutput',
  DustCollectorOutput = 'DustCollectorOutput',

  // Door and Safety Outputs
  DoorLockOutput = 'DoorLockOutput',
  SafetyRelayOutput = 'SafetyRelayOutput',

  // General Purpose Outputs
  GeneralOutput1 = 'GeneralOutput1',
  GeneralOutput2 = 'GeneralOutput2',
  GeneralOutput3 = 'GeneralOutput3',
  GeneralOutput4 = 'GeneralOutput4',
  GeneralOutput5 = 'GeneralOutput5',
  GeneralOutput6 = 'GeneralOutput6',
  GeneralOutput7 = 'GeneralOutput7',
  GeneralOutput8 = 'GeneralOutput8',

  // Custom outputs can be added here as needed
  Custom1 = 'Custom1',
  Custom2 = 'Custom2',
  Custom3 = 'Custom3',
  Custom4 = 'Custom4',
  Custom5 = 'Custom5'
}

// Cache for loaded function names to avoid repeated XML parsing
let _cachedOutputNames: { [key in MachineType]?: string[] } = {};

/**
 * Get Centroid output names dynamically from functions.xml based on machine type
 * @param machineType - Machine type to filter by ('All', 'Router', 'Mill', 'Lathe')
 * @param includeHidden - Whether to include hidden functions (default: false)
 * @returns Promise resolving to array of output names
 */
export async function getCentroidOutputNames(
  machineType: MachineType = 'All',
  includeHidden: boolean = false
): Promise<string[]> {
  // Check cache first
  if (_cachedOutputNames[machineType] && !includeHidden) {
    return _cachedOutputNames[machineType]!;
  }

  try {
    const functions = await loadFunctionsXml();
    const outputNames = filterFunctionNames(functions, machineType, 'Output', includeHidden);

    // Cache the results (only for non-hidden requests)
    if (!includeHidden) {
      _cachedOutputNames[machineType] = outputNames;
    }

    return outputNames;
  } catch (error) {
    // Fall back to static enum values on error
    return Object.values(CentroidOutputName);
  }
}

/**
 * Clear the output names cache - useful when functions.xml is updated
 */
export function clearCentroidOutputNamesCache(): void {
  _cachedOutputNames = {};
}
