import {
  Input as InputIcon,
  Output as OutputIcon
} from '@mui/icons-material';
import {
  Alert,
  Box,
  CircularProgress,
  FormControlLabel,
  List,
  Paper,
  Switch,
  Typography
} from '@mui/material';
import { Component } from 'react';
import { ConfigurationData } from '../../data/ConfigurationData';
import { ConfigurationState } from '../../data/ConfigurationState';
import { MachineData } from '../../data/MachineData';
import { MachineStateData } from '../../data/MachineStateData';
import { UserMessageQueue } from '../../data/UserMessageQueue';
import { Machine } from '../../machine/Machine';
import { LogCategory, Logger } from '../../utils/Logger';
import { ObserveState } from '../../utils/statemanager/ObserveState';
import { InputItem } from './InputItem';
import { OutputItem } from './OutputItem';

interface InputOutputDrawerProps {
  onViewChange?: (view: string) => void;
}

interface InputOutputDrawerState {
  loading: boolean;
  error: string | null;
  // Note: Override tracking moved to ConfigurationState for non-persistent storage
}

export class InputOutputDrawer extends Component<InputOutputDrawerProps, InputOutputDrawerState> {

  constructor(props: InputOutputDrawerProps) {
    super(props);
    this.state = {
      loading: false,
      error: null
      // Note: Override tracking moved to ConfigurationState
    };
  }

  private handleOverrideModeToggle = () => {
    const newState = !MachineStateData.Instance.isOverridingInputs;
    MachineStateData.Instance.isOverridingInputs = newState;

    // If turning off override mode, reset all overrides
    if (!newState) {
      this.handleResetAllOverrides();
    }

    //Logger.Instance.log(LogCategory.UserInterface, `Input override mode ${newState ? 'enabled' : 'disabled'}`);
  };

  private handleOutputOverrideModeToggle = () => {
    const newState = !MachineStateData.Instance.isOverridingOutputs;
    MachineStateData.Instance.isOverridingOutputs = newState;

    // If turning off override mode, reset all overrides
    if (!newState) {
      this.handleResetAllOutputOverrides();
    }

    //Logger.Instance.log(LogCategory.UserInterface, `Output override mode ${newState ? 'enabled' : 'disabled'}`);
  };

  private handleInputOverride = async (inputNumber: number, newState: boolean) => {
    try {
      // Call the machine to override the input
      const machine = Machine.getInstance();
      if (!machine) {
        throw new Error('Machine instance not available');
      }

      await machine.io.OverrideInput(inputNumber, newState);

      // Track the override in ConfigurationState (non-persistent)
      ConfigurationState.Instance.addInputOverride(inputNumber);

      // Find the input name for the notification
      const machineData = MachineData.Instance;
      const input = machineData.machineInputs?.find(inp => inp.number === inputNumber);
      const inputName = input?.name || `Input ${inputNumber}`;

      // Send user notification (this will override the automatic machine message)
      UserMessageQueue.Instance.addMessage(`🔧 ${inputName} (${inputNumber}) overridden to ${newState ? 'ON' : 'OFF'}`);

      //Logger.Instance.log(LogCategory.UserInterface, `${inputName} (${inputNumber}) overridden to ${newState ? 'ON' : 'OFF'}`);
    } catch (error) {
      Logger.Instance.logError(LogCategory.UserInterface, 'Failed to override input:', error);
    }
  };

  private handleRemoveInputOverride = async (inputNumber: number) => {
    try {
      // Reset the input override on the machine
      const machine = Machine.getInstance();
      if (!machine) {
        throw new Error('Machine instance not available');
      }

      await machine.io.ResetInputOverrides(); // This resets all, but we could implement a single input reset

      // Remove from override tracking in ConfigurationState
      ConfigurationState.Instance.removeInputOverride(inputNumber);

      // Find the input name for the notification
      const machineData = MachineData.Instance;
      const input = machineData.machineInputs?.find(inp => inp.number === inputNumber);
      const inputName = input?.name || `Input ${inputNumber}`;

      // Send user notification (this will override the automatic "All input overrides reset" message)
      UserMessageQueue.Instance.addMessage(`🔄 ${inputName} (${inputNumber}) reset to normal operation`);

      //Logger.Instance.log(LogCategory.UserInterface, `${inputName} (${inputNumber}) reset to normal operation`);
    } catch (error) {
      Logger.Instance.logError(LogCategory.UserInterface, 'Failed to reset input override:', error);
    }
  };

  private handleResetAllOverrides = async () => {
    try {
      // Reset all input overrides on the machine
      const machine = Machine.getInstance();
      if (!machine) {
        throw new Error('Machine instance not available');
      }

      await machine.io.ResetInputOverrides();

      // Clear all override tracking in ConfigurationState
      ConfigurationState.Instance.clearAllInputOverrides();

      //Logger.Instance.log(LogCategory.UserInterface, 'All input overrides reset to normal operation');
    } catch (error) {
      Logger.Instance.logError(LogCategory.UserInterface, 'Failed to reset all input overrides:', error);
    }
  };

  private handleOutputOverride = async (outputNumber: number, newState: boolean) => {
    try {
      // Call the machine to override the output
      const machine = Machine.getInstance();
      if (!machine) {
        throw new Error('Machine instance not available');
      }

      await machine.io.OverrideOutput(outputNumber, newState);

      // Track the override in ConfigurationState (non-persistent)
      ConfigurationState.Instance.addOutputOverride(outputNumber);

      // Find the output name for the notification
      const machineData = MachineData.Instance;
      const output = machineData.machineOutputs?.find(out => out.number === outputNumber);
      const outputName = output?.name || `Output ${outputNumber}`;

      // Send user notification (this will override the automatic machine message)
      UserMessageQueue.Instance.addMessage(`🔧 ${outputName} (${outputNumber}) overridden to ${newState ? 'ON' : 'OFF'}`);

      //Logger.Instance.log(LogCategory.UserInterface, `${outputName} (${outputNumber}) overridden to ${newState ? 'ON' : 'OFF'}`);
    } catch (error) {
      Logger.Instance.logError(LogCategory.UserInterface, 'Failed to override output:', error);
    }
  };

  private handleRemoveOutputOverride = async (outputNumber: number) => {
    try {
      // Reset the output override on the machine
      const machine = Machine.getInstance();
      if (!machine) {
        throw new Error('Machine instance not available');
      }

      await machine.io.ResetOutputOverrides(); // This resets all, but we could implement a single output reset

      // Remove from override tracking in ConfigurationState
      ConfigurationState.Instance.removeOutputOverride(outputNumber);

      // Find the output name for the notification
      const machineData = MachineData.Instance;
      const output = machineData.machineOutputs?.find(out => out.number === outputNumber);
      const outputName = output?.name || `Output ${outputNumber}`;

      // Send user notification (this will override the automatic "All output overrides reset" message)
      UserMessageQueue.Instance.addMessage(`🔄 ${outputName} (${outputNumber}) reset to normal operation`);

      //Logger.Instance.log(LogCategory.UserInterface, `${outputName} (${outputNumber}) reset to normal operation`);
    } catch (error) {
      Logger.Instance.logError(LogCategory.UserInterface, 'Failed to reset output override:', error);
    }
  };

  private handleResetAllOutputOverrides = async () => {
    try {
      // Reset all output overrides on the machine
      const machine = Machine.getInstance();
      if (!machine) {
        throw new Error('Machine instance not available');
      }

      await machine.io.ResetOutputOverrides();

      // Clear all override tracking in ConfigurationState
      ConfigurationState.Instance.clearAllOutputOverrides();

      //Logger.Instance.log(LogCategory.UserInterface, 'All output overrides reset to normal operation');
    } catch (error) {
      Logger.Instance.logError(LogCategory.UserInterface, 'Failed to reset all output overrides:', error);
    }
  };

  render() {
    const { loading, error } = this.state;

    return (
      <ObserveState
        listenTo={[MachineStateData.Instance, MachineData.Instance, ConfigurationState.Instance]}
        properties={['isOverridingInputs', 'isOverridingOutputs', 'machineInputs', 'machineOutputs', 'overriddenInputs', 'overriddenOutputs']}
        control={() => {
          const config = ConfigurationData.Instance;
          const machineData = MachineData.Instance;
          const machineStateData = MachineStateData.Instance;
          const isInputOverrideMode = machineStateData.isOverridingInputs;
          const isOutputOverrideMode = machineStateData.isOverridingOutputs;

          const inputs = (machineData.machineInputs || []).filter(input => input.use && input.number != null);
          const outputs = (machineData.machineOutputs || []).filter(output => output.use && output.number != null);

          return (
            <Box
              sx={{
                height: '100%',
                display: 'flex',
                flexDirection: 'column',
                backgroundColor: config.lightBackgroundColor
              }}
            >
              {/* Error Display */}
              {error && (
                <Alert severity="error" sx={{ m: 1 }}>
                  {error}
                </Alert>
              )}

              {/* Loading Indicator */}
              {loading && (
                <Box sx={{ display: 'flex', justifyContent: 'center', p: 2 }}>
                  <CircularProgress size={24} />
                </Box>
              )}

              {/* Scrollable Content */}
              <Box sx={{ flex: 1, overflow: 'auto' }}>
                {/* Inputs Section */}
                {inputs.length > 0 && (
                  <Paper sx={{ m: 1, overflow: 'hidden' }} variant="outlined">
                    <Box sx={{
                      p: 1.5,
                      backgroundColor: config.lightBackgroundColor,
                      borderBottom: `1px solid ${config.secondaryBorderColor}`
                    }}>
                      <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                          <InputIcon sx={{ color: config.primaryColor, fontSize: 18 }} />
                          <Typography variant="subtitle2" sx={{ fontWeight: 'bold', fontSize: '0.85rem' }}>
                            Inputs ({inputs.length})
                          </Typography>
                        </Box>

                        {/* Override Controls - positioned at right edge */}
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, ml: 'auto' }}>
                          {/* Override Mode Toggle - always at the far right */}
                          <FormControlLabel
                            control={
                              <Switch
                                checked={isInputOverrideMode}
                                onChange={this.handleOverrideModeToggle}
                                size="small"
                                sx={{
                                  '& .MuiSwitch-thumb': {
                                    color: isInputOverrideMode ? '#ff9800' : undefined
                                  },
                                  '& .MuiSwitch-track': {
                                    backgroundColor: isInputOverrideMode ? 'rgba(255, 152, 0, 0.5)' : undefined
                                  }
                                }}
                              />
                            }
                            label={
                              <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                                <Typography variant="caption" sx={{ fontSize: '0.7rem' }}>
                                  Override
                                </Typography>
                              </Box>
                            }
                            sx={{ m: 0 }}
                          />
                        </Box>
                      </Box>

                      {/* Warning message when override mode is enabled */}
                      {isInputOverrideMode && (
                        <Alert
                          severity="warning"
                          variant="outlined"
                          sx={{
                            mt: 1,
                            py: 0.5,
                            fontSize: '0.75rem',
                            '& .MuiAlert-message': { fontSize: '0.75rem' }
                          }}
                        >
                          Override mode is for testing purposes only. Use with caution.
                        </Alert>
                      )}
                    </Box>

                    <List sx={{ py: 0 }}>
                      {inputs
                        .sort((a, b) => (a.number || 0) - (b.number || 0))
                        .map((input, index, sortedInputs) => {
                          const isOverridden = input.number != null ? ConfigurationState.Instance.overriddenInputs.has(input.number) : false;
                          const elements = [
                            <InputItem
                              key={`input-${input.number}`}
                              input={input}
                              isOverridden={isOverridden}
                              onToggleOverride={this.handleInputOverride}
                              onRemoveOverride={this.handleRemoveInputOverride}
                            />
                          ];

                          // Check if there's a gap before the next input
                          if (index < sortedInputs.length - 1) {
                            const currentNumber = input.number || 0;
                            const nextNumber = sortedInputs[index + 1].number || 0;
                            if (nextNumber - currentNumber > 1) {
                              // Add extra spacing for gap
                              elements.push(
                                <Box key={`input-gap-${currentNumber}-${nextNumber}`} sx={{ height: '20px' }} />
                              );
                            }
                          }

                          return elements;
                        })
                        .flat()
                      }
                    </List>
                  </Paper>
                )}

                {/* Outputs Section */}
                {outputs.length > 0 && (
                  <Paper sx={{ m: 1, overflow: 'hidden' }} variant="outlined">
                    <Box sx={{
                      p: 1.5,
                      backgroundColor: config.lightBackgroundColor,
                      borderBottom: `1px solid ${config.secondaryBorderColor}`
                    }}>
                      <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                          <OutputIcon sx={{ color: config.primaryColor, fontSize: 18 }} />
                          <Typography variant="subtitle2" sx={{ fontWeight: 'bold', fontSize: '0.85rem' }}>
                            Outputs ({outputs.length})
                          </Typography>
                        </Box>

                        {/* Override Controls - positioned at right edge */}
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, ml: 'auto' }}>
                          {/* Override Mode Toggle - always at the far right */}
                          <FormControlLabel
                            control={
                              <Switch
                                checked={isOutputOverrideMode}
                                onChange={this.handleOutputOverrideModeToggle}
                                size="small"
                                sx={{
                                  '& .MuiSwitch-thumb': {
                                    color: isOutputOverrideMode ? '#ff9800' : undefined
                                  },
                                  '& .MuiSwitch-track': {
                                    backgroundColor: isOutputOverrideMode ? 'rgba(255, 152, 0, 0.5)' : undefined
                                  }
                                }}
                              />
                            }
                            label={
                              <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                                <Typography variant="caption" sx={{ fontSize: '0.7rem' }}>
                                  Override
                                </Typography>
                              </Box>
                            }
                            sx={{ m: 0 }}
                          />
                        </Box>
                      </Box>

                      {/* Warning message when override mode is enabled */}
                      {isOutputOverrideMode && (
                        <Alert
                          severity="warning"
                          variant="outlined"
                          sx={{
                            mt: 1,
                            py: 0.5,
                            fontSize: '0.75rem',
                            '& .MuiAlert-message': { fontSize: '0.75rem' }
                          }}
                        >
                          Override mode is for testing purposes only. Use with caution.
                        </Alert>
                      )}
                    </Box>

                    <List sx={{ py: 0 }}>
                      {outputs
                        .sort((a, b) => a.number - b.number)
                        .map((output, index, sortedOutputs) => {
                          const isOverridden = ConfigurationState.Instance.overriddenOutputs.has(output.number);
                          const elements = [
                            <OutputItem
                              key={`output-${output.number}`}
                              output={output}
                              isOverridden={isOverridden}
                              onToggleOverride={this.handleOutputOverride}
                              onRemoveOverride={this.handleRemoveOutputOverride}
                            />
                          ];

                          // Check if there's a gap before the next output
                          if (index < sortedOutputs.length - 1) {
                            const currentNumber = output.number;
                            const nextNumber = sortedOutputs[index + 1].number;
                            if (nextNumber - currentNumber > 1) {
                              // Add extra spacing for gap
                              elements.push(
                                <Box key={`output-gap-${currentNumber}-${nextNumber}`} sx={{ height: '20px' }} />
                              );
                            }
                          }

                          return elements;
                        })
                        .flat()
                      }
                    </List>
                  </Paper>
                )}

                {/* No I/O configured message */}
                {inputs.length === 0 && outputs.length === 0 && (
                  <Box sx={{ p: 3, textAlign: 'center' }}>
                    <Typography variant="body2" sx={{ color: config.mutedTextColor }}>
                      No inputs or outputs configured
                    </Typography>
                  </Box>
                )}
              </Box>
            </Box>
          );
        }}
      />
    );
  }
}
