import React from 'react';
import {
  Box,
  TextField,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  FormControlLabel,
  Switch,
  Grid,
  Typography,
  Divider
} from '@mui/material';
import { MachineInput } from '../../data/Machine/MachineInput';
import { InputTriggeredState } from '../../data/Machine/InputTriggeredState';
import { InputActiveColor } from '../../data/Machine/InputActiveColor';
import { getInputActiveColorHex } from '../../data/Machine/InputActiveColor';
import { CentroidInputName } from '../../data/Machine/CentroidInputName';
import { NullableNumberInput } from './NullableNumberInput';

export interface MachineInputEditorProps {
  /** The input to edit - changes are made directly to this object */
  input: MachineInput;
  /** Title to display. If undefined, uses default title. If null, hides title */
  title?: string | null;
}

/**
 * Simplified MachineInput editor that works directly with the input object.
 * Changes are automatically propagated via StateManager.
 */
export function MachineInputEditor({
  input,
  title
}: MachineInputEditorProps) {
  
  // Get display title
  const displayTitle = title === null ? null : (title || `Edit Input: ${input.name}`);

  // Get enum values for dropdowns
  const triggerStateOptions = Object.values(InputTriggeredState)
    .filter(value => typeof value === 'string');
  
  const activeColorOptions = Object.values(InputActiveColor)
    .filter(value => typeof value === 'number');
  
  const centroidMappingOptions = Object.values(CentroidInputName)
    .filter(value => typeof value === 'string');

  return (
    <Box sx={{ p: 3, maxHeight: 'fit-content', display: 'flex', flexDirection: 'column' }}>
      {displayTitle && (
        <>
          <Typography variant="h6" gutterBottom>
            {displayTitle}
          </Typography>
          <Divider sx={{ mb: 3 }} />
        </>
      )}

      <Grid container spacing={3}>
        {/* Input Number - Smaller */}
        <Grid item xs={12} md={3}>
          <NullableNumberInput
            label="Input Number"
            value={input.number}
            onChange={(value) => {
              input.number = value;
            }}
            fullWidth
          />
        </Grid>

        {/* Input Name - Bigger */}
        <Grid item xs={12} md={9}>
          <TextField
            label="Name"
            value={input.name}
            onChange={(e) => {
              input.name = e.target.value;
            }}
            fullWidth
            required
          />
        </Grid>

        {/* Active Text - Full width row */}
        <Grid item xs={12}>
          <TextField
            label="Active Text"
            value={input.activeText}
            onChange={(e) => {
              input.activeText = e.target.value;
            }}
            fullWidth
            required
          />
        </Grid>

        {/* Inactive Text - Full width row */}
        <Grid item xs={12}>
          <TextField
            label="Inactive Text"
            value={input.inactiveText}
            onChange={(e) => {
              input.inactiveText = e.target.value;
            }}
            fullWidth
            required
          />
        </Grid>

        {/* Active State */}
        <Grid item xs={12} md={6}>
          <FormControl fullWidth>
            <InputLabel>Active When</InputLabel>
            <Select
              value={input.activeState}
              onChange={(e) => {
                input.activeState = e.target.value as InputTriggeredState;
              }}
              label="Active When"
            >
              {triggerStateOptions.map((state) => (
                <MenuItem key={state} value={state}>
                  {state}
                </MenuItem>
              ))}
            </Select>
          </FormControl>
        </Grid>

        {/* Active Color */}
        <Grid item xs={12} md={6}>
          <FormControl fullWidth>
            <InputLabel>Active Color</InputLabel>
            <Select
              value={input.activeColor}
              onChange={(e) => {
                input.activeColor = e.target.value as InputActiveColor;
              }}
              label="Active Color"
              renderValue={(value) => (
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                  <Box
                    sx={{
                      width: 16,
                      height: 16,
                      borderRadius: '50%',
                      backgroundColor: getInputActiveColorHex(value as InputActiveColor),
                      border: '1px solid #ccc'
                    }}
                  />
                  {InputActiveColor[value as InputActiveColor]}
                </Box>
              )}
            >
              {activeColorOptions.map((color) => (
                <MenuItem key={color} value={color}>
                  <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                    <Box
                      sx={{
                        width: 16,
                        height: 16,
                        borderRadius: '50%',
                        backgroundColor: getInputActiveColorHex(color as InputActiveColor),
                        border: '1px solid #ccc'
                      }}
                    />
                    {InputActiveColor[color]}
                  </Box>
                </MenuItem>
              ))}
            </Select>
          </FormControl>
        </Grid>

        {/* Centroid Mapping */}
        <Grid item xs={12}>
          <FormControl fullWidth>
            <InputLabel>Centroid Mapping</InputLabel>
            <Select
              value={input.centroidMapping || ''}
              onChange={(e) => {
                const value = e.target.value;
                input.centroidMapping = value ? (value as CentroidInputName) : undefined;
              }}
              label="Centroid Mapping"
            >
              <MenuItem value="">
                <em>None</em>
              </MenuItem>
              {centroidMappingOptions.map((mapping) => (
                <MenuItem key={mapping} value={mapping}>
                  {mapping}
                </MenuItem>
              ))}
            </Select>
          </FormControl>
        </Grid>

        {/* Switches */}
        <Grid item xs={12}>
          <Box sx={{ display: 'flex', gap: 3, flexWrap: 'wrap' }}>
            <FormControlLabel
              control={
                <Switch
                  checked={input.use}
                  onChange={(e) => {
                    input.use = e.target.checked;
                  }}
                />
              }
              label="In Use"
            />
            <FormControlLabel
              control={
                <Switch
                  checked={input.isManuallyTestable}
                  onChange={(e) => {
                    input.isManuallyTestable = e.target.checked;
                  }}
                />
              }
              label="Manually Testable"
            />
          </Box>
        </Grid>
      </Grid>
    </Box>
  );
}
