import { Home as UnhomeIcon } from '@mui/icons-material';
import { Typography } from '@mui/material';
import React from 'react';
import { Machine } from '../../../../machine/Machine';
import { LogCategory, Logger } from '../../../../utils/Logger';
import { DataUtilities } from '../../../../utils/storage/DataUtilities';
import { FlowStep } from "../../../FlowStep";
import { FlowStepData } from "../../../FlowStepData";

export class UnhomeMachineStep extends FlowStep {
    readonly __type = 'UnhomeMachineStep';
    readonly category = ['Machine', 'System'];
    readonly name = 'Unhome Machine';
    readonly description = 'Removes homed status from machine axes';
    
    // Icon is created dynamically, not stored
    get icon(): React.ReactNode {
        return React.createElement(UnhomeIcon, { sx: { color: 'warning.main' } });
    }

    static readonly DONE_PATH = 'done';

    async execute(data: FlowStepData, prototypeRun: boolean): Promise<string | null> {
        if (prototypeRun) {
            //Logger.Instance.log(LogCategory.System, 'Prototype: Unhome machine');
            return UnhomeMachineStep.DONE_PATH;
        }

        try {
            await Machine.getInstance().system.UnhomeMachine();
            //Logger.Instance.log(LogCategory.System, 'Machine unhomed');
            return UnhomeMachineStep.DONE_PATH;
        } catch (error) {
            Logger.Instance.logError(LogCategory.System, 'Unhome machine failed:', error);
            return UnhomeMachineStep.DONE_PATH;
        }
    }

    results(): string[] {
        return [UnhomeMachineStep.DONE_PATH];
    }

    renderResultsUI(data: FlowStepData, result: string): React.ReactNode {
        return (
            <Typography variant="caption">
                Unhome machine: {result}
            </Typography>
        );
    }

    public toJSON(): any {
        const data = DataUtilities.getStorageData(this, ['icon']) as any;
        data.__type = this.__type;
        return data;
    }

    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data);
    }
}





