import { UserMessageQueue } from '../data/UserMessageQueue';
import { ICNCSetup, TravelLimitsResult } from '../machine/ICNCSetup';
import {
  ATCConfiguration,
  ATCValidationResult,
  AvailableParametersResponse,
  AxisConfiguration,
  CheckpointInfo,
  CheckpointSaveRequest,
  CompleteMachineConfiguration,
  ConfigurationDataRequest,
  DataItem,
  GlobalSystemConfiguration,
  IOConfiguration,
  ParameterSetRequest,
  ParameterValue,
  ProbeConfiguration,
  PWMConfiguration,
  SecondSpindleConfiguration,
  SpindleConfiguration,
  StepFrequencyRequest,
  SystemHardwareInfo,
  ToolTouchOffConfiguration,
  TouchPlateConfiguration,
  ValidationResult,
} from '../machine/Machine';

export class SimulatorCNCSetup implements ICNCSetup {

  // Configuration methods
  async ConfigureATC(config: ATCConfiguration): Promise<boolean> {
    UserMessageQueue.Instance.addMessage('✓ ATC configuration updated (simulator)');
    return true;
  }

  async ConfigureAxis(config: AxisConfiguration): Promise<boolean> {
    UserMessageQueue.Instance.addMessage('✓ Axis configuration updated (simulator)');
    return true;
  }

  async ConfigureCompleteMachine(config: CompleteMachineConfiguration): Promise<boolean> {
    UserMessageQueue.Instance.addMessage('✓ Complete machine configuration updated (simulator)');
    return true;
  }

  async ConfigureGlobalSystem(config: GlobalSystemConfiguration): Promise<boolean> {
    UserMessageQueue.Instance.addMessage('✓ Global system settings updated (simulator)');
    return true;
  }

  async ConfigureInputsOutputs(config: IOConfiguration): Promise<boolean> {
    UserMessageQueue.Instance.addMessage('✓ I/O configuration updated (simulator)');
    return true;
  }

  async ConfigurePWM(config: PWMConfiguration): Promise<boolean> {
    UserMessageQueue.Instance.addMessage('✓ PWM configuration updated (simulator)');
    return true;
  }

  async ConfigureProbe(config: ProbeConfiguration): Promise<boolean> {
    UserMessageQueue.Instance.addMessage('✓ Probe configuration updated (simulator)');
    return true;
  }

  async ConfigureSecondSpindle(config: SecondSpindleConfiguration): Promise<boolean> {
    UserMessageQueue.Instance.addMessage('✓ Second spindle configuration updated (simulator)');
    return true;
  }

  async ConfigureSpindle(config: SpindleConfiguration): Promise<boolean> {
    UserMessageQueue.Instance.addMessage('✓ Spindle configuration updated (simulator)');
    return true;
  }

  async ConfigureToolTouchOff(config: ToolTouchOffConfiguration): Promise<boolean> {
    UserMessageQueue.Instance.addMessage('✓ Tool touch off configuration updated (simulator)');
    return true;
  }

  async ConfigureTouchPlate(config: TouchPlateConfiguration): Promise<boolean> {
    UserMessageQueue.Instance.addMessage('✓ Touch plate configuration updated (simulator)');
    return true;
  }

  // Validation methods
  async ValidateATCConfiguration(config: ATCConfiguration): Promise<ATCValidationResult> {
    return {
      valid: true,
      issues: [],
      type: 'Simulated'
    };
  }

  async ValidateIOConfiguration(config: IOConfiguration): Promise<ValidationResult> {
    return {
      valid: true,
      issues: [],
      inputCount: 0,
      outputCount: 0
    };
  }

  // Parameter methods
  async GetAvailableParameters(): Promise<AvailableParametersResponse> {
    return {
      parameters: [],
    };
  }

  async GetParameter(parameter: number): Promise<ParameterValue> {
    return {
      parameter: parameter,
      value: 0,
    };
  }

  async SetParameter(request: ParameterSetRequest): Promise<ParameterValue> {
    UserMessageQueue.Instance.addMessage(`✓ Parameter set (simulator)`);
    return {
      parameter: request.parameter || 0,
      value: request.value || 0,
    };
  }

  // Step frequency methods
  async GetStepFrequency(): Promise<number> {
    return 25000; // Default simulator value
  }

  async SetStepFrequency(request: StepFrequencyRequest): Promise<void> {
    UserMessageQueue.Instance.addMessage(`✓ Step frequency set (simulator)`);
  }

  // Hardware info
  async GetSystemHardwareInfo(): Promise<SystemHardwareInfo> {
    // Return empty object - check actual API type for required fields
    return {} as SystemHardwareInfo;
  }

  // Data management methods - localStorage implementation
  private readonly STORAGE_PREFIX = 'havenCNC_data_';
  private readonly CHECKPOINT_PREFIX = 'havenCNC_checkpoint_';
  private readonly CHECKPOINT_LIST_KEY = 'havenCNC_checkpoints';

  private getStorageKey(name: string): string {
    return this.STORAGE_PREFIX + name;
  }

  private getCheckpointKey(checkpointName: string, dataName: string): string {
    return `${this.CHECKPOINT_PREFIX}${checkpointName}_${dataName}`;
  }

  async ListData(): Promise<string[]> {
    try {
      const files: string[] = [];

      // Iterate through localStorage keys to find our data files
      for (let i = 0; i < localStorage.length; i++) {
        const key = localStorage.key(i);
        if (key && key.startsWith(this.STORAGE_PREFIX)) {
          // Extract filename from storage key
          const filename = key.substring(this.STORAGE_PREFIX.length);
          if (filename.endsWith('.json')) {
            files.push(filename);
          }
        }
      }

      return files;
    } catch (error) {
      console.error('Failed to list data files:', error);
      return [];
    }
  }

  async GetData(name: string): Promise<string> {
    try {
      const storageKey = this.getStorageKey(name);
      const data = localStorage.getItem(storageKey);
      return data || '';
    } catch (error) {
      console.error(`Failed to get data ${name}:`, error);
      return '';
    }
  }

  async SetData(request: ConfigurationDataRequest): Promise<void> {
    try {
      if (!request.name || !request.content) {
        throw new Error('Name and content are required');
      }

      const storageKey = this.getStorageKey(request.name);
      localStorage.setItem(storageKey, request.content);
      UserMessageQueue.Instance.addMessage(`✓ Saved ${request.name} (simulator)`);
    } catch (error) {
      console.error('Failed to set data:', error);
      throw error;
    }
  }

  async DeleteData(name: string): Promise<void> {
    try {
      const storageKey = this.getStorageKey(name);
      if (localStorage.getItem(storageKey) !== null) {
        localStorage.removeItem(storageKey);
        UserMessageQueue.Instance.addMessage(`✓ Deleted ${name} (simulator)`);
      }
    } catch (error) {
      console.error(`Failed to delete data ${name}:`, error);
      throw error;
    }
  }

  // Checkpoint methods
  async ListCheckpoints(): Promise<CheckpointInfo[]> {
    try {
      const checkpointsJson = localStorage.getItem(this.CHECKPOINT_LIST_KEY);
      if (!checkpointsJson) {
        return [];
      }
      return JSON.parse(checkpointsJson);
    } catch (error) {
      console.error('Failed to list checkpoints:', error);
      return [];
    }
  }

  async GetCheckpointContents(checkpointName: string): Promise<DataItem[]> {
    try {
      const checkpoints = await this.ListCheckpoints();
      const checkpoint = checkpoints.find(cp => cp.name === checkpointName);

      if (!checkpoint) {
        return [];
      }

      // Get list of files from localStorage that belong to this checkpoint
      const contents: DataItem[] = [];
      const dataFiles = await this.ListData();

      for (const dataName of dataFiles) {
        const key = this.getCheckpointKey(checkpointName, dataName);
        const data = localStorage.getItem(key);
        if (data) {
          contents.push({
            name: dataName,
            content: data
          });
        }
      }

      return contents;
    } catch (error) {
      console.error(`Failed to get checkpoint contents for ${checkpointName}:`, error);
      return [];
    }
  }

  async SaveCheckpoint(request: CheckpointSaveRequest): Promise<void> {
    try {
      if (!request.checkpointName) {
        throw new Error('Checkpoint name is required');
      }

      // Get list of all current data files
      const dataFiles = await this.ListData();

      // Save snapshot of each data file under checkpoint-specific key
      for (const dataName of dataFiles) {
        const data = await this.GetData(dataName);
        const checkpointKey = this.getCheckpointKey(request.checkpointName, dataName);
        localStorage.setItem(checkpointKey, data);
      }

      // Update checkpoint metadata
      const checkpoints = await this.ListCheckpoints();
      const existingIndex = checkpoints.findIndex(cp => cp.name === request.checkpointName);

      const checkpointInfo: CheckpointInfo = {
        name: request.checkpointName,
        fileCount: dataFiles.length,
        created: new Date().toISOString()
      };

      if (existingIndex >= 0) {
        checkpoints[existingIndex] = checkpointInfo;
      } else {
        checkpoints.push(checkpointInfo);
      }

      localStorage.setItem(this.CHECKPOINT_LIST_KEY, JSON.stringify(checkpoints));
      UserMessageQueue.Instance.addMessage(`✓ Checkpoint '${request.checkpointName}' saved (simulator)`);
    } catch (error) {
      console.error('Failed to save checkpoint:', error);
      throw error;
    }
  }

  async RestoreCheckpoint(checkpointName: string): Promise<number> {
    try {
      const checkpoints = await this.ListCheckpoints();
      const checkpoint = checkpoints.find(cp => cp.name === checkpointName);

      if (!checkpoint) {
        UserMessageQueue.Instance.addMessage(`⚠ Checkpoint '${checkpointName}' not found`);
        return 0;
      }

      // Get all checkpoint data files
      const dataFiles = await this.ListData();
      let restoredCount = 0;

      for (const dataName of dataFiles) {
        const key = this.getCheckpointKey(checkpointName, dataName);
        const data = localStorage.getItem(key);
        if (data) {
          await this.SetData({
            name: dataName,
            content: data
          });
          restoredCount++;
        }
      }

      // Trigger DataManager to reload all data and fire StateManager events
      const { DataManager } = await import('../data/DataManager');
      await DataManager.Instance.initializeOnStartup();

      UserMessageQueue.Instance.addMessage(`✓ Checkpoint '${checkpointName}' restored (${restoredCount} files) (simulator)`);
      return restoredCount;
    } catch (error) {
      console.error(`Failed to restore checkpoint ${checkpointName}:`, error);
      throw error;
    }
  }

  async DeleteCheckpoint(checkpointName: string): Promise<void> {
    try {
      const checkpoints = await this.ListCheckpoints();
      const checkpoint = checkpoints.find(cp => cp.name === checkpointName);

      if (!checkpoint) {
        UserMessageQueue.Instance.addMessage(`⚠ Checkpoint '${checkpointName}' not found`);
        return;
      }

      // Delete all checkpoint data files
      const dataFiles = await this.ListData();
      for (const dataName of dataFiles) {
        const key = this.getCheckpointKey(checkpointName, dataName);
        localStorage.removeItem(key);
      }

      // Update checkpoint list
      const updatedCheckpoints = checkpoints.filter(cp => cp.name !== checkpointName);
      localStorage.setItem(this.CHECKPOINT_LIST_KEY, JSON.stringify(updatedCheckpoints));

      UserMessageQueue.Instance.addMessage(`✓ Checkpoint '${checkpointName}' deleted (simulator)`);
    } catch (error) {
      console.error(`Failed to delete checkpoint ${checkpointName}:`, error);
      throw error;
    }
  }

  // Travel limits method - simulator always returns null (no API to provide limits)
  async GetTravelLimits(): Promise<TravelLimitsResult | null> {
    // Simulator mode doesn't have travel limits from API
    // Soft limits will fall back to MachineData
    return null;
  }
}
