import { StateManager } from '../../utils/statemanager/StateManager';
import { Fixture } from './FixtureLibrary';
import { SaveableDataBase } from './SaveableDataBase';
import { DataUtilities } from '../../utils/storage/DataUtilities';

/**
 * Historical fixture position data
 * Stores snapshots of fixture positions with timestamps
 */
export interface FixtureHistory {
  id: string;
  fixtureNumber: string;
  name: string;
  xOffset: number;
  yOffset: number;
  zOffset: number;
  saveDate: Date;
  // Store original fixture data for reference
  originalFixtureName: string;
  originalSystemControlled: boolean;
  originalShowAsSelectable: boolean;
}

/**
 * Library for managing fixture position history
 * Maintains up to 5 historical positions per fixture number
 * Follows HavenCNC singleton pattern with file persistence
 */
export class FixtureHistoryLibrary extends SaveableDataBase {
  private static _instance: FixtureHistoryLibrary;
  private _fixtureHistories: FixtureHistory[] = [];

  /**
   * Filename for saving/loading fixture history data
   */
  protected get filename(): string {
    return 'fixture-history-library.json';
  }

  private constructor() {
    super();
    
    // Note: setupAutoSave() will be called after instance creation to avoid constructor issues
  }

  /**
   * Get all fixture histories for a specific fixture number
   */
  public getHistoriesForFixture(fixtureNumber: string): FixtureHistory[] {
    return this._fixtureHistories
      .filter(h => h.fixtureNumber === fixtureNumber)
      .sort((a, b) => b.saveDate.getTime() - a.saveDate.getTime()); // Most recent first
  }

  /**
   * Save current fixture position to history
   * Maintains maximum of 5 entries per fixture number
   */
  public saveFixturePosition(fixture: Fixture, customName?: string): void {
    const now = new Date();
    const baseName = customName || `Saved ${now.toLocaleDateString()} ${now.toLocaleTimeString()}`;
    
    // Ensure name is unique for this fixture number
    let uniqueName = baseName;
    let counter = 1;
    while (this.isNameTaken(fixture.fixtureNumber, uniqueName)) {
      uniqueName = `${baseName} (${counter})`;
      counter++;
    }

    const historyEntry: FixtureHistory = {
      id: this.generateId(),
      fixtureNumber: fixture.fixtureNumber,
      name: uniqueName,
      xOffset: fixture.xOffset,
      yOffset: fixture.yOffset,
      zOffset: fixture.zOffset,
      saveDate: now,
      // Store original fixture properties
      originalFixtureName: fixture.name,
      originalSystemControlled: fixture.systemControlled,
      originalShowAsSelectable: fixture.showAsSelectable
    };

    // Add to collection
    this._fixtureHistories.push(historyEntry);

    // Maintain maximum of 5 entries per fixture number
    this.trimHistoryForFixture(fixture.fixtureNumber);

    // Trigger state change for auto-save
    StateManager.propertyChanged(this, 'fixtureHistories');
  }

  /**
   * Restore fixture position from history
   */
  public restoreFixturePosition(historyId: string): FixtureHistory | null {
    const history = this._fixtureHistories.find(h => h.id === historyId);
    return history || null;
  }

  /**
   * Delete a specific history entry
   */
  public deleteHistory(historyId: string): void {
    const index = this._fixtureHistories.findIndex(h => h.id === historyId);
    if (index !== -1) {
      this._fixtureHistories.splice(index, 1);
      StateManager.propertyChanged(this, 'fixtureHistories');
    }
  }

  /**
   * Clear all history for a specific fixture number
   */
  public clearHistoryForFixture(fixtureNumber: string): void {
    this._fixtureHistories = this._fixtureHistories.filter(h => h.fixtureNumber !== fixtureNumber);
    StateManager.propertyChanged(this, 'fixtureHistories');
  }

  /**
   * Get all histories (for debugging/admin purposes)
   */
  public get allHistories(): FixtureHistory[] {
    return [...this._fixtureHistories];
  }

  /**
   * Check if a name is already taken for a specific fixture number
   */
  private isNameTaken(fixtureNumber: string, name: string): boolean {
    return this._fixtureHistories.some(h => 
      h.fixtureNumber === fixtureNumber && h.name === name
    );
  }

  /**
   * Maintain maximum of 5 entries per fixture number
   * Removes oldest entries when limit is exceeded
   */
  private trimHistoryForFixture(fixtureNumber: string): void {
    const fixtureHistories = this.getHistoriesForFixture(fixtureNumber);
    
    if (fixtureHistories.length > 5) {
      // Sort by date (oldest first) and remove excess
      const sortedOldest = fixtureHistories.sort((a, b) => a.saveDate.getTime() - b.saveDate.getTime());
      const toRemove = sortedOldest.slice(0, fixtureHistories.length - 5);
      
      toRemove.forEach(history => {
        const index = this._fixtureHistories.findIndex(h => h.id === history.id);
        if (index !== -1) {
          this._fixtureHistories.splice(index, 1);
        }
      });
    }
  }

  /**
   * Generate unique ID for history entries
   */
  private generateId(): string {
    return `history_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  }

  /**
   * IStorable implementation - serialize to JSON handling FixtureHistory array explicitly
   */
  public toJSON(): object {
    const baseData = DataUtilities.getStorageData(this, ['_instance', '_fixtureHistories']); // Exclude array from auto-processing
    
    // Handle _fixtureHistories array explicitly with proper serialization
    // Since FixtureHistory is an interface (not a class), we handle as plain objects
    return {
      ...baseData,
      _fixtureHistories: this._fixtureHistories.map(history => ({
        ...history,
        saveDate: history.saveDate.toISOString() // Convert Date to string for JSON
      }))
    };
  }

  /**
   * IStorable implementation - deserialize from JSON handling FixtureHistory array explicitly
   */
  public fromJSON(data: any): void {
    if (!data) return;
    
    // Load basic properties
    DataUtilities.loadStorageData(this, data, ['_instance', '_fixtureHistories']); // Exclude array from auto-processing
    
    // Handle _fixtureHistories array explicitly
    if (data._fixtureHistories && Array.isArray(data._fixtureHistories)) {
      this._fixtureHistories = data._fixtureHistories.map((historyData: any) => ({
        ...historyData,
        saveDate: new Date(historyData.saveDate) // Convert string back to Date
      }));
    }
  }

  /**
   * Update fixture history from loaded data (called by DataManager)
   * @deprecated Use fromJSON instead for consistency with IStorable pattern
   */
  public updateFromLoadedData(loadedHistories: any[]): void {
    if (!Array.isArray(loadedHistories)) return;

    this._fixtureHistories = [];
    for (const historyData of loadedHistories) {
      try {
        // Convert date strings back to Date objects
        const history: FixtureHistory = {
          ...historyData,
          saveDate: new Date(historyData.saveDate)
        };
        this._fixtureHistories.push(history);
      } catch (error) {
        console.warn('Failed to load fixture history entry:', error);
      }
    }
    
    StateManager.propertyChanged(this, 'fixtureHistories');
  }

  /**
   * Get the singleton instance
   */
  public static get Instance(): FixtureHistoryLibrary {
    if (!FixtureHistoryLibrary._instance) {
      FixtureHistoryLibrary._instance = new FixtureHistoryLibrary();
      // Setup auto-save after instance is fully created
      FixtureHistoryLibrary._instance.setupAutoSave();
    }
    return FixtureHistoryLibrary._instance;
  }
}
