import { UserMessageQueue } from '../data/UserMessageQueue';
import { ICNCSystem } from '../machine/ICNCSystem';
import { SystemStatus } from '../machine/Machine';

export class SimulatorCNCSystem implements ICNCSystem {

  async exit(): Promise<void> {
    UserMessageQueue.Instance.addMessage('✓ System exit initiated');
  }

  async GetSystemStatus(): Promise<SystemStatus> {
    // Return simulated system status
    return {
      currentDateTime: new Date(),
      isCNCConnected: true, // Simulator is always "connected"
      status: 'Simulator mode - all systems operational'
    };
  }

  async shutdown(): Promise<void> {
    UserMessageQueue.Instance.addMessage('✓ System shutdown initiated');
  }

  async restartCentroid(): Promise<void> {
    UserMessageQueue.Instance.addMessage('✓ Centroid system restarted');
  }

  async EmergencyStop(): Promise<void> {
    UserMessageQueue.Instance.addMessage('🚨 EMERGENCY STOP ACTIVATED');
  }

  async IsHomed(): Promise<boolean> {
    // In simulator, always consider machine homed for demo purposes
    return true;
  }

  async UnhomeMachine(): Promise<void> {
    UserMessageQueue.Instance.addMessage('✓ Machine unhomed');
  }

  async HomeMachine(): Promise<void> {
    UserMessageQueue.Instance.addMessage('✓ Machine homing complete');
  }

  async GetCurrentErrorState(): Promise<string[] | null> {
    // Simulator has no errors by default
    return null;
  }

  async ResetErrorState(): Promise<void> {
    UserMessageQueue.Instance.addMessage('✓ Error state reset');
  }

  async ResetMachine(): Promise<void> {
    UserMessageQueue.Instance.addMessage('✓ Machine reset complete');
  }

  async HasCurrentErrors(): Promise<boolean> {
    return false;
  }

  async IsConnectedToServer(): Promise<boolean> {
    // Simulator is always connected
    return true;
  }
}
