import { Color } from 'three';

/**
 * Interface for colorizing G-code segments based on metadata
 */
export interface SegmentMetadata {
  radius: number;
  segmentStart: THREE.Vector3;
  segmentEnd: THREE.Vector3;
  speed: number;
  temp: number;
  gCodeLine: number;
}

/**
 * Base interface for segment colorizers
 */
export interface SegmentColorizer {
  getColor(metadata: SegmentMetadata): Color;
}

/**
 * Simple colorizer that uses different colors for different line types
 */
export class SimpleColorizer implements SegmentColorizer {
  public travelColor = new Color(0x808080); // Gray for travel moves
  public extrusionColor = new Color(0x00ff00); // Green for extrusion
  public rapidColor = new Color(0xff0000); // Red for rapid moves

  getColor(metadata: SegmentMetadata): Color {
    if (metadata.radius === 0) {
      return this.rapidColor; // Rapid move
    } else if (metadata.radius < 0.01) {
      return this.travelColor; // Travel move
    } else {
      return this.extrusionColor; // Extrusion move
    }
  }
}

/**
 * Speed-based colorizer that colors segments based on movement speed
 */
export class SpeedColorizer implements SegmentColorizer {
  private minSpeed: number;
  private maxSpeed: number;

  constructor(minSpeed: number = 0, maxSpeed: number = 3000) {
    this.minSpeed = minSpeed;
    this.maxSpeed = maxSpeed;
  }

  getColor(metadata: SegmentMetadata): Color {
    if (metadata.radius === 0) {
      return new Color(0xff0000); // Red for rapid moves
    }

    // Normalize speed to 0-1 range
    const normalizedSpeed = (metadata.speed - this.minSpeed) / (this.maxSpeed - this.minSpeed);
    const clampedSpeed = Math.max(0, Math.min(1, normalizedSpeed));

    // Color from blue (slow) to red (fast)
    const hue = (1 - clampedSpeed) * 0.66; // 0.66 is blue in HSL, 0 is red
    return new Color().setHSL(hue, 1, 0.5);
  }
}
