import React, { useState, useCallback } from 'react';
import {
  Typography,
  Box,
  Paper,
  Button,
  TextField,
  Alert,
  List,
  ListItemText,
  ListItemIcon,
  ListItemButton,
  Chip,
  Tabs,
  Tab,
  FormControlLabel,
  Switch
} from '@mui/material';
import {
  CloudUpload as UploadIcon,
  Description as FileIcon,
  AccessTime as TimeIcon,
  ArrowBack as BackIcon,
  Build as ToolIcon,
  Straighten as DimensionIcon,
  ViewInAr as View3DIcon,
  Code as CodeIcon
} from '@mui/icons-material';
import { JobStorage, JobType, GCodeFile } from '../../../data/JobStorage';
import { RecentJobsDialog } from './RecentJobsDialog';
import { AvailableFilesDialog } from './AvailableFilesDialog';
import { Job } from '../../../data/Job';
import { Material } from '../../../data/Common/Material';
import { CNCViewType } from '../../MachineViewer/CNCViewer';
import { FullSizeCNCViewer } from '../../MachineViewer/FullSizeCNCViewer';
import { MachineStateData } from '../../../data/MachineStateData';
import { MachineData } from '../../../data/MachineData';
import { SimulatorView } from '../../../data/Common/SimulatorView';
import { ViewStyle } from '../../../data/Common/ViewStyle';
import { UserMessageQueue } from '../../../data/UserMessageQueue';
import { StateManager } from '../../../utils/statemanager/StateManager';
import { ObserveState } from '../../../utils/statemanager/ObserveState';

export interface GCodeStageProps {
  onMovingToNext?: () => void;
  getNextStepName?: () => string;
}

export function GCodeStage({ onMovingToNext, getNextStepName }: GCodeStageProps = {}) {
  const [, setHoveredJobIndex] = useState<number | null>(null);
  const [, setHoveredFileIndex] = useState<number | null>(null);
  const [isJobLoaded, setIsJobLoaded] = useState<boolean>(false);
  const [loadedJobName, setLoadedJobName] = useState<string>('');
  const [rightTabValue, setRightTabValue] = useState<number>(0);
  
  // Dialog state
  const [showRecentJobsDialog, setShowRecentJobsDialog] = useState<boolean>(false);
  const [showAvailableFilesDialog, setShowAvailableFilesDialog] = useState<boolean>(false);
  
  // New state for file preview
  const [selectedFileContent, setSelectedFileContent] = useState<string>('');
  
  // State for job inheritance switches
  const [useLastJobMaterial, setUseLastJobMaterial] = useState<boolean>(true);
  const [useLastJobClamps, setUseLastJobClamps] = useState<boolean>(true);
  
  // Cache recent jobs in state to avoid repeated creation
  const [recentJobs] = useState(() => JobStorage.Instance.getRecentJobs(JobType.Milling));
  
  // Instance references
  const jobStorage = JobStorage.Instance;
  const machineState = MachineStateData.Instance;
  
  // Utility function to format file age
  const formatFileAge = (lastModified?: Date): string => {
    if (!lastModified) return 'Unknown';
    
    const now = new Date();
    const diffMs = now.getTime() - lastModified.getTime();
    const diffMinutes = Math.floor(diffMs / (1000 * 60));
    const diffHours = Math.floor(diffMs / (1000 * 60 * 60));
    const diffDays = Math.floor(diffMs / (1000 * 60 * 60 * 24));
    
    if (diffMinutes < 1) return 'Just now';
    if (diffMinutes < 60) return `${diffMinutes} min ago`;
    if (diffHours < 24) return `${diffHours} hour${diffHours > 1 ? 's' : ''} ago`;
    if (diffDays === 1) return 'Yesterday';
    if (diffDays < 7) return `${diffDays} days ago`;
    return lastModified.toLocaleDateString();
  };
  
  // Utility function to format file size
  const formatFileSize = (size?: number): string => {
    if (!size) return 'Unknown size';
    
    const units = ['B', 'KB', 'MB', 'GB'];
    let unitIndex = 0;
    let fileSize = size;
    
    while (fileSize >= 1024 && unitIndex < units.length - 1) {
      fileSize /= 1024;
      unitIndex++;
    }
    
    return `${fileSize.toFixed(unitIndex === 0 ? 0 : 1)} ${units[unitIndex]}`;
  };
  
  // Create a focused simulator view for G-code preview
  const createPreviewSimulatorView = () => {
    const view = new SimulatorView();
    
    // Show essential elements for material stage: spoilboard, toolpaths, material, tool
    view.spoilBoard = ViewStyle.Show;          // Show spoilboard
    view.toolpaths = true;                     // Show toolpaths
    view.material = ViewStyle.Show;            // Show material (solid)
    view.tool = ViewStyle.Show;                // Show tool
    view.workHome = true;                      // Show work home for reference
    view.clamps = ViewStyle.SemiTransparent;   // Show clamps as semi-transparent
    
    // Hide everything else
    view.softLimits = false;
    view.machineZero = false;
    view.machineHome = false;
    view.gantry = ViewStyle.Hide;
    view.base = ViewStyle.Hide;
    view.bed = ViewStyle.Hide;
    view.railing = ViewStyle.Hide;
    view.spindle = ViewStyle.Hide;
    view.workPiece = ViewStyle.Hide;
    view.rotary = ViewStyle.Hide;
    view.verticalTable = ViewStyle.Hide;
    view.laser = ViewStyle.Hide;
    view.laserPointer = ViewStyle.Hide;
    view.drillHead = ViewStyle.Hide;
    view.atc = ViewStyle.Hide;
    
    return view;
  };
  
  // Create a temporary job for preview
  const createPreviewJob = useCallback((gcode: string, filename: string) => {
    // Logger.Instance.log(LogCategory.UserInterface, `Creating preview job for: ${filename}`, {
    //   useLastJobMaterial,
    //   useLastJobClamps,
    //   hasCurrentJob: !!machineState.currentJob,
    //   currentJobHasMaterial: !!(machineState.currentJob?.material),
    //   hasLastJob: !!machineState.lastJob
    // });
    
    let job: Job;
    
    // Determine which job to use as base: current job if it has material, otherwise last job
    const baseJob = (machineState.currentJob?.material) ? machineState.currentJob : machineState.lastJob;
    
    // Start with base job if available, otherwise create new job
    if (baseJob) { 
      job = baseJob.clone();
    } else {
      job = new Job();
    }
    
    // Handle material based on toggle switch
    if (useLastJobMaterial && baseJob?.material) {
      // Keep the existing material from base job
      job.material = baseJob.material.clone();
    } else {
      // Create new material with zero size when toggle is off or no base material
      job.material = new Material();
      job.material.xLength = 0;
      job.material.yLength = 0;
      job.material.height = 0;
    }
    
    // Handle clamps based on toggle switch
    if (useLastJobClamps && baseJob?.clamps) {
      // Keep the existing clamps from base job
      job.clamps = baseJob.clamps.map(clamp => clamp.clone());
    } else {
      // Empty the clamps array when toggle is off or no base clamps
      job.clamps = [];
    }
    
    // Always set the new G-code and name
    job.gcode = gcode;
    job.name = filename;
    
    return job;
  }, [machineState.currentJob, machineState.lastJob, useLastJobMaterial, useLastJobClamps]);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      loadFileContent(file, file.name, 'Uploaded File');
    }
  };

  const loadFileContent = (file: File, fileName: string, jobName: string) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const content = e.target?.result as string;
      previewGCode(content, fileName, jobName, file.lastModified, file.size);
    };
    reader.readAsText(file);
  };

  const previewJobFromStorage = (job: any) => {
    // Logger.Instance.log(LogCategory.UserInterface, `Previewing job from storage: ${job.name}`, {
    //   jobName: job.name,
    //   hasGCode: !!job.gcode,
    //   gCodeLength: job.gcode?.length || 0,
    //   materialInfo: `${job.material.xLength}" × ${job.material.yLength}" × ${job.material.height}"`
    // });
    
    const gCodeFile: GCodeFile = {
      name: `${job.name}.gcode`,
      content: job.gcode,
      description: `Job: ${job.name} - ${job.material.name} (${job.material.xLength}" × ${job.material.yLength}" × ${job.material.height}")`,
      materialType: job.material.type,
      estimatedTime: 'Variable'
    };
    previewGCode(job.gcode, gCodeFile.name, job.name, undefined, undefined);
  };

  const previewTemplateFile = (gCodeFile: GCodeFile) => {
    previewGCode(gCodeFile.content, gCodeFile.name, gCodeFile.name, gCodeFile.lastModified?.getTime(), gCodeFile.size);
  };

  const previewGCode = (content: string, fileName: string, jobName: string, lastModified?: number, size?: number) => {
    // Logger.Instance.log(LogCategory.UserInterface, `Previewing G-Code: ${jobName}`, {
    //   fileName,
    //   jobName,
    //   contentLength: content?.length || 0,
    //   hasContent: !!content
    // });
    
    // Set preview state
    setSelectedFileContent(content);
    setLoadedJobName(jobName);
    
    // Create and set proposed job for preview
    const previewJob = createPreviewJob(content, fileName);
    previewJob.name = jobName;
    machineState.proposedJob = previewJob;
    
    // Notify the state manager that the proposed job has changed
    StateManager.propertyChanged(machineState, 'proposedJob');
    
    UserMessageQueue.Instance.addMessage(`✓ G-Code file loaded: ${jobName}`);
  };

  // Handle material toggle change
  const handleMaterialToggleChange = (checked: boolean) => {
    setUseLastJobMaterial(checked);
    
    if (machineState.proposedJob) {
      if (checked) {
        // Restore material from base job
        const baseJob = (machineState.currentJob?.material) ? machineState.currentJob : machineState.lastJob;
        if (baseJob?.material) {
          machineState.proposedJob.material = baseJob.material.clone();
        }
      } else {
        // Clear material (zero size)
        const newMaterial = new Material();
        newMaterial.xLength = 0;
        newMaterial.yLength = 0;
        newMaterial.height = 0;
        machineState.proposedJob.material = newMaterial;
      }
      
      // Notify state change
      StateManager.propertyChanged(machineState, 'proposedJob');
    }
  };

  // Handle clamps toggle change
  const handleClampsToggleChange = (checked: boolean) => {
    setUseLastJobClamps(checked);
    
    if (machineState.proposedJob) {
      if (checked) {
        // Restore clamps from base job
        const baseJob = (machineState.currentJob?.material) ? machineState.currentJob : machineState.lastJob;
        if (baseJob?.clamps) {
          machineState.proposedJob.clamps = baseJob.clamps.map(clamp => clamp.clone());
        }
      } else {
        // Clear clamps
        machineState.proposedJob.clamps = [];
      }
      
      // Notify state change
      StateManager.propertyChanged(machineState, 'proposedJob');
    }
  };

  const handleClearSelection = () => {
    setIsJobLoaded(false);
    setLoadedJobName('');
    
    // Clear preview state
    setSelectedFileContent('');
    
    // Clear the proposed job
    machineState.proposedJob = undefined;
    
    // Notify the state manager that the proposed job has changed
    StateManager.propertyChanged(machineState, 'proposedJob');
    
    UserMessageQueue.Instance.addMessage('✓ Job selection cleared');
  };

  return (
    <Box sx={{ height: '100%', display: 'flex', flexDirection: 'column' }}>
      {!isJobLoaded && !selectedFileContent ? (
        // Selection View - Show when no job is loaded and no file selected
        <Box sx={{ display: 'flex', gap: 3, flex: 1 }}>
          {/* Left Side - Two Column Layout for Jobs and Files */}
          <Box sx={{ display: 'flex', gap: 2, flex: 1, maxWidth: '60%' }}>
            {/* Recent Jobs Column */}
            <Paper sx={{ p: 3, flex: 1 }}>
              <Typography variant="h6" gutterBottom>
                Recent Jobs
              </Typography>
              
              <List dense>
                {/* Special Items - Current Job and Last Job */}
                <ObserveState
                  listenTo={machineState}
                  properties={['currentJob', 'lastJob']}
                  control={() => (
                    <>
                      {/* Current Job */}
                      {machineState.currentJob && (
                        <Box sx={{ position: 'relative', mb: 1 }}>
                          <ListItemButton 
                            sx={{ 
                              borderRadius: 1,
                              border: '1px solid',
                              borderColor: 'divider',
                              backgroundColor: 'action.hover',
                              '&:hover': {
                                borderColor: 'primary.main',
                                backgroundColor: 'action.selected',
                              }
                            }}
                            onClick={() => previewJobFromStorage(machineState.currentJob!)}
                          >
                            <ListItemIcon>
                              <FileIcon />
                            </ListItemIcon>
                            <ListItemText 
                              primary={
                                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                                  <Typography variant="subtitle2">
                                    ⚡ {machineState.currentJob.name} (Current)
                                  </Typography>
                                </Box>
                              }
                              secondary={
                                <Box>
                                  <Typography variant="caption" component="div">
                                    {machineState.currentJob.material.name} - {machineState.currentJob.material.xLength}" × {machineState.currentJob.material.yLength}" × {machineState.currentJob.material.height}"
                                  </Typography>
                                  <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mt: 0.5 }}>
                                    <TimeIcon fontSize="small" />
                                    <Typography variant="caption">
                                      {machineState.currentJob.averageRuntimeFormatted} avg • {machineState.currentJob.executionCount} runs
                                    </Typography>
                                    <Chip 
                                      label={machineState.currentJob.material.type} 
                                      size="small" 
                                      variant="outlined"
                                      sx={{ height: 16, fontSize: '0.6rem' }}
                                    />
                                  </Box>
                                </Box>
                              }
                            />
                          </ListItemButton>
                        </Box>
                      )}
                      
                      {/* Last Job */}
                      {machineState.lastJob && machineState.lastJob !== machineState.currentJob && (
                        <Box sx={{ position: 'relative', mb: 1 }}>
                          <ListItemButton 
                            sx={{ 
                              borderRadius: 1,
                              border: '1px solid',
                              borderColor: 'divider',
                              backgroundColor: 'action.hover',
                              '&:hover': {
                                borderColor: 'secondary.main',
                                backgroundColor: 'action.selected',
                              }
                            }}
                            onClick={() => previewJobFromStorage(machineState.lastJob!)}
                          >
                            <ListItemIcon>
                              <FileIcon />
                            </ListItemIcon>
                            <ListItemText 
                              primary={
                                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                                  <Typography variant="subtitle2">
                                    🕐 {machineState.lastJob.name} (Last)
                                  </Typography>
                                </Box>
                              }
                              secondary={
                                <Box>
                                  <Typography variant="caption" component="div">
                                    {machineState.lastJob.material.name} - {machineState.lastJob.material.xLength}" × {machineState.lastJob.material.yLength}" × {machineState.lastJob.material.height}"
                                  </Typography>
                                  <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mt: 0.5 }}>
                                    <TimeIcon fontSize="small" />
                                    <Typography variant="caption">
                                      {machineState.lastJob.averageRuntimeFormatted} avg • {machineState.lastJob.executionCount} runs
                                    </Typography>
                                    <Chip 
                                      label={machineState.lastJob.material.type} 
                                      size="small" 
                                      variant="outlined"
                                      sx={{ height: 16, fontSize: '0.6rem' }}
                                    />
                                  </Box>
                                </Box>
                              }
                            />
                          </ListItemButton>
                        </Box>
                      )}
                    </>
                  )}
                />
                
                {/* Regular Recent Jobs */}
                {recentJobs.slice(0, 5).map((job, index) => (
                  <Box 
                    key={index} 
                    sx={{ position: 'relative', mb: 1 }}
                    onMouseEnter={() => setHoveredJobIndex(index)}
                    onMouseLeave={() => setHoveredJobIndex(null)}
                  >
                    <ListItemButton 
                      sx={{ 
                        borderRadius: 1,
                        border: '1px solid',
                        borderColor: 'divider',
                        '&:hover': {
                          borderColor: 'primary.main',
                        }
                      }}
                      onClick={() => previewJobFromStorage(job)}
                    >
                      <ListItemIcon>
                        <FileIcon />
                      </ListItemIcon>
                      <ListItemText 
                        primary={job.name} 
                        secondary={
                          <Box>
                            <Typography variant="caption" component="div">
                              {job.material.name} - {job.material.xLength}" × {job.material.yLength}" × {job.material.height}"
                            </Typography>
                            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mt: 0.5 }}>
                              <TimeIcon fontSize="small" />
                              <Typography variant="caption">
                                {job.averageRuntimeFormatted} avg • {job.executionCount} runs
                              </Typography>
                              <Chip 
                                label={job.material.type} 
                                size="small" 
                                variant="outlined"
                                sx={{ height: 16, fontSize: '0.6rem' }}
                              />
                            </Box>
                          </Box>
                        }
                      />
                    </ListItemButton>
                  </Box>
                ))}
              </List>
              
              {recentJobs.length > 5 && (
                <Box sx={{ textAlign: 'center', mt: 2 }}>
                  <Button 
                    variant="text" 
                    size="small"
                    onClick={() => setShowRecentJobsDialog(true)}
                  >
                    Show More ({recentJobs.length - 5} more)
                  </Button>
                </Box>
              )}
            </Paper>

            {/* New Files Column */}
            <Paper sx={{ p: 3, flex: 1 }}>
              <Typography variant="h6" gutterBottom>
                New Files
              </Typography>
              
              {/* Combined Files from All Locations */}
              <List dense>
                {(() => {
                  // Combine files from all locations
                  const allFiles: GCodeFile[] = [];
                  jobStorage.getFileLocations().forEach(location => {
                    const files = jobStorage.getFiles(JobType.Milling, location, 10);
                    allFiles.push(...files);
                  });
                  return allFiles.slice(0, 5); // Show only first 5 files
                })().map((gCodeFile, index) => (
                  <Box 
                    key={index} 
                    sx={{ position: 'relative', mb: 0.5 }}
                    onMouseEnter={() => setHoveredFileIndex(index)}
                    onMouseLeave={() => setHoveredFileIndex(null)}
                  >
                    <ListItemButton 
                      sx={{ 
                        borderRadius: 1,
                        border: '1px solid',
                        borderColor: 'divider',
                        '&:hover': {
                          borderColor: 'primary.main',
                        }
                      }}
                      onClick={() => previewTemplateFile(gCodeFile)}
                    >
                      <ListItemIcon>
                        <FileIcon />
                      </ListItemIcon>
                      <ListItemText 
                        primary={gCodeFile.name} 
                        secondary={
                          <Box>
                            <Typography variant="caption" component="div">
                              {formatFileAge(gCodeFile.lastModified)} • {formatFileSize(gCodeFile.size)}
                            </Typography>
                          </Box>
                        }
                      />
                    </ListItemButton>
                  </Box>
                ))}
              </List>
              
              {/* Show More Link */}
              {(() => {
                // Calculate total files for show more link
                const allFiles: GCodeFile[] = [];
                jobStorage.getFileLocations().forEach(location => {
                  const files = jobStorage.getFiles(JobType.Milling, location, 10);
                  allFiles.push(...files);
                });
                return allFiles.length > 5 ? (
                  <Box sx={{ textAlign: 'center', mt: 2 }}>
                    <Button 
                      variant="text" 
                      size="small"
                      onClick={() => setShowAvailableFilesDialog(true)}
                    >
                      Show More ({allFiles.length - 5} more)
                    </Button>
                  </Box>
                ) : null;
              })()}
              
              {/* Upload Button - Now below Show More */}
              <Box sx={{ display: 'flex', justifyContent: 'center', mt: 2 }}>
                <Button
                  variant="outlined"
                  component="label"
                  startIcon={<UploadIcon />}
                  size="small"
                >
                  Upload G-Code File
                  <input
                    type="file"
                    accept=".gcode,.nc,.cnc,.tap"
                    onChange={handleFileUpload}
                    hidden
                  />
                </Button>
              </Box>
            </Paper>
          </Box>

          {/* Right Side - Preview Message */}
          <Paper sx={{ 
            flex: 1, 
            display: 'flex', 
            alignItems: 'center', 
            justifyContent: 'center',
            minHeight: '400px',
            backgroundColor: 'action.hover'
          }}>
            <Box sx={{ textAlign: 'center', p: 4 }}>
              <View3DIcon sx={{ fontSize: 64, color: 'text.secondary', mb: 2 }} />
              <Typography variant="h5" color="text.secondary" gutterBottom>
                Select Job/File to See Preview
              </Typography>
              <Typography variant="body2" color="text.secondary">
                Choose a recent job or upload a new G-Code file to see the 3D toolpath preview
              </Typography>
            </Box>
          </Paper>

          {/* End of file selection view */}
        </Box>
      ) : (
        // Loaded View - Show when job is loaded
        <Box sx={{ display: 'flex', gap: 3, flex: 1 }}>
          {/* Left Column - File Analysis and Additional Content */}
          <Box sx={{ flex: 1, display: 'flex', flexDirection: 'column', gap: 2 }}>
            {/* File Analysis at top of left column */}
            <Paper sx={{ p: 3 }}>
              <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
                <Typography variant="h6">
                  File Analysis
                </Typography>
                <Button
                  variant="outlined"
                  startIcon={<BackIcon />}
                  onClick={handleClearSelection}
                  size="small"
                >
                  Pick Different Job/File
                </Button>
              </Box>

              <Alert severity="success" sx={{ mb: 3 }}>
                <Typography variant="subtitle2">
                  Job loaded successfully: {loadedJobName}
                </Typography>
                <Typography variant="caption">
                  G-Code is ready for the next stage of setup.
                </Typography>
              </Alert>

              {/* Job Inheritance Settings - Show if we have current job with material or last job */}
              {((machineState.currentJob?.material) || machineState.lastJob) && (
                <Paper sx={{ p: 2, mb: 3, backgroundColor: 'action.hover' }}>
                  <Typography variant="subtitle2" gutterBottom>
                    Inherit from {(machineState.currentJob?.material) ? 'Current Job' : 'Last Job'}
                  </Typography>
                  <Typography variant="caption" color="text.secondary" sx={{ mb: 2, display: 'block' }}>
                    Choose what to copy from the {(machineState.currentJob?.material) ? 'current' : 'previous'} job setup
                  </Typography>
                  
                  <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
                    <FormControlLabel
                      control={
                        <Switch
                          checked={useLastJobMaterial}
                          onChange={(e) => handleMaterialToggleChange(e.target.checked)}
                          color="primary"
                        />
                      }
                      label={`Use ${(machineState.currentJob?.material) ? 'current' : 'last'} job material`}
                    />
                    <FormControlLabel
                      control={
                        <Switch
                          checked={useLastJobClamps}
                          onChange={(e) => handleClampsToggleChange(e.target.checked)}
                          color="primary"
                        />
                      }
                      label={`Use ${(machineState.currentJob?.material) ? 'current' : 'last'} job clamps`}
                    />
                  </Box>
                </Paper>
              )}

              <Box sx={{ display: 'flex', gap: 4, flexWrap: 'wrap' }}>
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                  <TimeIcon color="primary" />
                  <Box>
                    <Typography variant="body2" color="text.secondary">Estimated Time</Typography>
                    <Typography variant="h6">
                      45 minutes
                    </Typography>
                  </Box>
                </Box>
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                  <ToolIcon color="primary" />
                  <Box>
                    <Typography variant="body2" color="text.secondary">Tools Required</Typography>
                    <Typography variant="h6">3 tools</Typography>
                  </Box>
                </Box>
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                  <DimensionIcon color="primary" />
                  <Box>
                    <Typography variant="body2" color="text.secondary">Material Required</Typography>
                    <Typography variant="h6">6" × 4" × 1"</Typography>
                  </Box>
                </Box>
                <Box>
                  <Typography variant="body2" color="text.secondary">Material Type</Typography>
                  <Chip 
                    label="Wood" 
                    color="primary" 
                    variant="outlined"
                    sx={{ mt: 0.5 }}
                  />
                </Box>
              </Box>
              
              <Box sx={{ mt: 2 }}>
                <Typography variant="body2" color="text.secondary">Description</Typography>
                <Typography variant="body1">
                  {loadedJobName === 'Uploaded File' ? 
                    'User uploaded G-code file ready for processing.' :
                    `Template file: ${loadedJobName}`
                  }
                </Typography>
              </Box>
            </Paper>

            {/* Additional content will go here in future updates */}
          </Box>

          {/* Right Column - Tabbed Interface */}
          <Paper sx={{ flex: 1, display: 'flex', flexDirection: 'column' }}>
            <Box sx={{ borderBottom: 1, borderColor: 'divider' }}>
              <Tabs 
                value={rightTabValue} 
                onChange={(_, newValue) => setRightTabValue(newValue)}
                aria-label="preview tabs"
              >
                <Tab 
                  icon={<View3DIcon />} 
                  label="Toolpath" 
                  iconPosition="start"
                />
                <Tab 
                  icon={<CodeIcon />} 
                  label="G-Code" 
                  iconPosition="start"
                />
              </Tabs>
            </Box>

            <Box sx={{ flex: 1, p: 3, display: 'flex', flexDirection: 'column' }}>
              {rightTabValue === 0 && (
                // Toolpath Viewer Tab
                <Box sx={{ flex: 1, display: 'flex', flexDirection: 'column' }}>
                  <Box sx={{ flex: 1, minHeight: 400 }}>
                    <ObserveState
                      listenTo={machineState}
                      properties={['proposedJob']}
                      control={() => (
                        <FullSizeCNCViewer
                          simulatorView={createPreviewSimulatorView()}
                          machineState={MachineStateData.Instance}
                          machineData={MachineData.Instance}
                          job={machineState.proposedJob || machineState.currentJob || Job.createTestJob()}
                          viewType={CNCViewType.Top}
                          enableOrbit={true}
                          enableClampDragging={false}
                          enableSpindleDrag={false}
                          isHardcodedSettings={true}
                        />
                      )}
                    />
                  </Box>
                </Box>
              )}

              {rightTabValue === 1 && (
                // G-Code Tab
                <Box sx={{ flex: 1, display: 'flex', flexDirection: 'column' }}>
                  {selectedFileContent ? (
                    <Box sx={{ flex: 1 }}>
                      <TextField
                        multiline
                        rows={25}
                        value={selectedFileContent}
                        fullWidth
                        variant="outlined"
                        InputProps={{
                          readOnly: true,
                          sx: { fontFamily: 'monospace', fontSize: '0.8rem' }
                        }}
                      />
                    </Box>
                  ) : (
                    <Box 
                      sx={{ 
                        flex: 1,
                        display: 'flex', 
                        alignItems: 'center', 
                        justifyContent: 'center',
                        border: '1px dashed',
                        borderColor: 'divider',
                        borderRadius: 1
                      }}
                    >
                      <Typography variant="body2" color="text.secondary">
                        Select a G-Code file to view its content
                      </Typography>
                    </Box>
                  )}
                </Box>
              )}
            </Box>
          </Paper>
        </Box>
      )}
      
      {/* Dialog Components */}
      <RecentJobsDialog
        open={showRecentJobsDialog}
        onClose={() => setShowRecentJobsDialog(false)}
        onJobSelect={previewJobFromStorage}
      />
      
      <AvailableFilesDialog
        open={showAvailableFilesDialog}
        onClose={() => setShowAvailableFilesDialog(false)}
        onFileSelect={previewTemplateFile}
      />
    </Box>
  );
};
