import React, { useState, useEffect, useCallback } from 'react';
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  Typography,
  Box,
  CircularProgress,
  Link,
  Stepper,
  Step,
  StepLabel,
  Alert
} from '@mui/material';
import { BugReport as BugReportIcon, CheckCircle as CheckCircleIcon } from '@mui/icons-material';
import { MachineInput } from '../../data/Machine/MachineInput';
import { InputTriggeredState } from '../../data/Machine/InputTriggeredState';

interface TestInputDialogProps {
  open: boolean;
  input: MachineInput | null;
  onClose: () => void;
}

enum TestInputStep {
  Instructions = 0,
  Testing = 1,
  Success = 2
}

export function TestInputDialog({ open, input, onClose }: TestInputDialogProps) {
  const [currentStep, setCurrentStep] = useState(TestInputStep.Instructions);
  const [countdown, setCountdown] = useState(10);

  // Reset state when dialog opens/closes
  useEffect(() => {
    if (open) {
      setCurrentStep(TestInputStep.Instructions);
      setCountdown(10);
    }
  }, [open]);

  // Countdown timer for testing period
  useEffect(() => {
    let timer: NodeJS.Timeout;
    
    if (currentStep === TestInputStep.Testing && countdown > 0) {
      timer = setTimeout(() => {
        setCountdown(prev => prev - 1);
      }, 1000);
    } else if (currentStep === TestInputStep.Testing && countdown === 0) {
      // Test period completed - show success
      setCurrentStep(TestInputStep.Success);
    }

    return () => {
      if (timer) clearTimeout(timer);
    };
  }, [currentStep, countdown, input?.name]);

  const handleStartTesting = useCallback(() => {
    setCurrentStep(TestInputStep.Testing);
    setCountdown(10);
  }, []);

  const handleClose = useCallback(() => {
    setCurrentStep(TestInputStep.Instructions);
    setCountdown(10);
    onClose();
  }, [onClose]);

  if (!input) return null;

  const steps = ['Instructions', 'Testing Input', 'Test Complete'];

  return (
    <Dialog open={open} onClose={handleClose} maxWidth="md" fullWidth>
      <DialogTitle>
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
          <BugReportIcon />
          Test Input: {input.name}
        </Box>
      </DialogTitle>
      
      <DialogContent>
        <Box sx={{ mb: 3 }}>
          <Stepper activeStep={currentStep} alternativeLabel>
            {steps.map((label) => (
              <Step key={label}>
                <StepLabel>{label}</StepLabel>
              </Step>
            ))}
          </Stepper>
        </Box>

        {currentStep === TestInputStep.Instructions && (
          <Box>
            <Typography variant="h6" sx={{ mb: 2 }}>
              Test Instructions
            </Typography>
            <Typography variant="body1" sx={{ mb: 2 }}>
              This process will guide you through testing the "{input.name}" input (Input #{input.number}).
            </Typography>
            
            <Alert severity="info" sx={{ mb: 2 }}>
              <Typography variant="body2">
                <strong>How to test this input:</strong>
              </Typography>
              <Typography variant="body2" component="ol" sx={{ mt: 1, pl: 2 }}>
                <li>Click "Start Test" below</li>
                <li>During the test period, trigger the physical input multiple times</li>
                <li>Watch the input status in the Input/Output drawer to verify it responds</li>
                <li>The test will complete automatically after the countdown</li>
              </Typography>
            </Alert>

            <Box sx={{ p: 2, backgroundColor: 'background.paper', border: '1px solid', borderColor: 'divider', borderRadius: 1, mb: 2 }}>
              <Typography variant="body2" sx={{ fontWeight: 'bold', mb: 1 }}>
                Input Details:
              </Typography>
              <Typography variant="body2" sx={{ mb: 0.5 }}>
                • <strong>Number:</strong> {input.number}
              </Typography>
              <Typography variant="body2" sx={{ mb: 0.5 }}>
                • <strong>Active State:</strong> {input.activeState === InputTriggeredState.Open ? 'Open' : 'Closed'} (Normally {input.activeState === InputTriggeredState.Open ? 'Closed' : 'Open'})
              </Typography>
              <Typography variant="body2" sx={{ mb: 0.5 }}>
                • <strong>When Active:</strong> {input.activeText}
              </Typography>
              <Typography variant="body2">
                • <strong>When Inactive:</strong> {input.inactiveText}
              </Typography>
            </Box>

            <Box sx={{ p: 2, backgroundColor: 'background.paper', border: '1px solid', borderColor: 'divider', borderRadius: 1 }}>
              <Typography variant="body2" sx={{ mb: 1 }}>
                <strong>Need help testing inputs?</strong>
              </Typography>
              <Link 
                href="https://example.com/input-testing-guide" 
                target="_blank" 
                rel="noopener noreferrer"
                sx={{ fontSize: '0.875rem' }}
              >
                📹 Watch: How to Test Machine Inputs
              </Link>
            </Box>
          </Box>
        )}

        {currentStep === TestInputStep.Testing && (
          <Box sx={{ textAlign: 'center' }}>
            <Typography variant="h6" sx={{ mb: 2 }}>
              Testing Input...
            </Typography>
            
            <Box sx={{ mb: 3 }}>
              <CircularProgress size={60} />
            </Box>
            
            <Typography variant="h4" sx={{ mb: 2, color: 'primary.main' }}>
              {countdown}
            </Typography>
            
            <Typography variant="body1" sx={{ mb: 2 }}>
              Please test the "{input.name}" input now
            </Typography>
            
            <Alert severity="info" sx={{ mb: 2 }}>
              <Typography variant="body2">
                Trigger the input several times and verify the status changes in the Input/Output drawer.
              </Typography>
            </Alert>

            <Typography variant="body2" color="text.secondary">
              Test period: {countdown} seconds remaining
            </Typography>
          </Box>
        )}

        {currentStep === TestInputStep.Success && (
          <Box sx={{ textAlign: 'center' }}>
            <Typography variant="h6" sx={{ mb: 2 }}>
              Test Complete!
            </Typography>
            
            <Box sx={{ display: 'flex', justifyContent: 'center', mb: 3 }}>
              <CheckCircleIcon sx={{ fontSize: 60, color: 'success.main' }} />
            </Box>
            
            <Typography variant="h4" sx={{ mb: 2, color: 'success.main', fontWeight: 'bold' }}>
              ✓ Success
            </Typography>
            
            <Typography variant="body1" sx={{ mb: 2 }}>
              Testing for "{input.name}" (Input #{input.number}) has been completed.
            </Typography>
            
            <Alert severity="success" sx={{ mb: 2 }}>
              <Typography variant="body2">
                If the input responded correctly during testing, it is working properly. 
                If not, check your physical connections and wiring.
              </Typography>
            </Alert>
            
            <Typography variant="body2" color="text.secondary">
              You can now close this dialog and continue with your workflow.
            </Typography>
          </Box>
        )}
      </DialogContent>
      
      <DialogActions>
        <Button onClick={handleClose}>
          {currentStep === TestInputStep.Success ? 'Close' : 'Cancel'}
        </Button>
        
        {currentStep === TestInputStep.Instructions && (
          <Button 
            onClick={handleStartTesting}
            variant="contained"
            startIcon={<BugReportIcon />}
          >
            Start Test
          </Button>
        )}
        
        {currentStep === TestInputStep.Success && (
          <Button 
            onClick={handleClose}
            variant="contained"
            color="success"
            startIcon={<CheckCircleIcon />}
          >
            Complete
          </Button>
        )}
      </DialogActions>
    </Dialog>
  );
}
