import { Calculate, CheckCircle, Warning } from "@mui/icons-material";
import {
  Alert,
  Box,
  Button,
  Chip,
  Divider,
  Grid,
  Paper,
  Typography
} from "@mui/material";
import React from "react";
import { ConfigurationData } from "../../../../data/ConfigurationData";
import { MachineData } from "../../../../data/MachineData";
import { MachineStateData } from "../../../../data/MachineStateData";
import { AutoBind } from "../../../../utils/AutoBind";
import { StateManager } from "../../../../utils/statemanager/StateManager";
import { FullSizeCNCViewer } from "../../../MachineViewer/FullSizeCNCViewer";
import { WizardStep } from "../../../Wizard/WizardStep";
import { AxisCalibrationWizard } from "../AxisCalibrationWizard";
import { AxisCalibrationData } from "./AxisCalibrationData";

export class AxisCalibrationResultStep extends WizardStep {
  constructor(wizard: AxisCalibrationWizard, priorStep: WizardStep | null = null) {
    super(wizard, priorStep);
  }

  getTitle(): string {

    return `${AxisCalibrationData.Instance.axis} Axis Calibration - Results`;
  }

  nextStep(): WizardStep | null {
    // User can choose to recalibrate
    const { AxisCalibrationPositionStep } = require("./AxisCalibrationPositionStep");
    return new AxisCalibrationPositionStep(this.wizard as AxisCalibrationWizard, this);
  }

  backStep(): WizardStep | null {
    return this.priorStep;
  }

  @AutoBind
  private async applyCalibration(): Promise<void> {
    const axisConfig = (this.wizard as AxisCalibrationWizard).state.axisConfig;

    // Calculate new turns ratio based on calibration factor
    const newTurnsRatio = axisConfig.overallTurnsRatio * AxisCalibrationData.Instance.calibrationFactor;

    // Apply the calculated calibration to the axis config (local data)
    axisConfig.overallTurnsRatio = newTurnsRatio;

    // Apply to machine via API
    const { Machine } = await import('../../../../machine/Machine');
    const { MachineConfigurationMapper } = await import('../../../../utils/MachineConfigurationMapper');
    const axisNumber = MachineData.Instance.axisConfigurations.indexOf(axisConfig) + 1;
    const apiConfig = MachineConfigurationMapper.convertAxisToAPIFormat(axisConfig, axisNumber);
    await Machine.getInstance().setup.ConfigureAxis(apiConfig);

    // Close the wizard
    this.wizard.closeWizard();
  }

  @AutoBind
  private async startIterativeTesting(): Promise<void> {
    // Apply current calibration factor immediately (local data)
    const axisConfig = (this.wizard as AxisCalibrationWizard).state.axisConfig;
    const newTurnsRatio = axisConfig.overallTurnsRatio * AxisCalibrationData.Instance.calibrationFactor;
    axisConfig.overallTurnsRatio = newTurnsRatio;

    // Apply to machine via API
    const { Machine } = await import('../../../../machine/Machine');
    const { MachineConfigurationMapper } = await import('../../../../utils/MachineConfigurationMapper');
    const axisNumber = MachineData.Instance.axisConfigurations.indexOf(axisConfig) + 1;
    const apiConfig = MachineConfigurationMapper.convertAxisToAPIFormat(axisConfig, axisNumber);
    await Machine.getInstance().setup.ConfigureAxis(apiConfig);

    // Reset for next test
    AxisCalibrationData.Instance.resetForNextTest();

    // Go to return step which will move back to start position
    const { AxisCalibrationReturnStep } = require("./AxisCalibrationReturnStep");
    const newStep = new AxisCalibrationReturnStep(this.wizard as AxisCalibrationWizard, this);

    // Set the current step and notify StateManager
    this.wizard.currentStep = newStep;
    StateManager.propertyChanged(this.wizard, 'currentStep');
  }

  render(): React.ReactNode {

    const axisConfig = (this.wizard as AxisCalibrationWizard).state.axisConfig;

    // Calculate accuracy metrics
    const errorDistance = Math.abs(AxisCalibrationData.Instance.actualMoveAmount - AxisCalibrationData.Instance.distanceToMove);
    const errorPercentage = (errorDistance / AxisCalibrationData.Instance.distanceToMove) * 100;
    const correctionFactor = AxisCalibrationData.Instance.calibrationFactor;
    const newTurnsRatio = axisConfig.overallTurnsRatio * correctionFactor;
    const isAccurate = errorPercentage <= 1; // Less than 1% error

    return (
      <Box sx={{ p: 3, height: '100%', display: 'flex', flexDirection: 'column', gap: 3 }}>
        <Alert severity={isAccurate ? "success" : "warning"} icon={isAccurate ? <CheckCircle /> : <Warning />}>
          Calibration calculation complete!
          {isAccurate ? " Your axis accuracy is excellent." : " Consider applying the calibration for improved accuracy."}
        </Alert>

        {/* Main Content Area */}
        <Box sx={{ display: 'flex', gap: 3, flex: 1, minHeight: 0 }}>
          {/* Left Side - Results Summary (50%) */}
          <Box sx={{ flex: '50%', display: 'flex', flexDirection: 'column', gap: 3 }}>

            {/* Results Summary */}
            <Paper sx={{ p: 3 }}>
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 2 }}>
                <Calculate />
                <Typography variant="h6">Calibration Results</Typography>
              </Box>

              <Grid container spacing={3}>
                {/* Movement Accuracy */}
                <Grid item xs={12}>
                  <Typography variant="subtitle2" color="text.secondary">Movement Accuracy</Typography>
                  <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap', mt: 1 }}>
                    <Chip
                      label={`Target: ${AxisCalibrationData.Instance.distanceToMove}"`}
                      color="primary"
                      variant="outlined"
                    />
                    <Chip
                      label={`Actual: ${AxisCalibrationData.Instance.actualMoveAmount}"`}
                      color={isAccurate ? "success" : "warning"}
                    />
                    <Chip
                      label={`Error: ${errorDistance.toFixed(4)}" (${errorPercentage.toFixed(2)}%)`}
                      color={errorPercentage <= 1 ? "success" : errorPercentage <= 5 ? "warning" : "error"}
                    />
                  </Box>
                </Grid>

                {/* Calibration Values */}
                <Grid item xs={12}>
                  <Typography variant="subtitle2" color="text.secondary">Calibration Values</Typography>
                  <Box sx={{ mt: 1 }}>
                    <Typography variant="body2">
                      <strong>Current Turns Ratio:</strong> {axisConfig.overallTurnsRatio.toFixed(6)}
                    </Typography>
                    <Typography variant="body2" color="primary">
                      <strong>New Turns Ratio:</strong> {newTurnsRatio.toFixed(6)}
                    </Typography>
                    <Typography variant="body2">
                      <strong>Correction Factor:</strong> {correctionFactor.toFixed(6)}
                    </Typography>
                  </Box>
                </Grid>
              </Grid>

              <Divider sx={{ my: 2 }} />

              {/* Recommendation */}
              <Alert severity={isAccurate ? "info" : "warning"}>
                {isAccurate ? (
                  <Typography variant="body2">
                    Your axis is already very accurate (≤1% error). You may choose to apply the minor correction or keep the current settings.
                  </Typography>
                ) : errorPercentage <= 5 ? (
                  <Typography variant="body2">
                    <strong>Recommended:</strong> Apply the calibration to improve accuracy from {errorPercentage.toFixed(2)}% error to near-perfect precision.
                  </Typography>
                ) : (
                  <Typography variant="body2">
                    <strong>Highly Recommended:</strong> Your axis has {errorPercentage.toFixed(2)}% error. Applying this calibration will significantly improve accuracy.
                  </Typography>
                )}
              </Alert>
            </Paper>
          </Box>

          {/* Right Side - 3D Viewer (50%) */}
          <Box sx={{ flex: '50%', display: 'flex', flexDirection: 'column', minHeight: 0 }}>
            <FullSizeCNCViewer
              simulatorView={ConfigurationData.Instance.defaultView}
              machineState={MachineStateData.Instance}
              machineData={MachineData.Instance}
              job={MachineStateData.Instance.currentJob!}
              enableOrbit={true}
              enableClampDragging={false}
              enableSpindleDrag={false}
            />
          </Box>
        </Box>

        {/* Action Buttons */}
        <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <Box sx={{ display: 'flex', gap: 2 }}>
            <Button
              variant="outlined"
              onClick={this.startIterativeTesting}
              color="warning"
            >
              Test/Adjust Tuning
            </Button>
          </Box>

          <Box sx={{ display: 'flex', gap: 2 }}>
            <Button
              variant="outlined"
              onClick={() => this.wizard.closeWizard()}
            >
              Cancel
            </Button>
            <Button
              variant="contained"
              onClick={this.applyCalibration}
              size="large"
            >
              Apply Calibration
            </Button>
          </Box>
        </Box>
      </Box>
    );
  }
}
