import { Wizard } from "../../Wizard/Wizard";
import { WizardManager } from "../../Wizard/WizardManager";
import { HomingPreparationStep } from "./steps/HomingPreparationStep";

export class HomingWizard extends Wizard {
  constructor() {
    const initialState = {
      isHoming: false,
      homingComplete: false,
      homingError: false,
      autoStarted: false
    };

    // Create the first step
    const firstStep = new HomingPreparationStep(null as any); // Temporary - will be set below

    super(
      firstStep,
      initialState,
      true, // canClose
      false, // clickAwayClose - don't allow accidental closure during homing
      '70%', // width
      '80%'  // height
    );

    // Now set the proper wizard reference
    firstStep.wizard = this;
    this.firstStep = firstStep;
    this.currentStep = firstStep;
  }

  /**
   * Show the automatic homing wizard
   * Note: Use HomingWizardManager.Instance.show() to automatically select the correct wizard
   */
  static show(): void {
    const wizard = new HomingWizard();
    WizardManager.Instance.start(wizard);
  }
}
