import { MachineOutput } from '../data/Machine/MachineOutput';
import { StateManager } from './statemanager/StateManager';
import { Logger, LogCategory } from './Logger';

/**
 * Utility functions for managing machine output number assignments
 */
export class OutputNumberManager {
  
  /**
   * Assigns a number to an output, handling conflicts and validation
   * @param targetOutput The output to assign the number to
   * @param newNumber The number to assign
   * @param allOutputs Array of all machine outputs
   * @param dataContext The data context to trigger state updates on
   * @returns Updated array of outputs with conflicts resolved
   */
  static assignOutputNumber(
    targetOutput: MachineOutput, 
    newNumber: number, 
    allOutputs: MachineOutput[],
    dataContext: any
  ): MachineOutput[] {
    // Validate that unused outputs never get assigned numbers
    if (!targetOutput.use && newNumber > 0) {
      Logger.Instance.logError(LogCategory.System, 
        `Cannot assign number ${newNumber} to unused output: ${targetOutput.name}`);
      return allOutputs;
    }

    // If assigning a real number (not 0), check for conflicts
    if (newNumber > 0) {
      // Find any existing outputs with the same number
      const conflictingOutputs = allOutputs.filter(output => 
        output !== targetOutput && 
        output.number === newNumber
      );

      // Unassign conflicting outputs
      conflictingOutputs.forEach(conflictOutput => {
        const oldNumber = conflictOutput.number;
        conflictOutput.number = 0; // Set to 0 for unassigned
        Logger.Instance.log(LogCategory.System, 
          `Unassigned output ${conflictOutput.name} from number ${oldNumber} due to conflict`);
      });

      if (conflictingOutputs.length > 0) {
        Logger.Instance.log(LogCategory.System, 
          `Resolved ${conflictingOutputs.length} output number conflicts for number ${newNumber}`);
      }
    }

    // Assign the number to the target output
    const oldNumber = targetOutput.number;
    targetOutput.number = newNumber;

    // Log the assignment
    if (newNumber === 0) {
      Logger.Instance.log(LogCategory.System, 
        `Unassigned output ${targetOutput.name} from number ${oldNumber}`);
    } else {
      Logger.Instance.log(LogCategory.System, 
        `Assigned output ${targetOutput.name} to number ${newNumber}`);
    }

    // Trigger state update
    StateManager.propertyChanged(dataContext, 'machineOutputs');

    return allOutputs;
  }

  /**
   * Validates that an output can be assigned a specific number
   * @param targetOutput The output to validate
   * @param newNumber The number to assign
   * @param allOutputs Array of all machine outputs
   * @returns Object with isValid flag and error message if invalid
   */
  static validateOutputNumberAssignment(
    targetOutput: MachineOutput,
    newNumber: number,
    allOutputs: MachineOutput[]
  ): { isValid: boolean; error?: string } {
    // Unused outputs cannot have numbers
    if (!targetOutput.use && newNumber > 0) {
      return {
        isValid: false,
        error: `Unused outputs cannot be assigned numbers. Enable the output first.`
      };
    }

    // Number must be positive if not 0
    if (newNumber < 0) {
      return {
        isValid: false,
        error: `Output number must be 0 or greater.`
      };
    }

    return { isValid: true };
  }

  /**
   * Gets all outputs that are currently unassigned (number = 0)
   * @param allOutputs Array of all machine outputs
   * @returns Array of unassigned outputs
   */
  static getUnassignedOutputs(allOutputs: MachineOutput[]): MachineOutput[] {
    return allOutputs.filter(output => 
      output.use && output.number === 0
    );
  }

  /**
   * Gets all outputs that are currently assigned to numbers
   * @param allOutputs Array of all machine outputs
   * @returns Array of assigned outputs, sorted by number
   */
  static getAssignedOutputs(allOutputs: MachineOutput[]): MachineOutput[] {
    return allOutputs
      .filter(output => output.use && output.number > 0)
      .sort((a, b) => a.number - b.number);
  }

  /**
   * Gets all outputs that are not in use
   * @param allOutputs Array of all machine outputs
   * @returns Array of unused outputs
   */
  static getUnusedOutputs(allOutputs: MachineOutput[]): MachineOutput[] {
    return allOutputs.filter(output => !output.use);
  }

  /**
   * Finds the next available output number
   * @param allOutputs Array of all machine outputs
   * @param startFrom Starting number to search from (default: 1)
   * @returns Next available output number
   */
  static getNextAvailableNumber(allOutputs: MachineOutput[], startFrom: number = 1): number {
    const usedNumbers = new Set(
      allOutputs
        .filter(output => output.use && output.number > 0)
        .map(output => output.number)
    );

    let nextNumber = startFrom;
    while (usedNumbers.has(nextNumber)) {
      nextNumber++;
    }

    return nextNumber;
  }

  /**
   * Ensures all unused outputs have their numbers set to 0
   * @param allOutputs Array of all machine outputs
   * @param dataContext The data context to trigger state updates on
   * @returns Updated array of outputs
   */
  static enforceUnusedOutputsNumberPolicy(allOutputs: MachineOutput[], dataContext: any): MachineOutput[] {
    let changesMade = false;

    allOutputs.forEach(output => {
      if (!output.use && output.number > 0) {
        const oldNumber = output.number;
        output.number = 0;
        changesMade = true;
        Logger.Instance.log(LogCategory.System, 
          `Enforced policy: Removed number ${oldNumber} from unused output: ${output.name}`);
      }
    });

    if (changesMade) {
      StateManager.propertyChanged(dataContext, 'machineOutputs');
    }

    return allOutputs;
  }
}
