import {
    Box,
    Button,
    Paper,
    ToggleButton,
    ToggleButtonGroup,
    Typography
} from "@mui/material";
import React from "react";
import { ConfigurationData } from "../../../../data/ConfigurationData";
import { MachineData } from "../../../../data/MachineData";
import { MachineStateData } from "../../../../data/MachineStateData";
import { ObserveState } from "../../../../utils/statemanager/ObserveState";
import { NumberInput } from "../../../Common/NumberInput";
import { FullSizeCNCViewer } from "../../../MachineViewer/FullSizeCNCViewer";
import { WizardStep } from "../../../Wizard/WizardStep";
import { AxisCalibrationWizard } from "../AxisCalibrationWizard";
import { AxisCalibrationData } from "./AxisCalibrationData";

export class AxisCalibrationMarkStep extends WizardStep {
  private markingPhase: 'start' | 'end';
  private nextStepOverride: WizardStep | null;

  constructor(wizard: AxisCalibrationWizard, priorStep: WizardStep | null = null, markingPhase: 'start' | 'end' = 'start', nextStep: WizardStep | null = null) {
    super(wizard, priorStep);
    this.markingPhase = markingPhase;
    this.nextStepOverride = nextStep;
  }

  getTitle(): string {
    const axisConfig = this.wizard.state.axisConfig;
    const phase = this.markingPhase === 'start' ? 'Starting' : 'Ending';
    return `${axisConfig.axisType} Axis Calibration - Mark ${phase} Position`;
  }

  nextStep(): WizardStep | null {
    // Use override if provided, otherwise use default flow
    if (this.nextStepOverride) {
      // Set the prior step of the next step to this step
      this.nextStepOverride.priorStep = this;
      return this.nextStepOverride;
    }
    
    if (this.markingPhase === 'start') {
      // After marking start, go to move step
      const { AxisCalibrationMoveStep } = require("./AxisCalibrationMoveStep");
      return new AxisCalibrationMoveStep(this.wizard as AxisCalibrationWizard, this);
    } else {
      // After marking end, go to results
      const { AxisCalibrationResultStep } = require("./AxisCalibrationResultStep");
      return new AxisCalibrationResultStep(this.wizard as AxisCalibrationWizard, this);
    }
  }

  backStep(): WizardStep | null {
    if (this.markingPhase === 'start') {
      // Go back to position step
      const { AxisCalibrationPositionStep } = require("./AxisCalibrationPositionStep");
      return new AxisCalibrationPositionStep(this.wizard as AxisCalibrationWizard, null);
    } else {
      // Go back to measure step
      const { AxisCalibrationMeasureStep } = require("./AxisCalibrationMeasureStep");
      return new AxisCalibrationMeasureStep(this.wizard as AxisCalibrationWizard, this.priorStep);
    }
  }

  render(): React.ReactNode {
    return (
      <ObserveState
        key="axis-calibration-mark-step"
        listenTo={AxisCalibrationData.Instance}
        properties={['markType', 'bitDiameter', 'markDepth', 'spindleSpeed', 'lineLength']}
        control={() => {
          return (
            <Box sx={{ p: 3, height: '100%', display: 'flex', flexDirection: 'column', gap: 3 }}>
              {/* Main Content Area */}
              <Box sx={{ display: 'flex', gap: 3, flex: 1, minHeight: 0 }}>
                {/* Left Side - Marking Options and Settings (50%) */}
                <Box sx={{ flex: '50%', display: 'flex', flexDirection: 'column', gap: 3 }}>
                  
                  {/* Marking Method Selection */}
                  <Paper sx={{ p: 2 }}>
                    <Typography variant="subtitle1" gutterBottom>
                      Marking Method
                    </Typography>
                    <ToggleButtonGroup
                      value={AxisCalibrationData.Instance.markType}
                      exclusive
                      onChange={(event, newValue) => {
                        if (newValue !== null) {
                          AxisCalibrationData.Instance.markType = newValue;
                        }
                      }}
                      aria-label="marking method"
                      size="large"
                      sx={{ width: '100%', mb: 2 }}
                    >
                      <ToggleButton value="manual" sx={{ flex: 1 }}>
                        Manual
                      </ToggleButton>
                      <ToggleButton value="drill" sx={{ flex: 1 }}>
                        Drill Mark
                      </ToggleButton>
                      <ToggleButton value="line" sx={{ flex: 1 }}>
                        Scribed Line
                      </ToggleButton>
                    </ToggleButtonGroup>
                    
                    <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>
                      {AxisCalibrationData.Instance.markType === 'manual' && 'Make your own reference mark or note the position'}
                      {AxisCalibrationData.Instance.markType === 'drill' && 'Create a small drill mark for precise reference'}
                      {AxisCalibrationData.Instance.markType === 'line' && 'Scribe a reference line across the material'}
                    </Typography>
                    
                    {/* Move instruction text here, below toggle buttons */}
                    {AxisCalibrationData.Instance.markType !== 'manual' && (
                      <Typography variant="body2" color="text.secondary" sx={{ fontWeight: 'medium' }}>
                        The machine will create a {AxisCalibrationData.Instance.markDepth}" deep reference mark using the current tool. 
                        Click "Create Mark" to proceed with automatic marking.
                      </Typography>
                    )}
                  </Paper>

                  {/* Tool Settings (only for drill/line) */}
                  {(AxisCalibrationData.Instance.markType === 'drill' || AxisCalibrationData.Instance.markType === 'line') && (
                    <Paper sx={{ p: 2 }}>
                      <Typography variant="subtitle1" gutterBottom>
                        Tool Settings
                      </Typography>
                      
                      {/* Bit Diameter */}
                      <Box sx={{ display: 'flex', gap: 2, alignItems: 'flex-start', mb: 2 }}>
                        <Box sx={{ flex: 1 }}>
                          <NumberInput
                            label="Bit Diameter (inches)"
                            value={AxisCalibrationData.Instance.bitDiameter}
                            onChange={(value) => {
                              AxisCalibrationData.Instance.bitDiameter = value || 0.25;
                            }}
                            min={0.001}
                            max={2}
                            precision={4}
                          />
                        </Box>
                        <Typography variant="body2" color="text.secondary" sx={{ flex: 1, pt: 1 }}>
                          Diameter of the current tool
                        </Typography>
                      </Box>

                      {/* Mark Depth */}
                      <Box sx={{ display: 'flex', gap: 2, alignItems: 'flex-start', mb: 2 }}>
                        <Box sx={{ flex: 1 }}>
                          <NumberInput
                            label="Mark Depth (inches)"
                            value={AxisCalibrationData.Instance.markDepth}
                            onChange={(value) => {
                              if (typeof value === 'number') {
                                AxisCalibrationData.Instance.markDepth = value;
                              } else {
                                AxisCalibrationData.Instance.markDepth = 0.1;
                              }
                            }}
                            min={0.001}
                            max={0.5}
                            precision={4}
                          />
                        </Box>
                        <Typography variant="body2" color="text.secondary" sx={{ flex: 1, pt: 1 }}>
                          Depth to cut/mark into the material
                        </Typography>
                      </Box>

                      {/* Spindle Speed */}
                      <Box sx={{ display: 'flex', gap: 2, alignItems: 'flex-start', mb: AxisCalibrationData.Instance.markType === 'line' ? 2 : 0 }}>
                        <Box sx={{ flex: 1 }}>
                          <NumberInput
                            label="Spindle Speed (RPM)"
                            value={AxisCalibrationData.Instance.spindleSpeed}
                            onChange={(value) => {
                              AxisCalibrationData.Instance.spindleSpeed = value || 12000;
                            }}
                            min={100}
                            max={30000}
                            precision={0}
                          />
                        </Box>
                        <Typography variant="body2" color="text.secondary" sx={{ flex: 1, pt: 1 }}>
                          Rotational speed for marking operation
                        </Typography>
                      </Box>

                      {/* Line Length (only for scribed line) */}
                      {AxisCalibrationData.Instance.markType === 'line' && (
                        <Box sx={{ display: 'flex', gap: 2, alignItems: 'flex-start' }}>
                          <Box sx={{ flex: 1 }}>
                            <NumberInput
                              label="Line Length (inches)"
                              value={AxisCalibrationData.Instance.lineLength}
                              onChange={(value) => {
                                AxisCalibrationData.Instance.lineLength = value || 1.0;
                              }}
                              min={0.1}
                              max={10}
                              precision={3}
                            />
                          </Box>
                          <Typography variant="body2" color="text.secondary" sx={{ flex: 1, pt: 1 }}>
                            Length of the scribed reference line
                          </Typography>
                        </Box>
                      )}
                    </Paper>
                  )}
                </Box>

                {/* Right Side - 3D Viewer (50%) */}
                <Box sx={{ flex: '50%', display: 'flex', flexDirection: 'column', minHeight: 0 }}>
                  <FullSizeCNCViewer 
                    simulatorView={ConfigurationData.Instance.defaultView}
                    machineState={MachineStateData.Instance}
                    machineData={MachineData.Instance}
                    job={MachineStateData.Instance.currentJob!}
                    enableOrbit={true}
                    enableClampDragging={false}
                    enableSpindleDrag={false}
                  />
                </Box>
              </Box>

              {/* Action Buttons */}
              <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <Button 
                  variant="outlined"
                  onClick={() => this.wizard.goToPreviousStep()}
                >
                  Back
                </Button>
                <Button 
                  variant="contained"
                  onClick={() => this.wizard.advanceToNextStep()}
                  size="large"
                >
                  {AxisCalibrationData.Instance.markType === 'manual' ? 'Continue' : 'Create Mark'}
                </Button>
              </Box>
            </Box>
          );
        }}
      />
    );
  }
}
