import { Settings as CheckIcon } from '@mui/icons-material';
import { Box, Button, Typography } from '@mui/material';
import React from 'react';
import { Machine } from '../../../../machine/Machine';
import { DataUtilities } from '../../../../utils/storage/DataUtilities';
import { FlowStep } from "../../../FlowStep";
import { FlowStepData } from "../../../FlowStepData";

export class IsSpindleRunningStep extends FlowStep {
    readonly __type = 'IsSpindleRunningStep';
    readonly category = ['Machine', 'Spindle'];
    readonly name = 'Is Spindle Running';
    readonly description = 'Checks if spindle is currently running';
    
    // Icon is created dynamically, not stored
    get icon(): React.ReactNode {
        return React.createElement(CheckIcon, { sx: { color: 'info.main' } });
    }

    static readonly TRUE_PATH = 'true';
    static readonly FALSE_PATH = 'false';

    async execute(data: FlowStepData, prototypeRun: boolean): Promise<string | null> {
        if (prototypeRun) {
            // Simulate random result for prototype
            return Math.random() > 0.5 ? IsSpindleRunningStep.TRUE_PATH : IsSpindleRunningStep.FALSE_PATH;
        }

        const isRunning = await Machine.getInstance().spindle.IsSpindleRunning();
        return isRunning ? IsSpindleRunningStep.TRUE_PATH : IsSpindleRunningStep.FALSE_PATH;
    }

    results(): string[] {
        return [IsSpindleRunningStep.TRUE_PATH, IsSpindleRunningStep.FALSE_PATH];
    }

    renderResultsUI(data: FlowStepData, result: string): React.ReactNode {
        return (
            <Typography variant="caption">
                Spindle running: {result === IsSpindleRunningStep.TRUE_PATH ? 'Yes' : 'No'}
            </Typography>
        );
    }

    renderEditUI(props: { onClose: () => void }): React.ReactNode {
        return (
            <Box sx={{ p: 2, minWidth: 300 }}>
                <Typography variant="h6" gutterBottom>Is Spindle Running Check</Typography>
                <Typography variant="body2" color="text.secondary">
                    This step has no configurable parameters.
                </Typography>
                <Typography variant="body2" sx={{ mt: 1 }}>
                    It simply checks if the spindle is currently running.
                </Typography>

                <Box sx={{ display: 'flex', gap: 1, justifyContent: 'flex-end', mt: 2 }}>
                    <Button variant="contained" onClick={props.onClose}>OK</Button>
                </Box>
            </Box>
        );
    }

    public toJSON(): any {
        const data = DataUtilities.getStorageData(this, ['icon']) as any;
        data.__type = this.__type;
        return data;
    }

    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data);
    }
}






