import { Wizard } from "../../Wizard/Wizard";
import { WizardManager } from "../../Wizard/WizardManager";
import { ManualHomingStep } from "./steps/ManualHomingStep";

export class ManualHomingWizard extends Wizard {
    constructor() {
        const initialState = {
            isHoming: false,
            homingComplete: false
        };

        // Create the first step
        const firstStep = new ManualHomingStep(null as any); // Temporary - will be set below

        super(
            firstStep,
            initialState,
            true, // canClose
            false, // clickAwayClose - don't allow accidental closure during homing
            '70%', // width
            '80%'  // height
        );

        // Now set the proper wizard reference
        firstStep.wizard = this;
        this.firstStep = firstStep;
        this.currentStep = firstStep;
    }

    static show(): void {
        const wizard = new ManualHomingWizard();
        WizardManager.Instance.start(wizard);
    }
}
