import React from 'react';
import { Cylinder, Box } from '@react-three/drei';
import { MachineData } from '../../../data/MachineData';
import { ConfigurationData } from '../../../data/ConfigurationData';
import { ObserveMultiProperties } from '../../../utils/statemanager/ObserveMultiProperties';
import { RotaryAxis } from '../../../data/MachineData';
import { SimulatorView } from '../../../data/Common/SimulatorView';
import { ViewStyle } from '../../../data/Common/ViewStyle';

interface RotaryProps {
  simulatorView: SimulatorView;
}

export function Rotary({ simulatorView }: RotaryProps) {
  const machineData = MachineData.Instance;
  const config = ConfigurationData.Instance;

  // Don't render if rotary axis is disabled
  if (machineData.rotaryAxis === RotaryAxis.None) {
    return null;
  }

  return (
    <ObserveMultiProperties
      listenTo={[
        { object: machineData, properties: ['rotaryAxis', 'rotaryAxisDirection', 'rotaryDiameter', 'rotaryLength', 'rotaryHeadDiameter', 'rotaryHeadLength', 'rotaryTailDiameter', 'rotaryTailLength', 'rotaryMotorDiameter', 'rotaryMotorLength', 'rotaryPostHeight', 'rotaryPostWidth', 'rotaryPostLength', 'rotaryBedWidth', 'rotaryBedHeight', 'rotaryZeroLocationX', 'rotaryZeroLocationY', 'rotaryZeroLocationZ', 'baseHeight', 'bedHeight', 'bedOffsetX', 'bedOffsetY'] },
        { object: config, properties: ['rotaryMotorColor', 'rotaryHeadColor', 'rotaryTailColor', 'rotaryPostColor', 'rotaryBedColor', 'rotaryTransparency'] }
      ]}
      control={() => {
        // Calculate position based on rotary type
        let baseZ: number;
        let baseX: number = 0;
        let baseY: number = 0;

        if (machineData.rotaryAxis === RotaryAxis.Fixed) {
          // Fixed rotary is relative to the base
          baseZ = machineData.baseHeight;
        } else {
          // Movable rotary is relative to the bed surface
          baseZ = machineData.baseHeight + machineData.bedHeight;
          baseX = machineData.bedOffsetX;
          baseY = machineData.bedOffsetY;
        }

        // Calculate center point of the rotary cylinder (the reference point)
        const centerX = baseX + machineData.rotaryZeroLocationX;
        const centerY = baseY + machineData.rotaryZeroLocationY;
        const centerZ = baseZ + machineData.rotaryZeroLocationZ;

        // Determine axis direction
        const isXAxis = machineData.rotaryAxisDirection === 'X';
        
        // Get component dimensions
        const motorRadius = machineData.rotaryMotorDiameter / 2;
        const headRadius = machineData.rotaryHeadDiameter / 2;
        const tailRadius = machineData.rotaryTailDiameter / 2;
        
        const motorLength = machineData.rotaryMotorLength;
        const headLength = machineData.rotaryHeadLength;
        const tailLength = machineData.rotaryTailLength;
        const rotaryLength = machineData.rotaryLength; // Distance between cylinder and tail
        
        const postHeight = machineData.rotaryPostHeight;
        const postWidth = machineData.rotaryPostWidth;
        const postLength = machineData.rotaryPostLength;
        
        const bedWidth = machineData.rotaryBedWidth;
        const bedHeight = machineData.rotaryBedHeight;

        // Calculate positions along the axis (all relative to center point)
        // Order: Motor -> Post1 -> [Cylinder Center] -> Post2 -> Tail
        // The rotaryLength is the distance between cylinder and tail
        // Motor starts at the edge of post1 (motor's back edge touches post's front edge)
        let motorOffset, post1Offset, post2Offset, tailOffset;
        
        if (isXAxis) {
          // X-axis: components spread along X direction
          post1Offset = -postLength / 2;  // Post at motor end
          motorOffset = post1Offset - postLength / 2 - motorLength / 2;  // Motor starts at post edge
          post2Offset = rotaryLength + postLength / 2;  // Post at tail end
          tailOffset = rotaryLength;  // Tail at rotaryLength distance from center
        } else {
          // Y-axis: components spread along Y direction  
          post1Offset = -postLength / 2;  // Post at motor end
          motorOffset = post1Offset - postLength / 2 - motorLength / 2;  // Motor starts at post edge (toward front)
          post2Offset = rotaryLength + postLength / 2;  // Post at tail end  
          tailOffset = rotaryLength;  // Tail at rotaryLength distance from center
        }

        // Determine material properties based on ViewStyle
        const isTransparent = simulatorView.rotary === ViewStyle.SemiTransparent;
        const isWireframe = simulatorView.rotary === ViewStyle.Wireframe;
        const opacity = isTransparent ? (config.rotaryTransparency || 0.15) : 1.0;

        return (
          <group>
            {/* Motor (cylinder at negative end) */}
            <Cylinder
              position={isXAxis 
                ? [centerX + motorOffset, centerY, centerZ]
                : [centerX, centerY + motorOffset, centerZ]
              }
              args={[motorRadius, motorRadius, motorLength, 16]}
              rotation={isXAxis ? [0, 0, Math.PI / 2] : [0, 0, 0]}
            >
              <meshPhongMaterial 
                color={config.rotaryMotorColor}
                transparent={isTransparent}
                opacity={opacity}
                wireframe={isWireframe}
              />
            </Cylinder>

            {/* Support Post 1 (at motor end) */}
            <Box
              position={isXAxis 
                ? [centerX + post1Offset, centerY, centerZ - postHeight / 2]
                : [centerX, centerY + post1Offset, centerZ - postHeight / 2]
              }
              args={[postWidth, postLength, postHeight]}
            >
              <meshPhongMaterial 
                color={config.rotaryPostColor}
                transparent={isTransparent}
                opacity={opacity}
                wireframe={isWireframe}
              />
            </Box>

            {/* Main Rotary Cylinder (at center - this is the reference point) */}
            <Cylinder
              position={[centerX, centerY, centerZ]}
              args={[headRadius, headRadius, headLength, 16]}
              rotation={isXAxis ? [0, 0, Math.PI / 2] : [0, 0, 0]}
            >
              <meshPhongMaterial 
                color={config.rotaryHeadColor}
                transparent={isTransparent}
                opacity={opacity}
                wireframe={isWireframe}
              />
            </Cylinder>

            {/* Support Post 2 (at tail end) */}
            <Box
              position={isXAxis 
                ? [centerX + post2Offset, centerY, centerZ - postHeight / 2]
                : [centerX, centerY + post2Offset, centerZ - postHeight / 2]
              }
              args={[postWidth, postLength, postHeight]}
            >
              <meshPhongMaterial 
                color={config.rotaryPostColor}
                transparent={isTransparent}
                opacity={opacity}
                wireframe={isWireframe}
              />
            </Box>

            {/* Tail (cylinder at rotaryLength distance from center) */}
            <Cylinder
              position={isXAxis 
                ? [centerX + tailOffset, centerY, centerZ]
                : [centerX, centerY + tailOffset, centerZ]
              }
              args={[tailRadius, tailRadius, tailLength, 16]}
              rotation={isXAxis ? [0, 0, Math.PI / 2] : [0, 0, 0]}
            >
              <meshPhongMaterial 
                color={config.rotaryTailColor}
                transparent={isTransparent}
                opacity={opacity}
                wireframe={isWireframe}
              />
            </Cylinder>

            {/* Rotary Bed (extends from post to post, including under posts) */}
            <Box
              position={isXAxis 
                ? [centerX + (post1Offset + post2Offset) / 2, centerY, centerZ - postHeight - bedHeight / 2]
                : [centerX, centerY + (post1Offset + post2Offset) / 2, centerZ - postHeight - bedHeight / 2]
              }
              args={isXAxis 
                ? [Math.abs(post2Offset - post1Offset) + postLength, bedWidth, bedHeight]
                : [bedWidth, Math.abs(post2Offset - post1Offset) + postLength, bedHeight]
              }
            >
              <meshPhongMaterial 
                color={config.rotaryBedColor}
                transparent={isTransparent}
                opacity={opacity}
                wireframe={isWireframe}
              />
            </Box>
          </group>
        );
      }}
    />
  );
}
