import React from "react";
import { Box, Typography, Link } from '@mui/material';
import { BaseWizardStep } from "../../../Wizard/BaseWizardStep";
import { Wizard } from "../../../Wizard/Wizard";
import { WizardStep } from "../../../Wizard/WizardStep";
import { ConfigurationData } from "../../../../data/ConfigurationData";
import { ZAxisReferenceType } from '../common/types';

export class InstructionsStep extends BaseWizardStep {
  constructor(wizard: Wizard, priorStep: WizardStep | null = null) {
    super(wizard, priorStep, "Next", "Back");
  }

  getTitle(): string {
    return "Manual Calibration Instructions";
  }

  nextStep(): WizardStep | null {
    // Dynamic import to avoid circular dependencies - go to positioning step
    const ManualPositionStep = require("./ManualPositionStep").ManualPositionStep;
    return new ManualPositionStep(this.wizard, this);
  }

  private getReferenceTitle(): string {
    switch (this.wizard.state.referenceType) {
      case ZAxisReferenceType.BED:
        return 'Machine Bed';
      case ZAxisReferenceType.SPOILBOARD:
        return 'Spoilboard';
      case ZAxisReferenceType.MATERIAL:
        return 'Material Surface';
      default:
        return 'Surface';
    }
  }

  render(): React.ReactNode {
    return this.renderWithButtons(
      <Box sx={{ display: 'flex', height: '100%' }}>
        <Box sx={{ flex: 1, pr: 3, display: 'flex', flexDirection: 'column', justifyContent: 'center' }}>
          <Typography variant="h6" sx={{ mb: 2 }}>
            Manual Touch-off Instructions
          </Typography>
          <Typography variant="body1" sx={{ mb: 3 }}>
            Lower the tool until it just touches the {this.getReferenceTitle().toLowerCase()}. Use a piece of paper to know when it touches - the paper should not be able to move.
          </Typography>
          
          <Box sx={{ mb: 3, p: 2, backgroundColor: ConfigurationData.Instance.lightBackgroundColor, borderRadius: 1 }}>
            <Typography variant="body2" sx={{ mb: 1 }}>
              📹 Need help? Watch our video tutorial:
            </Typography>
            <Link 
              href="https://www.youtube.com/watch?v=your-video-id" 
              target="_blank" 
              rel="noopener noreferrer"
              sx={{ 
                color: ConfigurationData.Instance.primaryColor,
                textDecoration: 'none',
                '&:hover': {
                  textDecoration: 'underline'
                }
              }}
            >
              How to Perform Manual Touch-off Calibration
            </Link>
          </Box>
          
          <Typography variant="body2" sx={{ mb: 2, color: 'warning.main' }}>
            ⚠ Take your time and be careful - small movements are key!
          </Typography>
        </Box>
        
        <Box sx={{ 
          width: '50%', 
          display: 'flex', 
          alignItems: 'center', 
          justifyContent: 'center', 
          backgroundColor: ConfigurationData.Instance.lightBackgroundColor, 
          borderRadius: 1 
        }}>
          <Typography variant="body2" color="text.secondary">
            [Instruction diagram: Tool touching surface with paper]
          </Typography>
        </Box>
      </Box>
    );
  }
}
