import React, { useRef, useEffect, useState, memo } from 'react';
import { Box } from '@mui/material';
import { CNCViewer, CNCViewerProps } from './CNCViewer';

export interface FullSizeCNCViewerProps extends Omit<CNCViewerProps, 'width' | 'height'> {
  /** Debounce delay in milliseconds to prevent size jitter (default: 500ms) */
  debounceDelay?: number;
  /** Minimum percentage change to trigger update (default: 10% = 0.1) */
  sizeChangeThreshold?: number;
}

// Memoized CNCViewer to prevent unnecessary re-renders
const MemoizedCNCViewer = memo(CNCViewer);

/**
 * A wrapper around CNCViewer that automatically calculates and provides stable
 * pixel dimensions based on its container size. Prevents re-render cascades
 * by debouncing size changes and using a threshold for minimum size changes.
 */
export function FullSizeCNCViewer({
  debounceDelay = 500,
  sizeChangeThreshold = 0.1, // 10% change required
  ...cncViewerProps
}: FullSizeCNCViewerProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const [dimensions, setDimensions] = useState({ width: 800, height: 600 });
  const resizeTimeoutRef = useRef<NodeJS.Timeout | null>(null);
  const lastDimensionsRef = useRef({ width: 800, height: 600 });
  const isInitializedRef = useRef(false);

  useEffect(() => {
    if (!containerRef.current) return;

    // Function to update dimensions with debouncing and threshold
    const updateDimensions = () => {
      if (!containerRef.current) return;

      const rect = containerRef.current.getBoundingClientRect();
      const newWidth = Math.max(200, Math.floor(rect.width)); // Minimum 200px
      const newHeight = Math.max(150, Math.floor(rect.height)); // Minimum 150px

      // Only update if the size change exceeds the percentage threshold or it's the first time
      const widthChangePercent = Math.abs(newWidth - lastDimensionsRef.current.width) / lastDimensionsRef.current.width;
      const heightChangePercent = Math.abs(newHeight - lastDimensionsRef.current.height) / lastDimensionsRef.current.height;

      if (!isInitializedRef.current || widthChangePercent >= sizeChangeThreshold || heightChangePercent >= sizeChangeThreshold) {
        const newDimensions = { width: newWidth, height: newHeight };
        lastDimensionsRef.current = newDimensions;
        setDimensions(newDimensions);
        isInitializedRef.current = true;
      }
    };

    // Debounced update function
    const debouncedUpdate = () => {
      if (resizeTimeoutRef.current) {
        clearTimeout(resizeTimeoutRef.current);
      }
      
      resizeTimeoutRef.current = setTimeout(updateDimensions, debounceDelay);
    };

    // Initial size calculation
    updateDimensions();

    // Set up ResizeObserver for responsive sizing
    const resizeObserver = new ResizeObserver(debouncedUpdate);
    resizeObserver.observe(containerRef.current);

    return () => {
      resizeObserver.disconnect();
      if (resizeTimeoutRef.current) {
        clearTimeout(resizeTimeoutRef.current);
      }
    };
  }, [debounceDelay, sizeChangeThreshold]); // Stable dependencies

  return (
    <Box
      ref={containerRef}
      sx={{
        width: '100%',
        height: '100%',
        minWidth: 200,
        minHeight: 150,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center'
      }}
    >
      <MemoizedCNCViewer
        {...cncViewerProps}
        width={dimensions.width}
        height={dimensions.height}
      />
    </Box>
  );
}
