/**
 * Material color definitions for common materials
 * Provides predefined colors for wood types, metals, and basic colors
 */

export interface MaterialColorDefinition {
  name: string;
  color: string;
  category: 'Wood' | 'Metal' | 'Basic';
  description?: string;
}

/**
 * Predefined material colors
 */
export class MaterialColors {
  private static _instance: MaterialColors;
  
  public readonly colors: MaterialColorDefinition[] = [
    // Wood colors
    {
      name: 'Pine',
      color: '#F5DEB3',
      category: 'Wood',
      description: 'Light yellowish wood'
    },
    {
      name: 'Maple',
      color: '#D2B48C',
      category: 'Wood',
      description: 'Light brown hardwood'
    },
    {
      name: 'Walnut',
      color: '#8B4513',
      category: 'Wood',
      description: 'Rich dark brown wood'
    },
    {
      name: 'Ebony',
      color: '#2F2F2F',
      category: 'Wood',
      description: 'Very dark hardwood'
    },
    
    // Metal colors
    {
      name: 'Steel',
      color: '#C0C0C0',
      category: 'Metal',
      description: 'Silvery gray metal'
    },
    {
      name: 'Aluminum',
      color: '#E6E6FA',
      category: 'Metal',
      description: 'Light silvery metal'
    },
    
    // Basic colors
    {
      name: 'Red',
      color: '#FF0000',
      category: 'Basic',
      description: 'Bright red'
    },
    {
      name: 'Blue',
      color: '#0000FF',
      category: 'Basic',
      description: 'Bright blue'
    },
    {
      name: 'Orange',
      color: '#FFA500',
      category: 'Basic',
      description: 'Bright orange'
    }
  ];
  
  private constructor() {
    // Private constructor for singleton
  }
  
  /**
   * Get the singleton instance
   */
  public static get Instance(): MaterialColors {
    if (!MaterialColors._instance) {
      MaterialColors._instance = new MaterialColors();
    }
    return MaterialColors._instance;
  }
  
  /**
   * Get colors by category
   */
  public getColorsByCategory(category: 'Wood' | 'Metal' | 'Basic'): MaterialColorDefinition[] {
    return this.colors.filter(color => color.category === category);
  }
  
  /**
   * Get all wood colors
   */
  public getWoodColors(): MaterialColorDefinition[] {
    return this.getColorsByCategory('Wood');
  }
  
  /**
   * Get all metal colors
   */
  public getMetalColors(): MaterialColorDefinition[] {
    return this.getColorsByCategory('Metal');
  }
  
  /**
   * Get all basic colors
   */
  public getBasicColors(): MaterialColorDefinition[] {
    return this.getColorsByCategory('Basic');
  }
  
  /**
   * Find a color by name
   */
  public getColorByName(name: string): MaterialColorDefinition | undefined {
    return this.colors.find(color => color.name.toLowerCase() === name.toLowerCase());
  }
  
  /**
   * Get color value by name
   */
  public getColorValue(name: string): string | undefined {
    const colorDef = this.getColorByName(name);
    return colorDef?.color;
  }
}
