import { StateManager } from '../utils/statemanager/StateManager';
import { IStorable } from '../common/IStorable';
import { DataUtilities } from '../utils/storage/DataUtilities';

/**
 * AppStateData manages the overall application state including initialization status
 * This singleton class tracks whether the app is loading, initialized, and ready for user interaction
 */
export class AppStateData implements IStorable {
  private static _instance: AppStateData;

  private _isLoading: boolean = true;
  private _isInitialized: boolean = false;
  private _initializationError: string | null = null;
  private _loadingMessage: string = 'Loading application...';

  private constructor() {
    // //console.log('AppStateData initialized');
  }

  /**
   * Get the singleton instance
   */
  public static get Instance(): AppStateData {
    if (!AppStateData._instance) {
      AppStateData._instance = new AppStateData();
    }
    return AppStateData._instance;
  }

  /**
   * Whether the application is currently loading data
   */
  public get isLoading(): boolean {
    return this._isLoading;
  }

  public set isLoading(value: boolean) {
    if (this._isLoading !== value) {
      this._isLoading = value;
      StateManager.propertyChanged(this, 'isLoading');
    }
  }

  /**
   * Whether the application has completed initialization
   */
  public get isInitialized(): boolean {
    return this._isInitialized;
  }

  public set isInitialized(value: boolean) {
    if (this._isInitialized !== value) {
      this._isInitialized = value;
      StateManager.propertyChanged(this, 'isInitialized');
    }
  }

  /**
   * Error message if initialization failed
   */
  public get initializationError(): string | null {
    return this._initializationError;
  }

  public set initializationError(value: string | null) {
    if (this._initializationError !== value) {
      this._initializationError = value;
      StateManager.propertyChanged(this, 'initializationError');
    }
  }

  /**
   * Current loading message to display to user
   */
  public get loadingMessage(): string {
    return this._loadingMessage;
  }

  public set loadingMessage(value: string) {
    if (this._loadingMessage !== value) {
      this._loadingMessage = value;
      StateManager.propertyChanged(this, 'loadingMessage');
    }
  }

  /**
   * Mark the application as fully initialized and ready for use
   * This triggers the UI to switch from splash screen to main interface
   */
  public markAsInitialized(): void {
    this.loadingMessage = 'Initialization complete';
    this.isLoading = false;
    this.isInitialized = true;
    this.initializationError = null;
    // //console.log('Application marked as initialized - UI should now show main interface');
  }

  /**
   * Mark initialization as failed with an error message
   */
  public markInitializationFailed(error: string): void {
    this.loadingMessage = 'Initialization failed';
    this.isLoading = false;
    this.isInitialized = false;
    this.initializationError = error;
    console.error('Application initialization failed:', error);
  }

  /**
   * Update the loading message (useful for showing progress)
   */
  public updateLoadingMessage(message: string): void {
    this.loadingMessage = message;
  }

  /**
   * Reset the app state (useful for testing or reinitializing)
   */
  public reset(): void {
    this.isLoading = true;
    this.isInitialized = false;
    this.initializationError = null;
    this.loadingMessage = 'Loading application...';
  }

  /**
   * Serialize to JSON using generic DataUtilities approach
   */
  public toJSON(): any {
    return DataUtilities.getStorageData(this);
  }

  /**
   * Load from JSON using generic DataUtilities approach
   */
  public fromJSON(data: any): void {
    DataUtilities.loadStorageData(this, data);
  }
}
