import { SwapHoriz as DirectionIcon } from '@mui/icons-material';
import { Box, FormControl, Grid, InputLabel, MenuItem, Select, TextField, Typography } from '@mui/material';
import React, { useState } from 'react';
import { IOEvent } from '../../../../machine/IOEvent';
import { Machine } from '../../../../machine/Machine';
import { MoveDirection } from '../../../../machine/MoveDirection';
import { DataUtilities } from '../../../../utils/storage/DataUtilities';
import { FlowStep } from "../../../FlowStep";
import { FlowStepData } from "../../../FlowStepData";

export class MoveDirectionUntilStep extends FlowStep {
    readonly __type = 'MoveDirectionUntilStep';
    readonly category = ['Machine', 'Movement'];
    readonly name = 'Move Direction Until';
    readonly description = 'Moves in specified direction until condition is met';
    
    // Icon is created dynamically, not stored
    get icon(): React.ReactNode {
        return React.createElement(DirectionIcon, { sx: { color: 'warning.main' } });
    }

    // Step parameters
    public direction: MoveDirection = MoveDirection.XPositive;
    public event: IOEvent = IOEvent.ToolTouchPad;
    public maxDistance?: number;
    public speed?: number;

    static readonly DONE_PATH = 'done';

    async execute(data: FlowStepData, prototypeRun: boolean): Promise<string | null> {
        if (prototypeRun) {
            return MoveDirectionUntilStep.DONE_PATH;
        }

        try {
            await Machine.getInstance().movement.MoveDirectionUntil(this.direction, this.event, this.maxDistance, this.speed);
            return MoveDirectionUntilStep.DONE_PATH;
        } catch (error) {
            console.error('MoveDirectionUntil failed:', error);
            return MoveDirectionUntilStep.DONE_PATH; // Still done, just with error logged
        }
    }

    results(): string[] {
        return [MoveDirectionUntilStep.DONE_PATH];
    }

    renderResultsUI(data: FlowStepData, result: string): React.ReactNode {
        return (
            <Typography variant="caption">
                Move {this.direction} until {this.event}: {result}
            </Typography>
        );
    }

    renderEditUI(props: { onClose: () => void }): React.ReactNode {
        const EditUI: React.FC = () => {
            const [direction, setDirection] = useState(this.direction);
            const [event, setEvent] = useState(this.event);
            const [maxDistance, setMaxDistance] = useState(this.maxDistance?.toString() || '');
            const [speed, setSpeed] = useState(this.speed?.toString() || '');

            // Update the instance when the local state changes
            React.useEffect(() => {
                this.direction = direction;
                this.event = event;
                this.maxDistance = maxDistance ? parseFloat(maxDistance) : undefined;
                this.speed = speed ? parseFloat(speed) : undefined;
            }, [direction, event, maxDistance, speed]);

            return (
                <Box sx={{ p: 2, minWidth: 400 }}>
                    <Typography variant="h6" gutterBottom>Move Direction Until Configuration</Typography>

                    <Grid container spacing={2} sx={{ mt: 1 }}>
                        <Grid item xs={6}>
                            <FormControl fullWidth size="small">
                                <InputLabel>Direction</InputLabel>
                                <Select
                                    value={direction}
                                    label="Direction"
                                    onChange={(e) => setDirection(e.target.value as MoveDirection)}
                                >
                                    <MenuItem value={MoveDirection.XPositive}>X Positive</MenuItem>
                                    <MenuItem value={MoveDirection.XNegative}>X Negative</MenuItem>
                                    <MenuItem value={MoveDirection.YPositive}>Y Positive</MenuItem>
                                    <MenuItem value={MoveDirection.YNegative}>Y Negative</MenuItem>
                                    <MenuItem value={MoveDirection.ZPositive}>Z Positive</MenuItem>
                                    <MenuItem value={MoveDirection.ZNegative}>Z Negative</MenuItem>
                                </Select>
                            </FormControl>
                        </Grid>
                        <Grid item xs={6}>
                            <FormControl fullWidth size="small">
                                <InputLabel>Event</InputLabel>
                                <Select
                                    value={event}
                                    label="Event"
                                    onChange={(e) => setEvent(e.target.value as IOEvent)}
                                >
                                    <MenuItem value={IOEvent.XLimit}>X Limit</MenuItem>
                                    <MenuItem value={IOEvent.YLimit}>Y Limit</MenuItem>
                                    <MenuItem value={IOEvent.ZLimit}>Z Limit</MenuItem>
                                    <MenuItem value={IOEvent.ToolTouchPad}>Tool Touch Pad</MenuItem>
                                    <MenuItem value={IOEvent.MaterialTouchPad}>Material Touch Pad</MenuItem>
                                </Select>
                            </FormControl>
                        </Grid>
                        <Grid item xs={6}>
                            <TextField
                                label="Max Distance (optional)"
                                type="number"
                                value={maxDistance}
                                onChange={(e) => setMaxDistance(e.target.value)}
                                fullWidth
                                size="small"
                                placeholder="No limit"
                            />
                        </Grid>
                        <Grid item xs={6}>
                            <TextField
                                label="Speed (optional)"
                                type="number"
                                value={speed}
                                onChange={(e) => setSpeed(e.target.value)}
                                fullWidth
                                size="small"
                                placeholder="Default speed"
                            />
                        </Grid>
                    </Grid>
                </Box>
            );
        };

        return React.createElement(EditUI);
    }

    public toJSON(): any {
        const data = DataUtilities.getStorageData(this, ['icon']) as any;
        data.__type = this.__type;
        return data;
    }

    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data);
    }
}





