import React from 'react';
import {
  Box,
  TextField,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  FormControlLabel,
  Switch,
  Grid,
  Typography,
  Divider
} from '@mui/material';
import { MachineOutput } from '../../data/Machine/MachineOutput';
import { CentroidOutputName } from '../../data/Machine/CentroidOutputName';
import { NullableNumberInput } from './NullableNumberInput';
import { ObserveState } from '../../utils/statemanager/ObserveState';

export interface MachineOutputEditorProps {
  /** The output to edit - changes are made directly to this object */
  output: MachineOutput;
  /** Title to display. If undefined, uses default title. If null, hides title */
  title?: string | null;
}

/**
 * Simplified MachineOutput editor that works directly with the output object.
 * Changes are automatically propagated via StateManager.
 */
export function MachineOutputEditor({
  output,
  title
}: MachineOutputEditorProps) {
  
  // Get display title
  const displayTitle = title === null ? null : (title || `Edit Output: ${output.name}`);
  
  // Get enum values for dropdown
  const centroidMappingOptions = Object.values(CentroidOutputName)
    .filter(value => typeof value === 'string');

  return (
    <ObserveState
      listenTo={output}
      properties={['number', 'name', 'activeText', 'inactiveText', 'centroidMapping', 'use']}
      control={() => (
        <Box sx={{ p: 3, maxHeight: 'fit-content', display: 'flex', flexDirection: 'column' }}>
          {displayTitle && (
            <>
              <Typography variant="h6" gutterBottom>
                {displayTitle}
              </Typography>
              <Divider sx={{ mb: 3 }} />
            </>
          )}

          <Grid container spacing={3}>
            {/* Output Number - Smaller */}
            <Grid item xs={12} md={3}>
              <NullableNumberInput
                label="Output Number"
                value={output.number}
                onChange={(value) => {
                  output.number = value || 0;
                }}
                fullWidth
                allowNegative={false}
                min={1}
                max={999}
              />
            </Grid>

            {/* Output Name - Bigger */}
            <Grid item xs={12} md={9}>
              <TextField
                label="Name"
                value={output.name}
                onChange={(e) => {
                  output.name = e.target.value;
                }}
                fullWidth
                required
              />
            </Grid>

            {/* Active Text - Full width row */}
            <Grid item xs={12}>
              <TextField
                label="Active Text"
                value={output.activeText}
                onChange={(e) => {
                  output.activeText = e.target.value;
                }}
                fullWidth
                required
                helperText="Text displayed when output is active/on"
              />
            </Grid>

            {/* Inactive Text - Full width row */}
            <Grid item xs={12}>
              <TextField
                label="Inactive Text"
                value={output.inactiveText}
                onChange={(e) => {
                  output.inactiveText = e.target.value;
                }}
                fullWidth
                required
                helperText="Text displayed when output is inactive/off"
              />
            </Grid>

            {/* Centroid Mapping */}
            <Grid item xs={12}>
              <FormControl fullWidth>
                <InputLabel>Centroid Mapping</InputLabel>
                <Select
                  value={output.centroidMapping || ''}
                  onChange={(e) => {
                    const value = e.target.value;
                    output.centroidMapping = value ? (value as CentroidOutputName) : undefined;
                  }}
                  label="Centroid Mapping"
                >
                  <MenuItem value="">
                    <em>None</em>
                  </MenuItem>
                  {centroidMappingOptions.map((mapping) => (
                    <MenuItem key={mapping} value={mapping}>
                      {mapping}
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
            </Grid>

            {/* Switches */}
            <Grid item xs={12}>
              <Box sx={{ display: 'flex', gap: 3, flexWrap: 'wrap' }}>
                <FormControlLabel
                  control={
                    <Switch
                      checked={output.use}
                      onChange={(e) => {
                        output.use = e.target.checked;
                      }}
                    />
                  }
                  label="In Use"
                />
              </Box>
            </Grid>
          </Grid>
        </Box>
      )}
    />
  );
}
