import { IStorable } from '../common/IStorable';
import { CNCPoint } from '../data/CNCPoint';
import { CoordinateType } from '../data/Common/CoordinateType';
import { Fixture, FixtureLibrary } from '../data/Common/FixtureLibrary';
import { CoordinateUtil } from '../utils/CoordinateUtil';
import { StateManager } from '../utils/statemanager/StateManager';
import { DataUtilities } from '../utils/storage/DataUtilities';
import { FlowStepData } from './FlowStepData';

export enum ReferencePointType {
    WorkHome = 'work-home',
    MachineZero = 'machine-zero',
    MachineHome = 'machine-home',
    FromData = 'from-data',
    FromKnownPoint = 'from-known-point'
}

export enum ZHandlingMode {
    Value = 'value',
    ZMax = 'zmax'
}

/**
 * Reusable class for calculating CNC positions with offsets and reference points.
 * Used in Move To Position, Set Current Fixture Point, Move To Until Event, etc.
 */
export class FlowPositionValue implements IStorable {
    public referenceType: ReferencePointType = ReferencePointType.WorkHome;
    public selectedFixture: string = '';
    public selectedDataPath: string = '';
    public offsetEnabled: boolean = false;
    public xOffset: number = 0;
    public yOffset: number = 0;
    public zOffset: number = 0;
    public zHandlingMode: ZHandlingMode = ZHandlingMode.Value;

    public setReferenceType(value: ReferencePointType): void {
        this.referenceType = value;
        StateManager.propertyChanged(this, 'referenceType');
    }

    public setSelectedFixture(value: string): void {
        this.selectedFixture = value;
        StateManager.propertyChanged(this, 'selectedFixture');
    }

    public setSelectedDataPath(value: string): void {
        this.selectedDataPath = value;
        StateManager.propertyChanged(this, 'selectedDataPath');
    }

    public setOffsetEnabled(value: boolean): void {
        this.offsetEnabled = value;
        StateManager.propertyChanged(this, 'offsetEnabled');
    }

    public setXOffset(value: number): void {
        this.xOffset = value;
        StateManager.propertyChanged(this, 'xOffset');
    }

    public setYOffset(value: number): void {
        this.yOffset = value;
        StateManager.propertyChanged(this, 'yOffset');
    }

    public setZOffset(value: number): void {
        this.zOffset = value;
        StateManager.propertyChanged(this, 'zOffset');
    }

    public setZHandlingMode(value: ZHandlingMode): void {
        this.zHandlingMode = value;
        StateManager.propertyChanged(this, 'zHandlingMode');
    }

    /**
     * Calculate point for UI display (without flow data)
     */
    public calculatePoint(): CNCPoint {
        let basePoint: CNCPoint;

        // Get available fixtures
        const availableFixtures = FixtureLibrary.Instance.fixtures
            .filter((fixture: Fixture) => fixture.showAsSelectable && !fixture.systemControlled);

        switch (this.referenceType) {
            case ReferencePointType.WorkHome:
                basePoint = new CNCPoint(0, 0, 0, CoordinateType.WorkZero);
                break;
            case ReferencePointType.MachineZero:
                basePoint = new CNCPoint(0, 0, 0, CoordinateType.MachineZero);
                break;
            case ReferencePointType.MachineHome:
                basePoint = new CNCPoint(0, 0, 0, CoordinateType.MachineHome);
                break;
            case ReferencePointType.FromData:
                // For UI display, show placeholder - actual calculation happens in execution
                basePoint = new CNCPoint(0, 0, 0, CoordinateType.WorkZero);
                break;
            case ReferencePointType.FromKnownPoint:
                const fixture = availableFixtures.find(f => f.fixtureNumber === this.selectedFixture);
                if (fixture) {
                    basePoint = new CNCPoint(fixture.xOffset, fixture.yOffset, fixture.zOffset, CoordinateType.MachineZero);
                } else {
                    basePoint = new CNCPoint(0, 0, 0, CoordinateType.WorkZero);
                }
                break;
            default:
                basePoint = new CNCPoint(0, 0, 0, CoordinateType.WorkZero);
        }

        // Apply offsets if enabled
        if (this.offsetEnabled) {
            let finalZOffset = this.zOffset;

            // If using Z Max mode, use machine's maximum Z position for the target coordinate type
            if (this.zHandlingMode === ZHandlingMode.ZMax) {
                finalZOffset = CoordinateUtil.getZMax(basePoint.coordinateType);
            }

            return new CNCPoint(
                basePoint.x + this.xOffset,
                basePoint.y + this.yOffset,
                this.zHandlingMode === ZHandlingMode.ZMax ? finalZOffset : basePoint.z + finalZOffset,
                basePoint.coordinateType
            );
        }

        return basePoint;
    }

    /**
     * Calculate actual point for execution with flow data
     */
    public calculateExecutionPoint(flowData?: FlowStepData): CNCPoint {
        let basePoint: CNCPoint;

        // Get available fixtures
        const availableFixtures = FixtureLibrary.Instance.fixtures
            .filter((fixture: Fixture) => fixture.showAsSelectable && !fixture.systemControlled);

        switch (this.referenceType) {
            case ReferencePointType.WorkHome:
                basePoint = new CNCPoint(0, 0, 0, CoordinateType.WorkZero);
                break;
            case ReferencePointType.MachineZero:
                basePoint = new CNCPoint(0, 0, 0, CoordinateType.MachineZero);
                break;
            case ReferencePointType.MachineHome:
                basePoint = new CNCPoint(0, 0, 0, CoordinateType.MachineHome);
                break;
            case ReferencePointType.FromData:
                basePoint = this.getDataPointByPath(this.selectedDataPath, flowData);
                break;
            case ReferencePointType.FromKnownPoint:
                const fixture = availableFixtures.find(f => f.fixtureNumber === this.selectedFixture);
                if (fixture) {
                    basePoint = new CNCPoint(fixture.xOffset, fixture.yOffset, fixture.zOffset, CoordinateType.MachineZero);
                } else {
                    basePoint = new CNCPoint(0, 0, 0, CoordinateType.WorkZero);
                }
                break;
            default:
                basePoint = new CNCPoint(0, 0, 0, CoordinateType.WorkZero);
        }

        // Apply offsets if enabled
        if (this.offsetEnabled) {
            let finalZOffset = this.zOffset;

            // If using Z Max mode, use machine's maximum Z position for the target coordinate type
            if (this.zHandlingMode === ZHandlingMode.ZMax) {
                finalZOffset = CoordinateUtil.getZMax(basePoint.coordinateType);
            }

            return new CNCPoint(
                basePoint.x + this.xOffset,
                basePoint.y + this.yOffset,
                this.zHandlingMode === ZHandlingMode.ZMax ? finalZOffset : basePoint.z + finalZOffset,
                basePoint.coordinateType
            );
        }

        return basePoint;
    }

    /**
     * Get a CNCPoint from flow data by path
     */
    private getDataPointByPath(path: string, flowData?: FlowStepData): CNCPoint {
        if (!flowData || !path) {
            return new CNCPoint(0, 0, 0, CoordinateType.WorkZero);
        }

        try {
            // Handle elements array access like "elements[0]"
            if (path.startsWith('elements[')) {
                const indexMatch = path.match(/elements\[(\d+)\]/);
                if (indexMatch) {
                    const index = parseInt(indexMatch[1]);
                    const element = flowData.elements[index];
                    if (element instanceof CNCPoint) {
                        return element;
                    }
                }
            }

            // Handle variables access like "variables.current.point"
            if (path.startsWith('variables.')) {
                const variables = (flowData as any).variables;
                if (variables && variables instanceof Map) {
                    const pathParts = path.split('.');
                    pathParts.shift(); // Remove 'variables'

                    if (pathParts.length > 0) {
                        let current = variables.get(pathParts[0]);

                        // Navigate through nested object properties
                        for (let i = 1; i < pathParts.length && current; i++) {
                            current = current[pathParts[i]];
                        }

                        if (current instanceof CNCPoint) {
                            return current;
                        }
                    }
                }
            }
        } catch (error) {
            console.warn('Error retrieving data point from path:', path, error);
        }

        // Return default point if path not found or not a CNCPoint
        return new CNCPoint(0, 0, 0, CoordinateType.WorkZero);
    }

    /**
     * Get allowed types for data selector (only CNCPoint)
     */
    public getAllowedTypes(): string[] {
        return ['CNCPoint'];
    }

    public toJSON(): any {
        return DataUtilities.getStorageData(this);
    }

    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data);
    }
}
