import { AxisType, MachineData } from '../data/MachineData';
import { MachineStateData } from '../data/MachineStateData';
import type { AxisConfiguration } from '../machine/Machine';
import { CoordinateUtil } from './CoordinateUtil';

/**
 * Utility class for mapping between MachineData internal representations
 * and machine API configuration formats
 */
export class MachineConfigurationMapper {
  /**
   * Convert soft limits from MachineZero coordinates to MachineHome travel limits
   * Returns plus and minus travel limits for a specific axis
   * 
   * @param axisType The type of axis (X, Y, Z, A, etc.)
   * @returns Object containing plusLimit and minusLimit, or null values if not applicable
   */
  public static getSoftLimitsForAxis(
    axisType: AxisType
  ): { plusLimit: number | null; minusLimit: number | null } {
    // Use existing CoordinateUtil method to get soft limits box
    const softLimitsBox = CoordinateUtil.getSoftLimitsBox(MachineStateData.Instance);
    
    // The box already has all 8 corner points computed
    // Convert the relevant corners to MachineHome coordinates
    const originMH = CoordinateUtil.toMachineHome(softLimitsBox.origin);
    const farCornerMH = CoordinateUtil.toMachineHome(softLimitsBox.boxPoints.rearRightUpper);

    // Extract travel limits for the specific axis
    // In MachineHome coordinates, home is at 0,0,0 and travel is typically negative
    switch (axisType) {
      case AxisType.X:
      case AxisType.XSlave:
        return {
          plusLimit: Math.max(originMH.x, farCornerMH.x),  // Positive travel from home
          minusLimit: Math.min(originMH.x, farCornerMH.x)  // Negative travel from home
        };

      case AxisType.Y:
      case AxisType.YSlave:
        return {
          plusLimit: Math.max(originMH.y, farCornerMH.y),
          minusLimit: Math.min(originMH.y, farCornerMH.y)
        };

      case AxisType.Z:
        return {
          plusLimit: Math.max(originMH.z, farCornerMH.z),
          minusLimit: Math.min(originMH.z, farCornerMH.z)
        };

      case AxisType.A:
        // Rotary axis - no soft limits by default
        return { plusLimit: null, minusLimit: null };

      case AxisType.Unset:
      default:
        return { plusLimit: null, minusLimit: null };
    }
  }

  /**
   * Map AxisType enum to API axis label string
   * 
   * @param axisType The internal AxisType enum value
   * @returns API-compatible axis label (X, Y, Z, A) or null for unset
   */
  public static mapAxisTypeToLabel(axisType: AxisType): string | null {
    switch (axisType) {
      case AxisType.X:
        return 'X';
      case AxisType.Y:
        return 'Y';
      case AxisType.Z:
        return 'Z';
      case AxisType.A:
        return 'A';
      case AxisType.XSlave:
        return 'X';
      case AxisType.YSlave:
        return 'Y';
      case AxisType.Unset:
      default:
        return null;
    }
  }

  /**
   * Check if an axis type represents a rotary axis
   * 
   * @param axisType The axis type to check
   * @returns True if the axis is rotary (A-axis)
   */
  public static isRotaryAxis(axisType: AxisType): boolean {
    return axisType === AxisType.A;
  }

  /**
   * Convert MachineData AxisConfig to API AxisConfiguration format
   * 
   * @param axis The internal AxisConfig object
   * @param axisNumber The 1-based axis number (1-6)
   * @param machineData Optional MachineData instance (defaults to singleton)
   * @returns AxisConfiguration object ready for API submission
   */
  public static convertAxisToAPIFormat(
    axis: any,
    axisNumber: number,
    machineData: MachineData = MachineData.Instance
  ): AxisConfiguration {
    // Map axis type to label
    const label = MachineConfigurationMapper.mapAxisTypeToLabel(axis.axisType);

    // Get travel limits for this axis
    const travelLimits = MachineConfigurationMapper.getSoftLimitsForAxis(
      axis.axisType
    );

    // Map all axis configuration properties
    return {
      axisNumber: axisNumber,
      label: label,
      stepsPerRevolution: axis.stepsPerRevolution,
      turnRatio: axis.overallTurnsRatio,
      backlashCompensation: axis.lashCompensation,
      maxRate: axis.maxRate,
      accelerationTime: axis.accelDecel,
      isReversed: axis.directionReversal,
      slowJogRate: axis.slowJogRate,
      fastJogRate: axis.fastJogRate,
      fastJogPlusDirection: axis.fastJogPlusDirection,
      fastJogMinusDirection: axis.fastJogMinusDirection,
      homingFeedrate: axis.homingFeedrate,
      stepSignalInverted: axis.stepSignalInverted,
      directionSignalInverted: axis.directionSignalInverted,
      enableSignalInverted: axis.enableSignalInverted,
      // Travel limits from soft limits converted to MachineHome coordinates
      plusTravelLimit: travelLimits.plusLimit,
      minusTravelLimit: travelLimits.minusLimit,
      // Axis type flags
      isRotary: MachineConfigurationMapper.isRotaryAxis(axis.axisType),
      // Optional fields - not currently used
      rotaryWrapAround: undefined,
      cAxisEnabled: undefined,
      preventDivideBy360: undefined,
      hideFromDRO: undefined,
      parallelToX: undefined,
      parallelToY: undefined,
    };
  }

  /**
   * Convert all configured axes from MachineData to API format
   * Skips axes with AxisType.Unset
   * 
   * @param machineData Optional MachineData instance (defaults to singleton)
   * @returns Array of AxisConfiguration objects
   */
  public static convertAllAxesToAPIFormat(
    machineData: MachineData = MachineData.Instance
  ): AxisConfiguration[] {
    const apiConfigs: AxisConfiguration[] = [];

    for (let i = 0; i < machineData.axisConfigurations.length; i++) {
      const axis = machineData.axisConfigurations[i];

      // Skip unset axes
      if (axis.axisType === AxisType.Unset) {
        continue;
      }

      // Convert to API format (axis numbers are 1-based)
      const apiConfig = MachineConfigurationMapper.convertAxisToAPIFormat(
        axis,
        i + 1,
        machineData
      );

      apiConfigs.push(apiConfig);
    }

    return apiConfigs;
  }
}
