import { Grid } from '@mui/material';
import { ApiMethodRegistry } from '../ApiMethodRegistry';

interface ProgramApiTestsProps {
  renderButton: (methodId: string) => React.ReactNode;
}

export function ProgramApiTests({ renderButton }: ProgramApiTestsProps) {
  const registry = ApiMethodRegistry.getInstance();
  const programMethods = registry.getMethodsByCategory('program');

  return (
    <Grid container spacing={2}>
      {programMethods.map((method) => (
        <Grid item xs={12} sm={6} md={4} key={method.id}>
          {renderButton(method.id)}
        </Grid>
      ))}
    </Grid>
  );
}