  /**
   * Get the singleton instance
   */
  public static get Instance(): MachineData {
    if (!MachineData._instance) {
      MachineData._instance = new MachineData();
      // Setup auto-save after instance is fully created
      MachineData._instance.setupAutoSave();
      // Load dynamic Centroid mappings asynchronously
      MachineData._instance.updateDynamicCentroidMappings();
    }
    return MachineData._instance;
  }

  /**
   * Update Centroid input/output mappings dynamically from functions.xml
   * This loads Router-specific mappings to complement the 'All' machine type mappings
   */
  private async updateDynamicCentroidMappings(): Promise<void> {
    try {
      // Load both 'All' and 'Router' machine types to get comprehensive mappings
      const [allInputs, routerInputs, allOutputs, routerOutputs] = await Promise.all([
        getCentroidInputNames('All'),
        getCentroidInputNames('Router'),
        getCentroidOutputNames('All'),
        getCentroidOutputNames('Router')
      ]);

      // Combine All and Router inputs/outputs, with Router taking precedence for duplicates
      const combinedInputs = new Set([...allInputs, ...routerInputs]);
      const combinedOutputs = new Set([...allOutputs, ...routerOutputs]);

      // Update machine input mappings where the name exists in dynamic list
      this._machineInputs.forEach(input => {
        if (input.centroidMapping && combinedInputs.has(input.centroidMapping)) {
          // Mapping is valid - keep it as is
          return;
        }

        // Try to find a dynamic mapping based on input description or name
        const inputNameLower = input.name.toLowerCase().replace(/[^a-z0-9]/g, '');
        const possibleMatches = Array.from(combinedInputs).filter(dynamicName =>
          dynamicName.toLowerCase().replace(/[^a-z0-9]/g, '').includes(inputNameLower) ||
          inputNameLower.includes(dynamicName.toLowerCase().replace(/[^a-z0-9]/g, ''))
        );

        if (possibleMatches.length > 0) {
          input.centroidMapping = possibleMatches[0];
        }
      });

      // Update machine output mappings where the name exists in dynamic list
      this._machineOutputs.forEach(output => {
        if (output.centroidMapping && combinedOutputs.has(output.centroidMapping)) {
          // Mapping is valid - keep it as is
          return;
        }

        // Try to find a dynamic mapping based on output description or name
        const outputNameLower = output.name.toLowerCase().replace(/[^a-z0-9]/g, '');
        const possibleMatches = Array.from(combinedOutputs).filter(dynamicName =>
          dynamicName.toLowerCase().replace(/[^a-z0-9]/g, '').includes(outputNameLower) ||
          outputNameLower.includes(dynamicName.toLowerCase().replace(/[^a-z0-9]/g, ''))
        );

        if (possibleMatches.length > 0) {
          output.centroidMapping = possibleMatches[0];
        }
      });

      // Successfully updated dynamic mappings (removed console.log to reduce test noise)

    } catch (error) {
      console.error('Failed to update dynamic Centroid mappings:', error);
      // Fall back to static enum values - no action needed as they're already set
    }
  }

