  public isInputNumberInUse(inputNumber: number): boolean {
    return this._machineInputs.some(input => input.number === inputNumber);
  }

  /**
   * Get the next available input number
   */
  public getNextAvailableInputNumber(): number {
    if (this._machineInputs.length === 0) return 1;

    const usedNumbers = this._machineInputs
      .map(input => input.number)
      .filter((num): num is number => num !== null && num !== undefined)
      .sort((a, b) => a - b);

    // Find the first gap in the sequence
    for (let i = 1; i <= usedNumbers.length + 1; i++) {
      if (!usedNumbers.includes(i)) {
        return i;
      }
    }

    // Fallback (should never reach here)
    const lastNumber = usedNumbers[usedNumbers.length - 1];
    return lastNumber ? lastNumber + 1 : 1;
  }

