import React from 'react';
import { CNCPoint } from '../data/CNCPoint';
import { CollisionResult, CollisionCheckInputs } from '../utils/CollisionDetection';
import { CollisionAction } from '../utils/CollisionDetection';
import { ConfigurationData } from '../data/ConfigurationData';

interface CollisionWarningModalProps {
  collisionResult: CollisionResult;
  options: Array<{
    action: CollisionAction;
    label: string;
    description: string;
    point?: CNCPoint;
  }>;
  onUserChoice: (action: CollisionAction, safePosition?: CNCPoint) => void;
  targetPosition: CNCPoint;
  fromPosition?: CNCPoint;
  collisionInputs?: CollisionCheckInputs;
}

export function CollisionWarningModal({ 
  collisionResult, 
  options, 
  onUserChoice, 
  targetPosition,
  fromPosition,
  collisionInputs
}: CollisionWarningModalProps) {
  const handleCopyDebugInfo = async () => {
    try {
      if (collisionInputs && fromPosition) {
        const { CollisionDetection } = await import('../utils/CollisionDetection');
        const debugInfo = CollisionDetection.generateDebugInfo(fromPosition, targetPosition, collisionInputs, collisionResult);
        await navigator.clipboard.writeText(debugInfo);
        alert('Debug info copied to clipboard!');
      } else {
        alert('Debug info not available - collision inputs or from position missing');
      }
    } catch (error) {
      console.error('Failed to copy debug info:', error);
      alert('Failed to copy debug info');
    }
  };

  const formatCoordinate = (point: CNCPoint) => {
    return `X: ${point.x.toFixed(3)}" Y: ${point.y.toFixed(3)}" Z: ${point.z.toFixed(3)}"`;
  };

  const getCollisionIcon = () => {
    switch (collisionResult.collisionType) {
      case 'SoftLimits':
        return '⚠️';
      case 'Material':
        return '📦';
      case 'Clamps':
        return '🔧';
      case 'Spoilboard':
        return '📋';
      case 'MachineBed':
        return '🏗️';
      default:
        return '❌';
    }
  };

  const getCollisionColor = () => {
    const config = ConfigurationData.Instance;
    switch (collisionResult.collisionType) {
      case 'SoftLimits':
        return config.limitsWarningColor; // Orange for limits
      case 'Material':
        return config.defaultMaterialColor; // Brown for material
      case 'Clamps':
        return config.defaultClampColor; // Blue for clamps
      default:
        return config.collisionErrorColor; // Red for other collisions
    }
  };

  return (
    <div style={{
      position: 'fixed',
      top: 0,
      left: 0,
      right: 0,
      bottom: 0,
      backgroundColor: ConfigurationData.Instance.modalBackdrop,
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      zIndex: 2000,
      fontFamily: 'Arial, sans-serif'
    }}>
      <div style={{
        backgroundColor: ConfigurationData.Instance.lightTextColor,
        borderRadius: '12px',
        padding: '24px',
        maxWidth: '500px',
        width: '90%',
        boxShadow: `0 8px 32px ${ConfigurationData.Instance.shadowColor}`,
        border: `3px solid ${getCollisionColor()}`
      }}>
        {/* Header */}
        <div style={{
          display: 'flex',
          alignItems: 'center',
          marginBottom: '16px',
          paddingBottom: '16px',
          borderBottom: `2px solid ${ConfigurationData.Instance.borderColor}`
        }}>
          <span style={{ fontSize: '32px', marginRight: '12px' }}>
            {getCollisionIcon()}
          </span>
          <div>
            <h2 style={{
              margin: 0,
              color: getCollisionColor(),
              fontSize: '20px',
              fontWeight: 'bold'
            }}>
              Collision Warning
            </h2>
            <p style={{
              margin: '4px 0 0 0',
              color: ConfigurationData.Instance.mutedTextColor,
              fontSize: '14px'
            }}>
              Move cannot be completed safely
            </p>
          </div>
        </div>

        {/* Collision Details */}
        <div style={{
          backgroundColor: ConfigurationData.Instance.lightBackgroundColor,
          padding: '16px',
          borderRadius: '8px',
          marginBottom: '20px',
          border: `1px solid ${getCollisionColor()}33`
        }}>
          <h3 style={{
            margin: '0 0 8px 0',
            fontSize: '16px',
            color: ConfigurationData.Instance.darkTextColor
          }}>
            Collision Details
          </h3>
          <p style={{
            margin: '0 0 8px 0',
            fontSize: '14px',
            color: ConfigurationData.Instance.mutedTextColor
          }}>
            <strong>Type:</strong> {collisionResult.collisionType}
          </p>
          <p style={{
            margin: '0 0 8px 0',
            fontSize: '14px',
            color: ConfigurationData.Instance.mutedTextColor
          }}>
            <strong>Target:</strong> {collisionResult.collisionTarget}
          </p>
          <p style={{
            margin: '0 0 8px 0',
            fontSize: '14px',
            color: ConfigurationData.Instance.mutedTextColor
          }}>
            <strong>Intended Position:</strong> {formatCoordinate(targetPosition)}
          </p>
          {collisionResult.intersectionPoint && (
            <p style={{
              margin: '0',
              fontSize: '14px',
              color: ConfigurationData.Instance.mutedTextColor
            }}>
              <strong>Collision Point:</strong> {formatCoordinate(collisionResult.intersectionPoint)}
            </p>
          )}
        </div>

        {/* Action Options */}
        <div style={{ marginBottom: '20px' }}>
          <h3 style={{
            margin: '0 0 12px 0',
            fontSize: '16px',
            color: ConfigurationData.Instance.darkTextColor
          }}>
            Choose an action:
          </h3>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
            {options.map((option, index) => {
              const getButtonColor = () => {
                switch (option.action) {
                  case CollisionAction.Cancel:
                    return ConfigurationData.Instance.mutedTextColor; // Gray
                  case CollisionAction.Proceed:
                    return ConfigurationData.Instance.errorColor; // Red
                  case CollisionAction.MoveSafe:
                    return ConfigurationData.Instance.successColor; // Green
                  default:
                    return ConfigurationData.Instance.primaryColor; // Blue
                }
              };

              return (
                <button
                  key={index}
                  onClick={() => onUserChoice(option.action, option.point)}
                  style={{
                    backgroundColor: getButtonColor(),
                    color: 'white',
                    border: 'none',
                    padding: '12px 16px',
                    borderRadius: '6px',
                    fontSize: '14px',
                    cursor: 'pointer',
                    textAlign: 'left',
                    transition: 'all 0.2s ease',
                    display: 'flex',
                    flexDirection: 'column',
                    gap: '4px'
                  }}
                  onMouseEnter={(e) => {
                    e.currentTarget.style.transform = 'translateY(-1px)';
                    e.currentTarget.style.boxShadow = `0 4px 12px ${ConfigurationData.Instance.shadowColor}`;
                  }}
                  onMouseLeave={(e) => {
                    e.currentTarget.style.transform = 'translateY(0)';
                    e.currentTarget.style.boxShadow = 'none';
                  }}
                >
                  <span style={{ fontWeight: 'bold' }}>
                    {option.label}
                  </span>
                  <span style={{ 
                    fontSize: '12px', 
                    opacity: 0.9,
                    fontWeight: 'normal'
                  }}>
                    {option.description}
                  </span>
                  {option.point && (
                    <span style={{ 
                      fontSize: '11px', 
                      opacity: 0.8,
                      fontFamily: 'monospace'
                    }}>
                      → {formatCoordinate(option.point)}
                    </span>
                  )}
                </button>
              );
            })}
          </div>
        </div>

        {/* Debug Tools */}
        {collisionInputs && fromPosition && (
          <div style={{ 
            marginBottom: '20px',
            paddingTop: '16px',
            borderTop: `1px solid ${ConfigurationData.Instance.borderColor}`
          }}>
            <button
              onClick={handleCopyDebugInfo}
              style={{
                width: '100%',
                padding: '8px 16px',
                backgroundColor: ConfigurationData.Instance.mutedTextColor,
                color: ConfigurationData.Instance.lightTextColor,
                border: 'none',
                borderRadius: '4px',
                fontSize: '12px',
                cursor: 'pointer',
                transition: 'background-color 0.2s'
              }}
              onMouseEnter={(e) => {
                e.currentTarget.style.backgroundColor = ConfigurationData.Instance.darkTextColor;
              }}
              onMouseLeave={(e) => {
                e.currentTarget.style.backgroundColor = ConfigurationData.Instance.mutedTextColor;
              }}
            >
              📋 Copy Debug Info to Clipboard
            </button>
          </div>
        )}

        {/* Footer */}
        <div style={{
          paddingTop: '16px',
          borderTop: `1px solid ${ConfigurationData.Instance.borderColor}`,
          fontSize: '12px',
          color: ConfigurationData.Instance.mutedTextColor,
          textAlign: 'center'
        }}>
          💡 Hover over the machine viewer to see collision areas highlighted
        </div>
      </div>
    </div>
  );
}
