/**
 * Utility class for data operations
 */
export class DataUtilities {
    private static idCounter = 0;

    /**
     * Generates a unique ID string
     * @returns A unique identifier string
     */
    public static generateUniqueId(): string {
        this.idCounter++;
        const timestamp = Date.now();
        const random = Math.floor(Math.random() * 10000);
        return `id_${timestamp}_${this.idCounter}_${random}`;
    }

    /**
     * Generates a GUID-like unique identifier
     * @returns A GUID-like string
     */
    public static generateGuid(): string {
        return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
            const r = Math.random() * 16 | 0;
            const v = c === 'x' ? r : ((r & 0x3) | 0x8);
            return v.toString(16);
        });
    }

    /**
     * Compares two objects for equality (deep comparison)
     * @param obj1 First object to compare
     * @param obj2 Second object to compare
     * @returns True if objects are equal, false otherwise
     */
    public static compare(obj1: any, obj2: any): boolean {
        if (obj1 === obj2) {
            return true;
        }

        if (obj1 == null || obj2 == null) {
            return false;
        }

        if (typeof obj1 !== typeof obj2) {
            return false;
        }

        if (typeof obj1 === 'object') {
            const keys1 = Object.keys(obj1);
            const keys2 = Object.keys(obj2);

            if (keys1.length !== keys2.length) {
                return false;
            }

            for (const key of keys1) {
                if (!keys2.includes(key)) {
                    return false;
                }

                if (!this.compare(obj1[key], obj2[key])) {
                    return false;
                }
            }

            return true;
        }

        return obj1 === obj2;
    }
}
