import { FlowStepLibrary } from './FlowStepLibrary';
import { EndStep } from './steps/EndStep';
import { EqualsStep } from './steps/EqualsStep';
import { ExistsStep } from './steps/ExistsStep';
import { GreaterThanEqualToStep } from './steps/GreaterThanEqualToStep';
import { LessThanEqualToStep } from './steps/LessThanEqualToStep';
import { StartStep } from './steps/StartStep';

// Movement Steps
import { AdjustFeedRateStep } from './steps/machine/movement/AdjustFeedRateStep';
import { GetCurrentFeedRateFactorStep } from './steps/machine/movement/GetCurrentFeedRateFactorStep';
import { GetCurrentPositionStep } from './steps/machine/movement/GetCurrentPositionStep';
import { GetMoveTypeStep } from './steps/machine/movement/GetMoveTypeStep';
import { MoveDirectionUntilStep } from './steps/machine/movement/MoveDirectionUntilStep';
import { MoveToStep } from './steps/machine/movement/MoveToStep';
import { MoveToUntilStep } from './steps/machine/movement/MoveToUntilStep';
import { ResetFeedRateFactorStep } from './steps/machine/movement/ResetFeedRateFactorStep';
import { SetCurrentFixturePointStep } from './steps/machine/movement/SetCurrentFixturePointStep';
import { SetMoveTypeStep } from './steps/machine/movement/SetMoveTypeStep';

// Spindle Steps
import { AdjustSpindleSpeedStep } from './steps/machine/spindle/AdjustSpindleSpeedStep';
import { GetCurrentSpindleSpeedFactorStep } from './steps/machine/spindle/GetCurrentSpindleSpeedFactorStep';
import { GetSpindleSpeedStep } from './steps/machine/spindle/GetSpindleSpeedStep';
import { IsSpindleRunningStep } from './steps/machine/spindle/IsSpindleRunningStep';
import { ResetSpindleSpeedFactorStep } from './steps/machine/spindle/ResetSpindleSpeedFactorStep';
import { SetSpindleSpeedStep } from './steps/machine/spindle/SetSpindleSpeedStep';
import { StartSpindleStep } from './steps/machine/spindle/StartSpindleStep';
import { StopSpindleStep } from './steps/machine/spindle/StopSpindleStep';
import { WarmUpSpindleStep } from './steps/machine/spindle/WarmUpSpindleStep';

// System Steps
import { EmergencyStopStep } from './steps/machine/system/EmergencyStopStep';
import { GetCurrentErrorStateStep } from './steps/machine/system/GetCurrentErrorStateStep';
import { HasCurrentErrorsStep } from './steps/machine/system/HasCurrentErrorsStep';
import { HomeMachineStep } from './steps/machine/system/HomeMachineStep';
import { IsHomedStep } from './steps/machine/system/IsHomedStep';
import { ResetErrorStateStep } from './steps/machine/system/ResetErrorStateStep';
import { StopMachineStep } from './steps/machine/system/StopMachineStep';
import { UnhomeMachineStep } from './steps/machine/system/UnhomeMachineStep';

// Features Steps
import { ChangeToToolStep } from './steps/machine/features/ChangeToToolStep';
import { CheckToolStep } from './steps/machine/features/CheckToolStep';
import { GetCurrentToolNumberStep } from './steps/machine/features/GetCurrentToolNumberStep';
import { MeasureAllToolsStep } from './steps/machine/features/MeasureAllToolsStep';
import { MeasureCurrentToolStep } from './steps/machine/features/MeasureCurrentToolStep';
import { RemoveToolStep } from './steps/machine/features/RemoveToolStep';
import { TouchOffStep } from './steps/machine/features/TouchOffStep';

// IO Steps
import { GetCurrentInputsStep } from './steps/machine/io/GetCurrentInputsStep';
import { GetCurrentOutputsStep } from './steps/machine/io/GetCurrentOutputsStep';
import { GetSystemInfoStep } from './steps/machine/io/GetSystemInfoStep';
import { IsInputActiveStep } from './steps/machine/io/IsInputActiveStep';
import { IsOutputActiveStep } from './steps/machine/io/IsOutputActiveStep';
import { SetOutputStateStep } from './steps/machine/io/SetOutputStateStep';

// Program Steps
import { EndStepRunStep } from './steps/machine/program/EndStepRunStep';
import { GetCurrentGCodeStep } from './steps/machine/program/GetCurrentGCodeStep';
import { GetCurrentLineNumberStep } from './steps/machine/program/GetCurrentLineNumberStep';
import { LoadGCodeStep } from './steps/machine/program/LoadGCodeStep';
import { ResumeAtStep } from './steps/machine/program/ResumeAtStep';
import { ResumeStep } from './steps/machine/program/ResumeStep';
import { RunFromCurrentStepStep } from './steps/machine/program/RunFromCurrentStepStep';
import { RunGCodeStep } from './steps/machine/program/RunGCodeStep';
import { StartStepRunStep } from './steps/machine/program/StartStepRunStep';
import { StepRunNextStep } from './steps/machine/program/StepRunNextStep';
import { StopStep } from './steps/machine/program/StopStep';

/**
 * FlowStepRegistration handles the registration of all FlowStep types
 * This should be called during application startup to ensure all steps are available
 */
export class FlowStepRegistration {
    private static initialized = false;

    /**
     * Initialize and register all available FlowStep types
     * This method is idempotent - calling it multiple times is safe
     */
    static initialize(): void {
        if (this.initialized) {
            return;
        }

        // Register system steps
        this.registerSystemSteps();

        // Register logic steps
        this.registerLogicSteps();

        // Register machine interface steps
        this.registerMachineSteps();

        this.initialized = true;
        // // //console.log('FlowStepRegistration: All flow steps registered successfully');
    }

    /**
     * Register system-level steps (Start, End, etc.)
     */
    private static registerSystemSteps(): void {
        FlowStepLibrary.registerStepType('StartStep', StartStep);
        FlowStepLibrary.registerStepType('EndStep', EndStep);
    }

    /**
     * Register logic and conditional steps
     */
    private static registerLogicSteps(): void {
        FlowStepLibrary.registerStepType('EqualsStep', EqualsStep);
        FlowStepLibrary.registerStepType('ExistsStep', ExistsStep);
        FlowStepLibrary.registerStepType('GreaterThanEqualToStep', GreaterThanEqualToStep);
        FlowStepLibrary.registerStepType('LessThanEqualToStep', LessThanEqualToStep);
    }

    /**
     * Register machine interface steps
     */
    private static registerMachineSteps(): void {
        // Movement steps
        FlowStepLibrary.registerStepType('MoveToStep', MoveToStep);
        FlowStepLibrary.registerStepType('MoveDirectionUntilStep', MoveDirectionUntilStep);
        FlowStepLibrary.registerStepType('GetCurrentPositionStep', GetCurrentPositionStep);
        FlowStepLibrary.registerStepType('SetMoveTypeStep', SetMoveTypeStep);
        FlowStepLibrary.registerStepType('GetMoveTypeStep', GetMoveTypeStep);
        FlowStepLibrary.registerStepType('MoveToUntilStep', MoveToUntilStep);
        FlowStepLibrary.registerStepType('SetCurrentFixturePointStep', SetCurrentFixturePointStep);
        FlowStepLibrary.registerStepType('GetCurrentFeedRateFactorStep', GetCurrentFeedRateFactorStep);
        FlowStepLibrary.registerStepType('AdjustFeedRateStep', AdjustFeedRateStep);
        FlowStepLibrary.registerStepType('ResetFeedRateFactorStep', ResetFeedRateFactorStep);

        // Spindle steps
        FlowStepLibrary.registerStepType('SetSpindleSpeedStep', SetSpindleSpeedStep);
        FlowStepLibrary.registerStepType('StartSpindleStep', StartSpindleStep);
        FlowStepLibrary.registerStepType('StopSpindleStep', StopSpindleStep);
        FlowStepLibrary.registerStepType('IsSpindleRunningStep', IsSpindleRunningStep);
        FlowStepLibrary.registerStepType('GetSpindleSpeedStep', GetSpindleSpeedStep);
        FlowStepLibrary.registerStepType('WarmUpSpindleStep', WarmUpSpindleStep);
        FlowStepLibrary.registerStepType('AdjustSpindleSpeedStep', AdjustSpindleSpeedStep);
        FlowStepLibrary.registerStepType('GetCurrentSpindleSpeedFactorStep', GetCurrentSpindleSpeedFactorStep);
        FlowStepLibrary.registerStepType('ResetSpindleSpeedFactorStep', ResetSpindleSpeedFactorStep);

        // Homing steps
        FlowStepLibrary.registerStepType('HomeMachineStep', HomeMachineStep);
        FlowStepLibrary.registerStepType('UnhomeMachineStep', UnhomeMachineStep);
        FlowStepLibrary.registerStepType('IsHomedStep', IsHomedStep);

        // Tool steps
        FlowStepLibrary.registerStepType('ChangeToToolStep', ChangeToToolStep);
        FlowStepLibrary.registerStepType('CheckToolStep', CheckToolStep);
        FlowStepLibrary.registerStepType('GetCurrentToolNumberStep', GetCurrentToolNumberStep);
        FlowStepLibrary.registerStepType('MeasureCurrentToolStep', MeasureCurrentToolStep);
        FlowStepLibrary.registerStepType('MeasureAllToolsStep', MeasureAllToolsStep);
        FlowStepLibrary.registerStepType('RemoveToolStep', RemoveToolStep);
        FlowStepLibrary.registerStepType('TouchOffStep', TouchOffStep);



        // Program Control steps
        FlowStepLibrary.registerStepType('EmergencyStopStep', EmergencyStopStep);
        FlowStepLibrary.registerStepType('StopMachineStep', StopMachineStep);
        FlowStepLibrary.registerStepType('ResumeStep', ResumeStep);
        FlowStepLibrary.registerStepType('ResumeAtStep', ResumeAtStep);
        FlowStepLibrary.registerStepType('StartStepRunStep', StartStepRunStep);
        FlowStepLibrary.registerStepType('EndStepRunStep', EndStepRunStep);
        FlowStepLibrary.registerStepType('StepRunNextStep', StepRunNextStep);
        FlowStepLibrary.registerStepType('RunFromCurrentStepStep', RunFromCurrentStepStep);
        FlowStepLibrary.registerStepType('StopStep', StopStep);

        // G-Code steps
        FlowStepLibrary.registerStepType('LoadGCodeStep', LoadGCodeStep);
        FlowStepLibrary.registerStepType('GetCurrentGCodeStep', GetCurrentGCodeStep);
        FlowStepLibrary.registerStepType('GetCurrentLineNumberStep', GetCurrentLineNumberStep);
        FlowStepLibrary.registerStepType('RunGCodeStep', RunGCodeStep);

        // I/O steps
        FlowStepLibrary.registerStepType('GetCurrentInputsStep', GetCurrentInputsStep);
        FlowStepLibrary.registerStepType('GetCurrentOutputsStep', GetCurrentOutputsStep);
        FlowStepLibrary.registerStepType('IsInputActiveStep', IsInputActiveStep);
        FlowStepLibrary.registerStepType('IsOutputActiveStep', IsOutputActiveStep);
        FlowStepLibrary.registerStepType('GetSystemInfoStep', GetSystemInfoStep);
        FlowStepLibrary.registerStepType('SetOutputStateStep', SetOutputStateStep);

        // Error Handling steps
        FlowStepLibrary.registerStepType('GetCurrentErrorStateStep', GetCurrentErrorStateStep);
        FlowStepLibrary.registerStepType('ResetErrorStateStep', ResetErrorStateStep);
        FlowStepLibrary.registerStepType('HasCurrentErrorsStep', HasCurrentErrorsStep);
    }

    /**
     * Get registration statistics
     */
    static getRegistrationInfo(): {
        isInitialized: boolean;
        totalSteps: number;
        categories: string[];
        stepsByCategory: Record<string, string[]>;
    } {
        const categories = FlowStepLibrary.getAllCategories();
        const stepsByCategory: Record<string, string[]> = {};

        categories.forEach(category => {
            const categoryKey = category.join('/');
            stepsByCategory[categoryKey] = FlowStepLibrary.getStepsByCategory(category);
        });

        const categoryPaths = categories.map(cat => cat.join('/'));

        return {
            isInitialized: this.initialized,
            totalSteps: FlowStepLibrary.getAllStepTypes().length,
            categories: categoryPaths,
            stepsByCategory
        };
    }

    /**
     * Force re-initialization (useful for testing or dynamic step loading)
     */
    static forceReinitialize(): void {
        this.initialized = false;
        this.initialize();
    }
}
