import React from "react";
import { Wizard } from "./Wizard";

export abstract class WizardStep {
    wizard: Wizard;
    priorStep: WizardStep | null;

    constructor(
        wizard: Wizard,
        priorStep: WizardStep | null = null
    ) {
        this.wizard = wizard;
        this.priorStep = priorStep;
    }

    abstract getTitle(): string;
    abstract nextStep(): WizardStep | null;
    abstract backStep(): WizardStep | null;
    abstract render(): React.ReactNode;
}
