import { Error as ErrorIcon } from '@mui/icons-material';
import { Typography } from '@mui/material';
import React from 'react';
import { Machine } from '../../../../machine/Machine';
import { DataUtilities } from '../../../../utils/storage/DataUtilities';
import { FlowStep } from "../../../FlowStep";
import { FlowStepData } from "../../../FlowStepData";

export class HasCurrentErrorsStep extends FlowStep {
    readonly __type = 'HasCurrentErrorsStep';
    readonly category = ['Machine', 'System'];
    readonly name = 'Has Current Errors';
    readonly description = 'Checks if machine has any current errors';
    
    // Icon is created dynamically, not stored
    get icon(): React.ReactNode {
        return React.createElement(ErrorIcon, { sx: { color: 'error.main' } });
    }

    static readonly TRUE_PATH = 'true';
    static readonly FALSE_PATH = 'false';

    async execute(data: FlowStepData, prototypeRun: boolean): Promise<string | null> {
        if (prototypeRun) {
            return HasCurrentErrorsStep.FALSE_PATH;
        }

        try {
            const hasErrors = await Machine.getInstance().system.HasCurrentErrors();
            return hasErrors ? HasCurrentErrorsStep.TRUE_PATH : HasCurrentErrorsStep.FALSE_PATH;
        } catch (error) {
            console.error('HasCurrentErrors failed:', error);
            return HasCurrentErrorsStep.TRUE_PATH; // Assume error if we can't check
        }
    }

    results(): string[] {
        return [HasCurrentErrorsStep.TRUE_PATH, HasCurrentErrorsStep.FALSE_PATH];
    }

    renderResultsUI(data: FlowStepData, result: string): React.ReactNode {
        return (
            <Typography variant="caption">
                Machine errors: {result === HasCurrentErrorsStep.TRUE_PATH ? 'Has errors' : 'No errors'}
            </Typography>
        );
    }

    public toJSON(): any {
        const data = DataUtilities.getStorageData(this, ['icon']) as any;
        data.__type = this.__type;
        return data;
    }

    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data);
    }
}






