import React from 'react';
import { SimulatorView } from '../../../data/Common/SimulatorView';
import { ConfigurationData } from '../../../data/ConfigurationData';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { MachineStateData } from '../../../data/MachineStateData';
import { ActionBus } from '../../../utils/actions/ActionBus';
import { MoveAction, MoveType } from '../../../utils/actions/MoveAction';
import { CoordinateUtil } from '../../../utils/CoordinateUtil';
import { ObserveMultiProperties } from '../../../utils/statemanager/ObserveMultiProperties';

export interface WorkHomeIndicatorProps {
  simulatorView: SimulatorView;
  machineState: MachineStateData;
}

export const WorkHomeIndicator: React.FC<WorkHomeIndicatorProps> = ({
  simulatorView,
  machineState
}) => {
  // State for tracking sphere hover
  const [isHovered, setIsHovered] = React.useState<boolean>(false);
  
  return (
    <ObserveMultiProperties
      listenTo={[
        { object: machineState, properties: ['currentWorkZero'] }
      ]}
      control={() => {
        const workZero = machineState.currentWorkZero;
        const config = ConfigurationData.Instance;
        
        // Convert work zero coordinates to simulator coordinates for rendering
        const simulatorWorkZero = CoordinateUtil.toSimulator(workZero);
        
        // Handler to move machine to work zero location
        const handleTargetClick = () => {
          // Keep current Z position unchanged
          const currentZ = machineState.currentMachinePoint.z;
          // Create and execute move action - move to work zero X,Y
          const moveAction = new MoveAction(machineState.currentMachinePoint.coordinateType, workZero.x, workZero.y, currentZ, undefined, MoveType.Coordinates);
          ActionBus.Instance.addAction(moveAction);
        };
        
        return (
          <group position={[simulatorWorkZero.x, simulatorWorkZero.y, simulatorWorkZero.z]}>
            {/* X axis - Red (positive direction only) */}
            <mesh position={[2.5, 0, 0]} rotation={[0, 0, Math.PI / 2]}>
              <cylinderGeometry args={[0.1, 0.1, 5, 8]} />
              <meshStandardMaterial color="#ff0000" />
            </mesh>
            
            {/* Y axis - Green (positive direction only) */}
            <mesh position={[0, 2.5, 0]}>
              <cylinderGeometry args={[0.1, 0.1, 5, 8]} />
              <meshStandardMaterial color="#00ff00" />
            </mesh>
            
            {/* Z axis - Blue (positive direction only) */}
            <mesh position={[0, 0, 2.5]} rotation={[Math.PI / 2, 0, 0]}>
              <cylinderGeometry args={[0.1, 0.1, 5, 8]} />
              <meshStandardMaterial color="#0000ff" />
            </mesh>
            
            {/* Origin sphere - Interactive target sphere */}
            <mesh
              onClick={handleTargetClick}
              onPointerOver={() => setIsHovered(true)}
              onPointerOut={() => setIsHovered(false)}
              castShadow
              receiveShadow
            >
              <sphereGeometry args={[ConfigurationData.Instance.targetSphereSize, 16, 16]} />
              <meshStandardMaterial 
                color={ConfigurationDataColors.toThreeJsColor(isHovered ? config.highlightColor : '#ffffff')} 
                transparent={true}
                opacity={isHovered ? 1.0 : 0.0}
              />
            </mesh>
          </group>
        );
      }}
    />
  );
};
