import {
  Box,
  Button,
  Paper,
  ToggleButton,
  ToggleButtonGroup,
  Typography
} from "@mui/material";
import React from "react";
import { ConfigurationData } from "../../../../data/ConfigurationData";
import { MachineData } from "../../../../data/MachineData";
import { MachineStateData } from "../../../../data/MachineStateData";
import { ObserveState } from "../../../../utils/statemanager/ObserveState";
import { NumberInput } from "../../../Common/NumberInput";
import { FullSizeCNCViewer } from "../../../MachineViewer/FullSizeCNCViewer";
import { WizardStep } from "../../../Wizard/WizardStep";
import { AxisCalibrationWizard } from "../AxisCalibrationWizard";
import { AxisCalibrationData, AxisCalibrationMeasurementMethod } from "./AxisCalibrationData";

export class AxisCalibrationMoveStep extends WizardStep {
  constructor(wizard: AxisCalibrationWizard, priorStep: WizardStep | null = null) {
    super(wizard, priorStep);
  }

  getTitle(): string {
    const axisConfig = this.wizard.state.axisConfig;
    return `${axisConfig.axisType} Axis Calibration - Move Axis`;
  }

  nextStep(): WizardStep | null {
    // After movement, go to marking step for ending position
    const { AxisCalibrationMarkStep } = require("./AxisCalibrationMarkStep");
    const { AxisCalibrationMeasureStep } = require("./AxisCalibrationMeasureStep");

    // Create the measure step as the next step after marking
    const measureStep = new AxisCalibrationMeasureStep(this.wizard as AxisCalibrationWizard, null);

    // Create the marking step with this as prior and measure as next
    return new AxisCalibrationMarkStep(this.wizard as AxisCalibrationWizard, this, 'end', measureStep);
  }

  backStep(): WizardStep | null {
    return this.priorStep;
  }

  private async performMove(): Promise<void> {
    try {
      const axis = AxisCalibrationData.Instance.axis.toUpperCase();
      const distance = AxisCalibrationData.Instance.distanceToMove;

      // Build G-code sequence based on which axis is being calibrated
      const gcode: string[] = ['G91']; // Incremental mode

      if (axis === 'Z') {
        // For Z-axis: just move the distance (always positive/up)
        gcode.push(`G0 Z${distance}`);
      } else {
        // For X/Y axes: Z+1, move distance, Z-1
        gcode.push('G0 Z1.0');              // Move up 1" on Z
        gcode.push(`G0 ${axis}${distance}`); // Move the distance on the target axis
        gcode.push('G0 Z-1.0');             // Move back down 1" on Z
      }

      gcode.push('G90'); // Return to absolute mode

      // Execute the movement sequence
      const { Machine } = await import('../../../../machine/Machine');
      await Machine.getInstance().program.RunGCode(gcode, true);

      // Move completed, advance to measurement step
      this.wizard.advanceToNextStep();
    } catch (error) {
      console.error("Error during axis movement:", error);
    }
  }

  render(): React.ReactNode {
    return (
      <ObserveState
        key="axis-calibration-move-step"
        listenTo={AxisCalibrationData.Instance}
        properties={['distanceToMove', 'measurementMethod', 'cumulativeAdjustment', 'isFirstCalibrationRun']}
        control={() => {


          return (
            <Box sx={{ p: 3, height: '100%', display: 'flex', flexDirection: 'column', gap: 3 }}>

              {/* Main Content Area */}
              <Box sx={{ display: 'flex', gap: 3, flex: 1, minHeight: 0 }}>
                {/* Left Side - Movement Configuration (50%) */}
                <Box sx={{ flex: '50%', display: 'flex', flexDirection: 'column', gap: 3 }}>

                  {/* Movement Description */}
                  <Paper sx={{ p: 2 }}>
                    <Typography variant="subtitle1" gutterBottom>
                      Movement Process
                    </Typography>

                    <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                      The calibration process will:
                    </Typography>
                    <Box component="ol" sx={{ pl: 2, mb: 0 }}>
                      <Typography component="li" variant="body2" color="text.secondary">
                        Move up on the Z-axis by 1" to clear the material
                      </Typography>
                      <Typography component="li" variant="body2" color="text.secondary">
                        Move {AxisCalibrationData.Instance.distanceToMove}" on the {AxisCalibrationData.Instance.axis.toUpperCase()}-axis
                      </Typography>
                      <Typography component="li" variant="body2" color="text.secondary">
                        Lower back down to allow marking the ending position
                      </Typography>
                      <Typography component="li" variant="body2" color="text.secondary">
                        Allow you to measure the actual distance between marks
                      </Typography>
                    </Box>
                  </Paper>

                  {/* Movement Configuration */}
                  <Paper sx={{ p: 2 }}>
                    <Typography variant="subtitle1" gutterBottom>
                      Movement Parameters
                    </Typography>

                    {/* Distance Input */}
                    <Box sx={{ display: 'flex', gap: 2, alignItems: 'flex-start', mb: 3 }}>
                      <Box sx={{ flex: 1 }}>
                        <NumberInput
                          label="Distance to Move (inches)"
                          value={AxisCalibrationData.Instance.distanceToMove}
                          onChange={(value) => {
                            AxisCalibrationData.Instance.distanceToMove = value || 1.0;
                          }}
                          min={0.1}
                          max={48}
                          precision={3}
                        />
                      </Box>
                      <Typography variant="body2" color="text.secondary" sx={{ flex: 1, pt: 1 }}>
                        Distance the machine will move for calibration
                      </Typography>
                    </Box>

                    {/* Measurement Method Toggle */}
                    <Typography variant="subtitle2" gutterBottom>
                      Measurement Method
                    </Typography>
                    <ToggleButtonGroup
                      value={AxisCalibrationData.Instance.measurementMethod}
                      exclusive
                      onChange={(event, newValue) => {
                        // Only update if a valid value is selected (prevent deselecting all)
                        if (newValue !== null) {
                          AxisCalibrationData.Instance.measurementMethod = newValue;
                        }
                      }}
                      aria-label="measurement method"
                      size="large"
                      sx={{ width: '100%', mb: 2 }}
                    >
                      <ToggleButton value={AxisCalibrationMeasurementMethod.CenterToCenter} sx={{ flex: 1 }}>
                        Center to Center
                      </ToggleButton>
                      <ToggleButton value={AxisCalibrationMeasurementMethod.InsideEdges} sx={{ flex: 1 }}>
                        Inside Edges
                      </ToggleButton>
                    </ToggleButtonGroup>

                    <Typography variant="body2" color="text.secondary">
                      {AxisCalibrationData.Instance.measurementMethod === AxisCalibrationMeasurementMethod.CenterToCenter
                        ? 'Measure from the center of the starting mark to the center of the ending mark'
                        : 'Measure from the inside edge of the starting mark to the inside edge of the ending mark'
                      }
                    </Typography>
                  </Paper>
                </Box>

                {/* Right Side - 3D Viewer (50%) */}
                <Box sx={{ flex: '50%', display: 'flex', flexDirection: 'column', minHeight: 0 }}>
                  <FullSizeCNCViewer
                    simulatorView={ConfigurationData.Instance.defaultView}
                    machineState={MachineStateData.Instance}
                    machineData={MachineData.Instance}
                    job={MachineStateData.Instance.currentJob!}
                    enableOrbit={true}
                    enableClampDragging={false}
                    enableSpindleDrag={false}
                  />
                </Box>
              </Box>

              {/* Action Buttons */}
              <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <Button
                  variant="outlined"
                  onClick={() => this.wizard.goToPreviousStep()}
                >
                  Back
                </Button>

                <Button
                  variant="contained"
                  onClick={() => this.performMove()}
                  size="large"
                  color="primary"
                >
                  Start Movement
                </Button>
              </Box>
            </Box>
          );
        }}
      />
    );
  }
}
