import { MachineInput } from '../data/Machine/MachineInput';
import { StateManager } from './statemanager/StateManager';
import { Logger, LogCategory } from './Logger';

/**
 * Utility functions for managing machine input number assignments
 */
export class InputNumberManager {
  
  /**
   * Assigns a number to an input, handling conflicts and validation
   * @param targetInput The input to assign the number to
   * @param newNumber The number to assign (null for unassigned)
   * @param allInputs Array of all machine inputs
   * @param dataContext The data context to trigger state updates on
   * @returns Updated array of inputs with conflicts resolved
   */
  static assignInputNumber(
    targetInput: MachineInput, 
    newNumber: number | null, 
    allInputs: MachineInput[],
    dataContext: any
  ): MachineInput[] {
    // Validate that unused inputs never get assigned numbers
    if (!targetInput.use && newNumber !== null) {
      Logger.Instance.logError(LogCategory.System, 
        `Cannot assign number ${newNumber} to unused input: ${targetInput.name}`);
      return allInputs;
    }

    // If assigning a real number (not null), check for conflicts
    if (newNumber !== null && newNumber > 0) {
      // Find any existing inputs with the same number
      const conflictingInputs = allInputs.filter(input => 
        input !== targetInput && 
        input.number === newNumber
      );

      // Unassign conflicting inputs
      conflictingInputs.forEach(conflictInput => {
        conflictInput.number = null;
        // Logger.Instance.log(LogCategory.System, 
        //   `Unassigned input ${conflictInput.name} from number ${oldNumber} due to conflict`);
      });

      if (conflictingInputs.length > 0) {
        // Logger.Instance.log(LogCategory.System, 
        //   `Resolved ${conflictingInputs.length} input number conflicts for number ${newNumber}`);
      }
    }

    // Assign the number to the target input
    targetInput.number = newNumber;

    // Log the assignment
    if (newNumber === null) {
      // Logger.Instance.log(LogCategory.System, 
      //   `Unassigned input ${targetInput.name} from number ${oldNumber}`);
    } else {
      // Logger.Instance.log(LogCategory.System, 
      //   `Assigned input ${targetInput.name} to number ${newNumber}`);
    }

    // Trigger state update
    StateManager.propertyChanged(dataContext, 'machineInputs');

    return allInputs;
  }

  /**
   * Validates that an input can be assigned a specific number
   * @param targetInput The input to validate
   * @param newNumber The number to assign
   * @param allInputs Array of all machine inputs
   * @returns Object with isValid flag and error message if invalid
   */
  static validateInputNumberAssignment(
    targetInput: MachineInput,
    newNumber: number | null,
    allInputs: MachineInput[]
  ): { isValid: boolean; error?: string } {
    // Unused inputs cannot have numbers
    if (!targetInput.use && newNumber !== null) {
      return {
        isValid: false,
        error: `Unused inputs cannot be assigned numbers. Enable the input first.`
      };
    }

    // Number must be positive if not null/0
    if (newNumber !== null && newNumber !== 0 && newNumber < 1) {
      return {
        isValid: false,
        error: `Input number must be greater than 0.`
      };
    }

    return { isValid: true };
  }

  /**
   * Gets all inputs that are currently unassigned (number = 0 or null)
   * @param allInputs Array of all machine inputs
   * @returns Array of unassigned inputs
   */
  static getUnassignedInputs(allInputs: MachineInput[]): MachineInput[] {
    return allInputs.filter(input => 
      input.use && (input.number === 0 || input.number === null)
    );
  }

  /**
   * Gets all inputs that are currently assigned to numbers
   * @param allInputs Array of all machine inputs
   * @returns Array of assigned inputs, sorted by number
   */
  static getAssignedInputs(allInputs: MachineInput[]): MachineInput[] {
    return allInputs
      .filter(input => input.use && input.number !== null && input.number !== undefined)
      .sort((a, b) => (a.number || 0) - (b.number || 0));
  }

  /**
   * Gets all inputs that are not in use
   * @param allInputs Array of all machine inputs
   * @returns Array of unused inputs
   */
  static getUnusedInputs(allInputs: MachineInput[]): MachineInput[] {
    return allInputs.filter(input => !input.use);
  }

  /**
   * Finds the next available input number
   * @param allInputs Array of all machine inputs
   * @param startFrom Starting number to search from (default: 1)
   * @returns Next available input number
   */
  static getNextAvailableNumber(allInputs: MachineInput[], startFrom: number = 1): number {
    const usedNumbers = new Set(
      allInputs
        .filter(input => input.use && input.number !== null && input.number !== undefined)
        .map(input => input.number as number)
    );

    let nextNumber = startFrom;
    while (usedNumbers.has(nextNumber)) {
      nextNumber++;
    }

    return nextNumber;
  }

  /**
   * Ensures all unused inputs have their numbers set to null
   * @param allInputs Array of all machine inputs
   * @param dataContext The data context to trigger state updates on
   * @returns Updated array of inputs
   */
  static enforceUnusedInputsNumberPolicy(allInputs: MachineInput[], dataContext: any): MachineInput[] {
    let changesAsMade = false;

    allInputs.forEach(input => {
      if (!input.use && input.number !== null) {
        input.number = null;
        changesAsMade = true;
        // Logger.Instance.log(LogCategory.System, 
        //   `Enforced policy: Removed number ${oldNumber} from unused input: ${input.name}`);
      }
    });

    if (changesAsMade) {
      StateManager.propertyChanged(dataContext, 'machineInputs');
    }

    return allInputs;
  }
}
