import { filterFunctionNames, loadFunctionsXml, type MachineType } from '../../utils/FunctionsXmlParser';

/**
 * Legacy Centroid input names enum for backward compatibility
 * @deprecated Use getCentroidInputNames() function instead for dynamic loading from functions.xml
 */
export enum CentroidInputName {
  // Emergency and Safety Inputs
  EstopInput = 'EstopInput',
  SafetyChainInput = 'SafetyChainInput',

  // Limit Switch Inputs
  XPlusLimit = 'XPlusLimit',
  XMinusLimit = 'XMinusLimit',
  YPlusLimit = 'YPlusLimit',
  YMinusLimit = 'YMinusLimit',
  ZPlusLimit = 'ZPlusLimit',
  ZMinusLimit = 'ZMinusLimit',

  // Home Switch Inputs
  XHomeInput = 'XHomeInput',
  YHomeInput = 'YHomeInput',
  ZHomeInput = 'ZHomeInput',

  // Probe Inputs
  ProbeInput = 'ProbeInput',

  // Spindle and Tool Inputs
  SpindleAtSpeedInput = 'SpindleAtSpeedInput',
  ToolChangeCompleteInput = 'ToolChangeCompleteInput',
  DrawBarOpenInput = 'DrawBarOpenInput',
  DrawBarClosedInput = 'DrawBarClosedInput',

  // Door and Enclosure Inputs
  DoorOpenInput = 'DoorOpenInput',
  EnclosureOpenInput = 'EnclosureOpenInput',

  // Coolant and Vacuum Inputs
  CoolantFlowInput = 'CoolantFlowInput',
  VacuumPressureInput = 'VacuumPressureInput',

  // General Purpose Inputs
  GeneralInput1 = 'GeneralInput1',
  GeneralInput2 = 'GeneralInput2',
  GeneralInput3 = 'GeneralInput3',
  GeneralInput4 = 'GeneralInput4',
  GeneralInput5 = 'GeneralInput5',
  GeneralInput6 = 'GeneralInput6',
  GeneralInput7 = 'GeneralInput7',
  GeneralInput8 = 'GeneralInput8',

  // Custom inputs can be added here as needed
  Custom1 = 'Custom1',
  Custom2 = 'Custom2',
  Custom3 = 'Custom3',
  Custom4 = 'Custom4',
  Custom5 = 'Custom5'
}

// Cache for loaded function names to avoid repeated XML parsing
let _cachedInputNames: { [key in MachineType]?: string[] } = {};

/**
 * Get Centroid input names dynamically from functions.xml based on machine type
 * @param machineType - Machine type to filter by ('All', 'Router', 'Mill', 'Lathe')
 * @param includeHidden - Whether to include hidden functions (default: false)
 * @returns Promise resolving to array of input names
 */
export async function getCentroidInputNames(
  machineType: MachineType = 'All',
  includeHidden: boolean = false
): Promise<string[]> {
  // Check cache first
  if (_cachedInputNames[machineType] && !includeHidden) {
    return _cachedInputNames[machineType]!;
  }

  try {
    const functions = await loadFunctionsXml();
    const inputNames = filterFunctionNames(functions, machineType, 'Input', includeHidden);

    // Cache the results (only for non-hidden requests)
    if (!includeHidden) {
      _cachedInputNames[machineType] = inputNames;
    }

    return inputNames;
  } catch (error) {
    // Fall back to static enum values on error
    return Object.values(CentroidInputName);
  }
}

/**
 * Clear the input names cache - useful when functions.xml is updated
 */
export function clearCentroidInputNamesCache(): void {
  _cachedInputNames = {};
}