import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  Divider,
  Grid,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Typography
} from '@mui/material';
import { Send as SendIcon, Refresh as RefreshIcon } from '@mui/icons-material';
import React, { useState, useCallback } from 'react';
import { AxisType, MachineData } from '../../../data/MachineData';
import { ObserveState } from '../../../utils/statemanager/ObserveState';
import { Machine } from '../../../machine/Machine';
import { UserMessageQueue } from '../../../data/UserMessageQueue';
import { Logger, LogCategory } from '../../../utils/Logger';
import { MachineConfigurationMapper } from '../../../utils/MachineConfigurationMapper';
import type { AxisConfiguration } from '../../../machine/Machine';

export function UpdateCentroidTab() {
  const [axisConfigurations, setAxisConfigurations] = useState<AxisConfiguration[]>([]);
  const [isSending, setIsSending] = useState(false);

  // Load/refresh the converted configurations
  const handleRefreshConfigurations = useCallback(() => {
    try {
      const machineData = MachineData.Instance;
      const configs = MachineConfigurationMapper.convertAllAxesToAPIFormat(machineData);
      setAxisConfigurations(configs);
      Logger.Instance.log(LogCategory.System, `Refreshed ${configs.length} axis configurations for review`);
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Error converting axis configurations:', error);
      UserMessageQueue.Instance.addMessage('❌ Error converting axis configurations');
    }
  }, []);

  // Send configurations to machine
  const handleSendToMachine = useCallback(async () => {
    if (axisConfigurations.length === 0) {
      UserMessageQueue.Instance.addMessage('⚠️ No configurations to send. Click Refresh first.');
      return;
    }

    setIsSending(true);
    try {
      const machine = Machine.getInstance();
      let successCount = 0;
      let failureCount = 0;

      for (const apiConfig of axisConfigurations) {
        const success = await machine.setup.ConfigureAxis(apiConfig);

        if (success) {
          successCount++;
          Logger.Instance.log(
            LogCategory.System,
            `Successfully configured axis ${apiConfig.axisNumber} (${apiConfig.label})`
          );
        } else {
          failureCount++;
          Logger.Instance.logError(
            LogCategory.System,
            `Failed to configure axis ${apiConfig.axisNumber} (${apiConfig.label})`
          );
        }
      }

      // Show result message
      if (failureCount === 0) {
        UserMessageQueue.Instance.addMessage(
          `✓ Successfully configured ${successCount} axis${successCount !== 1 ? 'es' : ''}`
        );
      } else if (successCount === 0) {
        UserMessageQueue.Instance.addMessage(`❌ Failed to configure all axes`);
      } else {
        UserMessageQueue.Instance.addMessage(
          `⚠ Configured ${successCount} axis${successCount !== 1 ? 'es' : ''}, ${failureCount} failed`
        );
      }
    } catch (error) {
      Logger.Instance.logError(
        LogCategory.System,
        'Error sending axis configurations to machine:',
        error
      );
      UserMessageQueue.Instance.addMessage('❌ Error sending axis configurations to machine');
    } finally {
      setIsSending(false);
    }
  }, [axisConfigurations]);

  // Format number for display (handle null/undefined)
  const formatNumber = (value: number | null | undefined, precision: number = 2): string => {
    if (value === null || value === undefined) return '-';
    return value.toFixed(precision);
  };

  // Format boolean for display
  const formatBoolean = (value: boolean | null | undefined): string => {
    if (value === null || value === undefined) return '-';
    return value ? 'Yes' : 'No';
  };

  return (
    <ObserveState
      key="update-centroid-tab"
      listenTo={MachineData.Instance}
      properties={['axisConfigurations', 'xLowerSoftLimitFromMachineZero', 'xUpperSoftLimitFromMachineZero',
        'yLowerSoftLimitFromMachineZero', 'yUpperSoftLimitFromMachineZero',
        'zLowerSoftLimitFromMachineZero', 'zUpperSoftLimitFromMachineZero']}
      control={() => {
        const machineData = MachineData.Instance;

        return (
          <Box sx={{ p: 3 }}>
            {/* Header */}
            <Box sx={{ mb: 3 }}>
              <Typography variant="h5" gutterBottom>
                Update Centroid Machine Configuration
              </Typography>
              <Typography variant="body2" color="text.secondary">
                Review and send machine configuration to the Centroid controller. This converts internal settings to the API format and displays the data before sending.
              </Typography>
            </Box>

            {/* Action Buttons */}
            <Box sx={{ display: 'flex', gap: 2, mb: 3 }}>
              <Button
                variant="outlined"
                startIcon={<RefreshIcon />}
                onClick={handleRefreshConfigurations}
                disabled={isSending}
              >
                Refresh Configuration Preview
              </Button>
              <Button
                variant="contained"
                color="primary"
                startIcon={<SendIcon />}
                onClick={handleSendToMachine}
                disabled={isSending || axisConfigurations.length === 0}
              >
                {isSending ? 'Sending...' : 'Send to Machine'}
              </Button>
            </Box>

            {/* Summary Card */}
            <Card sx={{ mb: 3, bgcolor: 'info.50', border: '1px solid', borderColor: 'info.200' }}>
              <CardContent>
                <Typography variant="h6" gutterBottom sx={{ color: 'info.main' }}>
                  Configuration Summary
                </Typography>
                <Grid container spacing={2}>
                  <Grid item xs={12} md={4}>
                    <Typography variant="body2" color="text.secondary">
                      Total Axes Configured:
                    </Typography>
                    <Typography variant="h4">
                      {machineData.axisConfigurations.filter(a => a.axisType !== AxisType.Unset).length}
                    </Typography>
                  </Grid>
                  <Grid item xs={12} md={4}>
                    <Typography variant="body2" color="text.secondary">
                      Configurations Ready to Send:
                    </Typography>
                    <Typography variant="h4" color={axisConfigurations.length > 0 ? 'success.main' : 'text.secondary'}>
                      {axisConfigurations.length}
                    </Typography>
                  </Grid>
                  <Grid item xs={12} md={4}>
                    <Typography variant="body2" color="text.secondary">
                      Status:
                    </Typography>
                    <Typography variant="h6" color={axisConfigurations.length > 0 ? 'success.main' : 'warning.main'}>
                      {axisConfigurations.length > 0 ? 'Ready' : 'Click Refresh'}
                    </Typography>
                  </Grid>
                </Grid>
              </CardContent>
            </Card>

            {/* Converted Configurations Table */}
            {axisConfigurations.length > 0 && (
              <Card>
                <CardContent>
                  <Typography variant="h6" gutterBottom>
                    Axis Configurations (API Format)
                  </Typography>
                  <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                    This is the data that will be sent to the Centroid controller
                  </Typography>

                  <TableContainer component={Paper} sx={{ maxHeight: 600 }}>
                    <Table stickyHeader size="small">
                      <TableHead>
                        <TableRow>
                          <TableCell><strong>Axis #</strong></TableCell>
                          <TableCell><strong>Label</strong></TableCell>
                          <TableCell><strong>Steps/Rev</strong></TableCell>
                          <TableCell><strong>Turn Ratio</strong></TableCell>
                          <TableCell><strong>Max Rate</strong></TableCell>
                          <TableCell><strong>Accel Time</strong></TableCell>
                          <TableCell><strong>Plus Limit</strong></TableCell>
                          <TableCell><strong>Minus Limit</strong></TableCell>
                          <TableCell><strong>Reversed</strong></TableCell>
                          <TableCell><strong>Rotary</strong></TableCell>
                        </TableRow>
                      </TableHead>
                      <TableBody>
                        {axisConfigurations.map((config, index) => (
                          <TableRow key={index} hover>
                            <TableCell>{config.axisNumber}</TableCell>
                            <TableCell><strong>{config.label}</strong></TableCell>
                            <TableCell>{formatNumber(config.stepsPerRevolution, 0)}</TableCell>
                            <TableCell>{formatNumber(config.turnRatio, 3)}</TableCell>
                            <TableCell>{formatNumber(config.maxRate, 0)}</TableCell>
                            <TableCell>{formatNumber(config.accelerationTime, 2)}</TableCell>
                            <TableCell sx={{ color: 'success.main' }}>
                              {formatNumber(config.plusTravelLimit, 2)}
                            </TableCell>
                            <TableCell sx={{ color: 'error.main' }}>
                              {formatNumber(config.minusTravelLimit, 2)}
                            </TableCell>
                            <TableCell>{formatBoolean(config.isReversed)}</TableCell>
                            <TableCell>{formatBoolean(config.isRotary)}</TableCell>
                          </TableRow>
                        ))}
                      </TableBody>
                    </Table>
                  </TableContainer>

                  <Divider sx={{ my: 3 }} />

                  {/* Additional Details */}
                  <Typography variant="h6" gutterBottom>
                    Additional Parameters
                  </Typography>

                  {axisConfigurations.map((config, index) => (
                    <Box key={index} sx={{ mb: 3 }}>
                      <Typography variant="subtitle1" gutterBottom sx={{ fontWeight: 'bold' }}>
                        Axis {config.axisNumber} ({config.label})
                      </Typography>
                      <Grid container spacing={2}>
                        <Grid item xs={6} md={3}>
                          <Typography variant="caption" color="text.secondary">
                            Backlash Compensation
                          </Typography>
                          <Typography variant="body2">
                            {formatNumber(config.backlashCompensation, 4)}
                          </Typography>
                        </Grid>
                        <Grid item xs={6} md={3}>
                          <Typography variant="caption" color="text.secondary">
                            Slow Jog Rate
                          </Typography>
                          <Typography variant="body2">
                            {formatNumber(config.slowJogRate, 0)}
                          </Typography>
                        </Grid>
                        <Grid item xs={6} md={3}>
                          <Typography variant="caption" color="text.secondary">
                            Fast Jog Rate
                          </Typography>
                          <Typography variant="body2">
                            {formatNumber(config.fastJogRate, 0)}
                          </Typography>
                        </Grid>
                        <Grid item xs={6} md={3}>
                          <Typography variant="caption" color="text.secondary">
                            Homing Feedrate
                          </Typography>
                          <Typography variant="body2">
                            {formatNumber(config.homingFeedrate, 0)}
                          </Typography>
                        </Grid>
                      </Grid>
                      <Divider sx={{ mt: 2 }} />
                    </Box>
                  ))}

                  {/* Axis Signal Inversion Section */}
                  <Typography variant="h6" gutterBottom sx={{ mt: 3 }}>
                    Axis Signal Inversion
                  </Typography>
                  <Paper sx={{ p: 2, bgcolor: 'grey.50' }}>
                    <Grid container spacing={2}>
                      {axisConfigurations.map((config, index) => (
                        <Grid item xs={12} md={6} lg={3} key={index}>
                          <Box sx={{ p: 2, border: 1, borderColor: 'divider', borderRadius: 1, bgcolor: 'background.paper' }}>
                            <Typography variant="subtitle2" gutterBottom sx={{ fontWeight: 'bold', mb: 1.5 }}>
                              Axis {config.axisNumber}
                            </Typography>
                            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
                              <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                                <Typography variant="body2">Step Signal</Typography>
                                <Typography variant="body2" sx={{ fontWeight: 'bold', color: config.stepSignalInverted ? 'success.main' : 'text.secondary' }}>
                                  {config.stepSignalInverted ? '✓' : '○'}
                                </Typography>
                              </Box>
                              <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                                <Typography variant="body2">Direction Signal *</Typography>
                                <Typography variant="body2" sx={{ fontWeight: 'bold', color: config.directionSignalInverted ? 'success.main' : 'text.secondary' }}>
                                  {config.directionSignalInverted ? '✓' : '○'}
                                </Typography>
                              </Box>
                              <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                                <Typography variant="body2">Enable Signal</Typography>
                                <Typography variant="body2" sx={{ fontWeight: 'bold', color: config.enableSignalInverted ? 'success.main' : 'text.secondary' }}>
                                  {config.enableSignalInverted ? '✓' : '○'}
                                </Typography>
                              </Box>
                            </Box>
                          </Box>
                        </Grid>
                      ))}
                    </Grid>
                    <Alert severity="info" sx={{ mt: 2 }}>
                      <Typography variant="caption">
                        * Note: Axis Signal Direction Inversion is not the same as changing the direction of the movement of an axis. 
                        Use the Direction Reversal setting to change the direction of movement of an axis.
                      </Typography>
                    </Alert>
                  </Paper>
                </CardContent>
              </Card>
            )}

            {/* Empty State */}
            {axisConfigurations.length === 0 && (
              <Paper sx={{ p: 6, textAlign: 'center', bgcolor: 'grey.50' }}>
                <Typography variant="h6" color="text.secondary" gutterBottom>
                  No Configurations Loaded
                </Typography>
                <Typography variant="body2" color="text.secondary" sx={{ mb: 3 }}>
                  Click "Refresh Configuration Preview" to load and review the current axis configurations
                </Typography>
                <Button
                  variant="contained"
                  startIcon={<RefreshIcon />}
                  onClick={handleRefreshConfigurations}
                >
                  Load Configuration Preview
                </Button>
              </Paper>
            )}
          </Box>
        );
      }}
    />
  );
}
