import { Output as OutputIcon } from '@mui/icons-material';
import { Typography } from '@mui/material';
import React from 'react';
import { Machine } from '../../../../machine/Machine';
import { LogCategory, Logger } from '../../../../utils/Logger';
import { DataUtilities } from '../../../../utils/storage/DataUtilities';
import { FlowStep } from "../../../FlowStep";
import { FlowStepData } from "../../../FlowStepData";

export class GetCurrentOutputsStep extends FlowStep {
    readonly __type = 'GetCurrentOutputsStep';
    readonly category = ['Machine', 'IO'];
    readonly name = 'Get Current Outputs';
    readonly description = 'Reads all current output states';
    
    // Icon is created dynamically, not stored
    get icon(): React.ReactNode {
        return React.createElement(OutputIcon, { sx: { color: 'primary.main' } });
    }
    static readonly SUCCESS_PATH = 'success';
    async execute(data: FlowStepData, prototypeRun: boolean): Promise<string | null> {
        if (prototypeRun) {
            //Logger.Instance.log(LogCategory.System, 'Prototype: Get current outputs');
            data.setVariable('currentOutputs', { 1: false, 2: true, 3: false });
            return GetCurrentOutputsStep.SUCCESS_PATH;
        }

        try {
            const outputs = await Machine.getInstance().io.GetCurrentOutputs();
            data.setVariable('currentOutputs', outputs);
            //Logger.Instance.log(LogCategory.System, `Retrieved ${Object.keys(outputs).length} output states`);
            return GetCurrentOutputsStep.SUCCESS_PATH;
        } catch (error) {
            Logger.Instance.logError(LogCategory.System, 'Get current outputs failed:', error);
            // Still return success with fallback value - the step completed its attempt
            data.setVariable('currentOutputs', {});
            return GetCurrentOutputsStep.SUCCESS_PATH;
        }
    }

    results(): string[] {
        return [GetCurrentOutputsStep.SUCCESS_PATH];
    }

    renderResultsUI(data: FlowStepData, result: string): React.ReactNode {
        const outputs = data.getVariable('currentOutputs') as Record<number, boolean> || {};
        const outputCount = Object.keys(outputs).length;
        return (
            <Typography variant="caption">
                Get outputs ({outputCount} channels): {result}
            </Typography>
        );
    }

    renderEditUI(props: { onClose: () => void }): React.ReactNode {
        return null; // No parameters, no edit UI needed
    }

    public toJSON(): any {
        const data = DataUtilities.getStorageData(this, ['icon']) as any;
        data.__type = this.__type;
        return data;
    }

    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data);
    }
}






