import { Input as InputIcon } from '@mui/icons-material';
import { Typography } from '@mui/material';
import React from 'react';
import { MachineData } from '../../../../data/MachineData';
import { Machine } from '../../../../machine/Machine';
import { LogCategory, Logger } from '../../../../utils/Logger';
import { DataUtilities } from '../../../../utils/storage/DataUtilities';
import { FlowStep } from "../../../FlowStep";
import { FlowStepData } from "../../../FlowStepData";

/**
 * Generic input checking step that can be configured for any machine input
 * Used by the factory to create input-specific step instances
 * Stores the input NAME - looks up number and text from MachineData at runtime
 */
export class CheckInputStep extends FlowStep {
    get __type(): string { return 'CheckInputStep'; }
    get category(): string[] { return ['Machine', 'IO', 'Inputs']; }

    private inputName: string = '';

    constructor(inputName?: string) {
        super();
        if (inputName !== undefined) {
            this.inputName = inputName;
        }
    }

    /**
     * Set the input name (used by factory)
     */
    public setInputName(inputName: string): void {
        this.inputName = inputName;
    }

    /**
     * Get the input configuration from MachineData by name
     */
    private getInputConfig() {
        const machineData = MachineData.Instance;
        const input = machineData.machineInputs.find(i => i.name === this.inputName);

        if (!input) {
            // Fallback if input not found
            return {
                name: this.inputName || 'Unknown Input',
                number: 0,
                activeText: 'Active',
                inactiveText: 'Inactive'
            };
        }

        return {
            name: input.name,
            number: input.number || 0,
            activeText: input.activeText,
            inactiveText: input.inactiveText
        };
    }

    get name(): string {
        return this.getInputConfig().name;
    }

    get description(): string {
        const config = this.getInputConfig();
        return `Check if ${config.name} is active (${config.activeText}/${config.inactiveText})`;
    }

    get icon(): React.ReactNode {
        return React.createElement(InputIcon, { sx: { color: 'primary.main' } });
    }

    async execute(data: FlowStepData, prototypeRun: boolean): Promise<string | null> {
        const config = this.getInputConfig();

        if (prototypeRun) {
            return Math.random() > 0.5 ? config.activeText : config.inactiveText;
        }

        try {
            const isActive = await Machine.getInstance().io.IsInputActive(config.number);
            data.setVariable(`input${config.number}Active`, isActive);
            data.setVariable(`input${config.number}State`, isActive ? config.activeText : config.inactiveText);
            return isActive ? config.activeText : config.inactiveText;
        } catch (error) {
            Logger.Instance.logError(LogCategory.System, `Check input ${config.number} (${config.name}) failed:`, error);
            // Return inactive text on error
            return config.inactiveText;
        }
    }

    results(): string[] {
        const config = this.getInputConfig();
        return [config.activeText, config.inactiveText];
    }

    renderResultsUI(data: FlowStepData, result: string): React.ReactNode {
        const config = this.getInputConfig();
        return (
            <Typography variant="caption">
                {config.name}: {result}
            </Typography>
        );
    }

    renderEditUI(props: { onClose: () => void }): React.ReactNode {
        const config = this.getInputConfig();
        return (
            <Typography variant="body2" sx={{ p: 2 }}>
                This step checks if "{config.name}" (Input {config.number || 'not configured'}) is in the active state ({config.activeText}).
            </Typography>
        );
    }

    public toJSON(): any {
        const data = DataUtilities.getStorageData(this, ['icon']) as any;
        data.__type = this.__type;
        data.inputName = this.inputName;
        return data;
    }

    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data);
        if (data.inputName !== undefined) {
            this.inputName = data.inputName;
        }
    }
}
