import React, { useState } from 'react';
import { ConfigurationData } from '../../data/ConfigurationData';
import {
  Box,
  TextField,
  Typography,
  Tooltip,
  Paper,
  Popover
} from '@mui/material';

interface ColorPickerProps {
  label?: string;
  value: string;
  onChange: (color: string) => void;
  disabled?: boolean;
  size?: 'small' | 'medium' | 'large';
  showHexInput?: boolean;
}

export const ColorPicker: React.FC<ColorPickerProps> = ({
  label,
  value,
  onChange,
  disabled = false,
  size = 'medium',
  showHexInput = true
}) => {
  const [anchorEl, setAnchorEl] = useState<HTMLElement | null>(null);
  const [tempHex, setTempHex] = useState(value);

  const getSizeValues = () => {
    switch (size) {
      case 'small':
        return { width: 48, height: 24, fontSize: '0.75rem' }; // 2x width for small
      case 'large':
        return { width: 96, height: 48, fontSize: '1rem' }; // 2x width for large
      default:
        return { width: 64, height: 32, fontSize: '0.875rem' }; // 2x width for medium
    }
  };

  const { width, height, fontSize } = getSizeValues();

  const handleColorSquareClick = (event: React.MouseEvent<HTMLElement>) => {
    if (!disabled) {
      setAnchorEl(event.currentTarget);
      setTempHex(value);
    }
  };

  const handleClose = () => {
    setAnchorEl(null);
  };

  const handleColorChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const newColor = event.target.value;
    setTempHex(newColor);
    onChange(newColor);
  };

  const handleHexChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const newHex = event.target.value;
    setTempHex(newHex);
    
    // Validate hex color format
    if (/^#[0-9A-F]{6}$/i.test(newHex) || /^#[0-9A-F]{3}$/i.test(newHex)) {
      onChange(newHex);
    }
  };

  const handleHexBlur = () => {
    // If invalid hex, revert to current value
    if (!/^#[0-9A-F]{6}$/i.test(tempHex) && !/^#[0-9A-F]{3}$/i.test(tempHex)) {
      setTempHex(value);
    }
  };

  const open = Boolean(anchorEl);

  return (
    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
      <Tooltip title={`Click to change color (${value})`} arrow>
        <Box
          onClick={handleColorSquareClick}
          sx={{
            width,
            height,
            backgroundColor: value,
            border: `2px solid ${ConfigurationData.Instance.secondaryBorderColor}`,
            borderRadius: 1,
            cursor: disabled ? 'not-allowed' : 'pointer',
            transition: 'all 0.2s ease',
            opacity: disabled ? 0.5 : 1,
            '&:hover': disabled ? {} : {
              transform: 'scale(1.05)',
              boxShadow: ConfigurationData.Instance.shadowColor
            }
          }}
        />
      </Tooltip>
      
      {label && (
        <Typography variant="body2" sx={{ fontSize }}>
          {label}
        </Typography>
      )}

      <Popover
        open={open}
        anchorEl={anchorEl}
        onClose={handleClose}
        anchorOrigin={{
          vertical: 'bottom',
          horizontal: 'left',
        }}
        transformOrigin={{
          vertical: 'top',
          horizontal: 'left',
        }}
      >
        <Paper sx={{ p: 2, minWidth: 200 }}>
          <Typography variant="subtitle2" gutterBottom>
            Choose Color
          </Typography>
          
          {/* Native color picker */}
          <Box sx={{ mb: 2 }}>
            <input
              type="color"
              value={value}
              onChange={handleColorChange}
              style={{
                width: '100%',
                height: 40,
                border: 'none',
                borderRadius: 4,
                cursor: 'pointer'
              }}
            />
          </Box>

          {/* Hex input */}
          {showHexInput && (
            <TextField
              fullWidth
              label="Hex Color"
              value={tempHex}
              onChange={handleHexChange}
              onBlur={handleHexBlur}
              size="small"
              placeholder="#FFFFFF"
              inputProps={{
                style: { fontFamily: 'monospace' }
              }}
              helperText="Format: #RRGGBB or #RGB"
            />
          )}
        </Paper>
      </Popover>
    </Box>
  );
};
