import React from 'react';
import { Line } from '@react-three/drei';
import { MachineData } from '../../../data/MachineData';
import { ConfigurationData } from '../../../data/ConfigurationData';
import { ObserveMultiProperties } from '../../../utils/statemanager/ObserveMultiProperties';
import { CoordinateUtil } from '../../../utils/CoordinateUtil';
import { CNCPoint } from '../../../data/CNCPoint';
import { CoordinateType } from '../../../data/Common/CoordinateType';

export function MachineHome() {
  const machineData = MachineData.Instance;

  return (
    <ObserveMultiProperties
      listenTo={[
        { object: machineData, properties: ['simulatorLimitsFromMachineBaseTopOriginX', 'simulatorLimitsFromMachineBaseTopOriginY', 'simulatorLimitsFromMachineBaseTopOriginZ', 'machineZeroCoordinatesFromMachineHomeX', 'machineZeroCoordinatesFromMachineHomeY', 'machineZeroCoordinatesFromMachineHomeZ', 'baseHeight', 'crosshairSize', 'crosshairLineWidth'] },
        { object: ConfigurationData.Instance, properties: ['machineHomeColor'] }
      ]}
      control={() => {
        // Get machine home point using MachineHome coordinate type
        // (0,0,0) in MachineHome coordinates represents the machine home corner
        const homePointMachineHome = new CNCPoint(0, 0, 0, CoordinateType.MachineHome);
        const homePoint = CoordinateUtil.toSimulator(homePointMachineHome);
        
        const crosshairSize = MachineData.Instance.crosshairSize; // Use configurable size
        const lineWidth = MachineData.Instance.crosshairLineWidth; // Use configurable line width
        const color = ConfigurationData.Instance.machineHomeColor; // Use configurable color

        return (
          <group>
            {/* X-axis line (green) */}
            <Line
              points={[
                [homePoint.x - crosshairSize, homePoint.y, homePoint.z],
                [homePoint.x + crosshairSize, homePoint.y, homePoint.z]
              ]}
              color={color}
              lineWidth={lineWidth}
            />
            
            {/* Y-axis line (green) */}
            <Line
              points={[
                [homePoint.x, homePoint.y - crosshairSize, homePoint.z],
                [homePoint.x, homePoint.y + crosshairSize, homePoint.z]
              ]}
              color={color}
              lineWidth={lineWidth}
            />
            
            {/* Z-axis line (green) */}
            <Line
              points={[
                [homePoint.x, homePoint.y, homePoint.z - crosshairSize],
                [homePoint.x, homePoint.y, homePoint.z + crosshairSize]
              ]}
              color={color}
              lineWidth={lineWidth}
            />
          </group>
        );
      }}
    />
  );
}
