import { RestartAlt as ResetIcon } from '@mui/icons-material';
import { Box, Button, Typography } from '@mui/material';
import React from 'react';
import { Machine } from '../../../../machine/Machine';
import { DataUtilities } from '../../../../utils/storage/DataUtilities';
import { FlowStep } from "../../../FlowStep";
import { FlowStepData } from "../../../FlowStepData";

export class ResetSpindleSpeedFactorStep extends FlowStep {
    readonly __type = 'ResetSpindleSpeedFactorStep';
    readonly category = ['Machine', 'Spindle'];
    readonly name = 'Reset Spindle Speed Factor';
    readonly description = 'Resets the spindle speed factor back to 1.0 (100%)';
    
    // Icon is created dynamically, not stored
    get icon(): React.ReactNode {
        return React.createElement(ResetIcon, { sx: { color: 'warning.main' } });
    }

    static readonly DONE_PATH = 'done';

    async execute(data: FlowStepData, prototypeRun: boolean): Promise<string | null> {
        if (prototypeRun) {
            return ResetSpindleSpeedFactorStep.DONE_PATH;
        }

        try {
            await Machine.getInstance().spindle.ResetSpindleSpeedFactor();
            return ResetSpindleSpeedFactorStep.DONE_PATH;
        } catch (error) {
            console.error('ResetSpindleSpeedFactor failed:', error);
            return ResetSpindleSpeedFactorStep.DONE_PATH; // Still done, just with error logged
        }
    }

    results(): string[] {
        return [ResetSpindleSpeedFactorStep.DONE_PATH];
    }

    renderResultsUI(data: FlowStepData, result: string): React.ReactNode {
        return (
            <Typography variant="caption">
                Reset spindle speed factor to 1.0 (100%): {result}
            </Typography>
        );
    }

    renderEditUI(props: { onClose: () => void }): React.ReactNode {
        return (
            <Box sx={{ p: 2, minWidth: 300 }}>
                <Typography variant="h6" gutterBottom>Reset Spindle Speed Factor</Typography>
                <Typography variant="body2" color="text.secondary">
                    This step resets the spindle speed adjustment factor back to 1.0 (100% normal speed).
                    Any previous speed adjustments will be cleared.
                </Typography>

                <Box sx={{ mt: 2 }}>
                    <Typography variant="subtitle2" gutterBottom>Effect:</Typography>
                    <Typography variant="body2" sx={{ color: 'warning.main' }}>
                        • Spindle speed factor will be set to 1.0
                    </Typography>
                    <Typography variant="body2" sx={{ color: 'warning.main' }}>
                        • Spindle will return to normal speed
                    </Typography>
                    <Typography variant="body2" sx={{ color: 'warning.main' }}>
                        • All previous adjustments will be cleared
                    </Typography>
                </Box>

                <Box sx={{ display: 'flex', gap: 1, justifyContent: 'flex-end', mt: 2 }}>
                    <Button variant="contained" onClick={props.onClose}>OK</Button>
                </Box>
            </Box>
        );
    }

    public toJSON(): any {
        const data = DataUtilities.getStorageData(this, ['icon']) as any;
        data.__type = this.__type;
        return data;
    }

    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data);
    }
}