import { IStorable } from '../../common/IStorable';
import { DataUtilities } from '../../utils/storage/DataUtilities';

/**
 * Machine Output class
 * Represents a physical output connection from the CNC machine control system
 */
export class MachineOutput implements IStorable {
  private _number: number;
  private _name: string;
  private _centroidMapping?: string;
  private _activeText: string;
  private _inactiveText: string;
  private _use: boolean;

  constructor(
    number: number, 
    name: string = `Output ${number}`, 
    centroidMapping?: string, 
    activeText: string = 'Active',
    inactiveText: string = 'Inactive',
    use: boolean = true
  ) {
    this._number = number;
    this._name = name;
    this._centroidMapping = centroidMapping;
    this._activeText = activeText;
    this._inactiveText = inactiveText;
    this._use = use;
  }

  /**
   * Output number (unique identifier for the physical output)
   */
  public get number(): number {
    return this._number;
  }

  public set number(value: number) {
    this._number = value;
  }

  /**
   * User-defined name for the output
   */
  public get name(): string {
    return this._name;
  }

  public set name(value: string) {
    this._name = value;
  }

  /**
   * Optional mapping to a Centroid control system output name
   */
  public get centroidMapping(): string | undefined {
    return this._centroidMapping;
  }

  public set centroidMapping(value: string | undefined) {
    this._centroidMapping = value;
  }

  /**
   * The triggered state - whether the output is triggered when open or closed
   */
  public get activeText(): string {
    return this._activeText;
  }

  public set activeText(value: string) {
    this._activeText = value;
  }

  /**
   * Text to display when the output is inactive
   */
  public get inactiveText(): string {
    return this._inactiveText;
  }

  public set inactiveText(value: string) {
    this._inactiveText = value;
  }

  /**
   * Whether this output is currently in use/enabled
   */
  public get use(): boolean {
    return this._use;
  }

  public set use(value: boolean) {
    this._use = value;
  }

  /**
   * Get a display-friendly description of the output states
   */
  public get stateDescription(): string {
    return `${this._activeText} / ${this._inactiveText}`;
  }

  /**
   * Check if this output has a Centroid mapping assigned
   */
  public get hasCentroidMapping(): boolean {
    return this._centroidMapping !== undefined;
  }

  /**
   * IStorable implementation
   */
  public toJSON(): object {
    return DataUtilities.getStorageData(this);
  }

  public fromJSON(data: any): void {
    DataUtilities.loadStorageData(this, data);
  }

  /**
   * Create a copy of this output
   */
  public clone(): MachineOutput {
    return new MachineOutput(
      this._number,
      this._name,
      this._centroidMapping,
      this._activeText,
      this._inactiveText,
      this._use
    );
  }

  /**
   * Validate the output configuration
   */
  public validate(): string[] {
    const errors: string[] = [];

    if (this._number < 1) {
      errors.push('Output number must be greater than 0');
    }

    if (!this._name || this._name.trim().length === 0) {
      errors.push('Output name cannot be empty');
    }

    if (!this._activeText || this._activeText.trim().length === 0) {
      errors.push('Active text cannot be empty');
    }

    if (!this._inactiveText || this._inactiveText.trim().length === 0) {
      errors.push('Inactive text cannot be empty');
    }

    return errors;
  }
}
