import {
  Close as CloseIcon,
  Delete as DeleteIcon,
  KeyboardArrowDown as MoveDownIcon,
  KeyboardArrowUp as MoveUpIcon,
  ControlPoint as ResetIcon,
} from '@mui/icons-material';
import {
  Box,
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  IconButton,
  TextField,
  Typography
} from '@mui/material';
import React, { useState } from 'react';
import { ConfigurationData } from '../../data/ConfigurationData';
import type { Flow } from '../../flow/Flow';
import { FlowStep } from '../../flow/FlowStep';

interface StepDetailsDialogProps {
  open: boolean;
  step: FlowStep | null;
  flow?: Flow;
  onClose: () => void;
  onDelete?: (stepId: string) => void;
  onEdit?: (step: FlowStep) => void;
  onMoveUp?: (stepId: string) => void;
  onMoveDown?: (stepId: string) => void;
  onResetPosition?: (stepId: string) => void;
  canMoveUp?: boolean;
  canMoveDown?: boolean;
}

export const StepDetailsDialog: React.FC<StepDetailsDialogProps> = (props) => {
  const {
    open,
    step,
    flow,
    onClose,
    onDelete,
    onMoveUp,
    onMoveDown,
    onResetPosition,
    canMoveUp = false,
    canMoveDown = false,
  } = props;

  // State for editable step name
  const [editingName, setEditingName] = useState(false);
  const [tempName, setTempName] = useState('');

  if (!step) return null;

  const handleDelete = () => {
    if (step.__type !== 'StartStep' && onDelete) {
      onDelete(step.id);
      onClose();
    }
  };

  const handleMoveUp = () => {
    if (onMoveUp) {
      onMoveUp(step.id);
      onClose();
    }
  };

  const handleMoveDown = () => {
    if (onMoveDown) {
      onMoveDown(step.id);
      onClose();
    }
  };

  const handleResetPosition = () => {
    if (onResetPosition && step.isManuallyPositioned) {
      onResetPosition(step.id);
      onClose();
    }
  };

  // Name editing functions
  const handleStartNameEdit = () => {
    setTempName(step.customName || step.name);
    setEditingName(true);
  };

  const handleSaveName = () => {
    const trimmedName = tempName.trim();
    if (trimmedName && trimmedName !== step.name) {
      step.customName = trimmedName;
    } else if (trimmedName === step.name) {
      // If name matches the default, clear custom name
      step.customName = undefined;
    }
    setEditingName(false);
  };

  const handleNameKeyPress = (event: React.KeyboardEvent) => {
    if (event.key === 'Enter') {
      (event.currentTarget as HTMLElement).blur(); // This will trigger onBlur (handleSaveName)
    } else if (event.key === 'Escape') {
      setEditingName(false);
      setTempName('');
    }
  };

  // Check if step has custom edit UI
  const stepEditUI = step.renderEditUI({ onClose, flow, flowStep: step });
  const hasCustomEditUI = stepEditUI !== null;

  return (
    <Dialog
      open={open}
      onClose={onClose}
      maxWidth="md"
      fullWidth
      PaperProps={{
        sx: {
          borderRadius: 2,
          maxHeight: '80vh',
        }
      }}
    >
      <DialogTitle sx={{
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        pb: 1,
        backgroundColor: ConfigurationData.Instance.lightBackgroundColor,
      }}>
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, flex: 1, mr: 2 }}>
          {editingName ? (
            <TextField
              fullWidth
              size="small"
              value={tempName}
              onChange={(e) => setTempName(e.target.value)}
              onBlur={handleSaveName}
              onKeyDown={handleNameKeyPress}
              placeholder={`Custom name (default: ${step.name})`}
              autoFocus
              variant="standard"
              sx={{
                '& .MuiInput-root': {
                  fontSize: '1.25rem',
                  fontWeight: 600,
                },
                '& .MuiInput-input': {
                  padding: '4px 0',
                }
              }}
            />
          ) : (
            <Typography
              variant="h6"
              component="div"
              sx={{
                cursor: 'pointer',
                padding: '4px 8px',
                borderRadius: 1,
                border: '1px solid transparent',
                '&:hover': {
                  backgroundColor: 'action.hover',
                  border: `1px solid ${ConfigurationData.Instance.borderColor}`
                },
                display: 'flex',
                alignItems: 'center',
                gap: 1
              }}
              onClick={handleStartNameEdit}
              title="Click to edit step name"
            >
              Step: {step.getDisplayName()}
              {step.customName && (
                <Typography component="span" variant="caption" color="text.secondary">
                  (custom)
                </Typography>
              )}
            </Typography>
          )}
        </Box>
        <IconButton onClick={onClose} size="small">
          <CloseIcon />
        </IconButton>
      </DialogTitle>

      <DialogContent sx={{ pt: 2 }}>
        {/* Step Description - only show when there's no custom edit UI */}
        {!hasCustomEditUI && step.description && (
          <Box sx={{ mb: 3 }}>
            <Typography variant="body1" color="text.secondary">
              {step.description}
            </Typography>
          </Box>
        )}

        {/* Custom Edit UI */}
        {hasCustomEditUI && (
          <>
            <Box sx={{ mb: 2 }}>
              {stepEditUI}
            </Box>
          </>
        )}
      </DialogContent>

      <DialogActions sx={{
        p: 2,
        backgroundColor: ConfigurationData.Instance.lightBackgroundColor,
        gap: 1,
        flexWrap: 'wrap',
        justifyContent: 'space-between',
      }}>
        {/* Left side - Position and Reset actions */}
        <Box sx={{ display: 'flex', gap: 1 }}>
          {canMoveUp && onMoveUp && (
            <Button
              variant="outlined"
              size="small"
              startIcon={<MoveUpIcon />}
              onClick={handleMoveUp}
              sx={{ minWidth: 'auto' }}
            >
              Move Up
            </Button>
          )}

          {canMoveDown && onMoveDown && (
            <Button
              variant="outlined"
              size="small"
              startIcon={<MoveDownIcon />}
              onClick={handleMoveDown}
              sx={{ minWidth: 'auto' }}
            >
              Move Down
            </Button>
          )}

          {step.isManuallyPositioned && onResetPosition && (
            <Button
              variant="outlined"
              size="small"
              startIcon={<ResetIcon />}
              onClick={handleResetPosition}
              color="info"
              sx={{ minWidth: 'auto' }}
            >
              Reset Position
            </Button>
          )}
        </Box>

        {/* Right side - Main actions */}
        <Box sx={{ display: 'flex', gap: 1 }}>
          {step.__type !== 'StartStep' && onDelete && (
            <Button
              variant="outlined"
              size="small"
              startIcon={<DeleteIcon />}
              onClick={handleDelete}
              color="error"
            >
              Delete
            </Button>
          )}

          <Button onClick={onClose} variant="outlined" size="small">
            Close
          </Button>
        </Box>
      </DialogActions>
    </Dialog>
  );
};
