import {
  Box,
  Card,
  CardContent,
  FormControl,
  Grid,
  InputLabel,
  MenuItem,
  Select,
  Typography
} from '@mui/material';
import { AxisType, MachineData, StepFrequency, getStepFrequencyLabel } from '../../../data/MachineData';
import { ObserveState } from '../../../utils/statemanager/ObserveState';
import { NumberInput } from '../../Common/NumberInput';
import { AxisConfigurationPanel } from './AxisConfigurationPanel';

export function AxisConfigurationTab() {
  return (
    <ObserveState
      key="axis-configuration-tab"
      listenTo={MachineData.Instance}
      properties={['axisConfigurations', 'stepFrequency', 'driveFaultDelay']}
      control={() => {
        const machineData = MachineData.Instance;

        return (
          <Box sx={{ p: 3 }}>
            <Box sx={{ mb: 3 }}>
              <Typography variant="h5" gutterBottom>
                Axis Configuration
              </Typography>
              <Typography variant="body2" color="text.secondary">
                Configure the 6 machine axes. Each axis can be configured for linear or rotary motion with specific motion parameters.
              </Typography>
            </Box>

            {/* Global Machine Settings */}
            <Card sx={{ mb: 3, bgcolor: 'primary.50', border: '2px solid', borderColor: 'primary.200' }}>
              <CardContent>
                <Typography variant="h6" gutterBottom sx={{ color: 'primary.main' }}>
                  Global System Configuration
                </Typography>
                <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                  These settings apply to all axes globally.
                </Typography>
                <Grid container spacing={3}>
                  <Grid item xs={12} md={6}>
                    <FormControl fullWidth>
                      <InputLabel>Step Frequency</InputLabel>
                      <Select
                        value={machineData.stepFrequency}
                        label="Step Frequency"
                        onChange={(e) => {
                          machineData.stepFrequency = e.target.value as StepFrequency;
                        }}
                      >
                        <MenuItem value={StepFrequency.Freq100k}>{getStepFrequencyLabel(StepFrequency.Freq100k)}</MenuItem>
                        <MenuItem value={StepFrequency.Freq200k}>{getStepFrequencyLabel(StepFrequency.Freq200k)}</MenuItem>
                        <MenuItem value={StepFrequency.Freq240k}>{getStepFrequencyLabel(StepFrequency.Freq240k)}</MenuItem>
                        <MenuItem value={StepFrequency.Freq300k}>{getStepFrequencyLabel(StepFrequency.Freq300k)}</MenuItem>
                        <MenuItem value={StepFrequency.Freq400k}>{getStepFrequencyLabel(StepFrequency.Freq400k)}</MenuItem>
                      </Select>
                    </FormControl>
                  </Grid>
                  <Grid item xs={12} md={6}>
                    <NumberInput
                      fullWidth
                      label="Drive Fault Delay (ms)"
                      value={machineData.driveFaultDelay}
                      onChange={(value) => {
                        machineData.driveFaultDelay = value || 250;
                      }}
                      min={0}
                      precision={0}
                    />
                  </Grid>
                </Grid>
              </CardContent>
            </Card>

            <Grid container spacing={3}>
              {machineData.axisConfigurations.map((axis, index) => (
                <Grid item xs={12} key={index}>
                  <Card
                    sx={{
                      bgcolor: axis.axisType === AxisType.Unset ? 'grey.50' : 'background.paper',
                      border: axis.axisType === AxisType.Unset ? '1px dashed' : '1px solid',
                      borderColor: axis.axisType === AxisType.Unset ? 'grey.300' : 'divider'
                    }}
                  >
                    <CardContent>
                      <AxisConfigurationPanel axis={axis} axisIndex={index} />
                    </CardContent>
                  </Card>
                </Grid>
              ))}
            </Grid>
          </Box>
        );
      }}
    />
  );
}
