import { Stop as StopIcon } from '@mui/icons-material';
import { Typography } from '@mui/material';
import React from 'react';
import { Machine } from '../../../../machine/Machine';
import { LogCategory, Logger } from '../../../../utils/Logger';
import { DataUtilities } from '../../../../utils/storage/DataUtilities';
import { FlowStep } from "../../../FlowStep";
import { FlowStepData } from "../../../FlowStepData";

export class StopSpindleStep extends FlowStep {
    readonly __type = 'StopSpindleStep';
    readonly category = ['Machine', 'Spindle'];
    readonly name = 'Stop Spindle';
    readonly description = 'Stops the spindle rotation';
    
    // Icon is created dynamically, not stored
    get icon(): React.ReactNode {
        return React.createElement(StopIcon, { sx: { color: 'error.main' } });
    }

    static readonly DONE_PATH = 'done';

    async execute(data: FlowStepData, prototypeRun: boolean): Promise<string | null> {
        if (prototypeRun) {
            return StopSpindleStep.DONE_PATH;
        }

        try {
            await Machine.getInstance().spindle.StopSpindle();
            return StopSpindleStep.DONE_PATH;
        } catch (error) {
            Logger.Instance.logError(LogCategory.System, 'StopSpindle failed:', error);
            return StopSpindleStep.DONE_PATH; // Still done, just with error logged
        }
    }

    results(): string[] {
        return [StopSpindleStep.DONE_PATH];
    }

    renderResultsUI(data: FlowStepData, result: string): React.ReactNode {
        return (
            <Typography variant="caption">
                Stop spindle: {result}
            </Typography>
        );
    }

    public toJSON(): any {
        const data = DataUtilities.getStorageData(this, ['icon']) as any;
        data.__type = this.__type;
        return data;
    }

    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data);
    }
}





