import { Error as ErrorIcon } from '@mui/icons-material';
import { Typography } from '@mui/material';
import React from 'react';
import { Machine } from '../../../../machine/Machine';
import { LogCategory, Logger } from '../../../../utils/Logger';
import { DataUtilities } from '../../../../utils/storage/DataUtilities';
import { FlowStep } from "../../../FlowStep";
import { FlowStepData } from "../../../FlowStepData";

export class GetCurrentErrorStateStep extends FlowStep {
    readonly __type = 'GetCurrentErrorStateStep';
    readonly category = ['Machine', 'System'];
    readonly name = 'Get Current Error State';
    readonly description = 'Retrieves the current error state of the machine';
    
    // Icon is created dynamically, not stored
    get icon(): React.ReactNode {
        return React.createElement(ErrorIcon, { sx: { color: 'error.main' } });
    }
    static readonly SUCCESS_PATH = 'success';
    async execute(data: FlowStepData, prototypeRun: boolean): Promise<string | null> {
        if (prototypeRun) {
            //Logger.Instance.log(LogCategory.System, 'Prototype: Get current error state');
            data.setVariable('errorState', null);
            return GetCurrentErrorStateStep.SUCCESS_PATH;
        }

        try {
            const errorState = await Machine.getInstance().system.GetCurrentErrorState();
            data.setVariable('errorState', errorState);
            //Logger.Instance.log(LogCategory.System, `Error state: ${errorState ? errorState.join(', ') : 'No errors'}`);
            return GetCurrentErrorStateStep.SUCCESS_PATH;
        } catch (error) {
            Logger.Instance.logError(LogCategory.System, 'Get current error state failed:', error);
            // Still return success with fallback value - the step completed its attempt
            data.setVariable('errorState', null);
            return GetCurrentErrorStateStep.SUCCESS_PATH;
        }
    }

    results(): string[] {
        return [GetCurrentErrorStateStep.SUCCESS_PATH];
    }

    renderResultsUI(data: FlowStepData, result: string): React.ReactNode {
        const errorState = data.getVariable('errorState') as string[] | null;
        const errorCount = errorState ? errorState.length : 0;
        return (
            <Typography variant="caption">
                Error state ({errorCount} errors): {result}
            </Typography>
        );
    }

    public toJSON(): any {
        const data = DataUtilities.getStorageData(this, ['icon']) as any;
        data.__type = this.__type;
        return data;
    }

    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data);
    }
}






