import React, { useState, useEffect, useCallback } from 'react';
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  Typography,
  Box,
  CircularProgress,
  Link,
  Stepper,
  Step,
  StepLabel,
  Alert
} from '@mui/material';
import { Search as SearchIcon, CheckCircle as CheckCircleIcon } from '@mui/icons-material';
import { MachineInput } from '../../data/Machine/MachineInput';

interface FindInputDialogProps {
  open: boolean;
  input: MachineInput | null;
  onClose: () => void;
  onConfirm: (input: MachineInput, detectedNumber: number) => void;
}

enum FindInputStep {
  Instructions = 0,
  Detecting = 1,
  Confirmation = 2
}

export function FindInputDialog({ open, input, onClose, onConfirm }: FindInputDialogProps) {
  const [currentStep, setCurrentStep] = useState(FindInputStep.Instructions);
  const [detectedNumber, setDetectedNumber] = useState<number | null>(null);
  const [countdown, setCountdown] = useState(5);

  // Reset state when dialog opens/closes
  useEffect(() => {
    if (open) {
      setCurrentStep(FindInputStep.Instructions);
      setDetectedNumber(null);
      setCountdown(5);
    }
  }, [open]);

  // Countdown timer for detection simulation
  useEffect(() => {
    let timer: NodeJS.Timeout;
    
    if (currentStep === FindInputStep.Detecting && countdown > 0) {
      timer = setTimeout(() => {
        setCountdown(prev => prev - 1);
      }, 1000);
    } else if (currentStep === FindInputStep.Detecting && countdown === 0) {
      // Simulate detection - generate a random input number for testing
      const simulatedNumber = Math.floor(Math.random() * 16) + 1; // Random number 1-16
      setDetectedNumber(simulatedNumber);
      setCurrentStep(FindInputStep.Confirmation);
    }

    return () => {
      if (timer) clearTimeout(timer);
    };
  }, [currentStep, countdown]);

  const handleStartDetection = useCallback(() => {
    setCurrentStep(FindInputStep.Detecting);
    setCountdown(5);
  }, []);

  const handleConfirmDetection = useCallback(() => {
    if (input && detectedNumber !== null) {
      onConfirm(input, detectedNumber);
    }
  }, [input, detectedNumber, onConfirm]);

  const handleClose = useCallback(() => {
    setCurrentStep(FindInputStep.Instructions);
    setDetectedNumber(null);
    setCountdown(5);
    onClose();
  }, [onClose]);

  if (!input) return null;

  const steps = ['Instructions', 'Detecting Input', 'Confirm Assignment'];

  return (
    <Dialog open={open} onClose={handleClose} maxWidth="md" fullWidth>
      <DialogTitle>
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
          <SearchIcon />
          Find Input: {input.name}
        </Box>
      </DialogTitle>
      
      <DialogContent>
        <Box sx={{ mb: 3 }}>
          <Stepper activeStep={currentStep} alternativeLabel>
            {steps.map((label) => (
              <Step key={label}>
                <StepLabel>{label}</StepLabel>
              </Step>
            ))}
          </Stepper>
        </Box>

        {currentStep === FindInputStep.Instructions && (
          <Box>
            <Typography variant="h6" sx={{ mb: 2 }}>
              Instructions
            </Typography>
            <Typography variant="body1" sx={{ mb: 2 }}>
              This process will help you identify which physical input number corresponds to "{input.name}".
            </Typography>
            
            <Alert severity="info" sx={{ mb: 2 }}>
              <Typography variant="body2">
                <strong>What you need to do:</strong>
              </Typography>
              <Typography variant="body2" component="ol" sx={{ mt: 1, pl: 2 }}>
                <li>Click "Start Detection" below</li>
                <li>When prompted, trigger the physical input (close/open the switch)</li>
                <li>The system will detect which input number changed</li>
                <li>Confirm the detected number to assign it to this input</li>
              </Typography>
            </Alert>

            <Box sx={{ p: 2, backgroundColor: 'background.paper', border: '1px solid', borderColor: 'divider', borderRadius: 1 }}>
              <Typography variant="body2" sx={{ mb: 1 }}>
                <strong>Need help triggering an input?</strong>
              </Typography>
              <Link 
                href="https://example.com/input-triggering-guide" 
                target="_blank" 
                rel="noopener noreferrer"
                sx={{ fontSize: '0.875rem' }}
              >
                📹 Watch: How to Trigger Machine Inputs
              </Link>
            </Box>
          </Box>
        )}

        {currentStep === FindInputStep.Detecting && (
          <Box sx={{ textAlign: 'center' }}>
            <Typography variant="h6" sx={{ mb: 2 }}>
              Detecting Input...
            </Typography>
            
            <Box sx={{ mb: 3 }}>
              <CircularProgress size={60} />
            </Box>
            
            <Typography variant="h4" sx={{ mb: 2, color: 'primary.main' }}>
              {countdown}
            </Typography>
            
            <Typography variant="body1" sx={{ mb: 2 }}>
              Please trigger the "{input.name}" input now
            </Typography>
            
            <Alert severity="warning">
              <Typography variant="body2">
                Make sure only the "{input.name}" input is triggered during detection to ensure accurate results.
              </Typography>
            </Alert>
          </Box>
        )}

        {currentStep === FindInputStep.Confirmation && detectedNumber !== null && (
          <Box sx={{ textAlign: 'center' }}>
            <Typography variant="h6" sx={{ mb: 2 }}>
              Input Detected!
            </Typography>
            
            <Box sx={{ display: 'flex', justifyContent: 'center', mb: 3 }}>
              <CheckCircleIcon sx={{ fontSize: 60, color: 'success.main' }} />
            </Box>
            
            <Typography variant="h3" sx={{ mb: 2, color: 'success.main', fontWeight: 'bold' }}>
              {detectedNumber}
            </Typography>
            
            <Typography variant="body1" sx={{ mb: 2 }}>
              The system detected input number <strong>{detectedNumber}</strong> was triggered.
            </Typography>
            
            <Alert severity="success" sx={{ mb: 2 }}>
              <Typography variant="body2">
                Click "Confirm Assignment" to assign input number {detectedNumber} to "{input.name}".
              </Typography>
            </Alert>
            
            <Typography variant="body2" color="text.secondary">
              If this doesn't look correct, click "Cancel" and try again.
            </Typography>
          </Box>
        )}
      </DialogContent>
      
      <DialogActions>
        <Button onClick={handleClose}>
          {currentStep === FindInputStep.Confirmation ? 'Cancel' : 'Close'}
        </Button>
        
        {currentStep === FindInputStep.Instructions && (
          <Button 
            onClick={handleStartDetection}
            variant="contained"
            startIcon={<SearchIcon />}
          >
            Start Detection
          </Button>
        )}
        
        {currentStep === FindInputStep.Confirmation && (
          <Button 
            onClick={handleConfirmDetection}
            variant="contained"
            color="success"
            startIcon={<CheckCircleIcon />}
          >
            Confirm Assignment
          </Button>
        )}
      </DialogActions>
    </Dialog>
  );
}
