import { Input as InputIcon } from '@mui/icons-material';
import { Box, TextField, Typography } from '@mui/material';
import React from 'react';
import { Machine } from '../../../../machine/Machine';
import { LogCategory, Logger } from '../../../../utils/Logger';
import { DataUtilities } from '../../../../utils/storage/DataUtilities';
import { FlowStep } from "../../../FlowStep";
import { FlowStepData } from "../../../FlowStepData";

export class IsInputActiveStep extends FlowStep {
    readonly __type = 'IsInputActiveStep';
    readonly category = ['Machine', 'IO'];
    readonly name = 'Is Input Active';
    readonly description = 'Checks if specific input is active';
    
    // Icon is created dynamically, not stored
    get icon(): React.ReactNode {
        return React.createElement(InputIcon, { sx: { color: 'primary.main' } });
    }

    public inputNumber: number = 1;

    static readonly TRUE_PATH = 'true';
    static readonly FALSE_PATH = 'false';
    static readonly ERROR_PATH = 'error';

    async execute(data: FlowStepData, prototypeRun: boolean): Promise<string | null> {
        if (prototypeRun) {
            //Logger.Instance.log(LogCategory.System, `Prototype: Check input ${this.inputNumber}`);
            return Math.random() > 0.5 ? IsInputActiveStep.TRUE_PATH : IsInputActiveStep.FALSE_PATH;
        }

        try {
            const isActive = await Machine.getInstance().io.IsInputActive(this.inputNumber);
            data.setVariable('inputActive', isActive);
            //Logger.Instance.log(LogCategory.System, `Input ${this.inputNumber} is ${isActive ? 'active' : 'inactive'}`);
            return isActive ? IsInputActiveStep.TRUE_PATH : IsInputActiveStep.FALSE_PATH;
        } catch (error) {
            Logger.Instance.logError(LogCategory.System, 'Check input failed:', error);
            return IsInputActiveStep.ERROR_PATH;
        }
    }

    results(): string[] {
        return [IsInputActiveStep.TRUE_PATH, IsInputActiveStep.FALSE_PATH, IsInputActiveStep.ERROR_PATH];
    }

    renderResultsUI(data: FlowStepData, result: string): React.ReactNode {
        return (
            <Typography variant="caption">
                Input {this.inputNumber}: {result}
            </Typography>
        );
    }

    renderEditUI(props: { onClose: () => void }): React.ReactNode {
        const EditUI = () => {
            const [inputNumber, setInputNumber] = React.useState(this.inputNumber);

            // Update the instance when the local state changes
            React.useEffect(() => {
                this.inputNumber = inputNumber;
            }, [inputNumber]);

            return (
                <Box sx={{ p: 2, minWidth: 300 }}>
                    <TextField
                        label="Input Number"
                        type="number"
                        value={inputNumber}
                        onChange={(e) => setInputNumber(parseInt(e.target.value) || 1)}
                        fullWidth
                        margin="normal"
                        inputProps={{ min: 1 }}
                    />
                </Box>
            );
        };

        return <EditUI />;
    }

    public toJSON(): any {
        const data = DataUtilities.getStorageData(this, ['icon']) as any;
        data.__type = this.__type;
        return data;
    }

    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data);
    }
}






