import React from 'react';
import { Grid, Typography, Paper, Button } from '@mui/material';
import { NumberInput } from './NumberInput';
import { ATCToolClamp } from '../../data/MachineData';
import { MachineStateData } from '../../data/MachineStateData';

interface ATCToolClampComponentProps {
  toolClamp: ATCToolClamp;
  onChange: () => void;
}

export function ATCToolClampComponent({
  toolClamp,
  onChange
}: ATCToolClampComponentProps) {
  
  const handleSetXY = () => {
    const machineState = MachineStateData.Instance;
    toolClamp.offsetX = machineState.currentMachinePoint.x;
    toolClamp.offsetY = machineState.currentMachinePoint.y;
    onChange();
  };

  const handleSetXYZ = () => {
    const machineState = MachineStateData.Instance;
    toolClamp.offsetX = machineState.currentMachinePoint.x;
    toolClamp.offsetY = machineState.currentMachinePoint.y;
    toolClamp.offsetZ = machineState.currentMachinePoint.z;
    onChange();
  };

  return (
    <Grid item xs={12}>
      <Paper elevation={1} sx={{ p: 2, mb: 1 }}>
        <Grid container spacing={2} alignItems="center">
          <Grid item xs={12} md={2}>
            <Typography variant="subtitle2">
              Tool {toolClamp.clampNumber}
            </Typography>
          </Grid>
          
          <Grid item xs={12} md={3}>
            <NumberInput
              fullWidth
              label="X Offset (mm)"
              value={toolClamp.offsetX}
              onChange={(value) => {
                toolClamp.offsetX = value;
                onChange();
              }}
              margin="normal"
              precision={3}
              size="small"
            />
          </Grid>
          
          <Grid item xs={12} md={3}>
            <NumberInput
              fullWidth
              label="Y Offset (mm)"
              value={toolClamp.offsetY}
              onChange={(value) => {
                toolClamp.offsetY = value;
                onChange();
              }}
              margin="normal"
              precision={3}
              size="small"
            />
          </Grid>
          
          <Grid item xs={12} md={2}>
            <NumberInput
              fullWidth
              label="Z Offset (mm)"
              value={toolClamp.offsetZ}
              onChange={(value) => {
                toolClamp.offsetZ = value;
                onChange();
              }}
              margin="normal"
              precision={3}
              size="small"
            />
          </Grid>

          <Grid item xs={12} md={2} sx={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
            <Button 
              variant="outlined" 
              size="small"
              onClick={handleSetXY}
            >
              Set XY
            </Button>
            <Button 
              variant="outlined" 
              size="small"
              onClick={handleSetXYZ}
            >
              Set XYZ
            </Button>
          </Grid>
        </Grid>
      </Paper>
    </Grid>
  );
}
