import { SignalRStateData } from '../data/SignalRStateData';
import { ICNCSystem } from '../machine/ICNCSystem';
import { Machine, SystemStatus } from '../machine/Machine';
import { CNCSystemApi } from '../services/src/apis/CNCSystemApi';
import { LogCategory, Logger } from '../utils/Logger';
import { MachineInterfaceManager } from '../utils/MachineInterfaceManager';
import { MachineData } from '../data/MachineData';


export class CentroidCNCSystem implements ICNCSystem {
  private readonly api: CNCSystemApi;

  constructor() {
    const config = MachineInterfaceManager.Instance.getServiceConfiguration();
    this.api = new CNCSystemApi(config || undefined);
  }

  async exit(): Promise<void> {
    try {
      await this.api.apiCNCSystemExitPost();
      Logger.Instance.log(LogCategory.System, 'System exit initiated');
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Failed to exit system:', error);
      throw error;
    }
  }

  async GetSystemStatus(): Promise<SystemStatus> {
    try {
      Logger.Instance.log(LogCategory.System, 'Attempting to call apiCNCSystemStatusGet...');
      Logger.Instance.log(LogCategory.System, 'Expected endpoint: /api/CNCSystem/Status');

      const response = await this.api.apiCNCSystemStatusGet();
      Logger.Instance.log(LogCategory.System, 'Retrieved system status successfully:', response);
      return response;
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Failed to get system status - error details:', error);

      // Log additional error information
      if (error && typeof error === 'object') {
        Logger.Instance.logError(LogCategory.System, 'Error type:', typeof error);
        Logger.Instance.logError(LogCategory.System, 'Error constructor:', error.constructor?.name);
        Logger.Instance.logError(LogCategory.System, 'Error message:', (error as any).message);
        Logger.Instance.logError(LogCategory.System, 'Error status:', (error as any).status);
        Logger.Instance.logError(LogCategory.System, 'Error response:', (error as any).response);
        Logger.Instance.logError(LogCategory.System, 'Error stack:', (error as any).stack);
      }

      throw error;
    }
  }

  async shutdown(): Promise<void> {
    try {
      await this.api.apiCNCSystemShutdownPost();
      Logger.Instance.log(LogCategory.System, 'System shutdown initiated');
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Failed to shutdown system:', error);
      throw error;
    }
  }

  async restartCentroid(): Promise<void> {
    try {
      await this.api.apiCNCSystemRestartCentroidPost();
      Logger.Instance.log(LogCategory.System, 'Centroid system restarted');
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Failed to restart Centroid:', error);
      throw error;
    }
  }

  async EmergencyStop(): Promise<void> {
    try {
      await this.api.apiCNCSystemEmergencyStopPost();
      Logger.Instance.log(LogCategory.System, 'Emergency stop activated');
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Failed to activate emergency stop:', error);
      throw error;
    }
  }

  async IsHomed(): Promise<boolean> {
    try {
      const response = await this.api.apiCNCSystemIsHomedGet();
      // API returns AxiosResponse with data property containing the boolean
      return (response as any).data === true;
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Failed to check homing status:', error);
      throw error;
    }
  }

  async UnhomeMachine(): Promise<void> {
    throw new Error('UnhomeMachine not implemented - will be implemented with G-code commands in Centroid');
  }

  async HomeMachine(): Promise<void> {
    Logger.Instance.log(LogCategory.System, '🏠 HomeMachine() method called - ENTRY POINT');
    Logger.Instance.log(LogCategory.System, 'Stack trace:', new Error().stack);

    try {
      Logger.Instance.log(LogCategory.System, 'Starting machine homing sequence...');
      // Get MachineData for future homing logic
      const machineData = MachineData.Instance;
      Logger.Instance.log(LogCategory.System, 'Got MachineData.Instance', machineData);
      
      const gcodeLines: string[] = [];
      Logger.Instance.log(LogCategory.System, 'Initialized gcodeLines array');

      // TEMPORARY DEBUG: Send simple G0 command instead of homing
      gcodeLines.push('G0 X5');
      Logger.Instance.log(LogCategory.System, 'DEBUG: Sending test G0 X5 command instead of homing');
      Logger.Instance.log(LogCategory.System, 'gcodeLines array:', gcodeLines);

      /* COMMENTED OUT FOR DEBUGGING
      // Check if using manual homing mode
      const useManualHoming = machineData.manuallyHomeMachine;

      // Build G-code for each configured axis
      for (const axis of machineData.axisConfigurations) {
        if (axis.axisType !== AxisType.Unset && axis.homingDirection !== HomingDirection.DoNotHome) {
          const axisLetter = axis.axisType.toString().charAt(0); // X, Y, Z, A, etc.
          
          if (!useManualHoming) {
            // Automatic mode: run homing routine with M91/M92
            const mCode = axis.homingDirection === HomingDirection.Plus ? 'M92' : 'M91';
            gcodeLines.push(`${mCode}/${axisLetter} F${axis.homingFeedrate}`);
          }
        }
      }

      // Add M26 commands at the end for all axes
      for (const axis of machineData.axisConfigurations) {
        if (axis.axisType !== AxisType.Unset && axis.homingDirection !== HomingDirection.DoNotHome) {
          const axisLetter = axis.axisType.toString().charAt(0);
          gcodeLines.push(`M26/${axisLetter}`);
        }
      }
      */

      if (gcodeLines.length === 0) {
        Logger.Instance.log(LogCategory.System, 'No axes configured for homing');
        return;
      }

      // Send all homing commands
      Logger.Instance.log(LogCategory.System, `Sending test G-code commands:`);
      gcodeLines.forEach((line, index) => {
        Logger.Instance.log(LogCategory.System, `  [${index + 1}] ${line}`);
      });

      Logger.Instance.log(LogCategory.System, 'About to call Machine.getInstance()...');
      const machine = Machine.getInstance();
      Logger.Instance.log(LogCategory.System, 'Got Machine instance:', machine);
      Logger.Instance.log(LogCategory.System, 'Machine.program:', machine.program);

      Logger.Instance.log(LogCategory.System, 'About to call machine.program.RunGCode with:', gcodeLines);
      await machine.program.RunGCode(gcodeLines, true);
      Logger.Instance.log(LogCategory.System, '✓ RunGCode returned successfully');
      Logger.Instance.log(LogCategory.System, 'API call completed successfully');

      Logger.Instance.log(LogCategory.System, 'Machine homing sequence completed');
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Failed to home machine:', error);

      // Log detailed error information
      if (error && typeof error === 'object') {
        Logger.Instance.logError(LogCategory.System, 'Error details - type:', typeof error);
        Logger.Instance.logError(LogCategory.System, 'Error details - name:', (error as any).name);
        Logger.Instance.logError(LogCategory.System, 'Error details - message:', (error as any).message);
        Logger.Instance.logError(LogCategory.System, 'Error details - status:', (error as any).status);
        Logger.Instance.logError(LogCategory.System, 'Error details - statusText:', (error as any).statusText);
        Logger.Instance.logError(LogCategory.System, 'Error details - response:', (error as any).response);
        Logger.Instance.logError(LogCategory.System, 'Error details - response.status:', (error as any).response?.status);
        Logger.Instance.logError(LogCategory.System, 'Error details - response.statusText:', (error as any).response?.statusText);
        Logger.Instance.logError(LogCategory.System, 'Error details - response.data:', (error as any).response?.data);
        Logger.Instance.logError(LogCategory.System, 'Error details - stack:', (error as any).stack);
      }

      throw error;
    }
  }

  async GetCurrentErrorState(): Promise<string[] | null> {
    try {
      const response = await this.api.apiCNCSystemGetCurrentErrorStateGet();
      // API returns AxiosResponse with data property containing the error array
      return (response as any).data || null;
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Failed to get current error state:', error);
      throw error;
    }
  }

  async ResetErrorState(): Promise<void> {
    try {
      await this.api.apiCNCSystemResetErrorStatePost();
      Logger.Instance.log(LogCategory.System, 'Error state reset');
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Failed to reset error state:', error);
      throw error;
    }
  }

  async ResetMachine(): Promise<void> {
    try {
      await this.api.apiCNCSystemResetMachinePost();
      Logger.Instance.log(LogCategory.System, 'Machine reset complete');
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Failed to reset machine:', error);
      throw error;
    }
  }

  async HasCurrentErrors(): Promise<boolean> {
    try {
      const response = await this.api.apiCNCSystemHasCurrentErrorsGet();
      // API returns AxiosResponse with data property containing the boolean
      return (response as any).data === true;
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Failed to check error status:', error);
      throw error;
    }
  }

  async IsConnectedToServer(): Promise<boolean> {
    try {
      console.log('[CentroidCNCSystem] IsConnectedToServer() - Starting checks...');
      
      // Check both API connection and SignalR connection
      console.log('[CentroidCNCSystem] Calling API: apiCNCSystemIsConnectedToCentroidGet...');
      const apiResponse = await this.api.apiCNCSystemIsConnectedToCentroidGet();
      console.log('[CentroidCNCSystem] API response received:', apiResponse);
      console.log('[CentroidCNCSystem] API response type:', typeof apiResponse);
      console.log('[CentroidCNCSystem] API response.data:', (apiResponse as any).data);
      
      // The API might return the boolean directly or wrapped in .data
      const isApiConnected = apiResponse === true || (apiResponse as any).data === true;
      console.log('[CentroidCNCSystem] API connected status:', isApiConnected);
      
      const isSignalRConnected = SignalRStateData.Instance.isConnected;
      console.log('[CentroidCNCSystem] SignalR connected status:', isSignalRConnected);
      console.log('[CentroidCNCSystem] SignalR connection state:', SignalRStateData.Instance.connectionState);
      
      const bothConnected = isApiConnected && isSignalRConnected;
      console.log(`[CentroidCNCSystem] Final result: ${bothConnected} (API=${isApiConnected}, SignalR=${isSignalRConnected})`);

      // Return true only if both connections are established
      return bothConnected;
    } catch (error) {
      console.error('[CentroidCNCSystem] ❌ Error checking server connection:', error);
      Logger.Instance.logError(LogCategory.System, 'Failed to check server connection:', error);
      
      // Log detailed error information
      if (error && typeof error === 'object') {
        console.error('[CentroidCNCSystem] Error details:', {
          message: (error as any).message,
          status: (error as any).status,
          response: (error as any).response
        });
      }
      
      // If API call fails, we're definitely not connected
      return false;
    }
  }
}