import { IStorable } from '../../common/IStorable';
import { StateManager } from '../../utils/statemanager/StateManager';
import { DataUtilities } from '../../utils/storage/DataUtilities';
import { InputActiveColor } from './InputActiveColor';
import { InputTriggeredState } from './InputTriggeredState';

/**
 * Machine Input class
 * Represents a physical input connection to the CNC machine control system
 */
export class MachineInput implements IStorable {
  private _number: number | null;
  private _name: string;
  private _centroidMapping?: string;
  private _activeState: InputTriggeredState;
  private _activeText: string;
  private _inactiveText: string;
  private _use: boolean;
  private _activeColor: InputActiveColor;
  private _isManuallyTestable: boolean;

  constructor(
    number: number | null = null, 
    name: string = 'New Input', 
    centroidMapping?: string, 
    activeState: InputTriggeredState = InputTriggeredState.Closed,
    activeText: string = 'Active',
    inactiveText: string = 'Inactive',
    use: boolean = true,
    activeColor: InputActiveColor = InputActiveColor.Red,
    isManuallyTestable: boolean = true
  ) {
    this._number = number;
    this._name = name;
    this._centroidMapping = centroidMapping;
    this._activeState = activeState;
    this._activeText = activeText;
    this._inactiveText = inactiveText;
    this._use = use;
    this._activeColor = activeColor;
    this._isManuallyTestable = isManuallyTestable;
  }

  /**
   * Input number (unique identifier for the physical input)
   */
  public get number(): number | null {
    return this._number;
  }

  public set number(value: number | null) {
    this._number = value;
  }

  /**
   * User-defined name for the input
   */
  public get name(): string {
    return this._name;
  }

  public set name(value: string) {
    this._name = value;
  }

  /**
   * Optional mapping to a Centroid control system input name
   */
  public get centroidMapping(): string | undefined {
    return this._centroidMapping;
  }

  public set centroidMapping(value: string | undefined) {
    this._centroidMapping = value;
  }

  /**
   * The active state - whether the input is active when open or closed
   */
  public get activeState(): InputTriggeredState {
    return this._activeState;
  }

  public set activeState(value: InputTriggeredState) {
    this._activeState = value;
  }

  /**
   * Text to display when the input is active
   */
  public get activeText(): string {
    return this._activeText;
  }

  public set activeText(value: string) {
    this._activeText = value;
    StateManager.propertyChanged(this, 'activeText');
  }

  /**
   * Text to display when the input is inactive
   */
  public get inactiveText(): string {
    return this._inactiveText;
  }

  public set inactiveText(value: string) {
    this._inactiveText = value;
    StateManager.propertyChanged(this, 'inactiveText');
  }

  // Backward compatibility properties
  public get openText(): string {
    return this._activeState === InputTriggeredState.Open ? this._activeText : this._inactiveText;
  }

  public set openText(value: string) {
    if (this._activeState === InputTriggeredState.Open) {
      this.activeText = value;
    } else {
      this.inactiveText = value;
    }
  }

  public get closedText(): string {
    return this._activeState === InputTriggeredState.Closed ? this._activeText : this._inactiveText;
  }

  public set closedText(value: string) {
    if (this._activeState === InputTriggeredState.Closed) {
      this.activeText = value;
    } else {
      this.inactiveText = value;
    }
  }

  // Backward compatibility for triggeredState
  public get triggeredState(): InputTriggeredState {
    return this._activeState;
  }

  public set triggeredState(value: InputTriggeredState) {
    this._activeState = value;
  }

  // Backward compatibility for triggeredStateDescription
  public get triggeredStateDescription(): string {
    return this.activeStateDescription;
  }

  /**
   * Whether this input is currently in use/enabled
   */
  public get use(): boolean {
    return this._use;
  }

  public set use(value: boolean) {
    this._use = value;
  }

  /**
   * The color to display when this input is active
   */
  public get activeColor(): InputActiveColor {
    return this._activeColor;
  }

  public set activeColor(value: InputActiveColor) {
    this._activeColor = value;
  }

  /**
   * Whether this input can be manually tested/overridden for testing purposes
   */
  public get isManuallyTestable(): boolean {
    return this._isManuallyTestable;
  }

  public set isManuallyTestable(value: boolean) {
    this._isManuallyTestable = value;
  }

  /**
   * Get a display-friendly description of the active state
   */
  public get activeStateDescription(): string {
    return this._activeState === InputTriggeredState.Closed ? 
      `${this._inactiveText} (Normally Open)` : 
      `${this._activeText} (Normally Closed)`;
  }

  /**
   * Check if this input has a Centroid mapping assigned
   */
  public get hasCentroidMapping(): boolean {
    return this._centroidMapping !== undefined;
  }

  /**
   * IStorable implementation
   */
  public toJSON(): object {
    return DataUtilities.getStorageData(this);
  }

  public fromJSON(data: any): void {
    DataUtilities.loadStorageData(this, data);
  }

  /**
   * Create a copy of this input
   */
  public clone(): MachineInput {
    return new MachineInput(
      this._number,
      this._name,
      this._centroidMapping,
      this._activeState,
      this._activeText,
      this._inactiveText,
      this._use,
      this._activeColor,
      this._isManuallyTestable
    );
  }

  /**
   * Validate the input configuration
   */
  public validate(): string[] {
    const errors: string[] = [];

    if (this._number !== null && this._number < 1) {
      errors.push('Input number must be greater than 0');
    }

    if (!this._name || this._name.trim().length === 0) {
      errors.push('Input name cannot be empty');
    }

    if (!this._activeText || this._activeText.trim().length === 0) {
      errors.push('Active text cannot be empty');
    }

    if (!this._inactiveText || this._inactiveText.trim().length === 0) {
      errors.push('Inactive text cannot be empty');
    }

    return errors;
  }
}
