import { IStorable } from "../common/IStorable";
import { DataUtilities } from "../utils/storage/DataUtilities";

export class FlowStepConnection implements IStorable {
    fromStepId: string;
    toStepId: string;
    fromStepPath: string;

    constructor(fromStepId: string, toStepId: string, fromStepPath: string) {
        this.fromStepId = fromStepId;
        this.toStepId = toStepId;
        this.fromStepPath = fromStepPath;
    }

    toJSON(): any {
        // Use generic DataUtilities approach - no exclusions needed for this simple class
        return DataUtilities.getStorageData(this, []);
    }

    fromJSON(json: any): void {
        // Use generic DataUtilities approach - no exclusions needed for this simple class
        DataUtilities.loadStorageData(this, json, []);
    }
}
