import {
  Box,
  Button,
  Checkbox,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  FormControl,
  FormControlLabel,
  InputLabel,
  MenuItem,
  Select,
  Typography
} from '@mui/material';
import { useState } from 'react';
import { AxisConfig, AxisType, HomingDirection, MachineData } from '../../../data/MachineData';
import { ObserveState } from '../../../utils/statemanager/ObserveState';
import { NumberInput } from '../../Common/NumberInput';
import { AxisCalibrationWizard } from '../../wizards/calibration/AxisCalibrationWizard';

interface AxisConfigurationPanelProps {
  axis: AxisConfig;
  axisIndex: number;
}

export function AxisConfigurationPanel({ axis, axisIndex }: AxisConfigurationPanelProps) {
  const [advancedSettingsOpen, setAdvancedSettingsOpen] = useState(false);

  const getAvailableAxisTypes = (): AxisType[] => {
    const allAxisConfigs = MachineData.Instance.axisConfigurations;
    const selectedTypes = allAxisConfigs
      .filter((config, index) => index !== axisIndex && config.axisType !== AxisType.Unset)
      .map(config => config.axisType);

    return Object.values(AxisType).filter(type =>
      type === AxisType.Unset ||
      type === axis.axisType ||
      !selectedTypes.includes(type)
    );
  };

  return (
    <ObserveState
      key="axis-config-machine-data"
      listenTo={MachineData.Instance}
      properties={['axisConfigurations']}
      control={() => (
        <ObserveState
          key={`axis-config-${axisIndex}`}
          listenTo={axis}
          properties={['axisType', 'stepsPerRevolution', 'overallTurnsRatio', 'lashCompensation', 'maxRate', 'accelDecel', 'directionReversal', 'slowJogRate', 'fastJogRate', 'fastJogPlusDirection', 'fastJogMinusDirection', 'homingFeedrate', 'homingDirection', 'stepSignalInverted', 'directionSignalInverted', 'enableSignalInverted']}
          control={() => (
            <Box sx={{ display: 'flex', alignItems: 'center', gap: '15px', width: '100%' }}>
              <Box
                sx={{
                  backgroundColor: 'grey.800',
                  color: 'white',
                  px: 1,
                  py: 1,
                  borderRadius: 1,
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  minHeight: '56px',
                  fontWeight: 'bold',
                  width: '40px',
                  fontSize: '0.9rem',
                  flexShrink: 0
                }}
              >
                {axisIndex + 1}
              </Box>

              <FormControl sx={{ minWidth: 120, flexShrink: 0 }}>
                <InputLabel>Axis Type</InputLabel>
                <Select
                  value={axis.axisType}
                  label="Axis Type"
                  onChange={(e) => {
                    const newValue = e.target.value as AxisType;
                    axis.axisType = newValue;
                  }}
                >
                  {getAvailableAxisTypes().map((type) => (
                    <MenuItem key={type} value={type}>
                      {type}
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>

              <FormControlLabel
                control={
                  <Checkbox
                    checked={axis.directionReversal}
                    onChange={(e) => {
                      axis.directionReversal = e.target.checked;
                    }}
                  />
                }
                label="Reverse"
                disabled={axis.axisType === AxisType.Unset}
                sx={{ flexShrink: 0 }}
              />

              {/* Slave Axis Info */}
              {(axis.axisType === AxisType.XSlave || axis.axisType === AxisType.YSlave) && (
                <Typography variant="body2" color="text.secondary" sx={{ p: 2, bgcolor: 'info.50', borderRadius: 1, border: '1px solid', borderColor: 'info.200', flex: 1 }}>
                  <strong>Slave Axis:</strong> Motion parameters are controlled by the master {axis.axisType === AxisType.XSlave ? 'X' : 'Y'} axis.
                  Only direction reversal can be configured independently.
                </Typography>
              )}

              {/* Motion Parameters */}
              {axis.axisType !== AxisType.Unset &&
                axis.axisType !== AxisType.XSlave &&
                axis.axisType !== AxisType.YSlave && (
                  <>
                    <NumberInput
                      label="Steps Per Revolution"
                      value={axis.stepsPerRevolution}
                      onChange={(value) => {
                        axis.stepsPerRevolution = value || 1600;
                      }}
                      precision={0}
                      sx={{ minWidth: 140, flexShrink: 0 }}
                    />

                    <NumberInput
                      label="Overall Turns Ratio"
                      value={axis.overallTurnsRatio}
                      onChange={(value) => {
                        axis.overallTurnsRatio = value || 5;
                      }}
                      min={0.1}
                      precision={3}
                      sx={{ minWidth: 140, flexShrink: 0 }}
                    />

                    <NumberInput
                      label={`Max Rate (${axis.axisType === AxisType.A ? 'deg/min' : 'in/min'})`}
                      value={axis.maxRate}
                      onChange={(value) => {
                        axis.maxRate = value || 50;
                      }}
                      precision={0}
                      sx={{ minWidth: 140, flexShrink: 0 }}
                    />

                    <Box sx={{ flex: 1 }} />

                    <Button
                      variant="outlined"
                      onClick={() => setAdvancedSettingsOpen(true)}
                      disabled={axis.axisType === (AxisType.Unset as AxisType)}
                      sx={{ flexShrink: 0 }}
                    >
                      Advanced
                    </Button>

                    {/* Calibration button - only for X, Y, Z axes */}
                    {(axis.axisType === AxisType.X || axis.axisType === AxisType.Y || axis.axisType === AxisType.Z) && (
                      <Button
                        variant="outlined"
                        color="secondary"
                        onClick={() => AxisCalibrationWizard.show(axis)}
                        sx={{ flexShrink: 0 }}
                      >
                        Calibrate
                      </Button>
                    )}
                  </>
                )}

              <Dialog
                open={advancedSettingsOpen}
                onClose={() => setAdvancedSettingsOpen(false)}
                maxWidth="sm"
                fullWidth
              >
                <DialogTitle>Advanced Settings - Axis {axisIndex + 1}</DialogTitle>
                <DialogContent>
                  <Box sx={{ display: 'flex', flexDirection: 'column', gap: '15px', mt: 2 }}>
                    <Typography variant="subtitle2" sx={{ mt: 1, mb: -1, fontWeight: 'bold' }}>Motion Parameters</Typography>

                    <NumberInput
                      label={`Lash Compensation (${axis.axisType === AxisType.A ? 'degrees' : 'inches'})`}
                      value={axis.lashCompensation}
                      onChange={(value) => {
                        axis.lashCompensation = value || 0;
                      }}
                      precision={3}
                    />

                    <NumberInput
                      label="Accel/Decel (seconds)"
                      value={axis.accelDecel}
                      onChange={(value) => {
                        axis.accelDecel = value || 0.5;
                      }}
                      min={0.1}
                      precision={1}
                    />

                    <Typography variant="subtitle2" sx={{ mt: 2, mb: -1, fontWeight: 'bold' }}>Jog Rates</Typography>

                    <NumberInput
                      label={`Slow Jog Rate (${axis.axisType === AxisType.A ? 'deg/min' : 'in/min'})`}
                      value={axis.slowJogRate}
                      onChange={(value) => {
                        axis.slowJogRate = value || 100;
                      }}
                      precision={0}
                    />

                    <NumberInput
                      label={`Fast Jog Rate (${axis.axisType === AxisType.A ? 'deg/min' : 'in/min'})`}
                      value={axis.fastJogRate}
                      onChange={(value) => {
                        axis.fastJogRate = value || 500;
                      }}
                      precision={0}
                    />

                    <NumberInput
                      label={`Fast Jog Plus Direction (${axis.axisType === AxisType.A ? 'deg/min' : 'in/min'})`}
                      value={axis.fastJogPlusDirection}
                      onChange={(value) => {
                        axis.fastJogPlusDirection = value || 500;
                      }}
                      precision={0}
                    />

                    <NumberInput
                      label={`Fast Jog Minus Direction (${axis.axisType === AxisType.A ? 'deg/min' : 'in/min'})`}
                      value={axis.fastJogMinusDirection}
                      onChange={(value) => {
                        axis.fastJogMinusDirection = value || 500;
                      }}
                      precision={0}
                    />

                    <NumberInput
                      label={`Homing Feedrate (${axis.axisType === AxisType.A ? 'deg/min' : 'in/min'})`}
                      value={axis.homingFeedrate}
                      onChange={(value) => {
                        axis.homingFeedrate = value || 100;
                      }}
                      precision={0}
                    />

                    <FormControl fullWidth>
                      <InputLabel>Homing Direction</InputLabel>
                      <Select
                        value={axis.homingDirection}
                        label="Homing Direction"
                        onChange={(e) => {
                          axis.homingDirection = e.target.value as HomingDirection;
                        }}
                      >
                        <MenuItem value={HomingDirection.Plus}>{HomingDirection.Plus}</MenuItem>
                        <MenuItem value={HomingDirection.Minus}>{HomingDirection.Minus}</MenuItem>
                        <MenuItem value={HomingDirection.DoNotHome}>{HomingDirection.DoNotHome}</MenuItem>
                      </Select>
                    </FormControl>

                    <Typography variant="subtitle2" sx={{ mt: 2, mb: -1, fontWeight: 'bold' }}>Signal Inversions (Parameter 961)</Typography>

                    <FormControlLabel
                      control={
                        <Checkbox
                          checked={axis.stepSignalInverted}
                          onChange={(e) => {
                            axis.stepSignalInverted = e.target.checked;
                          }}
                        />
                      }
                      label="Invert Step Signal"
                    />

                    <FormControlLabel
                      control={
                        <Checkbox
                          checked={axis.directionSignalInverted}
                          onChange={(e) => {
                            axis.directionSignalInverted = e.target.checked;
                          }}
                        />
                      }
                      label="Invert Direction Signal"
                    />

                    <FormControlLabel
                      control={
                        <Checkbox
                          checked={axis.enableSignalInverted}
                          onChange={(e) => {
                            axis.enableSignalInverted = e.target.checked;
                          }}
                        />
                      }
                      label="Invert Enable Signal"
                    />
                  </Box>
                </DialogContent>
                <DialogActions>
                  <Button onClick={() => setAdvancedSettingsOpen(false)}>
                    Close
                  </Button>
                </DialogActions>
              </Dialog>
            </Box>
          )}
        />
      )}
    />
  );
}