import { Box, TextField, TextFieldProps, Tooltip } from '@mui/material';
import React, { useEffect, useState } from 'react';
import { ConfigurationData } from '../../data/ConfigurationData';
import { NumberInputUtil } from '../../utils/NumberInputUtil';

export interface NullableNumberInputProps extends Omit<TextFieldProps, 'value' | 'onChange'> {
  value: number | null;
  onChange: (value: number | null) => void;
  allowNegative?: boolean;
  allowPositive?: boolean;
  allowFractions?: boolean;
  defaultUnit?: 'in' | 'mm';
  precision?: number;
  min?: number;
  max?: number;
  showHelperText?: boolean;
  beforeText?: string;
  afterText?: string;
  textColor?: string;
}

/**
 * Nullable number input component - allows null values (empty = not set)
 * - Supports null values (empty field = null)
 * - Full math expression support (1+2, 14/2, etc.)
 * - Unit conversion (25mm, 1.5in, 2")
 * - Fractions (1/8, 3 1/2, etc.)
 * - Shared parsing logic with NumberInput via NumberInputUtil
 */
export function NullableNumberInput({
  value,
  onChange,
  allowNegative = true,
  allowPositive = true,
  allowFractions = true,
  defaultUnit = 'in',
  precision = 3,
  min,
  max,
  showHelperText = true,
  beforeText = '',
  afterText = '',
  textColor,
  ...textFieldProps
}: NullableNumberInputProps) {
  const [textValue, setTextValue] = useState<string>('');
  const [isValid, setIsValid] = useState<boolean>(true);
  const [isEditing, setIsEditing] = useState<boolean>(false);
  const [isFocused, setIsFocused] = useState<boolean>(false);
  const [tooltipOpen, setTooltipOpen] = useState<boolean>(false);

  // Get configuration instance
  const config = ConfigurationData.Instance;

  // Convert number to text on value change (only when not editing)
  useEffect(() => {
    if (!isEditing) {
      if (value === null) {
        setTextValue('');
      } else if (value === 0) {
        setTextValue('0.000');
      } else {
        setTextValue(value.toFixed(precision));
      }
    }
  }, [value, isEditing, precision]);

  const parseTextToNumber = (text: string): { value: number; isValid: boolean } => {
    return NumberInputUtil.parseNumberInput(
      text,
      defaultUnit,
      allowNegative,
      allowPositive,
      allowFractions,
      precision,
      min,
      max
    );
  };

  const handleTextChange = (newText: string) => {
    setTextValue(newText);
    setIsEditing(true);

    // Allow empty string for null value
    if (newText.trim() === '') {
      setIsValid(true);
      return;
    }

    // Only do basic validation, don't evaluate/change value until user is done
    const { isValid: valid } = parseTextToNumber(newText);
    setIsValid(valid);
  };

  const commitValue = () => {
    // Handle empty string as null
    if (textValue.trim() === '') {
      if (value !== null) {
        onChange(null);
      }
      setTextValue('');
      setIsValid(true);
      setIsEditing(false);
      return;
    }

    const { value: parsedValue, isValid: valid } = parseTextToNumber(textValue);

    if (valid && parsedValue !== value) {
      onChange(parsedValue);
    }

    if (!valid) {
      // Reset to current value if invalid
      if (value === null) {
        setTextValue('');
      } else {
        setTextValue(value === 0 ? '0.000' : value.toFixed(precision));
      }
      setIsValid(true);
    } else {
      // Format the text nicely
      setTextValue(parsedValue === 0 ? '0.000' : parsedValue.toFixed(precision));
    }

    setIsEditing(false);
  };

  const handleBlur = () => {
    commitValue();
    setIsFocused(false);
  };

  const handleFocus = (e: React.FocusEvent<HTMLInputElement>) => {
    setIsFocused(true);
    // Select all text when focused for easy editing
    e.target.select();
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' || e.key === 'Tab') {
      commitValue();
    }
  };

  // Create tooltip content
  const tooltipContent = (
    <Box>
      {beforeText && <Box sx={{ marginBottom: 1 }}>{beforeText}</Box>}
      <Box sx={{ fontWeight: 'bold', marginBottom: 0.5 }}>Input Options:</Box>
      <Box component="ul" sx={{ margin: 0, paddingLeft: 2.5, fontSize: '0.875rem' }}>
        <li>Decimals: 1.5, -2.75</li>
        <li>Fractions: 1/8, 3/4</li>
        <li>Mixed numbers: 1 1/2, 2 3/8</li>
        <li>Math: 14 + 2, 10 - 1.5</li>
        <li>Units: 25mm, 1.5in, 2"</li>
        <li>Empty = Not Set (null)</li>
      </Box>
      {afterText && <Box sx={{ marginTop: 1 }}>{afterText}</Box>}
    </Box>
  );

  // Handle mouse enter/leave for hover behavior
  const handleMouseEnter = () => {
    if (config.shouldShowNumberInputTooltip()) {
      config.decrementTooltipCount();
      setTooltipOpen(true);
    }
  };

  const handleMouseLeave = () => {
    setTooltipOpen(false);
  };

  return (
    <Tooltip
      title={tooltipContent}
      arrow
      placement="left"
      open={tooltipOpen}
      onClose={() => setTooltipOpen(false)}
      disableHoverListener={!config.shouldShowNumberInputTooltip()}
      disableFocusListener={!config.shouldShowNumberInputTooltip()}
      disableTouchListener={!config.shouldShowNumberInputTooltip()}
    >
      <TextField
        {...textFieldProps}
        value={textValue}
        onChange={(e) => handleTextChange(e.target.value)}
        onBlur={handleBlur}
        onFocus={handleFocus}
        onKeyDown={handleKeyDown}
        onMouseEnter={handleMouseEnter}
        onMouseLeave={handleMouseLeave}
        error={!isValid || textFieldProps.error}
        helperText={
          showHelperText ? (
            !isValid
              ? 'Invalid number format'
              : textFieldProps.helperText
          ) : undefined
        }
        placeholder={allowFractions ? 'e.g., 1.5, 14 1/2, 25mm (empty = not set)' : 'e.g., 1.5, 14 + 2, 25mm (empty = not set)'}
        sx={{
          ...textFieldProps.sx,
          '& .MuiOutlinedInput-input': {
            textAlign: isFocused ? 'left' : 'right',
            transition: 'text-align 0.2s ease',
            color: textColor || (value === null ? 'text.disabled' : 'inherit'),
            fontFamily: '"SF Mono", Monaco, "Cascadia Code", "Roboto Mono", Consolas, "Courier New", monospace',
            fontVariantNumeric: 'slashed-zero',
            fontStyle: value === null && !isFocused ? 'italic' : 'normal'
          }
        }}
      />
    </Tooltip>
  );
}

export default NullableNumberInput;
