import { AxisConfig } from "../../../data/MachineData";
import { Wizard } from "../../Wizard/Wizard";
import { WizardManager } from "../../Wizard/WizardManager";
import { AxisCalibrationData } from "./steps/AxisCalibrationData";

export class AxisCalibrationWizard extends Wizard {
  constructor(axisConfig: AxisConfig) {
    // Setup the singleton calibration data for this axis
    AxisCalibrationData.createNew(axisConfig.axisType.toString());
    
    const initialState = {
      axisConfig: axisConfig
    };

    super(
      null as any, // Temporary - will be set below
      initialState,
      true, // canClose
      false, // clickAwayClose
      '90%', // width - make it much larger
      '80%' // height - make it much larger
    );

    // Create the first step with proper wizard reference
    const { AxisCalibrationPositionStep } = require("./steps/AxisCalibrationPositionStep");
    const firstStep = new AxisCalibrationPositionStep(this);
    this.firstStep = firstStep;
    this.currentStep = firstStep;
  }

  static show(axisConfig: AxisConfig): void {
    const wizard = new AxisCalibrationWizard(axisConfig);
    WizardManager.Instance.start(wizard);
  }
}