import { Home as HomeIcon } from '@mui/icons-material';
import { Box, Button, Typography } from '@mui/material';
import React from 'react';
import { Machine } from '../../../../machine/Machine';
import { DataUtilities } from '../../../../utils/storage/DataUtilities';
import { FlowStep } from "../../../FlowStep";
import { FlowStepData } from "../../../FlowStepData";

export class IsHomedStep extends FlowStep {
    readonly __type = 'IsHomedStep';
    readonly category = ['Machine', 'System'];
    readonly name = 'Is Machine Homed';
    readonly description = 'Checks if machine is properly homed';
    
    // Icon is created dynamically, not stored
    get icon(): React.ReactNode {
        return React.createElement(HomeIcon, { sx: { color: 'info.main' } });
    }

    static readonly TRUE_PATH = 'true';
    static readonly FALSE_PATH = 'false';

    async execute(data: FlowStepData, prototypeRun: boolean): Promise<string | null> {
        if (prototypeRun) {
            return IsHomedStep.TRUE_PATH;
        }

        try {
            const isHomed = await Machine.getInstance().system.IsHomed();
            return isHomed ? IsHomedStep.TRUE_PATH : IsHomedStep.FALSE_PATH;
        } catch (error) {
            console.error('IsHomed failed:', error);
            return IsHomedStep.FALSE_PATH;
        }
    }

    results(): string[] {
        return [IsHomedStep.TRUE_PATH, IsHomedStep.FALSE_PATH];
    }

    renderResultsUI(data: FlowStepData, result: string): React.ReactNode {
        return (
            <Typography variant="caption">
                Machine homing status: {result === IsHomedStep.TRUE_PATH ? 'Homed' : 'Not homed'}
            </Typography>
        );
    }

    renderEditUI(props: { onClose: () => void }): React.ReactNode {
        const EditUI: React.FC = () => {
            return (
                <Box sx={{ p: 2, minWidth: 300 }}>
                    <Typography variant="h6" gutterBottom>Machine Homing Status</Typography>

                    <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                        This step checks if the machine is currently homed. No configuration is required.
                    </Typography>

                    <Typography variant="body2" sx={{ mb: 2 }}>
                        <strong>Outputs:</strong>
                        <br />• True: Machine is homed and ready
                        <br />• False: Machine needs to be homed
                    </Typography>

                    <Typography variant="body2" sx={{ mb: 2, fontWeight: 'bold', color: 'warning.main' }}>
                        ⚠️ Most operations require the machine to be homed first.
                    </Typography>

                    <Box sx={{ display: 'flex', justifyContent: 'flex-end', mt: 3 }}>
                        <Button variant="contained" onClick={props.onClose}>OK</Button>
                    </Box>
                </Box>
            );
        };

        return <EditUI />;
    }

    public toJSON(): any {
        const data = DataUtilities.getStorageData(this, ['icon']) as any;
        data.__type = this.__type;
        return data;
    }

    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data);
    }
}






