import React from 'react';
import { ConfigurationData } from '../../data/ConfigurationData';
import { ObserveState } from '../../utils/statemanager/ObserveState';
import { WizardManager } from './WizardManager';

export const WizardContainer: React.FC = () => {
  return (
    <ObserveState
      listenTo={WizardManager.Instance}
      properties={['currentWizard']}
      control={() => {
        const currentWizard = WizardManager.Instance.currentWizard;
        
        if (!currentWizard) {
          return null;
        }

        return (
          <ObserveState
            listenTo={currentWizard}
            properties={['currentStep', 'state']}
            control={() => {
              const dialogStyle: React.CSSProperties = {
                position: 'fixed',
                top: '50%',
                left: '50%',
                transform: 'translate(-50%, -50%)',
                width: currentWizard.width,
                height: currentWizard.height,
                backgroundColor: 'white',
                borderRadius: '8px',
                boxShadow: `0 4px 20px ${ConfigurationData.Instance.shadowColor}`,
                zIndex: 1000,
                display: 'flex',
                flexDirection: 'column'
              };

              const overlayStyle: React.CSSProperties = {
                position: 'fixed',
                top: 0,
                left: 0,
                right: 0,
                bottom: 0,
                backgroundColor: ConfigurationData.Instance.modalBackdrop,
                zIndex: 999
              };

              const headerStyle: React.CSSProperties = {
                display: 'flex',
                justifyContent: 'space-between',
                alignItems: 'center',
                padding: '16px 20px',
                borderBottom: `1px solid ${ConfigurationData.Instance.borderColor}`,
                minHeight: '60px'
              };

              const closeButtonStyle: React.CSSProperties = {
                background: 'none',
                border: 'none',
                fontSize: '24px',
                cursor: 'pointer',
                padding: '4px',
                lineHeight: 1,
                color: ConfigurationData.Instance.mutedTextColor
              };

              const contentStyle: React.CSSProperties = {
                flex: 1,
                padding: '20px',
                overflow: 'auto'
              };

              const handleOverlayClick = (e: React.MouseEvent) => {
                if (currentWizard.clickAwayClose && e.target === e.currentTarget) {
                  currentWizard.closeWizard();
                }
              };

              const handleCloseClick = () => {
                currentWizard.closeWizard();
              };

              return (
                <div>
                  <div style={overlayStyle} onClick={handleOverlayClick} />
                  <div style={dialogStyle}>
                    <div style={headerStyle}>
                      <h2 style={{ margin: 0, fontSize: '18px', fontWeight: 600 }}>
                        {currentWizard.currentStep.getTitle()}
                      </h2>
                      {currentWizard.canClose && (
                        <button
                          style={closeButtonStyle}
                          onClick={handleCloseClick}
                          aria-label="Close"
                        >
                          ×
                        </button>
                      )}
                    </div>
                    <div style={contentStyle}>
                      {currentWizard.currentStep.render()}
                    </div>
                  </div>
                </div>
              );
            }}
          />
        );
      }}
    />
  );
};
