import { Cancel as CancelIcon, PlayArrow as ResumeIcon, Stop as StopIcon } from '@mui/icons-material';
import { Alert, Box, Button, TextField, Typography } from '@mui/material';
import React from 'react';
import { ConfigurationData } from '../../../../data/ConfigurationData';
import { Job } from '../../../../data/Job';
import { MachineData } from '../../../../data/MachineData';
import { MachineStateData } from '../../../../data/MachineStateData';
import { UserMessageQueue } from '../../../../data/UserMessageQueue';
import { Machine } from '../../../../machine/Machine';
import { CoordinateUtil } from '../../../../utils/CoordinateUtil';
import { ObserveState } from '../../../../utils/statemanager/ObserveState';
import { StateManager } from '../../../../utils/statemanager/StateManager';
import { CNCViewer, CNCViewType } from '../../../MachineViewer/CNCViewer';
import { WizardStep } from '../../../Wizard/WizardStep';
import { HomingCompletionStep } from './HomingCompletionStep';

export class HomingProgressStep extends WizardStep {
  public isHoming: boolean = false;
  public isStopped: boolean = false;

  getTitle(): string {
    return 'Homing in Progress';
  }

  nextStep(): WizardStep | null {
    return new HomingCompletionStep(this.wizard, this);
  }

  backStep(): WizardStep | null {
    return this.priorStep;
  }

  private async startHoming(): Promise<void> {
    try {
      this.isHoming = true;
      this.isStopped = false;
      this.wizard.state.isHoming = true;

      // Notify state manager of changes
      StateManager.propertyChanged(this, 'isHoming');
      StateManager.propertyChanged(this, 'isStopped');

      UserMessageQueue.Instance.addMessage('🏠 Starting homing sequence...');
      await Machine.getInstance().system.HomeMachine();

      this.isHoming = false;
      this.wizard.state.isHoming = false;
      this.wizard.state.homingComplete = true;

      // Notify state manager of changes
      StateManager.propertyChanged(this, 'isHoming');

      // Update machine state to reflect homed status
      MachineStateData.Instance.isHomed = true;

      UserMessageQueue.Instance.addMessage('✓ Homing sequence completed successfully');

      // Automatically advance to completion step
      setTimeout(() => {
        this.wizard.advanceToNextStep();
      }, 1000);

    } catch (error) {
      this.isHoming = false;
      this.wizard.state.isHoming = false;
      this.wizard.state.homingError = true;

      // Notify state manager of changes
      StateManager.propertyChanged(this, 'isHoming');

      UserMessageQueue.Instance.addMessage('❌ Homing sequence failed');
      console.error('Homing failed:', error);
    }
  }

  private async stopHoming(): Promise<void> {
    try {
      await Machine.getInstance().program.Stop();
      this.isHoming = false;
      this.isStopped = true;
      this.wizard.state.isHoming = false;

      // Force component re-render
      StateManager.propertyChanged(this, 'isHoming');
      StateManager.propertyChanged(this, 'isStopped');

      UserMessageQueue.Instance.addMessage('⏸ Homing sequence stopped');
    } catch (error) {
      console.error('Failed to stop homing:', error);
      UserMessageQueue.Instance.addMessage('❌ Failed to stop homing sequence');
    }
  }

  private async resumeHoming(): Promise<void> {
    this.isStopped = false;
    // Force component re-render
    StateManager.propertyChanged(this, 'isStopped');
    await this.startHoming();
  }

  private cancelHoming(): void {
    this.wizard.closeWizard();
    UserMessageQueue.Instance.addMessage('❌ Homing sequence cancelled');
  }

  render(): React.ReactNode {
    return (
      <ObserveState
        listenTo={this}
        properties={['isHoming', 'isStopped']}
        control={() => (
          <ObserveState
            listenTo={MachineStateData.Instance}
            properties={['currentMachinePoint']}
            control={() => this.renderContent()}
          />
        )}
      />
    );
  }

  private renderContent(): React.ReactNode {
    const { homingComplete = false, homingError = false, autoStarted = false } = this.wizard.state;

    // Auto-start homing when component first renders
    if (!autoStarted && !this.isHoming && !homingComplete && !homingError && !this.isStopped) {
      this.wizard.state.autoStarted = true;
      // Use setTimeout to avoid calling state updates during render
      setTimeout(() => this.startHoming(), 100);
    }

    return (
      <Box sx={{ p: 3, display: 'flex', flexDirection: 'column', gap: 3, height: '100%' }}>

        {/* Status Alert */}
        {this.isHoming && (
          <Alert severity="warning" sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
            <Typography>
              Homing sequence is running. The machine is moving to find its home position.
            </Typography>
          </Alert>
        )}

        {this.isStopped && (
          <Alert severity="info">
            <Typography variant="h6">Homing sequence stopped</Typography>
            <Typography>You can resume the homing process or cancel and exit the wizard.</Typography>
          </Alert>
        )}

        {homingComplete && (
          <Alert severity="success">
            <Typography variant="h6">Homing sequence completed successfully!</Typography>
            <Typography>The machine has found its home position and is ready for operation.</Typography>
          </Alert>
        )}

        {homingError && (
          <Alert severity="error">
            <Typography variant="h6">Homing sequence failed!</Typography>
            <Typography>Check the machine for mechanical issues and try again.</Typography>
          </Alert>
        )}

        {/* Main content area with 3D viewer and control buttons */}
        <Box sx={{ flex: 1, display: 'flex', gap: 2, minHeight: 0 }}>
          {/* 3D Viewer - takes most of the space */}
          <CNCViewer
            simulatorView={ConfigurationData.Instance.defaultView}
            machineState={MachineStateData.Instance}
            machineData={MachineData.Instance}
            job={MachineStateData.Instance.currentJob || Job.createTestJob()}
            width="900px"
            height="500px"
            enableOrbit={true}
            enableClampDragging={false}
            enableSpindleDrag={false}
            viewType={CNCViewType.Perspective}
          />

          {/* Control Buttons - right side */}
          <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 2, minWidth: 200 }}>

            {/* Current Position Display */}
            <Box sx={{ width: '100%', mb: 2 }}>
              <Typography variant="subtitle2" sx={{ mb: 1, fontWeight: 'bold' }}>
                Machine Position
              </Typography>
              <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
                <TextField
                  label="X"
                  size="small"
                  value={MachineStateData.Instance.currentMachinePoint.x.toFixed(4)}
                  InputProps={{ readOnly: true }}
                  fullWidth
                />
                <TextField
                  label="Y"
                  size="small"
                  value={MachineStateData.Instance.currentMachinePoint.y.toFixed(4)}
                  InputProps={{ readOnly: true }}
                  fullWidth
                />
                <TextField
                  label="Z"
                  size="small"
                  value={MachineStateData.Instance.currentMachinePoint.z.toFixed(4)}
                  InputProps={{ readOnly: true }}
                  fullWidth
                />
              </Box>
            </Box>

            {/* Machine Position Display */}
            <Box sx={{ width: '100%', mb: 2 }}>
              <Typography variant="subtitle2" sx={{ mb: 1, fontWeight: 'bold' }}>
                Work Position
              </Typography>
              <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
                <TextField
                  label="X"
                  size="small"
                  value={CoordinateUtil.toWorkZero(MachineStateData.Instance.currentMachinePoint).x.toFixed(4)}
                  InputProps={{ readOnly: true }}
                  fullWidth
                />
                <TextField
                  label="Y"
                  size="small"
                  value={CoordinateUtil.toWorkZero(MachineStateData.Instance.currentMachinePoint).y.toFixed(4)}
                  InputProps={{ readOnly: true }}
                  fullWidth
                />
                <TextField
                  label="Z"
                  size="small"
                  value={CoordinateUtil.toWorkZero(MachineStateData.Instance.currentMachinePoint).z.toFixed(4)}
                  InputProps={{ readOnly: true }}
                  fullWidth
                />
              </Box>
            </Box>

            {/* Stop button - shown when homing */}
            {this.isHoming && (
              <Button
                variant="contained"
                color="warning"
                size="large"
                onClick={() => this.stopHoming()}
                startIcon={<StopIcon />}
                sx={{
                  minWidth: 120,
                  minHeight: 60,
                  fontSize: '1.1rem',
                  fontWeight: 'bold'
                }}
              >
                Stop
              </Button>
            )}

            {/* Resume and Cancel buttons - shown when stopped */}
            {this.isStopped && (
              <>
                <Button
                  variant="contained"
                  color="success"
                  size="large"
                  onClick={() => this.resumeHoming()}
                  startIcon={<ResumeIcon />}
                  sx={{
                    minWidth: 120,
                    minHeight: 60,
                    fontSize: '1.1rem',
                    fontWeight: 'bold'
                  }}
                >
                  Resume
                </Button>

                <Button
                  variant="contained"
                  color="error"
                  size="large"
                  onClick={() => this.cancelHoming()}
                  startIcon={<CancelIcon />}
                  sx={{
                    minWidth: 120,
                    minHeight: 60,
                    fontSize: '1.1rem',
                    fontWeight: 'bold'
                  }}
                >
                  Cancel
                </Button>
              </>
            )}
          </Box>
        </Box>
      </Box>
    );
  }
}
