import {
  ToggleOff as ToggleOffIcon,
  ToggleOn as ToggleOnIcon
} from '@mui/icons-material';
import {
  Box,
  IconButton,
  ListItem,
  Tooltip,
  Typography
} from '@mui/material';
import { Component } from 'react';
import { getInputActiveColorHex } from '../../data/Machine/InputActiveColor';
import { MachineStateData } from '../../data/MachineStateData';
import { Machine } from '../../machine/Machine';
import { LogCategory, Logger } from '../../utils/Logger';
import { ObserveState } from '../../utils/statemanager/ObserveState';

interface InputItemProps {
  input: any;
  isOverridden: boolean;
  onToggleOverride: (inputNumber: number, newState: boolean) => void;
  onRemoveOverride: (inputNumber: number) => void;
}

interface InputItemState {
  inputState: boolean;
}

export class InputItem extends Component<InputItemProps, InputItemState> {
  private refreshInterval: NodeJS.Timeout | null = null;

  constructor(props: InputItemProps) {
    super(props);
    this.state = {
      inputState: false
    };
  }

  componentDidMount() {
    this.startRefresh();
  }

  componentWillUnmount() {
    this.stopRefresh();
  }

  private startRefresh = () => {
    this.refreshInputState();
    this.refreshInterval = setInterval(() => {
      this.refreshInputState();
    }, 500);
  };

  private stopRefresh = () => {
    if (this.refreshInterval) {
      clearInterval(this.refreshInterval);
      this.refreshInterval = null;
    }
  };

  private refreshInputState = async () => {
    try {
      const machine = Machine.getInstance();
      if (!machine) return;

      const inputStates = await machine.io.GetCurrentInputs();
      const newState = inputStates[this.props.input.number] || false;

      if (newState !== this.state.inputState) {
        this.setState({ inputState: newState });
      }
    } catch (error) {
      Logger.Instance.logError(LogCategory.UserInterface, 'Failed to refresh input state:', error);
    }
  };

  render() {
    const { input, isOverridden, onToggleOverride, onRemoveOverride } = this.props;
    const { inputState } = this.state;

    return (
      <ObserveState
        listenTo={[MachineStateData.Instance]}
        properties={['isOverridingInputs']}
        control={() => {
          const machineStateData = MachineStateData.Instance;
          const isOverrideMode = machineStateData.isOverridingInputs;
          const isActive = inputState;

          // Get the active color for this input from its activeColor property
          const activeColorHex = getInputActiveColorHex(input.activeColor);

          // Determine display text based on triggeredState and current physical state
          const displayText = isActive ? input.closedText : input.openText;

          return (
            <ListItem
              key={`input-${input.number}`}
              sx={{
                py: 0.75,
                px: 1.5,
                borderBottom: '1px solid #e0e0e0',
                minHeight: 48,
                display: 'flex',
                alignItems: 'center'
              }}
            >
              <Box sx={{
                display: 'flex',
                alignItems: 'center',
                width: '100%',
                gap: 1
              }}>
                {/* Input Number in Solid Box */}
                <Box
                  sx={{
                    width: 28,
                    height: 24,
                    backgroundColor: isActive ? activeColorHex : '#e0e0e0',
                    color: isActive ? 'white' : '#757575',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    borderRadius: 1,
                    fontSize: '0.75rem',
                    fontWeight: 'bold',
                    flexShrink: 0,
                    border: isOverridden ? '2px solid #ff9800' : 'none'
                  }}
                >
                  {input.number}
                </Box>

                {/* Input Name */}
                <Box sx={{ flex: 1, minWidth: 0 }}>
                  <Typography
                    variant="body2"
                    sx={{
                      fontSize: '0.8rem',
                      fontWeight: 500,
                      color: '#1a1a1a',
                      overflow: 'hidden',
                      textOverflow: 'ellipsis',
                      whiteSpace: 'nowrap'
                    }}
                  >
                    {input.name}
                  </Typography>
                </Box>

                {/* Active/Inactive Status Text */}
                <Box sx={{
                  minWidth: 80,
                  display: 'flex',
                  flexDirection: 'column',
                  alignItems: 'flex-end',
                  justifyContent: 'center'
                }}>
                  <Typography
                    variant="caption"
                    sx={{
                      fontSize: '0.7rem',
                      fontWeight: isActive ? 'bold' : 'normal',
                      color: isActive ? activeColorHex : '#757575',
                      textAlign: 'right'
                    }}
                  >
                    {displayText}
                  </Typography>

                  {/* Override indicator - only visible when in override mode and overridden */}
                  {isOverrideMode && isOverridden && (
                    <Typography
                      variant="caption"
                      sx={{
                        fontSize: '0.6rem',
                        color: '#ff9800',
                        fontWeight: 'bold',
                        textAlign: 'right',
                        lineHeight: 1
                      }}
                    >
                      OVERRIDDEN
                    </Typography>
                  )}
                </Box>

                {/* Override Toggle - only visible in override mode */}
                {isOverrideMode && (
                  <Box sx={{
                    minWidth: 60,
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'flex-end',
                    gap: 0.5
                  }}>
                    {isOverridden && (
                      <Tooltip title="Remove override">
                        <IconButton
                          size="small"
                          onClick={() => onRemoveOverride(input.number)}
                          sx={{
                            color: '#ff9800',
                            '&:hover': {
                              backgroundColor: 'rgba(255, 152, 0, 0.1)'
                            }
                          }}
                        >
                          ×
                        </IconButton>
                      </Tooltip>
                    )}

                    <Tooltip title={`Force ${isActive ? 'OFF' : 'ON'}`}>
                      <IconButton
                        size="small"
                        onClick={() => onToggleOverride(input.number, !isActive)}
                        sx={{
                          color: isActive ? '#4caf50' : '#757575',
                          '&:hover': {
                            backgroundColor: isActive ? 'rgba(76, 175, 80, 0.1)' : 'rgba(117, 117, 117, 0.1)'
                          }
                        }}
                      >
                        {isActive ? <ToggleOnIcon /> : <ToggleOffIcon />}
                      </IconButton>
                    </Tooltip>
                  </Box>
                )}
              </Box>
            </ListItem>
          );
        }}
      />
    );
  }
}
