import {
    Description as FileIcon,
    Save as SaveIcon
} from '@mui/icons-material';
import {
    Box,
    Chip,
    Divider,
    List,
    ListItem,
    ListItemButton,
    ListItemText,
    Paper,
    Typography,
} from '@mui/material';
import React from 'react';
import { ConfigurationData } from '../../data/ConfigurationData';
import { MachineStateData } from '../../data/MachineStateData';
import { ObserveState } from '../../utils/statemanager/ObserveState';

interface RecentJobsDrawerProps {
    onViewChange?: (view: string) => void;
}

interface Job {
    name: string;
    fileCount: number;
}

interface RecentFile {
    name: string;
    timestamp: string;
}

/**
 * Recent Jobs & Files Drawer Component
 * Displays recent jobs and NC files for quick access.
 */
export function RecentJobsDrawer(props: RecentJobsDrawerProps) {
    const config = ConfigurationData.Instance;

    // Mock data - replace with actual data from MachineStateData or JobStorage
    const jobs: Job[] = [
        { name: 'Spoilboard Surfacing', fileCount: 0 },
        { name: 'Cabinet Door Panel', fileCount: 2 },
        { name: 'Welcome Sign', fileCount: 2 },
    ];

    const files: RecentFile[] = [
        { name: 'spoilboard_surface.nc', timestamp: 'yesterday' },
        { name: 'cabinet_panel.nc', timestamp: '11 hours ago' },
        { name: 'welcome_sign.nc', timestamp: '11 hours ago' },
    ];

    const handleJobClick = (jobName: string) => {
        // Load the job
        console.log('Loading job:', jobName);
    };

    const handleFileClick = (fileName: string) => {
        // Load the file
        console.log('Loading file:', fileName);
    };

    return (
        <ObserveState
            key="recent-jobs-drawer"
            listenTo={MachineStateData.Instance}
            properties={['currentJob']}
            control={() => {
                return (
                    <Box
                        sx={{
                            height: '100%',
                            display: 'flex',
                            flexDirection: 'column',
                            backgroundColor: config.lightBackgroundColor,
                            overflow: 'hidden',
                        }}
                    >
                        {/* Header */}
                        <Box
                            sx={{
                                padding: 2,
                                backgroundColor: config.lightBackgroundColor,
                                borderBottom: `1px solid ${config.borderColor}`,
                                display: 'flex',
                                alignItems: 'center',
                                gap: 1,
                            }}
                        >
                            <SaveIcon sx={{ color: config.primaryColor }} />
                            <Typography variant="h6" sx={{ color: config.darkTextColor }}>
                                Coordinates
                            </Typography>
                        </Box>

                        {/* Scrollable Content */}
                        <Box
                            sx={{
                                flexGrow: 1,
                                overflow: 'auto',
                                padding: 2,
                            }}
                        >
                            {/* Jobs Section */}
                            <Paper
                                sx={{
                                    marginBottom: 3,
                                    overflow: 'hidden',
                                }}
                                variant="outlined"
                            >
                                <Box
                                    sx={{
                                        p: 1.5,
                                        backgroundColor: config.lightBackgroundColor,
                                        borderBottom: `1px solid ${config.borderColor}`,
                                    }}
                                >
                                    <Typography
                                        variant="subtitle2"
                                        sx={{
                                            fontWeight: 'bold',
                                            fontSize: '0.85rem',
                                            color: config.darkTextColor,
                                        }}
                                    >
                                        JOBS
                                    </Typography>
                                </Box>

                                <List sx={{ py: 0 }}>
                                    {jobs.map((job, index) => (
                                        <React.Fragment key={job.name}>
                                            <ListItem
                                                disablePadding
                                                secondaryAction={
                                                    job.fileCount > 0 ? (
                                                        <Chip
                                                            label={job.fileCount}
                                                            size="small"
                                                            sx={{
                                                                backgroundColor: config.lightBackgroundColor,
                                                                color: config.darkTextColor,
                                                                fontWeight: 'bold',
                                                                minWidth: '32px',
                                                            }}
                                                        />
                                                    ) : (
                                                        <Typography
                                                            variant="body2"
                                                            sx={{ color: config.mutedTextColor, fontSize: '0.85rem' }}
                                                        >
                                                            {job.fileCount}
                                                        </Typography>
                                                    )
                                                }
                                            >
                                                <ListItemButton onClick={() => handleJobClick(job.name)}>
                                                    <ListItemText
                                                        primary={job.name}
                                                        primaryTypographyProps={{
                                                            fontSize: '0.9rem',
                                                            color: config.darkTextColor,
                                                        }}
                                                    />
                                                </ListItemButton>
                                            </ListItem>
                                            {index < jobs.length - 1 && <Divider />}
                                        </React.Fragment>
                                    ))}
                                </List>
                            </Paper>

                            {/* Files Section */}
                            <Paper
                                sx={{
                                    overflow: 'hidden',
                                }}
                                variant="outlined"
                            >
                                <Box
                                    sx={{
                                        p: 1.5,
                                        backgroundColor: config.lightBackgroundColor,
                                        borderBottom: `1px solid ${config.borderColor}`,
                                    }}
                                >
                                    <Typography
                                        variant="subtitle2"
                                        sx={{
                                            fontWeight: 'bold',
                                            fontSize: '0.85rem',
                                            color: config.darkTextColor,
                                        }}
                                    >
                                        FILES
                                    </Typography>
                                </Box>

                                <List sx={{ py: 0 }}>
                                    {files.map((file, index) => (
                                        <React.Fragment key={file.name}>
                                            <ListItem
                                                disablePadding
                                                secondaryAction={
                                                    <Typography
                                                        variant="caption"
                                                        sx={{ color: config.mutedTextColor }}
                                                    >
                                                        {file.timestamp}
                                                    </Typography>
                                                }
                                            >
                                                <ListItemButton onClick={() => handleFileClick(file.name)}>
                                                    <FileIcon
                                                        sx={{
                                                            mr: 1.5,
                                                            fontSize: '1.2rem',
                                                            color: config.mutedTextColor,
                                                        }}
                                                    />
                                                    <ListItemText
                                                        primary={file.name}
                                                        primaryTypographyProps={{
                                                            fontSize: '0.9rem',
                                                            color: config.darkTextColor,
                                                        }}
                                                    />
                                                </ListItemButton>
                                            </ListItem>
                                            {index < files.length - 1 && <Divider />}
                                        </React.Fragment>
                                    ))}
                                </List>
                            </Paper>
                        </Box>
                    </Box>
                );
            }}
        />
    );
}
