import { Box } from '@mui/material';
import React, { useState } from 'react';
import { Flow } from '../../flow/Flow';
import { FlowEditor } from '../Flow/FlowEditor';
import { FlowManagementView } from './FlowManagementView';

interface FlowEditorState {
  flow: Flow;
  flowName: string;
}

export const FlowTab: React.FC = () => {
  const [currentEditor, setCurrentEditor] = useState<FlowEditorState | null>(null);
  const [, forceUpdate] = useState(0);

  const handleOpenFlow = (flow: Flow, flowName: string) => {
    setCurrentEditor({ flow, flowName });
  };

  const handleCloseEditor = () => {
    setCurrentEditor(null);
  };

  const handleFlowChange = (updatedFlow: Flow) => {
    // The Flow object already calls StateManager.propertiesChanged internally
    // Force React to re-render by updating the counter
    forceUpdate(prev => prev + 1);
  };

  return (
    <Box sx={{ height: '100%', width: '100%', position: 'relative', overflow: 'hidden' }}>
      {currentEditor ? (
        <FlowEditor
          flow={currentEditor.flow}
          flowName={currentEditor.flowName}
          width="100%"
          height="100%"
          onFlowChange={handleFlowChange}
          onClose={handleCloseEditor}
        />
      ) : (
        <FlowManagementView onOpenFlow={handleOpenFlow} />
      )}
    </Box>
  );
};
