import { FlowNumberValue } from '../../flow/FlowNumberValue';
import { StateManager } from '../../utils/statemanager/StateManager';
import { DataUtilities } from '../../utils/storage/DataUtilities';
import { IStorable } from '../../utils/storage/IStorable';

export enum ComparisonOperator {
    LessThan = 'lessThan',
    LessThanOrEqualTo = 'lessThanOrEqualTo'
}

export class LessThanEqualToStepData implements IStorable {
    private _leftDataPath: string = '';
    private _comparisonOperator: ComparisonOperator = ComparisonOperator.LessThanOrEqualTo;
    public rightValue: FlowNumberValue = new FlowNumberValue();

    // Left side data element selection
    get leftDataPath(): string {
        return this._leftDataPath;
    }

    set leftDataPath(value: string) {
        this._leftDataPath = value;
        StateManager.propertyChanged(this, 'leftDataPath');
    }

    // Comparison operator (less than vs less than or equal to)
    get comparisonOperator(): ComparisonOperator {
        return this._comparisonOperator;
    }

    set comparisonOperator(value: ComparisonOperator) {
        this._comparisonOperator = value;
        StateManager.propertyChanged(this, 'comparisonOperator');
    }

    // IStorable implementation
    public toJSON(): any {
        const baseData = DataUtilities.getStorageData(this, ['rightValue']);
        return {
            ...baseData,
            rightValue: this.rightValue.toJSON()
        };
    }

    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data, ['rightValue']);
        if (data.rightValue) {
            this.rightValue.fromJSON(data.rightValue);
        }
        // Migrate from old format
        else if (data._comparisonType !== undefined) {
            if (data._comparisonType === 'dataElement') {
                this.rightValue.valueSource = 'dataElement' as any;
                this.rightValue.dataPath = data._rightDataPath || '';
            } else {
                this.rightValue.valueSource = 'directValue' as any;
                this.rightValue.numberValue = data._numberValue || 0;
            }
        }
    }
}