import { Box, Button, ButtonGroup, IconButton, Typography } from '@mui/material';
import { Clear } from '@mui/icons-material';
import { useEffect, useRef, useState } from 'react';
import { ConfigurationData } from '../../data/ConfigurationData';
import { MessageDisplay, SignalRMessagesData } from '../../data/SignalRMessagesData';
import { ObserveState } from '../../utils/statemanager/ObserveState';

type MessageFilter = 'messages-only' | 'all';

export function MessageViewer() {
    const [config] = useState(() => ConfigurationData.Instance);
    const [filter, setFilter] = useState<MessageFilter>('messages-only');
    const messagesEndRef = useRef<HTMLDivElement>(null);
    const [messageCount, setMessageCount] = useState(0);

    // Auto-scroll to bottom when message count changes
    useEffect(() => {
        messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }, [messageCount]);

    const getMessageColor = (message: MessageDisplay): string => {
        const eventCode = message.eventCode;
        const eventType = message.eventType;

        // Use event code ranges for coloring if available
        if (eventCode !== undefined && eventCode !== null) {
            // Configuration messages (special codes)
            if ([111, 444, 555, 556, 777, 888, 999].includes(eventCode)) {
                return config.primaryColor; // Blue/Info
            }

            // Status and Info (300-399, with exceptions)
            if (eventCode >= 300 && eventCode <= 399) {
                if (eventCode === 306) return config.successColor; // Job Finished - Green
                if (eventCode >= 318 && eventCode <= 337) return config.errorColor; // Probe errors - Red
                if (eventCode >= 320 && eventCode <= 330) return config.errorColor; // Cancellations - Red
                return config.primaryColor; // Blue/Info
            }

            // Faults (400-499) - All RED
            if (eventCode >= 400 && eventCode <= 499) {
                return config.errorColor;
            }

            // Syntax errors (500-599) - Orange/Warning
            if (eventCode >= 500 && eventCode <= 599) {
                return config.warningColor;
            }

            // Cutter compensation errors (600-699) - Orange/Warning
            if (eventCode >= 600 && eventCode <= 699) {
                return config.warningColor;
            }

            // Parameter errors (700-799) - Orange/Warning
            if (eventCode >= 700 && eventCode <= 799) {
                return config.warningColor;
            }

            // Canned cycle errors (800-899) - Orange/Warning
            if (eventCode >= 800 && eventCode <= 899) {
                return config.warningColor;
            }

            // Miscellaneous errors (900-999) - Red
            if (eventCode >= 900 && eventCode <= 999) {
                return config.errorColor;
            }

            // Scaling errors (1000-1199) - Orange/Warning
            if (eventCode >= 1000 && eventCode <= 1199) {
                return config.warningColor;
            }

            // Startup messages (100-199)
            if (eventCode >= 100 && eventCode <= 199) {
                if (eventCode >= 102 && eventCode <= 106) return config.errorColor; // Startup errors
                return config.primaryColor; // Status messages
            }

            // Exit messages (200-299) - Blue/Info
            if (eventCode >= 200 && eventCode <= 299) {
                return config.primaryColor;
            }
        }

        // Fallback to eventType classification
        if (eventType) {
            if (eventType.includes('Error') || eventType.includes('Fault')) {
                return config.errorColor;
            }
            if (eventType.includes('Syntax') || eventType.includes('Parameter')) {
                return config.warningColor;
            }
            if (eventType.includes('Completed')) {
                return config.successColor;
            }
            if (eventType.includes('Job') || eventType.includes('Status')) {
                return config.primaryColor;
            }
        }

        // Fallback to severity if provided
        if (message.severity === 'Error') {
            return config.errorColor;
        }
        if (message.severity === 'Warning') {
            return config.warningColor;
        }

        // Type-based coloring (when no event code or type)
        switch (message.type) {
            case 'Job Completed':
                return config.successColor; // Green
            case 'Job Started':
            case 'Job Info':
            case 'Message':
                return config.primaryColor; // Blue/Info
            case 'Step Execution':
                return '#006400'; // Dark Green
            case 'DRO Update':
                return '#800080'; // Purple
            default:
                return config.darkTextColor; // Black/Normal
        }
    };

    const formatTimestamp = (date: Date): string => {
        const now = new Date();
        const diffMs = now.getTime() - date.getTime();
        const diffSecs = Math.floor(diffMs / 1000);
        const diffMins = Math.floor(diffSecs / 60);
        const diffHours = Math.floor(diffMins / 60);

        if (diffSecs < 60) {
            return `${diffSecs}s ago`;
        } else if (diffMins < 60) {
            return `${diffMins}m ago`;
        } else if (diffHours < 24) {
            return `${diffHours}h ago`;
        } else {
            return date.toLocaleTimeString();
        }
    };

    const scrollToBottom = () => {
        messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    };

    const handleClear = () => {
        SignalRMessagesData.Instance.clearMessages();
    };

    return (
        <Box sx={{ height: '100%', display: 'flex', flexDirection: 'column' }}>
            {/* Header with toggle and clear button */}
            <Box sx={{
                p: 1,
                borderBottom: `1px solid ${config.borderColor}`,
                display: 'flex',
                justifyContent: 'space-between',
                alignItems: 'center',
                backgroundColor: config.lightBackgroundColor,
                gap: 1
            }}>
                <Typography variant="subtitle2" sx={{ fontWeight: 'bold', color: config.darkTextColor, fontSize: '0.85rem' }}>
                    Messages
                </Typography>
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                    <ButtonGroup size="small" variant="outlined">
                        <Button
                            variant={filter === 'messages-only' ? 'contained' : 'outlined'}
                            onClick={() => setFilter('messages-only')}
                            sx={{
                                fontSize: '0.7rem',
                                textTransform: 'none',
                                minWidth: '70px',
                                py: 0.25
                            }}
                        >
                            Messages
                        </Button>
                        <Button
                            variant={filter === 'all' ? 'contained' : 'outlined'}
                            onClick={() => setFilter('all')}
                            sx={{
                                fontSize: '0.7rem',
                                textTransform: 'none',
                                minWidth: '50px',
                                py: 0.25
                            }}
                        >
                            All
                        </Button>
                    </ButtonGroup>
                    <IconButton 
                        size="small" 
                        onClick={handleClear}
                        title="Clear all messages"
                        sx={{ 
                            color: config.errorColor,
                            padding: '4px'
                        }}
                    >
                        <Clear fontSize="small" />
                    </IconButton>
                </Box>
            </Box>

            {/* Messages list */}
            <ObserveState
                key="message-viewer-list"
                listenTo={SignalRMessagesData.Instance}
                properties={['messages']}
                control={() => {
                    const allMessages = SignalRMessagesData.Instance.messages;

                    // Filter messages based on selected filter
                    const filteredMessages = filter === 'messages-only'
                        ? allMessages.filter(m => m.type === 'Message')
                        : allMessages;

                    // Update message count to trigger auto-scroll
                    if (filteredMessages.length !== messageCount) {
                        setMessageCount(filteredMessages.length);
                    }

                    return (
                        <Box sx={{
                            flex: 1,
                            overflow: 'auto',
                            p: 0.5
                        }}>
                            {filteredMessages.length === 0 ? (
                                <Box sx={{
                                    display: 'flex',
                                    alignItems: 'center',
                                    justifyContent: 'center',
                                    height: '100%'
                                }}>
                                    <Typography variant="body2" color="text.secondary" sx={{ fontStyle: 'italic', fontSize: '0.75rem' }}>
                                        No messages yet
                                    </Typography>
                                </Box>
                            ) : (
                                <>
                                    {filteredMessages.map((message) => {
                                        if (filter === 'messages-only') {
                                            // Compact single-line format for messages-only mode
                                            return (
                                                <Box
                                                    key={message.id}
                                                    sx={{
                                                        mb: 0.5,
                                                        px: 1,
                                                        py: 0.5,
                                                        borderLeft: `3px solid ${getMessageColor(message)}`,
                                                        backgroundColor: config.lightBackgroundColor,
                                                        borderRadius: '3px',
                                                        '&:hover': {
                                                            backgroundColor: config.borderColor
                                                        }
                                                    }}
                                                >
                                                    <Typography
                                                        variant="body2"
                                                        sx={{
                                                            color: config.darkTextColor,
                                                            fontSize: '0.75rem',
                                                            lineHeight: 1.3
                                                        }}
                                                    >
                                                        {message.message}
                                                    </Typography>
                                                </Box>
                                            );
                                        } else {
                                            // Two-column format for all messages mode
                                            return (
                                                <Box
                                                    key={message.id}
                                                    sx={{
                                                        mb: 0.5,
                                                        px: 1,
                                                        py: 0.5,
                                                        borderLeft: `3px solid ${getMessageColor(message)}`,
                                                        backgroundColor: config.lightBackgroundColor,
                                                        borderRadius: '3px',
                                                        display: 'flex',
                                                        gap: 1,
                                                        alignItems: 'flex-start',
                                                        '&:hover': {
                                                            backgroundColor: config.borderColor
                                                        }
                                                    }}
                                                >
                                                    <Typography
                                                        variant="caption"
                                                        sx={{
                                                            fontWeight: 'bold',
                                                            color: getMessageColor(message),
                                                            fontSize: '0.7rem',
                                                            minWidth: '80px',
                                                            flexShrink: 0
                                                        }}
                                                    >
                                                        {message.type}
                                                    </Typography>
                                                    <Typography
                                                        variant="body2"
                                                        sx={{
                                                            color: config.darkTextColor,
                                                            fontSize: '0.75rem',
                                                            lineHeight: 1.3,
                                                            flex: 1
                                                        }}
                                                    >
                                                        {message.message}
                                                    </Typography>
                                                </Box>
                                            );
                                        }
                                    })}
                                    <div ref={messagesEndRef} />
                                </>
                            )}
                        </Box>
                    );
                }}
            />
        </Box>
    );
}
