import { Add as AddIcon, BugReport as BugReportIcon, Delete as DeleteIcon, Edit as EditIcon, Search as SearchIcon } from '@mui/icons-material';
import {
  Box,
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Divider,
  FormControl,
  Grid,
  IconButton,
  List,
  ListItem,
  ListItemButton,
  ListItemText,
  MenuItem,
  Paper,
  Select,
  SvgIcon,
  Tooltip,
  Typography
} from '@mui/material';
import { useCallback, useEffect, useState } from 'react';
import { getInputActiveColorHex } from '../../../data/Machine/InputActiveColor';
import { InputTriggeredState } from '../../../data/Machine/InputTriggeredState';
import { MachineInput } from '../../../data/Machine/MachineInput';
import { MachineData } from '../../../data/MachineData';
import { ClosedCircuitIcon, OpenCircuitIcon } from '../../../icons';
import { Machine } from '../../../machine/Machine';
import { InputNumberManager } from '../../../utils/InputNumberManager';
import { LogCategory, Logger } from '../../../utils/Logger';
import { ObserveState } from '../../../utils/statemanager/ObserveState';
import { StateManager } from '../../../utils/statemanager/StateManager';
import { FindInputDialog } from '../../Common/FindInputDialog';
import { MachineInputEditor } from '../../Common/MachineInputEditor';
import { NullableNumberInput } from '../../Common/NullableNumberInput';
import { TestInputDialog } from '../../Common/TestInputDialog';

// SVG Icons for open/closed state
const OpenIcon = () => (
  <OpenCircuitIcon sx={{ color: 'success.main', width: 40, height: 40 }} />
);

const ClosedIcon = () => (
  <ClosedCircuitIcon sx={{ color: 'error.main', width: 40, height: 40 }} />
);

const UnknownIcon = () => (
  <SvgIcon viewBox="0 0 24 24" sx={{ color: 'text.disabled', width: 40, height: 40 }}>
    <circle cx="12" cy="12" r="10" fill="none" stroke="currentColor" strokeWidth="2" strokeDasharray="4,4" />
  </SvgIcon>
);

/**
 * InputsTab component - Manages machine input configuration
 * Shows list of all inputs that are 'used' ordered by input number
 * Allows editing input numbers and state meanings
 */
export function InputsTab() {
  const [machineData] = useState(() => MachineData.Instance);
  const [currentInputStates, setCurrentInputStates] = useState<Record<number, boolean>>({});
  const [editDialogOpen, setEditDialogOpen] = useState(false);
  const [editingInput, setEditingInput] = useState<MachineInput | null>(null);
  const [addInputDialogOpen, setAddInputDialogOpen] = useState(false);
  const [addInputIsCreatingNew, setAddInputIsCreatingNew] = useState(false);
  const [addInputCurrentItem, setAddInputCurrentItem] = useState<MachineInput | null>(null);
  const [addInputQueuedItems, setAddInputQueuedItems] = useState<Set<MachineInput>>(new Set());
  const [addInputDeleteQueue, setAddInputDeleteQueue] = useState<Set<MachineInput>>(new Set());
  const [findInputDialogOpen, setFindInputDialogOpen] = useState(false);
  const [findInputTarget, setFindInputTarget] = useState<MachineInput | null>(null);
  const [testInputDialogOpen, setTestInputDialogOpen] = useState(false);
  const [testInputTarget, setTestInputTarget] = useState<MachineInput | null>(null);

  // Fetch current input states from machine interface
  useEffect(() => {
    const fetchInputStates = async () => {
      try {
        const machineInterface = Machine.getInstance();
        const states = await machineInterface.io.GetCurrentInputs();
        setCurrentInputStates(states);
      } catch (error) {
        Logger.Instance.logError(LogCategory.System, 'Failed to fetch input states:', error);
      }
    };

    // Fetch initially
    fetchInputStates();

    // Set up polling to refresh input states every 500ms
    const intervalId = setInterval(fetchInputStates, 500);

    // Cleanup on unmount
    return () => clearInterval(intervalId);
  }, []);

  // Enforce policy that unused inputs should never have numbers
  useEffect(() => {
    InputNumberManager.enforceUnusedInputsNumberPolicy(machineData.machineInputs, machineData);
  }, [machineData.machineInputs, machineData]);

  // Get inputs grouped into unassigned and assigned sections using shared utilities
  const getGroupedInputs = useCallback(() => {
    const unassignedInputs = InputNumberManager.getUnassignedInputs(machineData.machineInputs);
    const assignedInputs = InputNumberManager.getAssignedInputs(machineData.machineInputs);

    // Debug logging
    // Logger.Instance.log(LogCategory.System, 
    //   `Input grouping - Total: ${machineData.machineInputs.length}, Unassigned: ${unassignedInputs.length}, Assigned: ${assignedInputs.length}`);

    return { unassignedInputs, assignedInputs };
  }, [machineData.machineInputs]);

  // Handle input number change using shared utility
  const handleInputNumberChange = useCallback((input: MachineInput, newNumber: number | null) => {
    // Validate the assignment first
    const validation = InputNumberManager.validateInputNumberAssignment(
      input,
      newNumber,
      machineData.machineInputs
    );

    if (!validation.isValid) {
      Logger.Instance.logError(LogCategory.UserInterface,
        `Cannot assign number to ${input.name}: ${validation.error}`);
      return;
    }

    // Use the shared utility to handle the assignment
    InputNumberManager.assignInputNumber(
      input,
      newNumber,
      machineData.machineInputs,
      machineData
    );
  }, [machineData]);

  // Handle state meaning change (currently selected dropdown value)
  const handleStateMeaningChange = useCallback((input: MachineInput, physicalState: 'open' | 'closed', meaning: 'active' | 'inactive') => {
    // Update the input configuration based on which meaning the user assigned to the physical state
    // The user is telling us what the current physical state means

    if (meaning === 'active') {
      // User says current physical state means "active"
      // So activeState should match the current physical state
      if (physicalState === 'open') {
        input.activeState = InputTriggeredState.Open; // Active when open
      } else if (physicalState === 'closed') {
        input.activeState = InputTriggeredState.Closed; // Active when closed
      }
    } else {
      // User says current physical state means "inactive"
      // So activeState should be the opposite of current physical state
      if (physicalState === 'open') {
        input.activeState = InputTriggeredState.Closed; // Inactive when open = active when closed
      } else if (physicalState === 'closed') {
        input.activeState = InputTriggeredState.Open; // Inactive when closed = active when open
      }
    }

    StateManager.propertyChanged(machineData, 'machineInputs');
    // Logger.Instance.log(LogCategory.UserInterface, 
    //   `Input "${input.name}": ${physicalState} state means ${meaning} → activeState: ${input.activeState}`);
  }, [machineData]);

  // Handle edit input
  const handleEditInput = useCallback((input: MachineInput) => {
    setEditingInput(input);
    setEditDialogOpen(true);
    //Logger.Instance.log(LogCategory.UserInterface, `Opening edit dialog for input: ${input.name}`);
  }, []);

  // Handle delete input - set use flag to false
  const handleDeleteInput = useCallback((input: MachineInput) => {
    input.use = false;
    StateManager.propertyChanged(machineData, 'machineInputs');
    //Logger.Instance.log(LogCategory.UserInterface, `Deleted input (set use=false): ${input.name}`);
  }, [machineData]);

  // Get unused inputs for the add dialog using shared utility
  const getUnusedInputs = useCallback(() => {
    return InputNumberManager.getUnusedInputs(machineData.machineInputs);
  }, [machineData.machineInputs]);

  // Handle opening add input dialog
  const handleOpenAddInput = useCallback(() => {
    setAddInputDialogOpen(true);
    setAddInputIsCreatingNew(false);
    setAddInputQueuedItems(new Set());

    // Set first unused input as current
    const unusedInputs = getUnusedInputs();
    if (unusedInputs.length > 0) {
      setAddInputCurrentItem(unusedInputs[0]);
    } else {
      setAddInputCurrentItem(null);
    }
  }, [getUnusedInputs]);

  // Handle closing add input dialog
  const handleCloseAddInput = useCallback(() => {
    setAddInputDialogOpen(false);
    setAddInputIsCreatingNew(false);
    setAddInputCurrentItem(null);
    setAddInputQueuedItems(new Set());
    setAddInputDeleteQueue(new Set());
  }, []);

  const handleCreateNewInputInAddDialog = useCallback(() => {
    try {
      // Create new input with null number (unassigned) and use: false so it appears in unused inputs list
      const newInput = new MachineInput(
        null, // number - start with null (unassigned)
        'New Input',
        undefined, // centroidMapping
        InputTriggeredState.Closed, // activeState
        'Active', // activeText
        'Inactive', // inactiveText
        false // use: false - this makes it appear in the left list as "unused"
      );

      // Add it to machine data immediately so it appears in the left list
      machineData.machineInputs.push(newInput);

      // Automatically queue it for addition (so it shows "Queued" status)
      setAddInputQueuedItems(prev => {
        const newSet = new Set(prev);
        newSet.add(newInput);
        return newSet;
      });

      // Trigger state update to refresh the UI
      StateManager.propertyChanged(machineData, 'machineInputs');

      // Set as current item for immediate editing
      setAddInputCurrentItem(newInput);
      setAddInputIsCreatingNew(true);

      // Logger.Instance.log(LogCategory.System, 
      //   `Created new input - Name: ${newInput.name}, Number: ${newInput.number}, Automatically queued for addition`);
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Failed to create new input:', error);
    }
  }, [machineData]);

  // Handlers for new Add Input dialog UI
  const handleSelectCurrentItem = useCallback((input: MachineInput) => {
    setAddInputCurrentItem(input);
    setAddInputIsCreatingNew(false);
  }, []);

  const handleQueueInputForAdd = useCallback((input: MachineInput) => {
    setAddInputQueuedItems(prev => {
      const newSet = new Set(prev);
      if (newSet.has(input)) {
        newSet.delete(input);
      } else {
        newSet.add(input);
      }
      return newSet;
    });
  }, []);

  const handleQueueInputForDelete = useCallback((input: MachineInput) => {
    setAddInputDeleteQueue(prev => {
      const newSet = new Set(prev);
      if (newSet.has(input)) {
        newSet.delete(input);
      } else {
        newSet.add(input);
      }
      return newSet;
    });
  }, []);

  const handleProcessQueuedInputs = useCallback(() => {
    // Process additions
    addInputQueuedItems.forEach(input => {
      input.use = true;
      input.number = null; // Set to unassigned
    });

    // Process deletions
    addInputDeleteQueue.forEach(input => {
      const index = machineData.machineInputs.indexOf(input);
      if (index > -1) {
        machineData.machineInputs.splice(index, 1);
      }
    });

    StateManager.propertyChanged(machineData, 'machineInputs');

    const addedCount = addInputQueuedItems.size;
    const deletedCount = addInputDeleteQueue.size;

    if (addedCount > 0) {
      // Logger.Instance.log(LogCategory.UserInterface, 
      //   `Added ${addedCount} inputs: ${Array.from(addInputQueuedItems).map(i => i.name).join(', ')}`);
    }

    if (deletedCount > 0) {
      // Logger.Instance.log(LogCategory.UserInterface, 
      //   `Deleted ${deletedCount} inputs: ${Array.from(addInputDeleteQueue).map(i => i.name).join(', ')}`);
    }

    handleCloseAddInput();
  }, [addInputQueuedItems, addInputDeleteQueue, machineData, handleCloseAddInput]);

  // Handlers for Find Input functionality
  const handleOpenFindInput = useCallback((input: MachineInput) => {
    setFindInputTarget(input);
    setFindInputDialogOpen(true);
    //Logger.Instance.log(LogCategory.UserInterface, `Opening find input dialog for: ${input.name}`);
  }, []);

  const handleCloseFindInput = useCallback(() => {
    setFindInputDialogOpen(false);
    setFindInputTarget(null);
  }, []);

  const handleConfirmInputDetection = useCallback((input: MachineInput, detectedNumber: number) => {
    // Use the shared utility to assign the detected number
    InputNumberManager.assignInputNumber(
      input,
      detectedNumber,
      machineData.machineInputs,
      machineData
    );

    // Close the dialog
    handleCloseFindInput();
  }, [machineData, handleCloseFindInput]);

  // Handlers for Test Input functionality
  const handleOpenTestInput = useCallback((input: MachineInput) => {
    setTestInputTarget(input);
    setTestInputDialogOpen(true);
    //Logger.Instance.log(LogCategory.UserInterface, `Opening test input dialog for: ${input.name}`);
  }, []);

  const handleCloseTestInput = useCallback(() => {
    setTestInputDialogOpen(false);
    setTestInputTarget(null);
  }, []);

  // Get current physical state from machine interface
  const getPhysicalState = useCallback((input: MachineInput): 'open' | 'closed' | 'unknown' => {
    // If input has no assigned number, return unknown
    if (input.number === 0 || input.number === null) {
      return 'unknown';
    }

    // Check if we have state data for this input number
    if (input.number in currentInputStates) {
      const inputValue = currentInputStates[input.number];

      // The physical state is independent of activeState configuration
      // We need a consistent interpretation of the boolean value from the machine interface
      // Let's use a standard convention: true = closed, false = open
      // This represents the physical circuit state, not the logical meaning
      return inputValue ? 'closed' : 'open';
    }

    // No state data available for this input
    return 'unknown';
  }, [currentInputStates]);

  // Get state meaning options
  const getStateMeaningOptions = useCallback((input: MachineInput) => {
    // The dropdown shows what the current physical state means (active or inactive)
    return [
      { value: 'active', label: input.activeText },
      { value: 'inactive', label: input.inactiveText }
    ];
  }, []);

  // Get current dropdown value based on physical state and active state
  const getCurrentMeaning = useCallback((input: MachineInput, physicalState: 'open' | 'closed' | 'unknown'): 'active' | 'inactive' | '' => {
    if (physicalState === 'unknown') return '';

    // If activeState matches physicalState, then current state is "active"
    // If activeState is 'Closed' and physicalState is 'closed' → active
    // If activeState is 'Open' and physicalState is 'open' → active
    // Otherwise → inactive
    if (input.activeState === InputTriggeredState.Closed && physicalState === 'closed') return 'active';
    if (input.activeState === InputTriggeredState.Open && physicalState === 'open') return 'active';
    return 'inactive';
  }, []);

  return (
    <>
      <ObserveState
        listenTo={machineData}
        properties={['machineInputs']}
        control={() => (
          <Box sx={{ p: 3, height: '100%', display: 'flex', flexDirection: 'column' }}>
            {/* Header with title and Add Input button */}
            <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 1 }}>
              <Typography variant="h6">
                Machine Inputs Configuration
              </Typography>
              <Button
                variant="contained"
                startIcon={<AddIcon />}
                onClick={handleOpenAddInput}
                disabled={getUnusedInputs().length === 0}
              >
                Add Input
              </Button>
            </Box>
            <Typography variant="body2" color="text.secondary" sx={{ mb: 3 }}>
              Configure input numbers and state meanings. When you change an input number, any conflicting input will be unassigned.
            </Typography>

            <Box sx={{ flex: 1, overflow: 'auto' }}>
              {(() => {
                const { unassignedInputs, assignedInputs } = getGroupedInputs();

                const renderInput = (input: MachineInput) => {
                  const physicalState = getPhysicalState(input);
                  const stateMeaningOptions = getStateMeaningOptions(input);
                  const currentMeaning = getCurrentMeaning(input, physicalState);

                  return (
                    <Paper
                      key={`${input.number}-${input.name}`}
                      elevation={2}
                      sx={{
                        mb: 2,
                        p: 2,
                        border: '1px solid',
                        borderColor: 'divider',
                        borderRadius: 2
                      }}
                    >
                      <Box sx={{
                        display: 'grid',
                        gridTemplateColumns: '120px 1fr 140px 30px 200px 120px',
                        gap: 2,
                        alignItems: 'center'
                      }}>
                        {/* Input Number */}
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                          <NullableNumberInput
                            value={input.number === 0 ? null : input.number}
                            onChange={(newNumber) => {
                              handleInputNumberChange(input, newNumber);
                            }}
                            size="small"
                            allowNegative={false}
                            min={1}
                            max={999}
                            sx={{ width: 80 }}
                          />
                        </Box>

                        {/* Input Name */}
                        <Typography
                          variant="body2"
                          sx={{
                            fontWeight: 500,
                            color: currentMeaning === 'active' ? getInputActiveColorHex(input.activeColor) : 'text.primary',
                            backgroundColor: currentMeaning === 'active' ? `${getInputActiveColorHex(input.activeColor)}20` : 'transparent',
                            padding: currentMeaning === 'active' ? '4px 8px' : '4px 0px',
                            borderRadius: currentMeaning === 'active' ? 1 : 0,
                            transition: 'all 0.2s ease'
                          }}
                        >
                          {input.name}{currentMeaning === 'active' ? ' (active)' : ''}
                        </Typography>

                        {/* Physical State */}
                        <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 1 }}>
                          {physicalState === 'open' && <OpenIcon />}
                          {physicalState === 'closed' && <ClosedIcon />}
                          {physicalState === 'unknown' && <UnknownIcon />}
                          <Typography variant="caption" color="text.secondary">
                            {physicalState}
                          </Typography>
                        </Box>

                        {/* Equals Sign */}
                        <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center' }}>
                          <Typography variant="h6" color="text.secondary" sx={{ fontWeight: 'bold' }}>
                            =
                          </Typography>
                        </Box>

                        {/* Current Meaning Dropdown */}
                        <FormControl size="small" fullWidth>
                          <Select
                            value={currentMeaning}
                            onChange={(e) => {
                              const meaning = e.target.value as 'active' | 'inactive';
                              if (meaning && physicalState !== 'unknown') {
                                handleStateMeaningChange(input, physicalState, meaning);
                              }
                            }}
                            disabled={physicalState === 'unknown'}
                            displayEmpty
                          >
                            {physicalState === 'unknown' && (
                              <MenuItem value="">
                                <em>Unknown State</em>
                              </MenuItem>
                            )}
                            {stateMeaningOptions.map((option) => (
                              <MenuItem key={option.value} value={option.value}>
                                {option.label}
                              </MenuItem>
                            ))}
                          </Select>
                        </FormControl>

                        {/* Actions */}
                        <Box sx={{ display: 'flex', gap: 0.5, justifyContent: 'center' }}>
                          {/* Test Button (for manually testable inputs) */}
                          {input.isManuallyTestable && (
                            <Tooltip title="Test input functionality">
                              <IconButton
                                onClick={() => handleOpenTestInput(input)}
                                size="small"
                                sx={{
                                  color: 'success.main',
                                  '&:hover': {
                                    backgroundColor: 'success.main',
                                    color: 'white'
                                  }
                                }}
                              >
                                <BugReportIcon />
                              </IconButton>
                            </Tooltip>
                          )}

                          <Tooltip title="Edit input details">
                            <IconButton onClick={() => handleEditInput(input)} size="small">
                              <EditIcon />
                            </IconButton>
                          </Tooltip>
                          <Tooltip title="Remove input from list">
                            <IconButton
                              onClick={() => handleDeleteInput(input)}
                              size="small"
                              sx={{ color: 'error.main' }}
                            >
                              <DeleteIcon />
                            </IconButton>
                          </Tooltip>
                        </Box>
                      </Box>
                    </Paper>
                  );
                };

                return (
                  <>
                    {/* Unassigned Inputs Section */}
                    {unassignedInputs.length > 0 && (
                      <Box sx={{ mb: 3 }}>
                        <Typography
                          variant="subtitle1"
                          sx={{
                            mb: 2,
                            fontWeight: 600,
                            color: 'warning.main',
                            borderBottom: '2px solid',
                            borderColor: 'warning.main',
                            pb: 0.5
                          }}
                        >
                          Unassigned Inputs ({unassignedInputs.length})
                        </Typography>

                        {/* Card layout for unassigned inputs - responsive grid */}
                        <Box sx={{
                          display: 'grid',
                          gridTemplateColumns: {
                            xs: '1fr',           // 1 column on extra small screens
                            sm: 'repeat(2, 1fr)' // 2 columns on small+ screens
                          },
                          gap: 2,
                          mt: 2
                        }}>
                          {unassignedInputs.map((input) => (
                            <Paper
                              key={`unassigned-${input.name}`}
                              elevation={2}
                              sx={{
                                p: 2,
                                border: '1px solid',
                                borderColor: 'divider',
                                borderRadius: 2,
                                backgroundColor: 'background.paper',
                                transition: 'all 0.2s ease',
                                '&:hover': {
                                  elevation: 4,
                                  transform: 'translateY(-1px)'
                                }
                              }}
                            >
                              {/* Single row layout: # [number] name [search] [delete] */}
                              <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                                {/* Hash symbol */}
                                <Typography variant="body2" sx={{ fontWeight: 500, color: 'text.secondary' }}>
                                  #
                                </Typography>

                                {/* Number input */}
                                <NullableNumberInput
                                  value={input.number === 0 ? null : input.number}
                                  onChange={(newNumber) => {
                                    handleInputNumberChange(input, newNumber);
                                  }}
                                  size="small"
                                  allowNegative={false}
                                  min={1}
                                  max={999}
                                  sx={{ width: 80 }}
                                />

                                {/* Input name - flexible width */}
                                <Typography
                                  variant="body1"
                                  sx={{
                                    fontWeight: 600,
                                    flex: 1,
                                    overflow: 'hidden',
                                    textOverflow: 'ellipsis',
                                    whiteSpace: 'nowrap',
                                    ml: 1
                                  }}
                                >
                                  {input.name}
                                </Typography>

                                {/* Action buttons */}
                                {/* Find Input Button (for manually testable inputs) */}
                                {input.isManuallyTestable && (
                                  <Tooltip title="Find input number automatically">
                                    <IconButton
                                      size="medium"
                                      onClick={() => handleOpenFindInput(input)}
                                      sx={{
                                        color: 'primary.main',
                                        '&:hover': {
                                          backgroundColor: 'primary.main',
                                          color: 'white'
                                        }
                                      }}
                                    >
                                      <SearchIcon sx={{ fontSize: '24px' }} />
                                    </IconButton>
                                  </Tooltip>
                                )}

                                {/* Delete Button */}
                                <Tooltip title="Remove input">
                                  <IconButton
                                    size="medium"
                                    onClick={() => handleDeleteInput(input)}
                                    sx={{
                                      color: 'text.secondary',
                                      '&:hover': {
                                        backgroundColor: 'error.main',
                                        color: 'white'
                                      }
                                    }}
                                  >
                                    <DeleteIcon sx={{ fontSize: '24px' }} />
                                  </IconButton>
                                </Tooltip>
                              </Box>
                            </Paper>
                          ))}
                        </Box>
                      </Box>
                    )}

                    {/* Assigned Inputs Section */}
                    {assignedInputs.length > 0 && (
                      <Box>
                        <Typography
                          variant="subtitle1"
                          sx={{
                            mb: 2,
                            fontWeight: 600,
                            color: 'primary.main',
                            borderBottom: '2px solid',
                            borderColor: 'primary.main',
                            pb: 0.5
                          }}
                        >
                          Assigned Inputs ({assignedInputs.length})
                        </Typography>

                        {/* Column Headers */}
                        <Box sx={{
                          display: 'grid',
                          gridTemplateColumns: '120px 1fr 140px 30px 200px 120px',
                          gap: 2,
                          alignItems: 'center',
                          mb: 1,
                          px: 2,
                          py: 1
                        }}>
                          <Typography variant="caption" sx={{ fontWeight: 600, color: 'text.secondary' }}>
                            #
                          </Typography>
                          <Typography variant="caption" sx={{ fontWeight: 600, color: 'text.secondary' }}>
                            Name
                          </Typography>
                          <Typography variant="caption" sx={{ fontWeight: 600, color: 'text.secondary', textAlign: 'center' }}>
                            Input State
                          </Typography>
                          <Box /> {/* Empty space for equals sign column */}
                          <Typography variant="caption" sx={{ fontWeight: 600, color: 'text.secondary' }}>
                            Machine State
                          </Typography>
                          <Typography variant="caption" sx={{ fontWeight: 600, color: 'text.secondary', textAlign: 'center' }}>
                            Actions
                          </Typography>
                        </Box>

                        {assignedInputs.map((input, index) => {
                          const elements = [renderInput(input)];

                          // Check if there's a gap before the next input
                          if (index < assignedInputs.length - 1) {
                            const currentNumber = input.number;
                            const nextNumber = assignedInputs[index + 1].number;
                            if (typeof currentNumber === 'number' && typeof nextNumber === 'number' && nextNumber - currentNumber > 1) {
                              // Add extra spacing for gap
                              elements.push(
                                <Box key={`gap-${currentNumber}-${nextNumber}`} sx={{ height: '20px' }} />
                              );
                            }
                          }

                          return elements;
                        }).flat()}
                      </Box>
                    )}
                  </>
                );
              })()}
            </Box>

            {(() => {
              const { unassignedInputs, assignedInputs } = getGroupedInputs();
              return (unassignedInputs.length === 0 && assignedInputs.length === 0);
            })() && (
                <Box sx={{ textAlign: 'center', mt: 4 }}>
                  <Typography variant="body2" color="text.secondary">
                    No inputs are currently marked as "used". Configure inputs in Machine Data to see them here.
                  </Typography>
                </Box>
              )}
          </Box>
        )}
      />

      {/* Add Input Dialog */}
      <Dialog
        open={addInputDialogOpen}
        onClose={handleCloseAddInput}
        maxWidth="lg"
        fullWidth
      >
        <DialogTitle>Add Machine Inputs</DialogTitle>
        <DialogContent>
          <Grid container spacing={2}>
            {/* Left Panel - Input List */}
            <Grid item xs={6}>
              <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                Select an input to configure, then click "Add" to queue it for addition.
              </Typography>
              <List sx={{
                border: '1px solid',
                borderColor: 'divider',
                borderRadius: 1,
                height: 'calc(100vh - 350px)',
                minHeight: 400,
                overflow: 'auto'
              }}>
                {getUnusedInputs().map((input) => {
                  const isQueued = addInputQueuedItems.has(input);
                  const isToDelete = addInputDeleteQueue.has(input);

                  return (
                    <ListItem
                      key={input.name}
                      disablePadding
                      sx={{
                        backgroundColor: addInputCurrentItem === input ? 'action.selected' : 'transparent',
                        borderBottom: '1px solid',
                        borderColor: 'divider',
                        opacity: isToDelete ? 0.6 : 1
                      }}
                    >
                      <ListItemButton
                        onClick={() => handleSelectCurrentItem(input)}
                        sx={{ flex: 1 }}
                        disabled={isToDelete}
                      >
                        <ListItemText
                          primary={
                            <Typography
                              sx={{
                                textDecoration: isToDelete ? 'line-through' : 'none',
                                color: isToDelete ? 'text.secondary' : 'text.primary'
                              }}
                            >
                              {input.name}
                            </Typography>
                          }
                          secondary={
                            <Box>
                              <Typography
                                variant="body2"
                                color="text.secondary"
                                sx={{ textDecoration: isToDelete ? 'line-through' : 'none' }}
                              >
                                Active: {input.activeText}
                              </Typography>
                              <Typography
                                variant="body2"
                                color="text.secondary"
                                sx={{ textDecoration: isToDelete ? 'line-through' : 'none' }}
                              >
                                Inactive: {input.inactiveText}
                              </Typography>
                            </Box>
                          }
                        />
                      </ListItemButton>
                      <Box sx={{ px: 1, display: 'flex', gap: 1 }}>
                        {/* Delete Button */}
                        <Tooltip title={isToDelete ? "Restore from delete queue" : "Queue for deletion"}>
                          <Button
                            size="small"
                            variant={isToDelete ? "outlined" : "text"}
                            color={isToDelete ? "warning" : "error"}
                            onClick={() => handleQueueInputForDelete(input)}
                            sx={{ minWidth: 60 }}
                          >
                            <DeleteIcon fontSize="small" />
                          </Button>
                        </Tooltip>

                        {/* Add Button - disabled if marked for deletion */}
                        {!isToDelete && (
                          isQueued ? (
                            <Tooltip title="Remove from add queue">
                              <Button
                                size="small"
                                variant="outlined"
                                color="warning"
                                onClick={() => handleQueueInputForAdd(input)}
                                sx={{ minWidth: 80 }}
                              >
                                Queued
                              </Button>
                            </Tooltip>
                          ) : (
                            <Tooltip title="Add this input to queue">
                              <Button
                                size="small"
                                variant="contained"
                                onClick={() => handleQueueInputForAdd(input)}
                                sx={{ minWidth: 80 }}
                              >
                                Add
                              </Button>
                            </Tooltip>
                          )
                        )}
                      </Box>
                    </ListItem>
                  );
                })}
                {getUnusedInputs().length === 0 && (
                  <ListItem>
                    <ListItemText
                      primary="No unused inputs available"
                      secondary="All inputs are already in use"
                    />
                  </ListItem>
                )}
              </List>
              <Box sx={{ mt: 2 }}>
                <Button
                  startIcon={<AddIcon />}
                  onClick={handleCreateNewInputInAddDialog}
                  variant="outlined"
                  size="small"
                >
                  Create New Input
                </Button>
              </Box>
            </Grid>

            {/* Right Panel - Input Editor */}
            <Grid item xs={6}>
              <Divider orientation="vertical" flexItem sx={{ position: 'absolute', left: '50%', top: 0, bottom: 0 }} />
              <Box sx={{ height: '100%', display: 'flex', flexDirection: 'column' }}>
                {addInputCurrentItem ? (
                  <Box sx={{ flexShrink: 0 }}>
                    <MachineInputEditor
                      input={addInputCurrentItem}
                      title={addInputIsCreatingNew ? "Create New Input" : `Edit: ${addInputCurrentItem?.name}`}
                    />
                  </Box>
                ) : (
                  <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'center', height: 300 }}>
                    <Typography variant="body2" color="text.secondary" align="center">
                      Select an input from the list to view and edit its properties
                    </Typography>
                  </Box>
                )}
              </Box>
            </Grid>
          </Grid>
        </DialogContent>
        <DialogActions>
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, width: '100%' }}>
            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.5 }}>
              {addInputQueuedItems.size > 0 && (
                <Typography variant="body2" color="text.secondary">
                  {addInputQueuedItems.size} input{addInputQueuedItems.size > 1 ? 's' : ''} queued for addition
                </Typography>
              )}
              {addInputDeleteQueue.size > 0 && (
                <Typography variant="body2" color="error.main">
                  {addInputDeleteQueue.size} input{addInputDeleteQueue.size > 1 ? 's' : ''} queued for deletion
                </Typography>
              )}
              {addInputQueuedItems.size === 0 && addInputDeleteQueue.size === 0 && (
                <Typography variant="body2" color="text.secondary">
                  No changes queued
                </Typography>
              )}
            </Box>
            <Box sx={{ ml: 'auto', display: 'flex', gap: 1 }}>
              <Button onClick={handleCloseAddInput}>Cancel</Button>
              <Button
                onClick={handleProcessQueuedInputs}
                variant="contained"
                disabled={addInputQueuedItems.size === 0 && addInputDeleteQueue.size === 0}
              >
                Done
              </Button>
            </Box>
          </Box>
        </DialogActions>
      </Dialog>

      {/* Edit Input Dialog */}
      <Dialog
        open={editDialogOpen}
        onClose={() => {
          setEditDialogOpen(false);
          setEditingInput(null);
        }}
        maxWidth="md"
        fullWidth
      >
        <DialogTitle>Edit Input</DialogTitle>
        <DialogContent>
          {editingInput && (
            <MachineInputEditor
              input={editingInput}
              title={null}
            />
          )}
        </DialogContent>
        <DialogActions>
          <Button
            onClick={() => {
              setEditDialogOpen(false);
              setEditingInput(null);
              //Logger.Instance.log(LogCategory.UserInterface, 'Input edit dialog closed');
            }}
            variant="contained"
            sx={{
              position: 'absolute',
              right: 24,
              bottom: 24
            }}
          >
            Done
          </Button>
        </DialogActions>
      </Dialog>

      {/* Find Input Dialog */}
      <FindInputDialog
        open={findInputDialogOpen}
        input={findInputTarget}
        onClose={handleCloseFindInput}
        onConfirm={handleConfirmInputDetection}
      />

      {/* Test Input Dialog */}
      <TestInputDialog
        open={testInputDialogOpen}
        input={testInputTarget}
        onClose={handleCloseTestInput}
      />
    </>
  );
}
