import {
  Box,
  Button,
  Paper,
  Typography
} from "@mui/material";
import React from "react";
import { ConfigurationData } from "../../../../data/ConfigurationData";
import { MachineData } from "../../../../data/MachineData";
import { MachineStateData } from "../../../../data/MachineStateData";
import { JogControls } from "../../../Common/JogControls";
import { FullSizeCNCViewer } from "../../../MachineViewer/FullSizeCNCViewer";
import { WizardStep } from "../../../Wizard/WizardStep";
import { AxisCalibrationWizard } from "../AxisCalibrationWizard";
import { AxisCalibrationData } from "./AxisCalibrationData";

export class AxisCalibrationPositionStep extends WizardStep {
  constructor(wizard: AxisCalibrationWizard, priorStep: WizardStep | null = null) {
    super(wizard, priorStep);
  }

  getTitle(): string {
    const axisConfig = this.wizard.state.axisConfig;
    return `${axisConfig.axisType} Axis Calibration - Position Setup`;
  }

  nextStep(): WizardStep | null {
    // Capture the current machine position as the starting point
    AxisCalibrationData.Instance.setStartingPointFromCurrent();
    
    // Go directly to marking step - user will mark the starting point
    const { AxisCalibrationMarkStep } = require("./AxisCalibrationMarkStep");
    return new AxisCalibrationMarkStep(this.wizard as AxisCalibrationWizard, this, 'start');
  }

  backStep(): WizardStep | null {
    return null; // This is the first step
  }

  render(): React.ReactNode {
    const axisConfig = this.wizard.state.axisConfig;
    
    return (
      <Box sx={{ p: 3, height: '100%', display: 'flex', flexDirection: 'column', gap: 3 }}>
        {/* Main Content Area */}
        <Box sx={{ display: 'flex', gap: 3, flex: 1, minHeight: 0 }}>
          {/* Left Side - Instructions and Controls (50%) */}
          <Box sx={{ flex: '50%', display: 'flex', flexDirection: 'column', gap: 3 }}>
            {/* Instructions */}
            <Paper sx={{ p: 2 }}>
              <Typography variant="subtitle1" gutterBottom>
                Position the {axisConfig.axisType} Axis
              </Typography>
              <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                Use the jog controls below to move the machine so the tool is <Typography component="span" color="error" sx={{ fontWeight: 'bold' }}>touching the material surface</Typography> at your desired starting position for the {axisConfig.axisType} axis calibration.
              </Typography>
              <Typography variant="body2" color="text.secondary">
                Choose a location where you can accurately measure movement along the {axisConfig.axisType} axis. The tool should be in contact with the material to ensure a precise reference point.
              </Typography>
            </Paper>

            {/* Jog Controls */}
            <Box sx={{ flex: 1, minHeight: 0 }}>
              <JogControls />
            </Box>
          </Box>

          {/* Right Side - 3D Viewer (50%) */}
          <Box sx={{ flex: '50%', display: 'flex', flexDirection: 'column', minHeight: 0 }}>
            <FullSizeCNCViewer 
              simulatorView={ConfigurationData.Instance.defaultView}
              machineState={MachineStateData.Instance}
              machineData={MachineData.Instance}
              job={MachineStateData.Instance.currentJob!}
              enableOrbit={true}
              enableClampDragging={false}
              enableSpindleDrag={true}
            />
          </Box>
        </Box>

        {/* Action Buttons */}
        <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <Button 
            variant="outlined"
            onClick={() => this.wizard.closeWizard()}
          >
            Cancel
          </Button>
          <Button 
            variant="contained"
            onClick={() => this.wizard.advanceToNextStep()}
            size="large"
          >
            Set Starting Position
          </Button>
        </Box>
      </Box>
    );
  }
}