import { PlayArrow as PlayArrowIcon } from '@mui/icons-material';
import { Box, Checkbox, FormControlLabel, TextField, Typography } from '@mui/material';
import React, { useState } from 'react';
import { Machine } from '../../../../machine/Machine';
import { DataUtilities } from '../../../../utils/storage/DataUtilities';
import { FlowStep } from "../../../FlowStep";
import { FlowStepData } from "../../../FlowStepData";

export class RunGCodeStep extends FlowStep {
    readonly __type = 'RunGCodeStep';
    readonly category = ['Machine', 'Program'];
    readonly name = 'Run G-Code';
    readonly description = 'Loads and executes G-Code program';
    
    // Icon is created dynamically, not stored
    get icon(): React.ReactNode {
        return React.createElement(PlayArrowIcon, { sx: { color: 'success.main' } });
    }

    // Step parameters
    public gcode: string[] = [
        'G21 ; Set units to millimeters',
        'G90 ; Absolute positioning',
        'G17 ; XY plane selection',
        'M3 S1000 ; Start spindle',
        'G0 X0 Y0 Z5 ; Move to start position',
        'G1 Z-1 F100 ; Plunge',
        'G1 X10 Y10 F300 ; Linear move',
        'G0 Z5 ; Retract',
        'M5 ; Stop spindle',
        'M30 ; Program end'
    ];
    public startImmediately: boolean = true;
    public gcodeParameterString: string = '';

    static readonly DONE_PATH = 'done';

    async execute(data: FlowStepData, prototypeRun: boolean): Promise<string | null> {
        if (prototypeRun) {
            return RunGCodeStep.DONE_PATH;
        }

        try {
            await Machine.getInstance().program.RunGCode(this.gcode, this.startImmediately, this.gcodeParameterString);
            return RunGCodeStep.DONE_PATH;
        } catch (error) {
            console.error('RunGCode failed:', error);
            return RunGCodeStep.DONE_PATH;
        }
    }

    results(): string[] {
        return [RunGCodeStep.DONE_PATH];
    }

    renderResultsUI(data: FlowStepData, result: string): React.ReactNode {
        return (
            <Typography variant="caption">
                Run G-code: {result} ({this.gcode.length} lines)
            </Typography>
        );
    }

    renderConfigurationUI(data: FlowStepData): React.ReactNode {
        const GCodeEditor = () => {
            const [gcodeText, setGCodeText] = useState(this.gcode.join('\n'));
            const [startImmediately, setStartImmediately] = useState(this.startImmediately);
            const [gcodeParameterString, setGcodeParameterString] = useState(this.gcodeParameterString);

            const handleGCodeChange = (event: React.ChangeEvent<HTMLInputElement>) => {
                const newValue = event.target.value;
                setGCodeText(newValue);
                this.gcode = newValue.split('\n').filter(line => line.trim() !== '');
            };

            const handleStartImmediatelyChange = (event: React.ChangeEvent<HTMLInputElement>) => {
                const newValue = event.target.checked;
                setStartImmediately(newValue);
                this.startImmediately = newValue;
            };

            const handleParameterStringChange = (event: React.ChangeEvent<HTMLInputElement>) => {
                const newValue = event.target.value;
                setGcodeParameterString(newValue);
                this.gcodeParameterString = newValue;
            };

            return (
                <Box sx={{ mt: 2 }}>
                    <Typography variant="subtitle1" gutterBottom>
                        G-Code Program
                    </Typography>
                    <TextField
                        fullWidth
                        multiline
                        rows={10}
                        value={gcodeText}
                        onChange={handleGCodeChange}
                        placeholder="Enter G-code commands, one per line..."
                        variant="outlined"
                        sx={{
                            fontFamily: 'monospace',
                            '& .MuiInputBase-input': {
                                fontFamily: 'monospace',
                                fontSize: '0.875rem'
                            }
                        }}
                    />
                    <Typography variant="caption" color="text.secondary" sx={{ mt: 1, display: 'block' }}>
                        {this.gcode.length} lines of G-code
                    </Typography>
                    <TextField
                        fullWidth
                        label="G-Code Parameter String"
                        value={gcodeParameterString}
                        onChange={handleParameterStringChange}
                        placeholder="Optional parameter string..."
                        variant="outlined"
                        sx={{ mt: 2 }}
                        helperText="Optional parameter string for G-code execution"
                    />
                    <FormControlLabel
                        control={
                            <Checkbox
                                checked={startImmediately}
                                onChange={handleStartImmediatelyChange}
                            />
                        }
                        label="Start immediately after loading"
                        sx={{ mt: 1 }}
                    />
                </Box>
            );
        };

        return React.createElement(GCodeEditor);
    }

    public toJSON(): any {
        const data = DataUtilities.getStorageData(this, ['icon']) as any;
        data.__type = this.__type;
        return data;
    }

    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data);
    }
}





