import { Box, Button, Typography } from '@mui/material';
import { Build } from '@mui/icons-material';
import { useState } from 'react';
import { ConfigurationData } from '../../data/ConfigurationData';
import { ToolLibrary } from '../../data/Common/ToolLibrary';
import { MachineStateData } from '../../data/MachineStateData';
import { ObserveState } from '../../utils/statemanager/ObserveState';
import { ToolSelectionDialog } from './ToolSelectionDialog';

export function CurrentToolSelector() {
    const [config] = useState(() => ConfigurationData.Instance);
    const [machineState] = useState(() => MachineStateData.Instance);
    const [toolLibrary] = useState(() => ToolLibrary.Instance);
    const [dialogOpen, setDialogOpen] = useState(false);

    return (
        <>
            <ObserveState
                key="current-tool-selector"
                listenTo={machineState}
                properties={['currentToolNumber']}
                control={() => {
                    const currentToolNumber = machineState.currentToolNumber;
                    const tool = toolLibrary.tools.find(t => t.toolNumber === currentToolNumber);

                    return (
                        <Box sx={{ width: '100%' }}>
                            <Typography
                                variant="caption"
                                sx={{
                                    color: config.mutedTextColor,
                                    display: 'block',
                                    mb: 0.5,
                                    fontSize: '0.75rem'
                                }}
                            >
                                Current Tool
                            </Typography>
                            <Button
                                fullWidth
                                variant="outlined"
                                onClick={() => setDialogOpen(true)}
                                startIcon={<Build />}
                                sx={{
                                    justifyContent: 'flex-start',
                                    textTransform: 'none',
                                    py: 1.5,
                                    borderColor: config.borderColor,
                                    '&:hover': {
                                        borderColor: config.primaryColor,
                                        backgroundColor: `${config.primaryColor}11`
                                    }
                                }}
                            >
                                {tool ? (
                                    <Typography variant="body1" sx={{ fontWeight: 'bold' }}>
                                        T{tool.toolNumber.toString().padStart(2, '0')} - {tool.displayName}
                                    </Typography>
                                ) : (
                                    <Typography variant="body1" color="text.secondary">
                                        No tool selected
                                    </Typography>
                                )}
                            </Button>
                        </Box>
                    );
                }}
            />

            <ToolSelectionDialog
                open={dialogOpen}
                onClose={() => setDialogOpen(false)}
            />
        </>
    );
}
