import React from 'react';
import { Box, Typography, Button, Alert } from '@mui/material';
import { CheckCircle as CheckIcon } from '@mui/icons-material';
import { WizardStep } from '../../../Wizard/WizardStep';
import { ConfigurationData } from '../../../../data/ConfigurationData';

export class HomingCompletionStep extends WizardStep {
  getTitle(): string {
    return 'Homing Complete';
  }

  nextStep(): WizardStep | null {
    return null; // Final step
  }

  backStep(): WizardStep | null {
    return this.priorStep;
  }

  render(): React.ReactNode {
    return (
      <Box sx={{ p: 3, display: 'flex', flexDirection: 'column', gap: 2, minHeight: 400 }}>
        <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 1, mb: 2 }}>
          <CheckIcon sx={{ fontSize: 80, color: 'success.main' }} />
          <Typography variant="h4" color="success.main" textAlign="center">
            Machine Successfully Homed!
          </Typography>
        </Box>

        <Alert severity="success" sx={{ mb: 2 }}>
          <Typography variant="h6" gutterBottom>
            Homing sequence completed successfully
          </Typography>
          <Typography variant="body2">
            Your CNC machine has found its home position and is now ready for operation. 
            All coordinate systems have been properly established.
          </Typography>
        </Alert>

        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1, mb: 2 }}>
          <Typography variant="h6" color="text.primary">
            What happens now:
          </Typography>
          <Box sx={{ ml: 2 }}>
            <Typography variant="body2" paragraph sx={{ mb: 1 }}>
              ✓ <strong>Machine coordinates established:</strong> The machine now knows its precise position
            </Typography>
            <Typography variant="body2" paragraph sx={{ mb: 1 }}>
              ✓ <strong>Work coordinates available:</strong> You can now set up fixtures and work offsets
            </Typography>
            <Typography variant="body2" paragraph sx={{ mb: 1 }}>
              ✓ <strong>Safe operation enabled:</strong> All safety systems are active and monitoring limits
            </Typography>
            <Typography variant="body2" paragraph sx={{ mb: 1 }}>
              ✓ <strong>Ready for jobs:</strong> You can now load and run CNC programs
            </Typography>
          </Box>
        </Box>

        <Alert severity="info" sx={{ mb: 2 }}>
          <Typography variant="body2">
            <strong>Tip:</strong> Your machine will remember its home position until it's powered off or an emergency stop is triggered. 
            You only need to home the machine once per session unless specifically required.
          </Typography>
        </Alert>

        <Box sx={{ display: 'flex', justifyContent: 'flex-end', mt: 'auto', pt: 2 }}>
          <Button
            variant="contained"
            size="large"
            onClick={() => this.wizard.closeWizard()}
            sx={{ 
              backgroundColor: ConfigurationData.Instance.primaryColor,
              minWidth: 200,
              py: 1.5
            }}
          >
            Done
          </Button>
        </Box>
      </Box>
    );
  }
}
