/**
 * Enum representing the available colors for displaying active machine inputs
 */
export enum InputActiveColor {
  Blue = 0,
  Red = 1,
  Green = 2,
  Yellow = 3
}

/**
 * Helper function to get the hex color value for an InputActiveColor
 */
export function getInputActiveColorHex(color: InputActiveColor): string {
  switch (color) {
    case InputActiveColor.Blue:
      return '#2196f3'; // Material Blue
    case InputActiveColor.Red:
      return '#f44336'; // Material Red
    case InputActiveColor.Green:
      return '#4caf50'; // Material Green
    case InputActiveColor.Yellow:
      return '#ff9800'; // Material Orange/Yellow
    default:
      return '#4caf50'; // Default to green
  }
}

/**
 * Helper function to get the display name for an InputActiveColor
 */
export function getInputActiveColorName(color: InputActiveColor): string {
  switch (color) {
    case InputActiveColor.Blue:
      return 'Blue';
    case InputActiveColor.Red:
      return 'Red';
    case InputActiveColor.Green:
      return 'Green';
    case InputActiveColor.Yellow:
      return 'Yellow';
    default:
      return 'Green';
  }
}
