import { LocationOn as LocationOnIcon } from '@mui/icons-material';
import { Typography } from '@mui/material';
import React from 'react';
import { CNCPoint } from '../../../../data/CNCPoint';
import { CoordinateType } from '../../../../data/Common/CoordinateType';
import { Machine } from '../../../../machine/Machine';
import { DataUtilities } from '../../../../utils/storage/DataUtilities';
import { FlowStep } from "../../../FlowStep";
import { FlowStepData } from "../../../FlowStepData";

export class GetCurrentPositionStep extends FlowStep {
    readonly __type = 'GetCurrentPositionStep';
    readonly category = ['Machine', 'Movement'];
    readonly name = 'Get Current Position';
    readonly description = 'Gets the current machine position';
    
    // Icon is created dynamically, not stored
    get icon(): React.ReactNode {
        return React.createElement(LocationOnIcon, { sx: { color: 'info.main' } });
    }
    static readonly SUCCESS_PATH = 'success';
    async execute(data: FlowStepData, prototypeRun: boolean): Promise<string | null> {
        if (prototypeRun) {
            return GetCurrentPositionStep.SUCCESS_PATH;
        }

        try {
            const position = await Machine.getInstance().movement.GetCurrentPosition();
            // Store position in flow data for use by subsequent steps
            data.setVariable('currentPosition', position);
            return GetCurrentPositionStep.SUCCESS_PATH;
        } catch (error) {
            console.error('GetCurrentPosition failed:', error);
            // Still return success with fallback value - the step completed its attempt
            data.setVariable('currentPosition', new CNCPoint(0, 0, 0, CoordinateType.MachineZero));
            return GetCurrentPositionStep.SUCCESS_PATH;
        }
    }

    results(): string[] {
        return [GetCurrentPositionStep.SUCCESS_PATH];
    }

    renderResultsUI(data: FlowStepData, result: string): React.ReactNode {
        const position = data.getVariable('currentPosition');
        return (
            <Typography variant="caption">
                Get current position: {result}
                {position && ` (X:${position.x}, Y:${position.y}, Z:${position.z})`}
            </Typography>
        );
    }

    public toJSON(): any {
        const data = DataUtilities.getStorageData(this, ['icon']) as any;
        data.__type = this.__type;
        return data;
    }

    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data);
    }
}






