import {
  Alert,
  Box,
  Button,
  Paper,
  Typography
} from "@mui/material";
import React from "react";
import { ConfigurationData } from "../../../../data/ConfigurationData";
import { MachineData } from "../../../../data/MachineData";
import { MachineStateData } from "../../../../data/MachineStateData";
import { AutoBind } from "../../../../utils/AutoBind";
import { FullSizeCNCViewer } from "../../../MachineViewer/FullSizeCNCViewer";
import { WizardStep } from "../../../Wizard/WizardStep";
import { AxisCalibrationWizard } from "../AxisCalibrationWizard";
import { AxisCalibrationData } from "./AxisCalibrationData";

export class AxisCalibrationReturnStep extends WizardStep {
  constructor(wizard: AxisCalibrationWizard, priorStep: WizardStep | null = null) {
    super(wizard, priorStep);
  }

  getTitle(): string {
    return `${AxisCalibrationData.Instance.axis} Axis Calibration - Return to Starting Position`;
  }

  nextStep(): WizardStep | null {
    // Go back to position step (first step) to continue iterative calibration
    const { AxisCalibrationPositionStep } = require("./AxisCalibrationPositionStep");
    return new AxisCalibrationPositionStep(this.wizard as AxisCalibrationWizard, this);
  }

  backStep(): WizardStep | null {
    return this.priorStep;
  }

  @AutoBind
  private continueCalibration(): void {
    this.wizard.advanceToNextStep();
  }

  render(): React.ReactNode {
    return (
      <Box sx={{ p: 3, height: '100%', display: 'flex', flexDirection: 'column', gap: 3 }}>

        <Alert severity="info">
          <Typography variant="body1">
            <strong>Return and Re-Test</strong>
          </Typography>
          <Typography variant="body2" sx={{ mt: 1 }}>
            The calibration has been applied. You can now return to the starting position and run another test to verify the accuracy.
          </Typography>
        </Alert>

        {/* Main Content Area */}
        <Box sx={{ display: 'flex', gap: 3, flex: 1, minHeight: 0 }}>
          {/* Left Side - Instructions (50%) */}
          <Box sx={{ flex: '50%', display: 'flex', flexDirection: 'column', gap: 3 }}>

            {/* Return Instructions */}
            <Paper sx={{ p: 3 }}>
              <Typography variant="h6" gutterBottom>
                Return to Starting Position
              </Typography>

              <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                The return process will:
              </Typography>

              <Box component="ol" sx={{ pl: 2, mb: 3 }}>
                <Typography component="li" variant="body2" color="text.secondary" sx={{ mb: 1 }}>
                  Move up 1" in Z to clear any obstacles
                </Typography>
                <Typography component="li" variant="body2" color="text.secondary" sx={{ mb: 1 }}>
                  Return to the original X/Y starting position
                </Typography>
                <Typography component="li" variant="body2" color="text.secondary" sx={{ mb: 1 }}>
                  Move down 1" in Z to the original height
                </Typography>
                <Typography component="li" variant="body2" color="text.secondary" sx={{ mb: 1 }}>
                  Allow you to mark, move {AxisCalibrationData.Instance.distanceToMove}" again, and re-measure
                </Typography>
              </Box>

              <Typography variant="body2" color="text.secondary">
                You can repeat this process as many times as needed to achieve the desired accuracy.
                the desired accuracy. You can repeat this process as many times as needed.
              </Typography>
            </Paper>
          </Box>

          {/* Right Side - 3D Viewer (50%) */}
          <Box sx={{ flex: '50%', display: 'flex', flexDirection: 'column', minHeight: 0 }}>
            <FullSizeCNCViewer
              simulatorView={ConfigurationData.Instance.defaultView}
              machineState={MachineStateData.Instance}
              machineData={MachineData.Instance}
              job={MachineStateData.Instance.currentJob!}
              enableOrbit={true}
              enableClampDragging={false}
              enableSpindleDrag={false}
            />
          </Box>
        </Box>

        {/* Action Buttons */}
        <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <Button
            variant="outlined"
            onClick={() => this.wizard.goToPreviousStep()}
          >
            Back to Results
          </Button>

          <Button
            variant="contained"
            onClick={this.continueCalibration}
            size="large"
          >
            Continue Calibration
          </Button>
        </Box>
      </Box>
    );
  }
}