import * as THREE from 'three';
import { CNCPoint } from '../data/CNCPoint';
import { Box } from '../data/Common/Box';
import { BoxIntersectionResult } from '../data/Common/BoxIntersectionResult';
import { BoxPoints } from '../data/Common/BoxPoints';
import { CoordinateType } from '../data/Common/CoordinateType';
import { MaterialPositionReference } from '../data/Common/MaterialPositionReference';
import { Plane } from '../data/Common/Plane';
import { PlaneOffset } from '../data/Common/PlaneOffset';
import { ToolLibrary } from '../data/Common/ToolLibrary';
import { MachineData } from '../data/MachineData';
import { MachineStateData } from '../data/MachineStateData';
import { ToolOffsets } from '../data/types';

/**
 * Coordinate transformation utilities
 * Direct conversion from C# CoordinateUtil class
 */
export class CoordinateUtil {
  /**
   * Get machine home corner point in simulator coordinates
   * This represents the positive extents of the machine's travel limits
   * @returns CNCPoint in Simulator coordinate system
   * Direct conversion from C# SimulatorLimitsFrom3DZero property
   */
  static get machineHomeCorner(): CNCPoint {
    const machineData = MachineData.Instance;
    return new CNCPoint(
      machineData.simulatorLimitsFromMachineBaseTopOriginX,
      machineData.simulatorLimitsFromMachineBaseTopOriginY,
      machineData.baseHeight + machineData.simulatorLimitsFromMachineBaseTopOriginZ,
      CoordinateType.Simulator
    );
  }

  /**
   * Get machine zero point in simulator coordinates
   * This is the origin point for machine coordinate system expressed in simulator coordinates
   * @returns CNCPoint in Simulator coordinate system
   * Direct conversion from C# SimulatorMachineZero property
   */
  static get machineZeroPoint(): CNCPoint {
    const homeCorner = CoordinateUtil.machineHomeCorner;
    const machineData = MachineData.Instance;

    return new CNCPoint(
      homeCorner.x + machineData.machineZeroCoordinatesFromMachineHomeX,
      homeCorner.y + machineData.machineZeroCoordinatesFromMachineHomeY,
      homeCorner.z + machineData.machineZeroCoordinatesFromMachineHomeZ,
      CoordinateType.Simulator
    );
  }

  /**
   * Get spoilboard zero point (top surface of spoilboard in simulator coordinates)
   * This provides a reference point for positioning materials on the spoilboard surface
   */
  static get spoilboardZero(): CNCPoint {
    const machineData = MachineData.Instance;
    const machineState = MachineStateData.Instance;

    // Calculate spoilboard top surface Z coordinate
    const spoilboardTopZ = machineData.baseHeight + machineData.bedHeight + machineState.spoilBoardHeight;

    // Calculate spoilboard front-left corner position relative to the bed
    // X: bed offset from base front-left + spoilboard X offset  
    // Y: bed offset from base front-left + spoilboard Y offset

    return new CNCPoint(
      machineData.bedOffsetX + machineState.spoilboardX,
      machineData.bedOffsetY + machineState.spoilboardY,
      spoilboardTopZ,
      CoordinateType.Simulator
    );
  }

  /**
   * Get machine home as a CNCPoint in machine coordinates
   * This computes the home position based on simulatorLimitsFromMachineBaseTopOrigin
   * adjusted for the machine base dimensions
   */
  static get machineHome(): CNCPoint {
    const machineData = MachineData.Instance;

    // The simulator limits are defined from the machine base top origin
    // We need to convert these to machine coordinates by accounting for the base height
    return new CNCPoint(
      machineData.simulatorLimitsFromMachineBaseTopOriginX,
      machineData.simulatorLimitsFromMachineBaseTopOriginY,
      machineData.simulatorLimitsFromMachineBaseTopOriginZ + machineData.baseHeight,  // Adjust for base height
      CoordinateType.Simulator
    );
  }

  /**
   * Convert any point to machine zero coordinate system
   * This is the canonical coordinate system - all other conversions go through this
   * @param point The point to convert
   */
  static toMachineZero(point: CNCPoint): CNCPoint {
    const { coordinateType } = point;

    if (coordinateType === CoordinateType.MachineZero) {
      return point;
    }

    if (coordinateType === CoordinateType.WorkZero) {
      const currentWorkZero = MachineStateData.Instance.currentWorkZero;
      return new CNCPoint(
        point.x + currentWorkZero.x,
        point.y + currentWorkZero.y,
        point.z + currentWorkZero.z,
        CoordinateType.MachineZero
      );
    }

    if (coordinateType === CoordinateType.Simulator) {
      const machineZeroPoint = CoordinateUtil.machineZeroPoint;
      return new CNCPoint(
        point.x - machineZeroPoint.x,
        point.y - machineZeroPoint.y,
        point.z - machineZeroPoint.z,
        CoordinateType.MachineZero
      );
    }

    if (coordinateType === CoordinateType.MachineHome) {
      const homeCorner = CoordinateUtil.machineHomeCorner;
      const machineZeroPoint = CoordinateUtil.machineZeroPoint;
      return new CNCPoint(
        point.x + homeCorner.x - machineZeroPoint.x,
        point.y + homeCorner.y - machineZeroPoint.y,
        point.z + homeCorner.z - machineZeroPoint.z,
        CoordinateType.MachineZero
      );
    }

    if (coordinateType === CoordinateType.WorkZeroWithOffsets) {
      const currentWorkZero = MachineStateData.Instance.currentWorkZero;
      const toolOffsets = CoordinateUtil.getCurrentOffsets();
      // WorkZeroWithOffsets is tool TIP position relative to fixture
      // To get spindle BOTTOM position (MachineZero), subtract tool offsets
      return new CNCPoint(
        point.x + currentWorkZero.x - toolOffsets.x,
        point.y + currentWorkZero.y - toolOffsets.y,
        point.z + currentWorkZero.z - toolOffsets.z,
        CoordinateType.MachineZero
      );
    }

    throw new Error(`Invalid coordinate type: ${coordinateType}`);
  }

  /**
   * Get the effective tool length for coordinate calculations
   * Uses measured length if available, otherwise falls back to lengthBelowHolder
   * @deprecated Use getCurrentOffsets() instead for more comprehensive offset handling
   */
  private static getEffectiveToolLength(): number {
    return CoordinateUtil.getCurrentOffsets().z;
  }

  /**
   * Convert any point to fixture offset coordinate system (spindle bottom relative to fixture)
   * Simplified approach: convert to MachineZero first, then apply fixture offset transformation
   * @param point The point to convert
   */
  static toFixtureOffset(point: CNCPoint): CNCPoint {
    const { coordinateType } = point;

    if (coordinateType === CoordinateType.WorkZero) {
      return point;
    }

    // First convert to MachineZero (canonical coordinate system)
    const machineZeroPoint = CoordinateUtil.toMachineZero(point);

    // Then convert from MachineZero to FixtureOffset (WorkZero)
    const currentWorkZero = MachineStateData.Instance.currentWorkZero;

    return new CNCPoint(
      machineZeroPoint.x - currentWorkZero.x,
      machineZeroPoint.y - currentWorkZero.y,
      machineZeroPoint.z - currentWorkZero.z,
      CoordinateType.WorkZero
    );
  }

  /**
   * Convert any point to simulator coordinate system
   * Simplified approach: convert to MachineZero first, then apply Simulator transformation
   * @param point The point to convert
   */
  static toSimulator(point: CNCPoint): CNCPoint {
    const { coordinateType } = point;

    if (coordinateType === CoordinateType.Simulator) {
      return point;
    }

    // First convert to MachineZero (canonical coordinate system)
    const machineZeroPoint = CoordinateUtil.toMachineZero(point);

    // Then convert from MachineZero to Simulator
    const simulatorMachineZero = CoordinateUtil.machineZeroPoint;

    return new CNCPoint(
      machineZeroPoint.x + simulatorMachineZero.x,
      machineZeroPoint.y + simulatorMachineZero.y,
      machineZeroPoint.z + simulatorMachineZero.z,
      CoordinateType.Simulator
    );
  }

  /**
   * Convert any point to machine home coordinate system
   * Machine home coordinates have their origin at the machine home corner point
   * Simplified approach: convert to MachineZero first, then apply MachineHome transformation
   * @param point The point to convert
   */
  static toMachineHome(point: CNCPoint): CNCPoint {
    const { coordinateType } = point;

    if (coordinateType === CoordinateType.MachineHome) {
      return point;
    }

    // First convert to MachineZero (canonical coordinate system)
    const machineZeroPoint = CoordinateUtil.toMachineZero(point);

    // Then convert from MachineZero to MachineHome
    // MachineHome origin is at the machine home corner in simulator coordinates
    const homeCorner = CoordinateUtil.machineHomeCorner;
    const simulatorMachineZero = CoordinateUtil.machineZeroPoint;

    return new CNCPoint(
      machineZeroPoint.x - homeCorner.x + simulatorMachineZero.x,
      machineZeroPoint.y - homeCorner.y + simulatorMachineZero.y,
      machineZeroPoint.z - homeCorner.z + simulatorMachineZero.z,
      CoordinateType.MachineHome
    );
  }

  /**
   * Convert any point to work zero coordinate system with tool offsets applied (tool tip position)
   * This is the main coordinate system users see - represents tool tip position relative to fixture
   * @param point The point to convert
   */
  static toWorkZero(point: CNCPoint): CNCPoint {
    const { coordinateType } = point;

    if (coordinateType === CoordinateType.WorkZeroWithOffsets) {
      return point;
    }

    // First convert to FixtureOffset coordinate system (spindle bottom relative to fixture)
    const fixtureOffsetPoint = CoordinateUtil.toFixtureOffset(point);

    // Get current tool offsets
    const offsets = CoordinateUtil.getCurrentOffsets();

    // Tool extends DOWN from spindle, so tip is BELOW spindle position
    // When fixture offset Z is positive (spindle above fixture), and tool extends down,
    // the tool tip is CLOSER to fixture, so work zero Z is LESS than fixture offset Z
    // Therefore: work zero = fixture offset - tool length
    return new CNCPoint(
      fixtureOffsetPoint.x + offsets.x,  // Tool X offset
      fixtureOffsetPoint.y + offsets.y,  // Tool Y offset
      fixtureOffsetPoint.z + offsets.z,  // Tool extends DOWN from spindle
      CoordinateType.WorkZeroWithOffsets
    );
  }

  /**
   * Get the current tool offset values
   * Returns the X, Y, Z offsets for the currently selected tool
   * @returns ToolOffsets containing the current tool offsets (X, Y, Z)
   */
  static getCurrentOffsets(): ToolOffsets {
    const machineState = MachineStateData.Instance;
    const toolLibrary = ToolLibrary.Instance;

    // Get current tool from machine state
    const currentToolNumber = machineState.currentToolNumber;
    if (!currentToolNumber) {
      // No tool selected, return zero offsets
      return { x: 0, y: 0, z: 0 };
    }

    // Find tool in library by tool number
    const tool = toolLibrary.tools.find(t => t.toolNumber === currentToolNumber);
    if (!tool) {
      // Tool not found, return zero offsets
      return { x: 0, y: 0, z: 0 };
    }

    // Return tool offsets as simple x, y, z values
    // Note: Tool lengths are stored as negative values (extending downward from spindle)
    // For coordinate calculations, we need the absolute value since we want to offset 
    // work coordinates to represent tool tip position
    return {
      x: tool.toolOffsetX || 0,
      y: tool.toolOffsetY || 0,
      z: tool.measuredLength || tool.lengthBelowHolder || 0 // Use absolute value for coordinate offset
    };
  }

  /**
   * Convert Point3D to simulator coordinate system
   * Direct conversion from C# ToSimulator overload
   */
  static toSimulatorFromPoint3D(point: { x: number; y: number; z: number }): CNCPoint {
    return CoordinateUtil.toSimulator(
      new CNCPoint(point.x, point.y, point.z, CoordinateType.Simulator)
    );
  }

  /**
   * Calculate machine position to place tool tip at a given fixture position
   * @param fixturePosition The fixture position in MachineZero coordinates
   * @returns Machine position in MachineZero coordinates where tool tip will be at the fixture
   */
  static machinePositionForToolTipAtFixture(fixturePosition: CNCPoint): CNCPoint {
    // Fixture position is in MachineZero coordinates
    // We need to calculate where the machine (spindle bottom) should be
    // so that the tool tip is at the fixture position

    // Get current tool offsets (stored as negative for tools extending down)
    const offsets = CoordinateUtil.getCurrentOffsets();

    // Tool offsets are negative (e.g., -2.0 for 2" tool extending down)
    // To position spindle so tip reaches fixture, we subtract the negative offset
    // Example: fixture at -5, tool at -2.0, spindle should be at -5 - (-2.0) = -3
    return new CNCPoint(
      fixturePosition.x - offsets.x,
      fixturePosition.y - offsets.y,
      fixturePosition.z - offsets.z,
      CoordinateType.MachineZero
    );
  }

  /**
   * Calculate API fixture offset from current work zero position
   * This is used when setting fixture points - it gets the current work zero (fixture offset)
   * and adjusts it for tool offsets to get the spindle bottom position to send to the API.
   * Tool lengths are stored as negative values (extending down from spindle).
   * @returns CNCPoint in MachineHome coordinates representing spindle bottom position
   */
  static toAPIFixtureOffset(): CNCPoint {
    // Get current work zero (fixture offset) from machine state
    const currentWorkZero = MachineStateData.Instance.currentWorkZero;

    // Convert to MachineHome coordinates
    const machineHomePoint = CoordinateUtil.toMachineHome(currentWorkZero);

    // Get current tool offsets (Z is stored as negative for tools extending down)
    const toolOffsets = CoordinateUtil.getCurrentOffsets();

    // Subtract tool offsets (subtracting negative values adds them)
    // This gives us the spindle bottom position that the API needs
    return new CNCPoint(
      machineHomePoint.x - toolOffsets.x,
      machineHomePoint.y - toolOffsets.y,
      machineHomePoint.z - toolOffsets.z,
      CoordinateType.MachineHome
    );
  }

  /**
   * Get intersection point between a plane and a line segment
   * Using Three.js for robust intersection calculations with proper bounds checking
   */
  static getIntersectionPoint(
    plane: Plane,
    point1: CNCPoint,
    point2: CNCPoint
  ): CNCPoint | null {
    // Convert all points to MachineZero coordinate system first
    point1 = CoordinateUtil.toMachineZero(point1);
    point2 = CoordinateUtil.toMachineZero(point2);

    const planeMachineZero = new Plane(
      CoordinateUtil.toMachineZero(plane.point1),
      CoordinateUtil.toMachineZero(plane.point2),
      CoordinateUtil.toMachineZero(plane.point3),
      CoordinateUtil.toMachineZero(plane.point4)
    );

    // Create Three.js vectors for the line segment
    const lineStart = new THREE.Vector3(point1.x, point1.y, point1.z);
    const lineEnd = new THREE.Vector3(point2.x, point2.y, point2.z);
    const lineDirection = new THREE.Vector3().subVectors(lineEnd, lineStart).normalize();

    // Create a ray from the line segment
    const ray = new THREE.Ray(lineStart, lineDirection);

    // Create Three.js plane from the 4 corner points
    // Use first 3 points to define the plane
    const p1 = new THREE.Vector3(planeMachineZero.point1.x, planeMachineZero.point1.y, planeMachineZero.point1.z);
    const p2 = new THREE.Vector3(planeMachineZero.point2.x, planeMachineZero.point2.y, planeMachineZero.point2.z);
    const p3 = new THREE.Vector3(planeMachineZero.point3.x, planeMachineZero.point3.y, planeMachineZero.point3.z);

    const threePlane = new THREE.Plane().setFromCoplanarPoints(p1, p2, p3);

    // Find intersection with the infinite plane
    const intersectionPoint = ray.intersectPlane(threePlane, new THREE.Vector3());

    if (!intersectionPoint) {
      return null; // Ray is parallel to plane or no intersection
    }

    // Check if intersection is within the line segment bounds
    const segmentLength = lineStart.distanceTo(lineEnd);
    const intersectionDistance = lineStart.distanceTo(intersectionPoint);

    if (intersectionDistance > segmentLength) {
      return null; // Intersection is beyond the line segment
    }

    // Check if intersection point is within the rectangular face bounds
    // Create bounding box from the 4 plane points
    const faceBox = new THREE.Box3();
    faceBox.setFromPoints([
      new THREE.Vector3(planeMachineZero.point1.x, planeMachineZero.point1.y, planeMachineZero.point1.z),
      new THREE.Vector3(planeMachineZero.point2.x, planeMachineZero.point2.y, planeMachineZero.point2.z),
      new THREE.Vector3(planeMachineZero.point3.x, planeMachineZero.point3.y, planeMachineZero.point3.z),
      new THREE.Vector3(planeMachineZero.point4.x, planeMachineZero.point4.y, planeMachineZero.point4.z)
    ]);

    // Check if intersection point is within the face bounds
    if (!faceBox.containsPoint(intersectionPoint)) {
      return null; // Intersection is outside the rectangular face
    }

    return new CNCPoint(intersectionPoint.x, intersectionPoint.y, intersectionPoint.z, CoordinateType.MachineZero);
  }

  /**
   * Compute the 8 corner points of a box
   * Direct conversion from C# ComputeBoxPoints method
   */
  static computeBoxPoints(
    origin: CNCPoint,
    width: number,
    length: number,
    height: number
  ): BoxPoints {
    return {
      frontLeftLower: new CNCPoint(origin.x, origin.y, origin.z, origin.coordinateType),
      frontRightLower: new CNCPoint(origin.x + width, origin.y, origin.z, origin.coordinateType),
      rearRightLower: new CNCPoint(origin.x + width, origin.y + length, origin.z, origin.coordinateType),
      rearLeftLower: new CNCPoint(origin.x, origin.y + length, origin.z, origin.coordinateType),
      frontLeftUpper: new CNCPoint(origin.x, origin.y, origin.z + height, origin.coordinateType),
      frontRightUpper: new CNCPoint(origin.x + width, origin.y, origin.z + height, origin.coordinateType),
      rearRightUpper: new CNCPoint(origin.x + width, origin.y + length, origin.z + height, origin.coordinateType),
      rearLeftUpper: new CNCPoint(origin.x, origin.y + length, origin.z + height, origin.coordinateType)
    };
  }

  /**
   * Compute intersection of a line with a box using Three.js
   * More efficient and robust than checking individual faces
   */
  static computeIntersectionWithBox(
    box: Box,
    currentPoint: CNCPoint,
    point: CNCPoint,
    offset: number = 0.0,
    offsetDirection: PlaneOffset = PlaneOffset.Inside
  ): BoxIntersectionResult {
    // Add null checks
    if (!box) {
      return { intersectionPoint: point, faceName: null };
    }

    try {
      // Convert all inputs to MachineZero for consistent calculations
      const machineZeroBox = box.toMachineZero();
      const machineZeroCurrentPoint = CoordinateUtil.toMachineZero(currentPoint);
      const machineZeroTargetPoint = CoordinateUtil.toMachineZero(point);

      // Get the box bounds
      const boxPoints = machineZeroBox.boxPoints;

      // Calculate the actual box bounds (min/max coordinates)
      const minX = Math.min(boxPoints.frontLeftLower.x, boxPoints.frontRightLower.x, boxPoints.rearLeftLower.x, boxPoints.rearRightLower.x);
      const maxX = Math.max(boxPoints.frontLeftLower.x, boxPoints.frontRightLower.x, boxPoints.rearLeftLower.x, boxPoints.rearRightLower.x);
      const minY = Math.min(boxPoints.frontLeftLower.y, boxPoints.frontRightLower.y, boxPoints.rearLeftLower.y, boxPoints.rearRightLower.y);
      const maxY = Math.max(boxPoints.frontLeftLower.y, boxPoints.frontRightLower.y, boxPoints.rearLeftLower.y, boxPoints.rearRightLower.y);
      const minZ = Math.min(boxPoints.frontLeftLower.z, boxPoints.frontLeftUpper.z, boxPoints.frontRightLower.z, boxPoints.frontRightUpper.z);
      const maxZ = Math.max(boxPoints.frontLeftLower.z, boxPoints.frontLeftUpper.z, boxPoints.frontRightLower.z, boxPoints.frontRightUpper.z);

      // Apply offset if specified
      let adjustedMinX = minX, adjustedMaxX = maxX;
      let adjustedMinY = minY, adjustedMaxY = maxY;
      let adjustedMinZ = minZ, adjustedMaxZ = maxZ;

      if (offset !== 0.0) {
        const offsetMultiplier = offsetDirection === PlaneOffset.Inside ? offset : -offset;
        adjustedMinX = minX + offsetMultiplier;
        adjustedMaxX = maxX - offsetMultiplier;
        adjustedMinY = minY + offsetMultiplier;
        adjustedMaxY = maxY - offsetMultiplier;
        adjustedMinZ = minZ + offsetMultiplier;
        adjustedMaxZ = maxZ - offsetMultiplier;
      }

      // Create Three.js Box3 for intersection
      const threeBox = new THREE.Box3(
        new THREE.Vector3(adjustedMinX, adjustedMinY, adjustedMinZ),
        new THREE.Vector3(adjustedMaxX, adjustedMaxY, adjustedMaxZ)
      );

      // Create ray from movement line
      const rayOrigin = new THREE.Vector3(machineZeroCurrentPoint.x, machineZeroCurrentPoint.y, machineZeroCurrentPoint.z);
      const rayTarget = new THREE.Vector3(machineZeroTargetPoint.x, machineZeroTargetPoint.y, machineZeroTargetPoint.z);
      const rayDirection = new THREE.Vector3().subVectors(rayTarget, rayOrigin).normalize();
      const ray = new THREE.Ray(rayOrigin, rayDirection);

      // Find intersection with the box
      const intersectionPoint = ray.intersectBox(threeBox, new THREE.Vector3());

      if (!intersectionPoint) {
        return { intersectionPoint: null, faceName: null };
      }

      // Check if intersection is within the line segment (not beyond it)
      const segmentLength = rayOrigin.distanceTo(rayTarget);
      const intersectionDistance = rayOrigin.distanceTo(intersectionPoint);

      if (intersectionDistance > segmentLength) {
        return { intersectionPoint: null, faceName: null };
      }

      // Determine which face was hit by checking which coordinate is at the boundary
      let faceName: string | null = null;
      const tolerance = 1e-6;

      if (Math.abs(intersectionPoint.x - adjustedMinX) < tolerance) {
        faceName = 'Left';
      } else if (Math.abs(intersectionPoint.x - adjustedMaxX) < tolerance) {
        faceName = 'Right';
      } else if (Math.abs(intersectionPoint.y - adjustedMinY) < tolerance) {
        faceName = 'Front';
      } else if (Math.abs(intersectionPoint.y - adjustedMaxY) < tolerance) {
        faceName = 'Back';
      } else if (Math.abs(intersectionPoint.z - adjustedMinZ) < tolerance) {
        faceName = 'Bottom';
      } else if (Math.abs(intersectionPoint.z - adjustedMaxZ) < tolerance) {
        faceName = 'Top';
      }

      return {
        intersectionPoint: new CNCPoint(intersectionPoint.x, intersectionPoint.y, intersectionPoint.z, CoordinateType.MachineZero),
        faceName
      };

    } catch (error) {
      // If any error occurs, return the target point in MachineZero
      return { intersectionPoint: CoordinateUtil.toMachineZero(point), faceName: null };
    }
  }

  /**
   * Get current simulator Z coordinate
   * Direct conversion from C# CurrentSimulatorZ property
   */
  static get currentSimulatorZ(): number {
    return CoordinateUtil.toSimulator(
      new CNCPoint(
        0,
        0,
        MachineStateData.Instance.currentMachinePoint.z,
        CoordinateType.MachineZero
      )
    ).z;
  }

  /**
   * Move a point away from box edge by specified distance
   * Direct conversion from C# MoveAwayFromBoxEdge method
   */
  static moveAwayFromBoxEdge(
    box: Box,
    point: CNCPoint,
    direction: PlaneOffset,
    distance: number,
    respectBottomOfBox: boolean = true
  ): CNCPoint {
    // Check if box is null
    if (!box) {
      return point; // If box is null, return the original point
    }

    // Store original coordinate type to preserve it
    const originalCoordinateType = point.coordinateType;

    // Convert point to MachineZero coordinate system
    point = CoordinateUtil.toMachineZero(point);

    // Convert box points to MachineZero coordinate system
    const boxPoints = box.boxPoints;
    const boxPointsMachineZero = CoordinateUtil.computeBoxPoints(
      CoordinateUtil.toMachineZero(boxPoints.frontLeftLower),
      box.width,
      box.length,
      box.height
    );

    if (direction === PlaneOffset.Inside) {
      // For inside direction, move point away from edges toward the center of the box
      // Check left edge - if too close, move away from left edge (toward center)
      if (point.x <= boxPointsMachineZero.frontLeftLower.x + distance / 2) {
        point = new CNCPoint(point.x + distance, point.y, point.z, point.coordinateType);
      }
      // Check right edge - if too close, move away from right edge (toward center)
      if (point.x >= boxPointsMachineZero.frontRightLower.x - distance / 2) {
        point = new CNCPoint(point.x - distance, point.y, point.z, point.coordinateType);
      }
      // Check front edge - if too close, move away from front edge (toward center)
      if (point.y <= boxPointsMachineZero.frontLeftLower.y + distance / 2) {
        point = new CNCPoint(point.x, boxPointsMachineZero.frontLeftLower.y + distance, point.z, point.coordinateType);
      }
      // Check back edge - if too close, move away from back edge (toward center)
      if (point.y >= boxPointsMachineZero.rearLeftLower.y - distance / 2) {
        point = new CNCPoint(point.x, boxPointsMachineZero.rearLeftLower.y - distance, point.z, point.coordinateType);
      }
      // Check top edge - if too close, move away from top edge (toward center)
      if (point.z >= boxPointsMachineZero.frontLeftUpper.z - distance / 2) {
        point = new CNCPoint(point.x, point.y, boxPointsMachineZero.frontLeftUpper.z - distance, point.coordinateType);
      }
      // Check bottom edge - if too close, move away from bottom edge (toward center)
      if (respectBottomOfBox && point.z <= boxPointsMachineZero.frontLeftLower.z + distance / 2) {
        point = new CNCPoint(point.x, point.y, boxPointsMachineZero.frontLeftLower.z + distance, point.coordinateType);
      }
    } else { // PlaneOffset.Outside
      // For outside direction, move point away from the box entirely
      // Check if point is near left edge - if so, move away from left edge (further left)
      if (point.x <= boxPointsMachineZero.frontLeftLower.x + distance / 2) {
        point = new CNCPoint(boxPointsMachineZero.frontLeftLower.x - distance, point.y, point.z, point.coordinateType);
      }
      // Check if point is near right edge - if so, move away from right edge (further right)
      if (point.x >= boxPointsMachineZero.frontRightLower.x - distance / 2) {
        point = new CNCPoint(boxPointsMachineZero.frontRightLower.x + distance, point.y, point.z, point.coordinateType);
      }
      // Check if point is near front edge - if so, move away from front edge (further forward)
      if (point.y <= boxPointsMachineZero.frontLeftLower.y + distance / 2) {
        point = new CNCPoint(point.x, boxPointsMachineZero.frontLeftLower.y - distance, point.z, point.coordinateType);
      }
      // Check if point is near back edge - if so, move away from back edge (further back)
      if (point.y >= boxPointsMachineZero.rearLeftLower.y - distance / 2) {
        point = new CNCPoint(point.x, boxPointsMachineZero.rearLeftLower.y + distance, point.z, point.coordinateType);
      }
      // Check if point is near top edge - if so, move away from top edge (further up)
      if (point.z >= boxPointsMachineZero.frontLeftUpper.z - distance / 2) {
        point = new CNCPoint(point.x, point.y, boxPointsMachineZero.frontLeftUpper.z + distance, point.coordinateType);
      }
      // Check if point is near bottom edge - if so, move away from bottom edge (further down)
      if (respectBottomOfBox && point.z <= boxPointsMachineZero.frontLeftLower.z + distance / 2) {
        point = new CNCPoint(point.x, point.y, boxPointsMachineZero.frontLeftLower.z - distance, point.coordinateType);
      }
    }

    // Convert back to original coordinate type
    if (originalCoordinateType === CoordinateType.WorkZero) {
      return CoordinateUtil.toFixtureOffset(point);
    } else if (originalCoordinateType === CoordinateType.Simulator) {
      return CoordinateUtil.toSimulator(point);
    } else {
      return point; // Already in MachineZero
    }
  }

  /**
   * Gets the bounding box for the machine bed in machine coordinates
   */
  public static getBedBox(machineStateData: MachineStateData): Box {
    const machineData = MachineData.Instance;

    // Calculate bed position - position relative to base front-left corner (0,0) plus offsets
    // When offsets are 0,0, bed should be at front-left corner of base
    const bedXOffset = machineData.bedOffsetX;
    const bedYOffset = machineData.bedOffsetY;

    // Position bed below the spoilboard
    // Calculate spoilboard Z position and place bed below it
    const spoilZero = CoordinateUtil.spoilboardZero;
    const spoilZeroMachine = CoordinateUtil.toMachineZero(spoilZero);
    const spoilboardBottomZ = spoilZeroMachine.z - machineStateData.spoilBoardHeight;
    const bedZPosition = spoilboardBottomZ - machineData.bedHeight;

    const bedOrigin = new CNCPoint(
      bedXOffset,
      bedYOffset,
      bedZPosition, // Bed positioned below spoilboard
      CoordinateType.MachineZero
    );

    return new Box(
      bedOrigin,
      machineData.bedWidth,
      machineData.bedLength,
      machineData.bedHeight
    );
  }

  /**
   * Gets the soft limits bounding box in machine coordinates
   */
  public static getSoftLimitsBox(machineStateData: MachineStateData): Box {
    const machineData = MachineData.Instance;

    // Get machine travel limits from soft limit configuration
    const softLimitsOrigin = new CNCPoint(
      machineData.xLowerSoftLimitFromMachineZero, // Start at X lower limit
      machineData.yLowerSoftLimitFromMachineZero, // Start at Y lower limit
      machineData.zLowerSoftLimitFromMachineZero, // Start at Z lower limit
      CoordinateType.MachineZero
    );

    return new Box(
      softLimitsOrigin,
      machineData.xUpperSoftLimitFromMachineZero - machineData.xLowerSoftLimitFromMachineZero, // Travel width
      machineData.yUpperSoftLimitFromMachineZero - machineData.yLowerSoftLimitFromMachineZero, // Travel length
      machineData.zUpperSoftLimitFromMachineZero - machineData.zLowerSoftLimitFromMachineZero // Travel height
    );
  }

  /**
   * Gets the Z height of the top of the gantry bar
   * Builds from base height + bed height + gantry height + gantry bar height
   */
  public static getGantryZHeight(): number {
    const machineData = MachineData.Instance;
    return machineData.baseHeight + machineData.gantryHeight + machineData.gantryBarHeight;
  }

  /**
   * Gets the maximum Z position for a given coordinate type
   * Returns the machine's upper soft limit transformed to the specified coordinate system
   * @param coordinateType The coordinate system to return the Z max value in
   * @returns Maximum Z position in the specified coordinate system
   */
  public static getZMax(coordinateType: CoordinateType): number {
    const machineData = MachineData.Instance;

    // Upper soft limit is stored in machine zero coordinates
    const zMaxInMachineZero = machineData.zUpperSoftLimitFromMachineZero;

    // Create a point at the Z max in machine zero coordinates
    const zMaxPoint = new CNCPoint(0, 0, zMaxInMachineZero, CoordinateType.MachineZero);

    // Transform to the requested coordinate system
    switch (coordinateType) {
      case CoordinateType.MachineZero:
        return zMaxPoint.z;
      case CoordinateType.WorkZero:
        return CoordinateUtil.toFixtureOffset(zMaxPoint).z;
      case CoordinateType.MachineHome:
        return CoordinateUtil.toMachineHome(zMaxPoint).z;
      case CoordinateType.Simulator:
        return CoordinateUtil.toSimulator(zMaxPoint).z;
      default:
        return zMaxInMachineZero;
    }
  }



  /**
   * Gets the bounding box for the spoilboard in machine coordinates
   */
  public static getSpoilboardBox(machineStateData: MachineStateData): Box {
    const spoilZero = CoordinateUtil.spoilboardZero;

    // Convert spoilboard zero from Simulator to MachineZero coordinates
    const spoilZeroMachine = CoordinateUtil.toMachineZero(spoilZero);

    // spoilZero represents the top surface, but Box origin should be bottom corner
    // So we need to subtract the spoilboard height to get the bottom corner
    const spoilboardOrigin = new CNCPoint(
      spoilZeroMachine.x,
      spoilZeroMachine.y,
      spoilZeroMachine.z - machineStateData.spoilBoardHeight,
      CoordinateType.MachineZero
    );

    return new Box(
      spoilboardOrigin,
      machineStateData.spoilBoardWidth,
      machineStateData.spoilBoardYLength,
      machineStateData.spoilBoardHeight
    );
  }

  /**
   * Gets the bounding box for the material in machine coordinates
   * Material offsets behavior depends on the position reference:
   * - WorkHome: offsets are subtracted from work zero position (current behavior)
   * - Spoilboard: offsets are added to spoilboard zero position
   * Material Z starts at the top of the spoilboard
   */
  public static getMaterialBox(machineStateData: MachineStateData): Box {
    const job = machineStateData.currentJob;
    if (!job) {
      // Return empty box if no job
      const origin = new CNCPoint(0, 0, 0, CoordinateType.MachineZero);
      return new Box(origin, 0, 0, 0);
    }

    const material = job.material;
    const spoilboardBox = CoordinateUtil.getSpoilboardBox(machineStateData);
    const workZero = machineStateData.currentWorkZero;

    let materialOrigin: CNCPoint;

    if (job.materialPositionReference === MaterialPositionReference.Spoilboard) {
      // Spoilboard reference: offsets are added to spoilboard position
      const spoilboardZero = CoordinateUtil.spoilboardZero;
      const spoilboardZeroMachine = CoordinateUtil.toMachineZero(spoilboardZero);
      materialOrigin = new CNCPoint(
        spoilboardZeroMachine.x + job.materialXOffset,
        spoilboardZeroMachine.y + job.materialYOffset,
        spoilboardBox.origin.z + spoilboardBox.height,  // Top of spoilboard
        CoordinateType.MachineZero
      );
    } else {
      // WorkHome reference: offsets are subtracted from work zero position (original behavior)
      materialOrigin = new CNCPoint(
        workZero.x - job.materialXOffset,
        workZero.y - job.materialYOffset,
        spoilboardBox.origin.z + spoilboardBox.height,  // Top of spoilboard
        CoordinateType.MachineZero
      );
    }

    return new Box(
      materialOrigin,
      material.xLength,
      material.yLength,
      material.height
    );
  }

  /**
   * Gets the material corner position in machine coordinates
   * This is the reference point for clamp positioning and material placement
   */
  public static getMaterialCornerPosition(machineStateData: MachineStateData): CNCPoint {
    const job = machineStateData.currentJob;
    if (!job) {
      return new CNCPoint(0, 0, 0, CoordinateType.MachineZero);
    }

    const workZero = machineStateData.currentWorkZero;

    if (job.materialPositionReference === MaterialPositionReference.Spoilboard) {
      // Spoilboard reference: material corner is spoilboard zero + offsets
      const spoilboardZero = CoordinateUtil.spoilboardZero;
      const spoilboardZeroMachine = CoordinateUtil.toMachineZero(spoilboardZero);
      return new CNCPoint(
        spoilboardZeroMachine.x + job.materialXOffset,
        spoilboardZeroMachine.y + job.materialYOffset,
        spoilboardZeroMachine.z, // Z is irrelevant for clamp positioning
        CoordinateType.MachineZero
      );
    } else {
      // WorkHome reference: material corner is work zero - offsets (original behavior)
      return new CNCPoint(
        workZero.x - job.materialXOffset,
        workZero.y - job.materialYOffset,
        workZero.z, // Z is irrelevant for clamp positioning
        CoordinateType.MachineZero
      );
    }
  }

  /**
   * Gets individual bounding boxes for each clamp in machine coordinates
   * Clamps are positioned relative to the material corner (which depends on materialPositionReference)
   * Returns an array of individual clamp boxes instead of one oversized combined box
   */
  public static getClampsBoxes(machineStateData: MachineStateData): Box[] {
    const job = machineStateData.currentJob;
    if (!job || job.clamps.length === 0) {
      return [];
    }

    const spoilboardBox = CoordinateUtil.getSpoilboardBox(machineStateData);
    const materialCorner = CoordinateUtil.getMaterialCornerPosition(machineStateData);
    const clampBoxes: Box[] = [];

    for (const clamp of job.clamps) {
      // Clamp position: material corner + clamp offsets, Z on spoilboard surface
      const clampX = materialCorner.x + clamp.clampOffsetX;
      const clampY = materialCorner.y + clamp.clampOffsetY;
      const clampZ = spoilboardBox.origin.z + spoilboardBox.height; // Top of spoilboard

      // Create individual clamp box
      const clampOrigin = new CNCPoint(clampX, clampY, clampZ, CoordinateType.MachineZero);
      const clampBox = new Box(
        clampOrigin,
        clamp.clampXWidth,
        clamp.clampYWidth,
        clamp.clampHeight
      );

      clampBoxes.push(clampBox);
    }

    return clampBoxes;
  }

  /**
   * @deprecated Use getClampsBoxes() instead to get individual clamp boxes
   * Gets the combined bounding box for all clamps in machine coordinates
   * This method creates false positives by including empty space between clamps
   */
  public static getClampsBox(machineStateData: MachineStateData): Box | null {
    const job = machineStateData.currentJob;
    if (!job || job.clamps.length === 0) {
      return null;
    }

    const spoilboardBox = CoordinateUtil.getSpoilboardBox(machineStateData);
    const materialCorner = CoordinateUtil.getMaterialCornerPosition(machineStateData);

    // Find the bounding box that contains all clamps
    let minX = Number.MAX_VALUE;
    let minY = Number.MAX_VALUE;
    let minZ = Number.MAX_VALUE;
    let maxX = Number.MIN_VALUE;
    let maxY = Number.MIN_VALUE;
    let maxZ = Number.MIN_VALUE;

    for (const clamp of job.clamps) {
      // Clamp position: material corner + clamp offsets, Z on spoilboard surface
      const clampX = materialCorner.x + clamp.clampOffsetX;
      const clampY = materialCorner.y + clamp.clampOffsetY;
      const clampZ = spoilboardBox.origin.z + spoilboardBox.height; // Top of spoilboard

      // Clamp bounding box
      const clampMaxX = clampX + clamp.clampXWidth;
      const clampMaxY = clampY + clamp.clampYWidth;
      const clampMaxZ = clampZ + clamp.clampHeight;

      minX = Math.min(minX, clampX);
      minY = Math.min(minY, clampY);
      minZ = Math.min(minZ, clampZ);
      maxX = Math.max(maxX, clampMaxX);
      maxY = Math.max(maxY, clampMaxY);
      maxZ = Math.max(maxZ, clampMaxZ);
    }

    const clampsOrigin = new CNCPoint(minX, minY, minZ, CoordinateType.MachineZero);
    return new Box(
      clampsOrigin,
      maxX - minX,
      maxY - minY,
      maxZ - minZ
    );
  }

  /**
   * Calculate distance from current machine Z position to spoilboard top surface
   * Returns positive value when above spoilboard, negative when below
   */
  static distanceToSpoilboard(): number {
    const machineState = MachineStateData.Instance;

    // Current machine Z position
    const currentZ = machineState.currentMachinePoint.z;

    // Get spoilboard box and calculate top surface Z position
    const spoilboardBox = CoordinateUtil.getSpoilboardBox(machineState);
    const spoilboardTopZ = spoilboardBox.origin.z + spoilboardBox.height;

    return currentZ - spoilboardTopZ;
  }

  /**
   * Calculate distance from current machine Z position to bed top surface
   * Returns positive value when above bed, negative when below
   */
  static distanceToBed(): number {
    const machineState = MachineStateData.Instance;

    // Current machine Z position
    const currentZ = machineState.currentMachinePoint.z;

    // Get bed box and calculate top surface Z position
    const bedBox = CoordinateUtil.getBedBox(machineState);
    const bedTopZ = bedBox.origin.z + bedBox.height;

    return currentZ - bedTopZ;
  }

  /**
   * Calculate distance from current machine Z position to material top surface
   * Returns positive value when above material, negative when below
   */
  static distanceToMaterial(): number {
    const machineState = MachineStateData.Instance;

    // Current machine Z position
    const currentZ = machineState.currentMachinePoint.z;

    // Get material box and calculate top surface Z position
    const materialBox = CoordinateUtil.getMaterialBox(machineState);
    const materialTopZ = materialBox.origin.z + materialBox.height;

    return currentZ - materialTopZ;
  }

  /**
   * Check if the spindle is positioned over the material
   * Returns true if spindle X,Y position is within material bounds
   */
  static isSpindleOverMaterial(): boolean {
    const machineState = MachineStateData.Instance;
    const currentPos = machineState.currentMachinePoint;

    // Get material box bounds
    const materialBox = CoordinateUtil.getMaterialBox(machineState);

    // Check if spindle X,Y position is within material bounds
    const isWithinX = currentPos.x >= materialBox.origin.x &&
      currentPos.x <= (materialBox.origin.x + materialBox.width);
    const isWithinY = currentPos.y >= materialBox.origin.y &&
      currentPos.y <= (materialBox.origin.y + materialBox.length);

    return isWithinX && isWithinY;
  }

  /**
   * Get machine home bounding box in simulator coordinates
   * Returns the minimum and maximum extents of the machine's travel limits
   * Uses the verified getSoftLimitsBox method to avoid code duplication
   */
  static getMachineHomeBounds(): { min: CNCPoint; max: CNCPoint } {
    const machineState = MachineStateData.Instance;

    // Get the soft limits box in machine coordinates
    const softLimitsBox = CoordinateUtil.getSoftLimitsBox(machineState);

    // Convert the box origin and far corner to simulator coordinates
    const minPoint = CoordinateUtil.toSimulator(softLimitsBox.origin);
    const maxPoint = CoordinateUtil.toSimulator(
      new CNCPoint(
        softLimitsBox.origin.x + softLimitsBox.width,
        softLimitsBox.origin.y + softLimitsBox.length,
        softLimitsBox.origin.z + softLimitsBox.height,
        softLimitsBox.origin.coordinateType
      )
    );

    return {
      min: minPoint,
      max: maxPoint
    };
  }

  /**
   * Get machine zero position in simulator coordinates
   * Convenience method that returns the pre-calculated machine zero point
   */
  static getMachineZeroPosition(): CNCPoint {
    return CoordinateUtil.machineZeroPoint;
  }

  /**
   * Get machine home corner points in simulator coordinates
   * Returns an array of 8 corner points defining the machine home bounding box
   */
  static getMachineHomeCorners(): CNCPoint[] {
    const bounds = CoordinateUtil.getMachineHomeBounds();
    const min = bounds.min;
    const max = bounds.max;

    return [
      new CNCPoint(min.x, min.y, min.z, CoordinateType.Simulator), // Bottom-front-left
      new CNCPoint(max.x, min.y, min.z, CoordinateType.Simulator), // Bottom-front-right
      new CNCPoint(max.x, max.y, min.z, CoordinateType.Simulator), // Bottom-back-right
      new CNCPoint(min.x, max.y, min.z, CoordinateType.Simulator), // Bottom-back-left
      new CNCPoint(min.x, min.y, max.z, CoordinateType.Simulator), // Top-front-left
      new CNCPoint(max.x, min.y, max.z, CoordinateType.Simulator), // Top-front-right
      new CNCPoint(max.x, max.y, max.z, CoordinateType.Simulator), // Top-back-right
      new CNCPoint(min.x, max.y, max.z, CoordinateType.Simulator), // Top-back-left
    ];
  }
}
