/**
 * XML parsing utilities for functions.xml
 * Provides functionality to extract input and output names based on machine type filters
 */

export type MachineType = 'All' | 'Router' | 'Mill' | 'Lathe';

export interface PlcFunction {
  type: 'Input' | 'Output' | 'HomeLimit';
  name: string;
  displayName: string;
  machineTypes: MachineType[];
  isRequired: boolean;
  isCustom: boolean;
  hidden: boolean;
  tooltip?: string;
}

/**
 * Parse functions.xml content and extract PlcFunction data
 * @param xmlContent - The raw XML content from functions.xml
 * @returns Array of parsed PlcFunction objects
 */
export function parseFunctionsXml(xmlContent: string): PlcFunction[] {
  const parser = new DOMParser();
  const xmlDoc = parser.parseFromString(xmlContent, 'text/xml');

  // Check for parsing errors
  const parseError = xmlDoc.querySelector('parsererror');
  if (parseError) {
    throw new Error(`XML parsing error: ${parseError.textContent}`);
  }

  const functions: PlcFunction[] = [];
  const plcFunctionElements = xmlDoc.querySelectorAll('PlcFunction');

  plcFunctionElements.forEach(element => {
    const typeAttribute = element.getAttribute('xsi:type');
    if (!typeAttribute) return;

    // Extract basic properties
    const nameElement = element.querySelector('Name');
    const displayNameElement = element.querySelector('DisplayName');
    const isRequiredElement = element.querySelector('IsRequired');
    const isCustomElement = element.querySelector('IsCustom');
    const hiddenElement = element.querySelector('Hidden');
    const tooltipElement = element.querySelector('Tooltip');

    if (!nameElement || !displayNameElement) return;

    // Extract machine types
    const machineTypeElements = element.querySelectorAll('Machine > MachineType');
    const machineTypes: MachineType[] = [];

    machineTypeElements.forEach(mtElement => {
      const machineType = mtElement.textContent?.trim() as MachineType;
      if (machineType && ['All', 'Router', 'Mill', 'Lathe'].includes(machineType)) {
        machineTypes.push(machineType);
      }
    });

    // If no machine types specified, assume 'All'
    if (machineTypes.length === 0) {
      machineTypes.push('All');
    }

    const plcFunction: PlcFunction = {
      type: typeAttribute as 'Input' | 'Output' | 'HomeLimit',
      name: nameElement.textContent?.trim() || '',
      displayName: displayNameElement.textContent?.trim() || '',
      machineTypes,
      isRequired: isRequiredElement?.textContent?.trim() === 'true',
      isCustom: isCustomElement?.textContent?.trim() === 'true',
      hidden: hiddenElement?.textContent?.trim() === 'true',
      tooltip: tooltipElement?.textContent?.trim() || undefined
    };

    functions.push(plcFunction);
  });

  return functions;
}

/**
 * Filter PlcFunction array by machine type and function type
 * @param functions - Array of PlcFunction objects
 * @param machineType - Machine type to filter by ('All' includes all types)
 * @param functionType - Type of function ('Input' or 'Output')
 * @param includeHidden - Whether to include hidden functions (default: false)
 * @returns Filtered array of function names
 */
export function filterFunctionNames(
  functions: PlcFunction[],
  machineType: MachineType,
  functionType: 'Input' | 'Output',
  includeHidden: boolean = false
): string[] {
  return functions
    .filter(func => {
      // Filter by function type
      if (func.type !== functionType) return false;

      // Filter by hidden status
      if (!includeHidden && func.hidden) return false;

      // Filter by machine type
      if (machineType === 'All') return true;
      return func.machineTypes.includes(machineType) || func.machineTypes.includes('All');
    })
    .map(func => func.name)
    .filter(name => name.length > 0)
    .sort(); // Sort alphabetically for consistent ordering
}

/**
 * Load and parse functions.xml file from the src directory (development) or public directory (production)
 * @returns Promise resolving to parsed PlcFunction array
 */
export async function loadFunctionsXml(): Promise<PlcFunction[]> {
  try {
    let xmlContent: string;

    // In test environment, use require to load the file directly
    if (typeof process !== 'undefined' && process.env.NODE_ENV === 'test') {
      const fs = require('fs');
      const path = require('path');

      // Try src directory first, then public
      try {
        xmlContent = fs.readFileSync(path.join(process.cwd(), 'src', 'functions.xml'), 'utf8');
      } catch {
        xmlContent = fs.readFileSync(path.join(process.cwd(), 'public', 'functions.xml'), 'utf8');
      }
    } else {
      // In browser environment, use fetch
      let response: Response;

      // In development/testing, try to load from src directory first
      response = await fetch('/src/functions.xml');

      // If src directory fails, try public directory
      if (!response.ok) {
        response = await fetch('/functions.xml');
      }

      if (!response.ok) {
        throw new Error(`Failed to load functions.xml: ${response.status} ${response.statusText}`);
      }

      xmlContent = await response.text();
    }

    return parseFunctionsXml(xmlContent);
  } catch (error) {
    console.error('Error loading functions.xml:', error);
    // Return empty array if file cannot be loaded
    return [];
  }
}