import { Stop as StopIcon } from '@mui/icons-material';
import { Typography } from '@mui/material';
import React from 'react';
import { Machine } from '../../../../machine/Machine';
import { LogCategory, Logger } from '../../../../utils/Logger';
import { DataUtilities } from '../../../../utils/storage/DataUtilities';
import { FlowStep } from "../../../FlowStep";
import { FlowStepData } from "../../../FlowStepData";

export class EndStepRunStep extends FlowStep {
    readonly __type = 'EndStepRunStep';
    readonly category = ['Machine', 'Program'];
    readonly name = 'End Step Run';
    readonly description = 'Ends step-by-step program execution';
    
    // Icon is created dynamically, not stored
    get icon(): React.ReactNode {
        return React.createElement(StopIcon, { sx: { color: 'warning.main' } });
    }

    static readonly DONE_PATH = 'done';

    async execute(data: FlowStepData, prototypeRun: boolean): Promise<string | null> {
        if (prototypeRun) {
            //Logger.Instance.log(LogCategory.System, 'Prototype: End step run mode');
            return EndStepRunStep.DONE_PATH;
        }

        try {
            await Machine.getInstance().program.EndStepRun();
            //Logger.Instance.log(LogCategory.System, 'Step run mode ended');
            return EndStepRunStep.DONE_PATH;
        } catch (error) {
            Logger.Instance.logError(LogCategory.System, 'End step run failed:', error);
            return EndStepRunStep.DONE_PATH; // Still done, just with error logged
        }
    }

    results(): string[] {
        return [EndStepRunStep.DONE_PATH];
    }

    renderResultsUI(data: FlowStepData, result: string): React.ReactNode {
        return (
            <Typography variant="caption">
                End step run: {result}
            </Typography>
        );
    }

    public toJSON(): any {
        const data = DataUtilities.getStorageData(this, ['icon']) as any;
        data.__type = this.__type;
        return data;
    }

    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data);
    }
}






