import { CheckCircle as CheckIcon, Home as HomeIcon } from '@mui/icons-material';
import { Alert, Box, Button, Paper, Typography } from '@mui/material';
import React from 'react';
import { ConfigurationData } from '../../../../data/ConfigurationData';
import { MachineData } from '../../../../data/MachineData';
import { MachineStateData } from '../../../../data/MachineStateData';
import { UserMessageQueue } from '../../../../data/UserMessageQueue';
import { Machine } from '../../../../machine/Machine';
import { ObserveState } from '../../../../utils/statemanager/ObserveState';
import { StateManager } from '../../../../utils/statemanager/StateManager';
import { JogControls } from '../../../Common/JogControls';
import { FullSizeCNCViewer } from '../../../MachineViewer/FullSizeCNCViewer';
import { WizardStep } from '../../../Wizard/WizardStep';

export class ManualHomingStep extends WizardStep {
    private isProcessing: boolean = false;

    getTitle(): string {
        return 'Manual Homing';
    }

    nextStep(): WizardStep | null {
        return null; // Only step
    }

    backStep(): WizardStep | null {
        return null; // Only step
    }

    private async setMachineHome(): Promise<void> {
        try {
            this.isProcessing = true;
            StateManager.propertyChanged(this, 'isProcessing');

            UserMessageQueue.Instance.addMessage('🏠 Setting machine home position...');

            // Call the HomeMachine API
            await Machine.getInstance().system.HomeMachine();

            // Update machine state
            MachineStateData.Instance.isHomed = true;
            this.wizard.state.homingComplete = true;

            UserMessageQueue.Instance.addMessage('✓ Machine home set successfully');

            this.isProcessing = false;
            StateManager.propertyChanged(this, 'isProcessing');

            // Close wizard after brief delay
            setTimeout(() => {
                this.wizard.closeWizard();
            }, 1500);

        } catch (error) {
            this.isProcessing = false;
            StateManager.propertyChanged(this, 'isProcessing');

            UserMessageQueue.Instance.addMessage('❌ Failed to set machine home');
            console.error('Manual homing failed:', error);
        }
    }

    render(): React.ReactNode {
        return (
            <ObserveState
                key="manual-homing-step"
                listenTo={this}
                properties={['isProcessing']}
                control={() => (
                    <Box sx={{ p: 3, height: '100%', display: 'flex', flexDirection: 'column', gap: 3 }}>
                        <Alert severity="info" icon={<HomeIcon />}>
                            <Typography variant="h6" gutterBottom>
                                Manual Homing Instructions
                            </Typography>
                            <Typography variant="body2">
                                Use the jog controls to manually move the machine to the home position.
                                Once the machine is at the correct home position, click "Set Machine Home" to complete the homing process.
                            </Typography>
                        </Alert>

                        {/* Main Content Area */}
                        <Box sx={{ display: 'flex', gap: 3, flex: 1, minHeight: 0 }}>
                            {/* Left Side - Jog Controls (40%) */}
                            <Box sx={{ flex: '0 0 40%', display: 'flex', flexDirection: 'column', gap: 2 }}>
                                <Paper sx={{ p: 2, flex: 1 }}>
                                    <Typography variant="subtitle1" gutterBottom sx={{ fontWeight: 'bold' }}>
                                        Jog Controls
                                    </Typography>
                                    <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                                        Move the machine to the desired home position
                                    </Typography>
                                    <JogControls />
                                </Paper>
                            </Box>

                            {/* Right Side - 3D Viewer (60%) */}
                            <Box sx={{ flex: '0 0 60%', display: 'flex', flexDirection: 'column', minHeight: 0 }}>
                                <FullSizeCNCViewer
                                    simulatorView={ConfigurationData.Instance.defaultView}
                                    machineState={MachineStateData.Instance}
                                    machineData={MachineData.Instance}
                                    job={MachineStateData.Instance.currentJob!}
                                    enableOrbit={true}
                                    enableClampDragging={false}
                                    enableSpindleDrag={true}
                                />
                            </Box>
                        </Box>

                        {/* Action Buttons */}
                        <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', pt: 2 }}>
                            <Button
                                variant="outlined"
                                onClick={() => this.wizard.closeWizard()}
                                disabled={this.isProcessing}
                            >
                                Cancel
                            </Button>

                            <Button
                                variant="contained"
                                onClick={() => this.setMachineHome()}
                                disabled={this.isProcessing}
                                size="large"
                                startIcon={this.wizard.state.homingComplete ? <CheckIcon /> : <HomeIcon />}
                                color={this.wizard.state.homingComplete ? "success" : "primary"}
                                sx={{ minWidth: 200 }}
                            >
                                {this.isProcessing ? 'Setting Home...' :
                                    this.wizard.state.homingComplete ? 'Home Set!' :
                                        'Set Machine Home'}
                            </Button>
                        </Box>
                    </Box>
                )}
            />
        );
    }
}
