import {
    Box,
    Button,
    Paper,
    Typography
} from "@mui/material";
import React from "react";
import { ConfigurationData } from "../../../../data/ConfigurationData";
import { MachineData } from "../../../../data/MachineData";
import { MachineStateData } from "../../../../data/MachineStateData";
import { ObserveState } from "../../../../utils/statemanager/ObserveState";
import { NumberInput } from "../../../Common/NumberInput";
import { FullSizeCNCViewer } from "../../../MachineViewer/FullSizeCNCViewer";
import { WizardStep } from "../../../Wizard/WizardStep";
import { AxisCalibrationWizard } from "../AxisCalibrationWizard";
import { AxisCalibrationData } from "./AxisCalibrationData";

export class AxisCalibrationMeasureStep extends WizardStep {
  constructor(wizard: AxisCalibrationWizard, priorStep: WizardStep | null = null) {
    super(wizard, priorStep);
  }

  getTitle(): string {
    return `${AxisCalibrationData.Instance.axis} Axis Calibration - Measure Movement`;
  }

  nextStep(): WizardStep | null {
    if (AxisCalibrationData.Instance.actualMoveAmount > 0) {
      // Go directly to results step since we have the measurement
      const { AxisCalibrationResultStep } = require("./AxisCalibrationResultStep");
      return new AxisCalibrationResultStep(this.wizard as AxisCalibrationWizard, this);
    }
    return null;
  }

  backStep(): WizardStep | null {
    return this.priorStep;
  }

  private calculateCalibration(): void {
    if (AxisCalibrationData.Instance.actualMoveAmount >= 0.001 && AxisCalibrationData.Instance.distanceToMove > 0) {
      // The AxisCalibrationData automatically calculates the calibration factor
      // when actualMoveAmount is set, so we just need to proceed to next step
      this.wizard.advanceToNextStep();
    }
  }



  render(): React.ReactNode {
    const dataInstance = AxisCalibrationData.Instance;
    
    return (
      <ObserveState
        key="axis-calibration-measure-step"
        listenTo={dataInstance}
        properties={['actualMoveAmount', 'distanceToMove']}
        control={() => {
          
          return (
            <Box sx={{ p: 3, height: '100%', display: 'flex', flexDirection: 'column', gap: 3 }}>

              {/* Main Content Area */}
              <Box sx={{ display: 'flex', gap: 3, flex: 1, minHeight: 0 }}>
                {/* Left Side - Measurement Input (50%) */}
                <Box sx={{ flex: '50%', display: 'flex', flexDirection: 'column', gap: 3 }}>
                  
                  {/* Measurement Input */}
                  <Paper sx={{ p: 2 }}>
                    <Typography variant="subtitle1" gutterBottom>
                      Measure Actual Distance Moved
                    </Typography>
                    
                    <Box sx={{ display: 'flex', gap: 3, mb: 3, alignItems: 'center' }}>
                      <Box sx={{ textAlign: 'center', p: 1, borderRadius: 1, backgroundColor: 'grey.100' }}>
                        <Typography variant="caption" color="text.secondary">Commanded</Typography>
                        <Typography variant="h6" color="primary">{AxisCalibrationData.Instance.distanceToMove}"</Typography>
                      </Box>
                      <Typography variant="h4" color="text.secondary">→</Typography>
                      <Box sx={{ textAlign: 'center', p: 1, borderRadius: 1, backgroundColor: 'grey.100' }}>
                        <Typography variant="caption" color="text.secondary">Actual (measured)</Typography>
                        <Typography variant="h6" color={AxisCalibrationData.Instance.actualMoveAmount > 0 ? 'success.main' : 'text.secondary'}>
                          {AxisCalibrationData.Instance.actualMoveAmount > 0 ? `${AxisCalibrationData.Instance.actualMoveAmount}"` : '? "'}
                        </Typography>
                      </Box>
                    </Box>


                    <NumberInput
                      label="Actual Distance Moved (inches)"
                      value={AxisCalibrationData.Instance.actualMoveAmount}
                      onChange={(value) => {
                        AxisCalibrationData.Instance.actualMoveAmount = value;
                      }}
                      min={0.001}
                      max={100}
                      precision={4}
                      helperText="Use a ruler or measuring tool to determine the actual distance moved"
                      autoFocus
                      sx={{ mb: 2 }}
                    />
                  </Paper>
                </Box>

                {/* Right Side - 3D Viewer (50%) */}
                <Box sx={{ flex: '50%', display: 'flex', flexDirection: 'column', minHeight: 0 }}>
                  <FullSizeCNCViewer 
                    simulatorView={ConfigurationData.Instance.defaultView}
                    machineState={MachineStateData.Instance}
                    machineData={MachineData.Instance}
                    job={MachineStateData.Instance.currentJob!}
                    enableOrbit={true}
                    enableClampDragging={false}
                    enableSpindleDrag={false}
                  />
                </Box>
              </Box>

              {/* Action Buttons */}
              <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <Box sx={{ display: 'flex', gap: 2 }}>
                  <Button 
                    variant="outlined"
                    onClick={() => this.wizard.goToPreviousStep()}
                  >
                    Back
                  </Button>
                </Box>
                
                <Button 
                  variant="contained"
                  onClick={() => this.calculateCalibration()}
                  disabled={AxisCalibrationData.Instance.actualMoveAmount < 0.001}
                  size="large"
                >
                  Calculate Results
                </Button>
              </Box>
            </Box>
          );
        }}
      />
    );
  }
}