import { Speed as SpeedIcon } from '@mui/icons-material';
import { Box, Button, Typography } from '@mui/material';
import React from 'react';
import { Machine } from '../../../../machine/Machine';
import { DataUtilities } from '../../../../utils/storage/DataUtilities';
import { FlowStep } from "../../../FlowStep";
import { FlowStepData } from "../../../FlowStepData";

export class GetCurrentSpindleSpeedFactorStep extends FlowStep {
    readonly __type = 'GetCurrentSpindleSpeedFactorStep';
    readonly category = ['Machine', 'Spindle'];
    readonly name = 'Get Current Spindle Speed Factor';
    readonly description = 'Gets the current spindle speed adjustment factor';
    
    // Icon is created dynamically, not stored
    get icon(): React.ReactNode {
        return React.createElement(SpeedIcon, { sx: { color: 'info.main' } });
    }

    static readonly DONE_PATH = 'done';

    async execute(data: FlowStepData, prototypeRun: boolean): Promise<string | null> {
        if (prototypeRun) {
            data.setVariable('spindleSpeedFactor', 1.0);
            return GetCurrentSpindleSpeedFactorStep.DONE_PATH;
        }

        try {
            const factor = await Machine.getInstance().spindle.GetCurrentSpindleSpeedFactor();
            data.setVariable('spindleSpeedFactor', factor);
            return GetCurrentSpindleSpeedFactorStep.DONE_PATH;
        } catch (error) {
            console.error('GetCurrentSpindleSpeedFactor failed:', error);
            data.setVariable('spindleSpeedFactor', 1.0);
            return GetCurrentSpindleSpeedFactorStep.DONE_PATH;
        }
    }

    results(): string[] {
        return [GetCurrentSpindleSpeedFactorStep.DONE_PATH];
    }

    renderResultsUI(data: FlowStepData, result: string): React.ReactNode {
        const factor = data.getVariable('spindleSpeedFactor') || 1.0;
        const percentage = (factor * 100).toFixed(1);
        return (
            <Typography variant="caption">
                Spindle speed factor: {factor} ({percentage}%)
            </Typography>
        );
    }

    renderEditUI(props: { onClose: () => void }): React.ReactNode {
        return (
            <Box sx={{ p: 2, minWidth: 300 }}>
                <Typography variant="h6" gutterBottom>Get Current Spindle Speed Factor</Typography>
                <Typography variant="body2" color="text.secondary">
                    This step retrieves the current spindle speed adjustment factor.
                    The result will be stored in the 'spindleSpeedFactor' variable.
                </Typography>

                <Box sx={{ mt: 2 }}>
                    <Typography variant="subtitle2" gutterBottom>Factor Values:</Typography>
                    <Typography variant="body2">
                        • 1.0 = Normal speed (100%)
                    </Typography>
                    <Typography variant="body2">
                        • 0.5 = Half speed (50%)
                    </Typography>
                    <Typography variant="body2">
                        • 2.0 = Double speed (200%)
                    </Typography>
                </Box>

                <Box sx={{ display: 'flex', gap: 1, justifyContent: 'flex-end', mt: 2 }}>
                    <Button variant="contained" onClick={props.onClose}>OK</Button>
                </Box>
            </Box>
        );
    }

    public toJSON(): any {
        const data = DataUtilities.getStorageData(this, ['icon']) as any;
        data.__type = this.__type;
        return data;
    }

    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data);
    }
}