import React from 'react';
import { CNCPoint } from '../data/CNCPoint';
import { CollisionResult, CollisionCheckInputs, CollisionAction } from './CollisionDetection';
import { ModalManager, Modal } from './ModalManager';
import { CollisionWarningModal } from '../components/CollisionWarningModal';

/**
 * Specialized manager for collision warning modals
 * Uses the generic ModalManager for consistency
 */
export class CollisionModalManager {
  private static _instance: CollisionModalManager;
  private static readonly COLLISION_MODAL_ID = 'collision-warning';
  private static readonly COLLISION_MODAL_PRIORITY = 100; // High priority for collision warnings

  public static get Instance(): CollisionModalManager {
    if (!CollisionModalManager._instance) {
      CollisionModalManager._instance = new CollisionModalManager();
    }
    return CollisionModalManager._instance;
  }

  /**
   * Check if a collision warning modal is currently active
   */
  public get hasActiveCollision(): boolean {
    return ModalManager.Instance.isModalActive(CollisionModalManager.COLLISION_MODAL_ID);
  }

  /**
   * Show a collision warning modal
   */
  public showCollisionWarning(
    collisionResult: CollisionResult,
    options: Array<{
      action: CollisionAction;
      label: string;
      description: string;
      point?: CNCPoint;
    }>,
    onUserChoice: (action: CollisionAction, safePosition?: CNCPoint) => void,
    targetPosition: CNCPoint,
    fromPosition?: CNCPoint,
    collisionInputs?: CollisionCheckInputs
  ): void {
    const modal: Modal = {
      id: CollisionModalManager.COLLISION_MODAL_ID,
      priority: CollisionModalManager.COLLISION_MODAL_PRIORITY,
      render: () => React.createElement(CollisionWarningModal, {
        collisionResult,
        options,
        onUserChoice: (action: CollisionAction, safePosition?: CNCPoint) => {
          // Clear the modal first
          this.clearCollisionWarning();
          // Then execute the user's choice
          onUserChoice(action, safePosition);
        },
        targetPosition,
        fromPosition,
        collisionInputs
      })
    };

    ModalManager.Instance.showModal(modal);
  }

  /**
   * Clear/hide any active collision warning modal
   */
  public clearCollisionWarning(): void {
    ModalManager.Instance.closeModal(CollisionModalManager.COLLISION_MODAL_ID);
  }
}
