import { Output as OutputIcon } from '@mui/icons-material';
import { Typography } from '@mui/material';
import React from 'react';
import { MachineData } from '../../../../data/MachineData';
import { Machine } from '../../../../machine/Machine';
import { LogCategory, Logger } from '../../../../utils/Logger';
import { DataUtilities } from '../../../../utils/storage/DataUtilities';
import { FlowStep } from "../../../FlowStep";
import { FlowStepData } from "../../../FlowStepData";

/**
 * Generic output checking step that can be configured for any machine output
 * Used by the factory to create output-specific step instances
 * Stores the output NAME - looks up number and text from MachineData at runtime
 */
export class CheckOutputStep extends FlowStep {
    get __type(): string { return 'CheckOutputStep'; }
    get category(): string[] {
        const outputConfig = this.getOutputConfig();
        return ['Machine', 'IO', 'Outputs', outputConfig.name];
    }

    private outputName: string = '';

    constructor(outputName?: string) {
        super();
        if (outputName !== undefined) {
            this.outputName = outputName;
        }
    }

    /**
     * Set the output name (used by factory)
     */
    public setOutputName(outputName: string): void {
        this.outputName = outputName;
    }

    /**
     * Get the output configuration from MachineData by name
     */
    private getOutputConfig() {
        const machineData = MachineData.Instance;
        const output = machineData.machineOutputs.find(o => o.name === this.outputName);

        if (!output) {
            // Fallback if output not found
            return {
                name: this.outputName || 'Unknown Output',
                number: 0,
                activeText: 'On',
                inactiveText: 'Off'
            };
        }

        return {
            name: output.name,
            number: output.number || 0,
            activeText: output.activeText,
            inactiveText: output.inactiveText
        };
    }

    get name(): string {
        const config = this.getOutputConfig();
        return `Is ${config.name} On`;
    }

    get description(): string {
        const config = this.getOutputConfig();
        return `Check if ${config.name} is on (${config.activeText}/${config.inactiveText})`;
    }

    get icon(): React.ReactNode {
        return React.createElement(OutputIcon, { sx: { color: 'secondary.main' } });
    }

    async execute(data: FlowStepData, prototypeRun: boolean): Promise<string | null> {
        const config = this.getOutputConfig();

        if (prototypeRun) {
            return Math.random() > 0.5 ? config.activeText : config.inactiveText;
        }

        try {
            const isActive = await Machine.getInstance().io.IsOutputActive(config.number);
            data.setVariable(`output${config.number}Active`, isActive);
            data.setVariable(`output${config.number}State`, isActive ? config.activeText : config.inactiveText);
            return isActive ? config.activeText : config.inactiveText;
        } catch (error) {
            Logger.Instance.logError(LogCategory.System, `Check output ${config.number} (${config.name}) failed:`, error);
            // Return inactive text on error
            return config.inactiveText;
        }
    }

    results(): string[] {
        const config = this.getOutputConfig();
        return [config.activeText, config.inactiveText];
    }

    renderResultsUI(data: FlowStepData, result: string): React.ReactNode {
        const config = this.getOutputConfig();
        return (
            <Typography variant="caption">
                {config.name}: {result}
            </Typography>
        );
    }

    renderEditUI(props: { onClose: () => void }): React.ReactNode {
        const config = this.getOutputConfig();
        return (
            <Typography variant="body2" sx={{ p: 2 }}>
                This step checks if "{config.name}" (Output {config.number || 'not configured'}) is on ({config.activeText}).
            </Typography>
        );
    }

    public toJSON(): any {
        const data = DataUtilities.getStorageData(this, ['icon']) as any;
        data.__type = this.__type;
        data.outputName = this.outputName;
        return data;
    }

    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data);
        if (data.outputName !== undefined) {
            this.outputName = data.outputName;
        }
    }
}
