import { Box, Paper, Typography } from '@mui/material';
import { Component } from 'react';
import { CNCSimulatorView } from '../CNCViewerDemo';
import { FlowTab } from '../Views/FlowTab';
import { Home } from '../Views/Home';
import { Laser } from '../Views/Laser';
import { Learning } from '../Views/Learning';
import { MDIView } from '../Views/MDIView';
import { Milling } from '../Views/Milling';
import { Settings } from '../Views/Settings';
import { System } from '../Views/System';
import { Turning } from '../Views/Turning';

interface MainContentProps {
  selectedView: string;
  onViewChange?: (view: string) => void;
}

export class MainContent extends Component<MainContentProps> {
  renderContent = () => {
    const { onViewChange } = this.props;

    switch (this.props.selectedView) {
      case 'home':
        return <Home onViewChange={onViewChange} />;
      case 'viewer':
        return <CNCSimulatorView />;
      case 'mdi':
        return <MDIView />;
      case 'learning':
        return <Learning />;
      case 'milling':
        return <Milling />;
      case 'turning':
        return <Turning />;
      case 'laser':
        return <Laser />;
      case 'settings':
        return <Settings />;
      case 'system':
        return <System />;
      case 'flow':
        return <FlowTab />;
      default:
        return (
          <Paper sx={{ p: 3, height: '100%' }}>
            <Typography variant="h4" gutterBottom>
              Welcome to HavenCNC
            </Typography>
            <Typography variant="body1">
              Select a view from the navigation panel to get started.
            </Typography>
          </Paper>
        );
    }
  };

  render() {
    return (
      <Box sx={{ p: 2, height: '100%', overflow: 'auto' }}>
        {this.renderContent()}
      </Box>
    );
  }
}
