import { IStorable } from "../../../../common/IStorable";
import { CNCPoint } from "../../../../data/CNCPoint";
import { CoordinateType } from "../../../../data/Common/CoordinateType";
import { Machine } from "../../../../machine/Machine";
import { StateManager } from "../../../../utils/statemanager/StateManager";
import { DataUtilities } from "../../../../utils/storage/DataUtilities";

export enum AxisCalibrationMarkType {
  Manual = "manual",
  Drill = "drill",
  Line = "line"
}

export enum AxisCalibrationMeasurementMethod {
  CenterToCenter = "center-to-center",
  InsideEdges = "inside-edges"
}

/**
 * Data structure for axis calibration wizard
 * Manages all state for the calibration process with StateManager integration
 * Implemented as singleton pattern
 */
export class AxisCalibrationData implements IStorable {
  private static _instance: AxisCalibrationData;

  // Starting position where calibration begins
  private _startingPoint: CNCPoint;

  // Distance to move for calibration measurement
  private _distanceToMove: number;

  // Type of marking method to use
  private _markType: AxisCalibrationMarkType;

  // Method for measuring distance (center-to-center or inside edges)
  private _measurementMethod: AxisCalibrationMeasurementMethod;

  // Depth to cut/mark into material (for drill/line methods)
  private _markDepth: number;

  // Diameter of the current tool (for drill/line methods)
  private _bitDiameter: number;

  // Spindle speed for marking operations (RPM)
  private _spindleSpeed: number;

  // Length of scribed line (for line marking method)
  private _lineLength: number;

  // Actual distance moved (measured result)
  private _actualMoveAmount: number;

  // Which axis is being calibrated (X, Y, or Z)
  private _axis: string;

  // Calculated calibration factor (actual / commanded)
  private _calibrationFactor: number;

  private constructor() {
    this._axis = "";
    this._startingPoint = new CNCPoint(0, 0, 0, CoordinateType.MachineZero);
    this._distanceToMove = 36.0; // Default 1 inch
    this._markType = AxisCalibrationMarkType.Manual;
    this._measurementMethod = AxisCalibrationMeasurementMethod.CenterToCenter;
    this._markDepth = 0.1;
    this._bitDiameter = 0.25;
    this._spindleSpeed = 12000; // Default 12000 RPM
    this._lineLength = 1.0; // Default 1 inch
    this._actualMoveAmount = 0;
    this._calibrationFactor = 1.0;
  }

  public static get Instance(): AxisCalibrationData {
    if (!AxisCalibrationData._instance) {
      AxisCalibrationData._instance = new AxisCalibrationData();
    }
    return AxisCalibrationData._instance;
  }

  public static createNew(axis: string): AxisCalibrationData {
    AxisCalibrationData._instance = new AxisCalibrationData();
    AxisCalibrationData._instance._axis = axis;
    return AxisCalibrationData._instance;
  }

  // Getters and setters with StateManager integration
  public get startingPoint(): CNCPoint {
    return this._startingPoint;
  }

  public set startingPoint(value: CNCPoint) {
    this._startingPoint = value;
    StateManager.propertyChanged(this, 'startingPoint');
  }

  public get distanceToMove(): number {
    return this._distanceToMove;
  }

  public set distanceToMove(value: number) {
    this._distanceToMove = value;
    StateManager.propertyChanged(this, 'distanceToMove');
  }

  public get markType(): AxisCalibrationMarkType {
    return this._markType;
  }

  public set markType(value: AxisCalibrationMarkType) {
    this._markType = value;
    StateManager.propertyChanged(this, 'markType');
  }

  public get measurementMethod(): AxisCalibrationMeasurementMethod {
    return this._measurementMethod;
  }

  public set measurementMethod(value: AxisCalibrationMeasurementMethod) {
    this._measurementMethod = value;
    StateManager.propertyChanged(this, 'measurementMethod');
  }

  public get markDepth(): number {
    return this._markDepth;
  }

  public set markDepth(value: number) {
    this._markDepth = value;
    StateManager.propertyChanged(this, 'markDepth');
  }

  public get bitDiameter(): number {
    return this._bitDiameter;
  }

  public set bitDiameter(value: number) {
    this._bitDiameter = value;
    StateManager.propertyChanged(this, 'bitDiameter');
  }

  public get spindleSpeed(): number {
    return this._spindleSpeed;
  }

  public set spindleSpeed(value: number) {
    this._spindleSpeed = value;
    StateManager.propertyChanged(this, 'spindleSpeed');
  }

  public get lineLength(): number {
    return this._lineLength;
  }

  public set lineLength(value: number) {
    this._lineLength = value;
    StateManager.propertyChanged(this, 'lineLength');
  }

  public get actualMoveAmount(): number {
    return this._actualMoveAmount;
  }

  public set actualMoveAmount(value: number) {
    this._actualMoveAmount = value;
    // Calibration factor should be distanceToMove / actualMoveAmount
    // If we commanded 10" and got 9", factor = 10/9 = 1.111 (need MORE revolutions)
    // If we commanded 10" and got 11", factor = 10/11 = 0.909 (need FEWER revolutions)
    this._calibrationFactor = this._distanceToMove / value;
    StateManager.propertyChanged(this, 'actualMoveAmount');
    StateManager.propertyChanged(this, 'calibrationFactor');
  }

  public get axis(): string {
    return this._axis;
  }

  public get calibrationFactor(): number {
    return this._calibrationFactor;
  }

  public get calibrationPercentage(): number {
    return (this._calibrationFactor - 1.0) * 100;
  }

  public get isCalibrationNeeded(): boolean {
    const tolerance = 0.001; // 0.1% tolerance
    return Math.abs(this._calibrationFactor - 1.0) > tolerance;
  }

  // Utility methods
  public reset(): void {
    this._startingPoint = new CNCPoint(0, 0, 0, CoordinateType.MachineZero);
    this._distanceToMove = 1.0;
    this._markType = AxisCalibrationMarkType.Manual;
    this._measurementMethod = AxisCalibrationMeasurementMethod.CenterToCenter;
    this._markDepth = 0.1;
    this._bitDiameter = 0.25;
    this._spindleSpeed = 12000;
    this._lineLength = 1.0;
    this._actualMoveAmount = 0;
    this._calibrationFactor = 1.0;
    StateManager.propertyChanged(this, 'reset');
  }

  public resetForNextTest(): void {
    // Reset for next test iteration
    this._actualMoveAmount = 0;
    this._calibrationFactor = 1.0;
    StateManager.propertyChanged(this, 'actualMoveAmount');
    StateManager.propertyChanged(this, 'calibrationFactor');
  }

  public setupForAxis(axis: string): void {
    this._axis = axis;
    this.reset();
  }

  public async setStartingPointFromCurrent(): Promise<void> {
    // Get current machine position from the machine interface
    const currentPosition = await Machine.getInstance().movement.GetCurrentPosition();
    this._startingPoint = currentPosition;
    StateManager.propertyChanged(this, 'startingPoint');
  }

  // IStorable implementation
  public toJSON(): any {
    return DataUtilities.getStorageData(this);
  }

  public fromJSON(data: any): void {
    DataUtilities.loadStorageData(this, data);
    // Ensure CNCPoint is properly restored
    if (data._startingPoint) {
      this._startingPoint = new CNCPoint(
        data._startingPoint.x || 0,
        data._startingPoint.y || 0,
        data._startingPoint.z || 0,
        data._startingPoint.coordinateType || CoordinateType.MachineZero
      );
    }
  }
}