import { Add as AddIcon, Delete as DeleteIcon, Edit as EditIcon } from '@mui/icons-material';
import {
  Box,
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Divider,
  Grid,
  IconButton,
  List,
  ListItem,
  ListItemButton,
  ListItemText,
  Paper,
  Tooltip,
  Typography
} from '@mui/material';
import { useCallback, useEffect, useState } from 'react';
import { MachineOutput } from '../../../data/Machine/MachineOutput';
import { MachineData } from '../../../data/MachineData';
import { Machine } from '../../../machine/Machine';
import { LogCategory, Logger } from '../../../utils/Logger';
import { OutputNumberManager } from '../../../utils/OutputNumberManager';
import { ObserveState } from '../../../utils/statemanager/ObserveState';
import { StateManager } from '../../../utils/statemanager/StateManager';
import { MachineOutputEditor } from '../../Common/MachineOutputEditor';
import { NullableNumberInput } from '../../Common/NullableNumberInput';

/**
 * OutputsTab component - Manages machine output configuration
 * Shows unassigned outputs as cards and assigned outputs in a grid layout
 */
export function OutputsTab() {
  const [machineData] = useState(() => MachineData.Instance);
  const [currentOutputStates, setCurrentOutputStates] = useState<Record<number, boolean>>({});
  const [editDialogOpen, setEditDialogOpen] = useState(false);
  const [editingOutput, setEditingOutput] = useState<MachineOutput | null>(null);
  const [addOutputDialogOpen, setAddOutputDialogOpen] = useState(false);
  const [addOutputIsCreatingNew, setAddOutputIsCreatingNew] = useState(false);
  const [addOutputCurrentItem, setAddOutputCurrentItem] = useState<MachineOutput | null>(null);
  const [addOutputQueuedItems, setAddOutputQueuedItems] = useState<Set<MachineOutput>>(new Set());
  const [addOutputDeleteQueue, setAddOutputDeleteQueue] = useState<Set<MachineOutput>>(new Set());

  // Fetch current output states from machine interface
  useEffect(() => {
    const fetchOutputStates = async () => {
      try {
        const machineInterface = Machine.getInstance();
        const states = await machineInterface.io.GetCurrentOutputs();
        setCurrentOutputStates(states);
      } catch (error) {
        Logger.Instance.logError(LogCategory.System, 'Failed to fetch output states:', error);
      }
    };

    // Fetch initially
    fetchOutputStates();

    // Set up polling to refresh output states every 500ms (same as inputs)
    const intervalId = setInterval(fetchOutputStates, 500);

    // Cleanup interval on unmount
    return () => {
      clearInterval(intervalId);
    };
  }, []);

  // Enforce policy that unused outputs should never have numbers
  useEffect(() => {
    OutputNumberManager.enforceUnusedOutputsNumberPolicy(machineData.machineOutputs, machineData);
  }, [machineData.machineOutputs, machineData]);

  // Get outputs grouped into unassigned and assigned sections using shared utilities
  const getGroupedOutputs = useCallback(() => {
    const unassignedOutputs = OutputNumberManager.getUnassignedOutputs(machineData.machineOutputs);
    const assignedOutputs = OutputNumberManager.getAssignedOutputs(machineData.machineOutputs);

    // Debug logging
    // Logger.Instance.log(LogCategory.System, 
    //   `Output grouping - Total: ${machineData.machineOutputs.length}, Unassigned: ${unassignedOutputs.length}, Assigned: ${assignedOutputs.length}`);

    return { unassignedOutputs, assignedOutputs };
  }, [machineData.machineOutputs]);

  // Handle output number changes
  const handleOutputNumberChange = useCallback((output: MachineOutput, newNumber: number | null) => {
    const numberToAssign = newNumber ?? 0;

    // Validate before assignment
    const validation = OutputNumberManager.validateOutputNumberAssignment(output, numberToAssign, machineData.machineOutputs);
    if (!validation.isValid) {
      Logger.Instance.logError(LogCategory.UserInterface, `Invalid output assignment: ${validation.error}`);
      return;
    }

    // Use OutputNumberManager to handle assignment and conflicts
    OutputNumberManager.assignOutputNumber(output, numberToAssign, machineData.machineOutputs, machineData);

    // Logger.Instance.log(LogCategory.UserInterface, 
    //   `Output number changed: ${output.name} ${newNumber ? `assigned to ${newNumber}` : 'unassigned'}`);
  }, [machineData]);

  // Handle output editing - opens edit dialog
  const handleEditOutput = useCallback((output: MachineOutput) => {
    setEditingOutput(output);
    setEditDialogOpen(true);
    //Logger.Instance.log(LogCategory.UserInterface, `Opening edit dialog for output: ${output.name}`);
  }, []);

  // Handle output deletion from main tab - set use flag to false and clear number
  const handleDeleteOutput = useCallback((output: MachineOutput) => {
    output.use = false;
    output.number = 0; // Clear the assigned number
    StateManager.propertyChanged(machineData, 'machineOutputs');
    //Logger.Instance.log(LogCategory.UserInterface, `Deleted output (set use=false, cleared number): ${output.name}`);
  }, [machineData]);

  // Get current physical state for display from stored state data
  const getPhysicalState = useCallback((output: MachineOutput): 'active' | 'inactive' | 'unknown' => {
    // If output has no assigned number, return unknown
    if (output.number === 0) {
      return 'unknown';
    }

    // Check if we have state data for this output number
    if (output.number in currentOutputStates) {
      const outputValue = currentOutputStates[output.number];
      // For outputs: true = active, false = inactive
      return outputValue ? 'active' : 'inactive';
    }

    // No state data available for this output
    return 'unknown';
  }, [currentOutputStates]);

  // Get unused outputs for the add dialog using shared utility
  const getUnusedOutputs = useCallback((): MachineOutput[] => {
    const unusedOutputs = OutputNumberManager.getUnusedOutputs(machineData.machineOutputs);
    //Logger.Instance.log(LogCategory.UserInterface, `getUnusedOutputs called - Found ${unusedOutputs.length} unused outputs`);
    //Logger.Instance.log(LogCategory.UserInterface, `Total machine outputs: ${machineData.machineOutputs.length}`);
    //Logger.Instance.log(LogCategory.UserInterface, `All outputs:`, machineData.machineOutputs.map(o => `${o.name} (use: ${o.use})`));
    //Logger.Instance.log(LogCategory.UserInterface, `Unused outputs:`, unusedOutputs.map(o => `${o.name} (use: ${o.use})`));
    return unusedOutputs;
  }, [machineData.machineOutputs]);

  // Handle opening add output dialog
  const handleOpenAddOutput = useCallback(() => {
    setAddOutputDialogOpen(true);
    setAddOutputIsCreatingNew(false);
    setAddOutputQueuedItems(new Set());

    // Set first unused output as current
    const unusedOutputs = getUnusedOutputs();
    if (unusedOutputs.length > 0) {
      setAddOutputCurrentItem(unusedOutputs[0]);
    } else {
      setAddOutputCurrentItem(null);
    }
    //Logger.Instance.log(LogCategory.UserInterface, 'Add outputs dialog opened');
  }, [getUnusedOutputs]);

  // Handle closing add output dialog
  const handleCloseAddOutput = useCallback(() => {
    setAddOutputDialogOpen(false);
    setAddOutputIsCreatingNew(false);
    setAddOutputCurrentItem(null);
    setAddOutputQueuedItems(new Set());
    setAddOutputDeleteQueue(new Set());
    //Logger.Instance.log(LogCategory.UserInterface, 'Add outputs dialog closed');
  }, []);

  // Handle selecting current item in add dialog
  const handleSelectCurrentItem = useCallback((output: MachineOutput) => {
    setAddOutputCurrentItem(output);
    //Logger.Instance.log(LogCategory.UserInterface, `Selected output: ${output.name}`);
  }, []);

  // Handle queueing output for addition
  const handleQueueOutputForAdd = useCallback((output: MachineOutput) => {
    //Logger.Instance.log(LogCategory.UserInterface, `Queue button clicked for: ${output.name} (${output.constructor.name})`);

    setAddOutputQueuedItems(prev => {
      const newSet = new Set(prev);
      const wasQueued = newSet.has(output);

      //Logger.Instance.log(LogCategory.UserInterface, `Output ${output.name} was${wasQueued ? '' : ' not'} in queue before click`);
      //Logger.Instance.log(LogCategory.UserInterface, `Queue before:`, Array.from(newSet).map(o => `${o.name} (${o === output ? 'SAME REF' : 'DIFF REF'})`));

      if (wasQueued) {
        newSet.delete(output);
        //Logger.Instance.log(LogCategory.UserInterface, `Removed output from add queue: ${output.name}. Queue size: ${newSet.size}`);
      } else {
        newSet.add(output);
        //Logger.Instance.log(LogCategory.UserInterface, `Added output to add queue: ${output.name}. Queue size: ${newSet.size}`);
      }
      //Logger.Instance.log(LogCategory.UserInterface, `Current add queue:`, Array.from(newSet).map(o => o.name));
      return newSet;
    });
  }, []);

  // Handle queueing output for deletion
  const handleQueueOutputForDelete = useCallback((output: MachineOutput) => {
    setAddOutputDeleteQueue(prev => {
      const newSet = new Set(prev);
      if (newSet.has(output)) {
        newSet.delete(output);
        //Logger.Instance.log(LogCategory.UserInterface, `Removed output from delete queue: ${output.name}`);
      } else {
        newSet.add(output);
        //Logger.Instance.log(LogCategory.UserInterface, `Added output to delete queue: ${output.name}`);
      }
      return newSet;
    });
  }, []);

  // Handle creating new output in add dialog
  const handleCreateNewOutputInAddDialog = useCallback(() => {
    //Logger.Instance.log(LogCategory.System, 'handleCreateNewOutputInAddDialog called!');
    try {
      const newOutput = new MachineOutput(
        0, // number - start with 0 (unassigned)
        'New Output',
        undefined, // centroidMapping
        'Active', // activeText
        'Inactive', // inactiveText
        false // use: false - this makes it appear in the left list as "unused"
      );

      // Add it to machine data immediately so it appears in the left list
      machineData.machineOutputs.push(newOutput);
      //Logger.Instance.log(LogCategory.System, `Added new output to machineData. Total outputs now: ${machineData.machineOutputs.length}`);
      //Logger.Instance.log(LogCategory.System, `New output details: ${newOutput.name}, use: ${newOutput.use}, number: ${newOutput.number}`);

      // Trigger state update to refresh the UI first
      StateManager.propertyChanged(machineData, 'machineOutputs');
      //Logger.Instance.log(LogCategory.System, 'StateManager.propertyChanged called for machineOutputs');

      // Set as current item for immediate editing
      setAddOutputCurrentItem(newOutput);
      setAddOutputIsCreatingNew(true);
      //Logger.Instance.log(LogCategory.System, `Set current item to: ${newOutput.name}, isCreatingNew: true`);

      // Automatically queue it for addition (so it shows "Queued" status)
      setAddOutputQueuedItems(prev => {
        const newSet = new Set(prev);
        newSet.add(newOutput);
        //Logger.Instance.log(LogCategory.System, `Added to queue. Queue size: ${newSet.size}`);
        return newSet;
      });

      // Logger.Instance.log(LogCategory.System, 
      //   `Created new output - Name: ${newOutput.name}, Number: ${newOutput.number}, Automatically queued for addition`);
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Failed to create new output:', error);
    }
  }, [machineData]);

  // Process queued outputs (add/delete)
  const handleProcessQueuedOutputs = useCallback(() => {
    //Logger.Instance.log(LogCategory.UserInterface, `Processing queued outputs. Add queue size: ${addOutputQueuedItems.size}, Delete queue size: ${addOutputDeleteQueue.size}`);

    // Process additions - mark queued outputs as in use
    addOutputQueuedItems.forEach(output => {
      //Logger.Instance.log(LogCategory.UserInterface, `Processing add: ${output.name}, changing use from ${output.use} to true`);
      output.use = true;
      output.number = 0; // Set to unassigned initially
      //Logger.Instance.log(LogCategory.UserInterface, `After change: ${output.name}, use: ${output.use}, number: ${output.number}`);
    });

    // Process deletions
    addOutputDeleteQueue.forEach(output => {
      const index = machineData.machineOutputs.indexOf(output);
      if (index > -1) {
        machineData.machineOutputs.splice(index, 1);
      }
    });

    // Notify state manager of changes
    StateManager.propertyChanged(machineData, 'machineOutputs');

    const addedCount = addOutputQueuedItems.size;
    const deletedCount = addOutputDeleteQueue.size;

    if (addedCount > 0) {
      // Logger.Instance.log(LogCategory.UserInterface, 
      //   `Added ${addedCount} outputs: ${Array.from(addOutputQueuedItems).map(o => o.name).join(', ')}`);
    }

    if (deletedCount > 0) {
      // Logger.Instance.log(LogCategory.UserInterface, 
      //   `Deleted ${deletedCount} outputs: ${Array.from(addOutputDeleteQueue).map(o => o.name).join(', ')}`);
    }

    // Close dialog
    handleCloseAddOutput();
  }, [addOutputQueuedItems, addOutputDeleteQueue, machineData, handleCloseAddOutput]);

  return (
    <ObserveState
      listenTo={machineData}
      properties={['machineOutputs']}
      control={() => (
        <>
          <Box sx={{ height: '100%', display: 'flex', flexDirection: 'column', p: 3 }}>
            <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
              <Typography variant="h5">Machine Outputs</Typography>
              <Button
                variant="contained"
                startIcon={<AddIcon />}
                onClick={handleOpenAddOutput}
              >
                Add Outputs
              </Button>
            </Box>

            {(() => {
              const { unassignedOutputs, assignedOutputs } = getGroupedOutputs();

              return (
                <>
                  {/* Unassigned Outputs Section */}
                  {unassignedOutputs.length > 0 && (
                    <Box sx={{ mb: 3 }}>
                      <Typography
                        variant="subtitle1"
                        sx={{
                          mb: 2,
                          fontWeight: 600,
                          color: 'warning.main',
                          borderBottom: '2px solid',
                          borderColor: 'warning.main',
                          pb: 0.5
                        }}
                      >
                        Unassigned Outputs ({unassignedOutputs.length})
                      </Typography>

                      {/* Card layout for unassigned outputs - responsive grid */}
                      <Box sx={{
                        display: 'grid',
                        gridTemplateColumns: {
                          xs: '1fr',           // 1 column on extra small screens
                          sm: 'repeat(2, 1fr)' // 2 columns on small+ screens
                        },
                        gap: 2,
                        mt: 2
                      }}>
                        {unassignedOutputs.map((output) => (
                          <Paper
                            key={`unassigned-${output.name}`}
                            elevation={2}
                            sx={{
                              p: 2,
                              border: '1px solid',
                              borderColor: 'divider',
                              borderRadius: 2,
                              backgroundColor: 'background.paper',
                              transition: 'all 0.2s ease',
                              '&:hover': {
                                elevation: 4,
                                transform: 'translateY(-1px)'
                              }
                            }}
                          >
                            {/* Single row layout: # [number] name [edit] [delete] */}
                            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                              {/* Hash symbol */}
                              <Typography variant="body2" sx={{ fontWeight: 500, color: 'text.secondary' }}>
                                #
                              </Typography>

                              {/* Number input */}
                              <NullableNumberInput
                                value={output.number === 0 ? null : output.number}
                                onChange={(newNumber) => {
                                  handleOutputNumberChange(output, newNumber);
                                }}
                                size="small"
                                allowNegative={false}
                                min={1}
                                max={999}
                                sx={{ width: 80 }}
                              />

                              {/* Output name - flexible width */}
                              <Typography
                                variant="body1"
                                sx={{
                                  fontWeight: 600,
                                  flex: 1,
                                  overflow: 'hidden',
                                  textOverflow: 'ellipsis',
                                  whiteSpace: 'nowrap',
                                  ml: 1
                                }}
                              >
                                {output.name}
                              </Typography>

                              {/* Action buttons */}
                              {/* Edit Button */}
                              <Tooltip title="Edit output">
                                <IconButton
                                  size="medium"
                                  onClick={() => handleEditOutput(output)}
                                  sx={{
                                    color: 'text.secondary',
                                    '&:hover': {
                                      backgroundColor: 'primary.main',
                                      color: 'white'
                                    }
                                  }}
                                >
                                  <EditIcon sx={{ fontSize: '24px' }} />
                                </IconButton>
                              </Tooltip>

                              {/* Delete Button */}
                              <Tooltip title="Remove output">
                                <IconButton
                                  size="medium"
                                  onClick={() => handleDeleteOutput(output)}
                                  sx={{
                                    color: 'text.secondary',
                                    '&:hover': {
                                      backgroundColor: 'error.main',
                                      color: 'white'
                                    }
                                  }}
                                >
                                  <DeleteIcon sx={{ fontSize: '24px' }} />
                                </IconButton>
                              </Tooltip>
                            </Box>
                          </Paper>
                        ))}
                      </Box>
                    </Box>
                  )}

                  {/* Assigned Outputs Section */}
                  {assignedOutputs.length > 0 && (
                    <Box>
                      <Typography
                        variant="subtitle1"
                        sx={{
                          mb: 2,
                          fontWeight: 600,
                          color: 'primary.main',
                          borderBottom: '2px solid',
                          borderColor: 'primary.main',
                          pb: 0.5
                        }}
                      >
                        Assigned Outputs ({assignedOutputs.length})
                      </Typography>

                      {/* Column Headers */}
                      <Box sx={{
                        display: 'grid',
                        gridTemplateColumns: '120px 1fr 140px 200px 120px',
                        gap: 2,
                        alignItems: 'center',
                        mb: 1,
                        px: 2,
                        py: 1
                      }}>
                        <Typography variant="caption" sx={{ fontWeight: 600, color: 'text.secondary' }}>
                          #
                        </Typography>
                        <Typography variant="caption" sx={{ fontWeight: 600, color: 'text.secondary' }}>
                          Name
                        </Typography>
                        <Typography variant="caption" sx={{ fontWeight: 600, color: 'text.secondary', textAlign: 'center' }}>
                          Output State
                        </Typography>
                        <Typography variant="caption" sx={{ fontWeight: 600, color: 'text.secondary' }}>
                          Description
                        </Typography>
                        <Typography variant="caption" sx={{ fontWeight: 600, color: 'text.secondary', textAlign: 'center' }}>
                          Actions
                        </Typography>
                      </Box>

                      {assignedOutputs.map((output, index) => {
                        const physicalState = getPhysicalState(output);
                        const isActive = physicalState === 'active';
                        const isInactive = physicalState === 'inactive';

                        const elements = [(
                          <Box
                            key={`assigned-${output.name}-${output.number}`}
                            sx={{
                              display: 'grid',
                              gridTemplateColumns: '120px 1fr 140px 200px 120px',
                              gap: 2,
                              alignItems: 'center',
                              px: 2,
                              py: 1.5,
                              backgroundColor: 'background.paper',
                              border: '1px solid',
                              borderColor: 'divider',
                              borderRadius: 1,
                              mb: 1,
                              '&:hover': {
                                backgroundColor: 'action.hover'
                              }
                            }}
                          >
                            {/* Number */}
                            <NullableNumberInput
                              value={output.number === 0 ? null : output.number}
                              onChange={(newNumber) => handleOutputNumberChange(output, newNumber)}
                              size="small"
                              allowNegative={false}
                              min={1}
                              max={999}
                              sx={{ width: 80 }}
                            />

                            {/* Name */}
                            <Typography variant="body2" sx={{ fontWeight: 500 }}>
                              {output.name}
                            </Typography>

                            {/* State indicator */}
                            <Box sx={{ display: 'flex', justifyContent: 'center' }}>
                              <Box
                                sx={{
                                  width: 12,
                                  height: 12,
                                  borderRadius: '50%',
                                  backgroundColor: isActive ? 'success.main' : isInactive ? 'grey.400' : 'grey.300',
                                  border: '1px solid',
                                  borderColor: isActive ? 'success.dark' : 'grey.500'
                                }}
                              />
                            </Box>

                            {/* Description */}
                            <Typography variant="body2" color="text.secondary">
                              {isActive ? output.activeText : output.inactiveText}
                            </Typography>

                            {/* Actions */}
                            <Box sx={{ display: 'flex', justifyContent: 'center', gap: 0.5 }}>
                              <Tooltip title="Edit output">
                                <IconButton
                                  size="small"
                                  onClick={() => handleEditOutput(output)}
                                  sx={{ color: 'text.secondary' }}
                                >
                                  <EditIcon fontSize="small" />
                                </IconButton>
                              </Tooltip>

                              <Tooltip title="Remove output">
                                <IconButton
                                  size="small"
                                  onClick={() => handleDeleteOutput(output)}
                                  sx={{ color: 'text.secondary' }}
                                >
                                  <DeleteIcon fontSize="small" />
                                </IconButton>
                              </Tooltip>
                            </Box>
                          </Box>
                        )];

                        // Check if there's a gap before the next output
                        if (index < assignedOutputs.length - 1) {
                          const currentNumber = output.number;
                          const nextNumber = assignedOutputs[index + 1].number;
                          if (typeof currentNumber === 'number' && typeof nextNumber === 'number' && nextNumber - currentNumber > 1) {
                            // Add extra spacing for gap
                            elements.push(
                              <Box key={`gap-${currentNumber}-${nextNumber}`} sx={{ height: '20px' }} />
                            );
                          }
                        }

                        return elements;
                      }).flat()}
                    </Box>
                  )}
                </>
              );
            })()}

            {(() => {
              const { unassignedOutputs, assignedOutputs } = getGroupedOutputs();
              return (unassignedOutputs.length === 0 && assignedOutputs.length === 0);
            })() && (
                <Box sx={{ textAlign: 'center', mt: 4 }}>
                  <Typography variant="body2" color="text.secondary">
                    No outputs are currently marked as "used". Configure outputs in Machine Data to see them here.
                  </Typography>
                </Box>
              )}
          </Box>

          {/* Edit Output Dialog */}
          <Dialog
            open={editDialogOpen}
            onClose={() => {
              setEditDialogOpen(false);
              setEditingOutput(null);
            }}
            maxWidth="md"
            fullWidth
          >
            <DialogTitle>Edit Output</DialogTitle>
            <DialogContent>
              {editingOutput && (
                <MachineOutputEditor
                  output={editingOutput}
                  title={null}
                />
              )}
            </DialogContent>
            <DialogActions>
              <Button
                onClick={() => {
                  setEditDialogOpen(false);
                  setEditingOutput(null);
                  //Logger.Instance.log(LogCategory.UserInterface, 'Output edit dialog closed');
                }}
                variant="contained"
                sx={{
                  position: 'absolute',
                  right: 24,
                  bottom: 24
                }}
              >
                Done
              </Button>
            </DialogActions>
          </Dialog>

          {/* Add Output Dialog */}
          <Dialog
            open={addOutputDialogOpen}
            onClose={handleCloseAddOutput}
            maxWidth="lg"
            fullWidth
          >
            <DialogTitle>Add Machine Outputs</DialogTitle>
            <DialogContent>
              <Grid container spacing={2}>
                {/* Left Panel - Output List */}
                <Grid item xs={6}>
                  <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                    Select an output to configure, then click "Add" to queue it for addition.
                  </Typography>
                  <List sx={{
                    border: '1px solid',
                    borderColor: 'divider',
                    borderRadius: 1,
                    height: 'calc(100vh - 350px)',
                    minHeight: 400,
                    overflow: 'auto'
                  }}>
                    {getUnusedOutputs().map((output) => {
                      const isQueued = addOutputQueuedItems.has(output);
                      const isToDelete = addOutputDeleteQueue.has(output);

                      // Debug logging for queue state
                      //Logger.Instance.log(LogCategory.UserInterface, `Rendering output ${output.name}: queued=${isQueued}, toDelete=${isToDelete}`);

                      return (
                        <ListItem
                          key={output.name}
                          disablePadding
                          sx={{
                            backgroundColor: addOutputCurrentItem === output ? 'action.selected' : 'transparent',
                            borderBottom: '1px solid',
                            borderColor: 'divider',
                            opacity: isToDelete ? 0.6 : 1
                          }}
                        >
                          <ListItemButton
                            onClick={() => handleSelectCurrentItem(output)}
                            sx={{ flex: 1 }}
                            disabled={isToDelete}
                          >
                            <ListItemText
                              primary={
                                <Typography
                                  sx={{
                                    textDecoration: isToDelete ? 'line-through' : 'none',
                                    color: isToDelete ? 'text.secondary' : 'text.primary'
                                  }}
                                >
                                  {output.name}
                                </Typography>
                              }
                              secondary={
                                <Box>
                                  <Typography
                                    variant="body2"
                                    color="text.secondary"
                                    sx={{ textDecoration: isToDelete ? 'line-through' : 'none' }}
                                  >
                                    Active: {output.activeText}
                                  </Typography>
                                  <Typography
                                    variant="body2"
                                    color="text.secondary"
                                    sx={{ textDecoration: isToDelete ? 'line-through' : 'none' }}
                                  >
                                    Inactive: {output.inactiveText}
                                  </Typography>
                                </Box>
                              }
                            />
                          </ListItemButton>
                          <Box sx={{ px: 1, display: 'flex', gap: 1 }}>
                            {/* Delete Button */}
                            <Tooltip title={isToDelete ? "Restore from delete queue" : "Queue for deletion"}>
                              <Button
                                size="small"
                                variant={isToDelete ? "outlined" : "text"}
                                color={isToDelete ? "warning" : "error"}
                                onClick={() => handleQueueOutputForDelete(output)}
                                sx={{ minWidth: 60 }}
                              >
                                <DeleteIcon fontSize="small" />
                              </Button>
                            </Tooltip>

                            {/* Add Button - disabled if marked for deletion */}
                            {!isToDelete && (
                              isQueued ? (
                                <Tooltip title="Remove from add queue">
                                  <Button
                                    size="small"
                                    variant="outlined"
                                    color="warning"
                                    onClick={() => handleQueueOutputForAdd(output)}
                                    sx={{ minWidth: 80 }}
                                  >
                                    Queued
                                  </Button>
                                </Tooltip>
                              ) : (
                                <Tooltip title="Add this output to queue">
                                  <Button
                                    size="small"
                                    variant="contained"
                                    onClick={() => handleQueueOutputForAdd(output)}
                                    sx={{ minWidth: 80 }}
                                  >
                                    Add
                                  </Button>
                                </Tooltip>
                              )
                            )}
                          </Box>
                        </ListItem>
                      );
                    })}
                    {getUnusedOutputs().length === 0 && (
                      <ListItem>
                        <ListItemText
                          primary="No unused outputs available"
                          secondary="All outputs are already in use"
                        />
                      </ListItem>
                    )}
                  </List>
                  <Box sx={{ mt: 2 }}>
                    <Button
                      startIcon={<AddIcon />}
                      onClick={handleCreateNewOutputInAddDialog}
                      variant="outlined"
                      size="small"
                    >
                      Create New Output
                    </Button>
                  </Box>
                </Grid>

                {/* Right Panel - Output Editor */}
                <Grid item xs={6}>
                  <Divider orientation="vertical" flexItem sx={{ position: 'absolute', left: '50%', top: 0, bottom: 0 }} />
                  <Box sx={{ height: '100%', display: 'flex', flexDirection: 'column' }}>
                    {addOutputCurrentItem ? (
                      <Box sx={{ flexShrink: 0 }}>
                        <MachineOutputEditor
                          output={addOutputCurrentItem}
                          title={addOutputIsCreatingNew ? "Create New Output" : `Edit: ${addOutputCurrentItem?.name}`}
                        />
                      </Box>
                    ) : (
                      <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'center', height: 300 }}>
                        <Typography variant="body2" color="text.secondary" align="center">
                          Select an output from the list to view and edit its properties
                        </Typography>
                      </Box>
                    )}
                  </Box>
                </Grid>
              </Grid>
            </DialogContent>
            <DialogActions>
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, width: '100%' }}>
                <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.5 }}>
                  {addOutputQueuedItems.size > 0 && (
                    <Typography variant="body2" color="text.secondary">
                      {addOutputQueuedItems.size} output{addOutputQueuedItems.size > 1 ? 's' : ''} queued for addition
                    </Typography>
                  )}
                  {addOutputDeleteQueue.size > 0 && (
                    <Typography variant="body2" color="error.main">
                      {addOutputDeleteQueue.size} output{addOutputDeleteQueue.size > 1 ? 's' : ''} queued for deletion
                    </Typography>
                  )}
                  {addOutputQueuedItems.size === 0 && addOutputDeleteQueue.size === 0 && (
                    <Typography variant="body2" color="text.secondary">
                      No changes queued
                    </Typography>
                  )}
                </Box>
                <Box sx={{ ml: 'auto', display: 'flex', gap: 1 }}>
                  <Button onClick={handleCloseAddOutput}>Cancel</Button>
                  <Button
                    onClick={handleProcessQueuedOutputs}
                    variant="contained"
                    disabled={addOutputQueuedItems.size === 0 && addOutputDeleteQueue.size === 0}
                  >
                    Done
                  </Button>
                </Box>
              </Box>
            </DialogActions>
          </Dialog>
        </>
      )}
    />
  );
}
