import React from 'react';
import { Box, Typography, Button, Alert } from '@mui/material';
import { Warning as WarningIcon, Home as HomeIcon } from '@mui/icons-material';
import { WizardStep } from '../../../Wizard/WizardStep';
import { HomingProgressStep } from './HomingProgressStep';
import { ConfigurationData } from '../../../../data/ConfigurationData';

export class HomingPreparationStep extends WizardStep {
  getTitle(): string {
    return 'Prepare for Homing';
  }

  nextStep(): WizardStep | null {
    return new HomingProgressStep(this.wizard, this);
  }

  backStep(): WizardStep | null {
    return null; // First step
  }

  render(): React.ReactNode {
    return (
      <Box sx={{ p: 3, display: 'flex', flexDirection: 'column', gap: 3, minHeight: 400 }}>
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, mb: 2 }}>
          <WarningIcon sx={{ fontSize: 40, color: 'warning.main' }} />
          <Typography variant="h5" color="warning.main">
            Safety Check Required
          </Typography>
        </Box>

        <Alert severity="warning" sx={{ mb: 3 }}>
          <Typography variant="h6" gutterBottom>
            Before starting the homing sequence:
          </Typography>
        </Alert>

        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2, ml: 2 }}>
          <Typography variant="body1">
            ✓ <strong>Clear the work area:</strong> Remove all workpieces, tools, and clamps from the machine bed
          </Typography>
          <Typography variant="body1">
            ✓ <strong>Check spindle:</strong> Ensure the spindle is clear and no tool is loaded
          </Typography>
          <Typography variant="body1">
            ✓ <strong>Verify limits:</strong> Make sure all limit switches are functioning and accessible
          </Typography>
          <Typography variant="body1">
            ✓ <strong>Emergency stop:</strong> Ensure the emergency stop button is easily accessible
          </Typography>
        </Box>

        <Alert severity="info" sx={{ mt: 2 }}>
          <Typography variant="body2">
            The homing sequence will move all axes to their home positions. The machine will:
            <br />• Move Z-axis up to the upper limit
            <br />• Move X-axis to the lower limit  
            <br />• Move Y-axis to the lower limit
          </Typography>
        </Alert>

        <Box sx={{ display: 'flex', justifyContent: 'flex-end', gap: 2, mt: 'auto', pt: 3 }}>
          <Button
            variant="contained"
            size="large"
            onClick={() => this.wizard.advanceToNextStep()}
            startIcon={<HomeIcon />}
            sx={{ 
              backgroundColor: ConfigurationData.Instance.primaryColor,
              minWidth: 200,
              py: 1.5
            }}
          >
            Start Homing Sequence
          </Button>
        </Box>
      </Box>
    );
  }
}
