import { Output as OutputIcon } from '@mui/icons-material';
import { Box, TextField, Typography } from '@mui/material';
import React from 'react';
import { Machine } from '../../../../machine/Machine';
import { LogCategory, Logger } from '../../../../utils/Logger';
import { DataUtilities } from '../../../../utils/storage/DataUtilities';
import { FlowStep } from "../../../FlowStep";
import { FlowStepData } from "../../../FlowStepData";

export class IsOutputActiveStep extends FlowStep {
    readonly __type = 'IsOutputActiveStep';
    readonly category = ['Machine', 'IO'];
    readonly name = 'Is Output Active';
    readonly description = 'Checks if specific output is active';
    
    // Icon is created dynamically, not stored
    get icon(): React.ReactNode {
        return React.createElement(OutputIcon, { sx: { color: 'primary.main' } });
    }

    public outputNumber: number = 1;

    static readonly TRUE_PATH = 'true';
    static readonly FALSE_PATH = 'false';
    static readonly ERROR_PATH = 'error';

    async execute(data: FlowStepData, prototypeRun: boolean): Promise<string | null> {
        if (prototypeRun) {
            //Logger.Instance.log(LogCategory.System, `Prototype: Check output ${this.outputNumber}`);
            return Math.random() > 0.5 ? IsOutputActiveStep.TRUE_PATH : IsOutputActiveStep.FALSE_PATH;
        }

        try {
            const isActive = await Machine.getInstance().io.IsOutputActive(this.outputNumber);
            data.setVariable('outputActive', isActive);
            //Logger.Instance.log(LogCategory.System, `Output ${this.outputNumber} is ${isActive ? 'active' : 'inactive'}`);
            return isActive ? IsOutputActiveStep.TRUE_PATH : IsOutputActiveStep.FALSE_PATH;
        } catch (error) {
            Logger.Instance.logError(LogCategory.System, 'Check output failed:', error);
            return IsOutputActiveStep.ERROR_PATH;
        }
    }

    results(): string[] {
        return [IsOutputActiveStep.TRUE_PATH, IsOutputActiveStep.FALSE_PATH, IsOutputActiveStep.ERROR_PATH];
    }

    renderResultsUI(data: FlowStepData, result: string): React.ReactNode {
        return (
            <Typography variant="caption">
                Output {this.outputNumber}: {result}
            </Typography>
        );
    }

    renderEditUI(props: { onClose: () => void }): React.ReactNode {
        const EditUI = () => {
            const [outputNumber, setOutputNumber] = React.useState(this.outputNumber);

            // Update the instance when the local state changes
            React.useEffect(() => {
                this.outputNumber = outputNumber;
            }, [outputNumber]);

            return (
                <Box sx={{ p: 2, minWidth: 300 }}>
                    <TextField
                        label="Output Number"
                        type="number"
                        value={outputNumber}
                        onChange={(e) => setOutputNumber(parseInt(e.target.value) || 1)}
                        fullWidth
                        margin="normal"
                        inputProps={{ min: 1 }}
                    />
                </Box>
            );
        };

        return <EditUI />;
    }

    public toJSON(): any {
        const data = DataUtilities.getStorageData(this, ['icon']) as any;
        data.__type = this.__type;
        return data;
    }

    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data);
    }
}






