import {
  Box,
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  TextField,
  ToggleButton,
  ToggleButtonGroup,
  Typography,
} from '@mui/material';
import React, { useState } from 'react';
import { ConfigurationData } from '../../data/ConfigurationData';

interface FixtureNameInputDialogProps {
  open: boolean;
  onClose: () => void;
  onSave: (name: string, useCurrentLocation: boolean) => void;
  currentFixtureName: string;
  existingNames: string[];
}

export function FixtureNameInputDialog({
  open,
  onClose,
  onSave,
  currentFixtureName,
  existingNames
}: FixtureNameInputDialogProps) {
  const [name, setName] = useState('');
  const [error, setError] = useState('');
  const [useCurrentLocation, setUseCurrentLocation] = useState(true);

  const handleSave = () => {
    const trimmedName = name.trim();

    // Validation
    if (!trimmedName) {
      setError('Please enter a name for the fixture');
      return;
    }

    if (existingNames.includes(trimmedName)) {
      setError('This name is already used for this fixture number. Please choose a different name.');
      return;
    }

    onSave(trimmedName, useCurrentLocation);
    handleClose();
  };

  const handleClose = () => {
    setName('');
    setError('');
    setUseCurrentLocation(true);
    onClose();
  };

  const handleNameChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setName(event.target.value);
    // Clear error when user starts typing
    if (error) {
      setError('');
    }
  };

  const handleKeyPress = (event: React.KeyboardEvent) => {
    if (event.key === 'Enter') {
      handleSave();
    }
  };

  return (
    <Dialog open={open} onClose={handleClose} maxWidth="sm" fullWidth>
      <DialogTitle>Create Saved Point</DialogTitle>
      <DialogContent sx={{ pb: 2 }}>
        <Box sx={{ mb: 3 }}>
          <ToggleButtonGroup
            value={useCurrentLocation ? 'location' : 'fixture'}
            exclusive
            onChange={(_, newValue) => {
              if (newValue !== null) {
                setUseCurrentLocation(newValue === 'location');
              }
            }}
            fullWidth
            sx={{
              mb: 2,
              '& .MuiToggleButton-root': {
                color: ConfigurationData.Instance.mutedTextColor,
                backgroundColor: ConfigurationData.Instance.lightBackgroundColor,
                borderColor: ConfigurationData.Instance.borderColor,
                borderWidth: '2px',
                '&.Mui-selected': {
                  backgroundColor: ConfigurationData.Instance.primaryColor,
                  color: ConfigurationData.Instance.lightTextColor,
                  borderColor: ConfigurationData.Instance.primaryColor,
                  fontWeight: 'bold',
                  '&:hover': {
                    backgroundColor: ConfigurationData.Instance.primaryColor,
                  }
                },
                '&:hover': {
                  borderColor: ConfigurationData.Instance.primaryColor,
                  backgroundColor: ConfigurationData.Instance.lightBackgroundColor,
                }
              }
            }}
          >
            <ToggleButton value="fixture">
              Current Fixture Position
            </ToggleButton>
            <ToggleButton value="location">
              Current Machine Location
            </ToggleButton>
          </ToggleButtonGroup>

          <Typography variant="body2" color="text.secondary">
            {useCurrentLocation
              ? `Create a saved point at the current machine location.`
              : `Create a saved point using the position stored in fixture ${currentFixtureName}.`
            }
          </Typography>
        </Box>

        <TextField
          autoFocus
          margin="dense"
          label="Saved Point Name"
          fullWidth
          variant="outlined"
          value={name}
          onChange={handleNameChange}
          onKeyPress={handleKeyPress}
          error={!!error}
          helperText={error || 'Enter a unique name for this saved point'}
          placeholder="e.g., Top Left Corner, Center Position, etc."
          sx={{
            '& .MuiOutlinedInput-root': {
              backgroundColor: ConfigurationData.Instance.lightTextColor,
            }
          }}
        />
      </DialogContent>
      <DialogActions>
        <Button onClick={handleClose} variant="outlined">
          Cancel
        </Button>
        <Button
          onClick={handleSave}
          variant="contained"
          disabled={!name.trim()}
          sx={{ fontWeight: 'bold' }}
        >
          Create Saved Point
        </Button>
      </DialogActions>
    </Dialog>
  );
}
