import { MachineData } from '../data/MachineData';
import { Machine } from '../machine/Machine';
import { FlowStep } from './FlowStep';
import { FlowStepLibrary } from './FlowStepLibrary';
import { FlowStepRegistration } from './FlowStepRegistration';
import { FlowStepCategory, IFlowStepFactory } from './IFlowStepFactory';
import { CallFlowStep } from './steps/flows/CallFlowStep';
import { CheckInputStep } from './steps/machine/io/CheckInputStep';
import { CheckOutputStep } from './steps/machine/io/CheckOutputStep';
import { TurnOutputOffStep } from './steps/machine/io/TurnOutputOffStep';
import { TurnOutputOnStep } from './steps/machine/io/TurnOutputOnStep';

/**
 * Factory for creating flow steps and managing step categories
 * This is the single source of truth for all flow step information
 * Supports both static (registered) and dynamic (generated) steps
 */
export class FlowStepFactory implements IFlowStepFactory {
    private static instance: FlowStepFactory;
    private initialized = false;
    private categoryCache: Map<string, FlowStepCategory> = new Map();
    private registeredFlowStepTypes: Set<string> = new Set();

    private constructor() {
        // Don't initialize here - use lazy initialization when methods are called
    }

    /**
     * Get the singleton instance
     */
    public static get Instance(): FlowStepFactory {
        if (!FlowStepFactory.instance) {
            FlowStepFactory.instance = new FlowStepFactory();
        }
        return FlowStepFactory.instance;
    }

    /**
     * Ensure the factory is initialized
     */
    private ensureInitialized(): void {
        if (!this.initialized) {
            // Initialize the registration system (loads all static steps)
            FlowStepRegistration.initialize();

            // Register dynamic steps
            this.registerDynamicSteps();

            this.initialized = true;

            // Register flow steps asynchronously (don't block initialization)
            this.registerFlowSteps();
        }
    }

    /**
     * Register dynamically generated steps
     * These steps are created based on machine configuration
     */
    private registerDynamicSteps(): void {
        // Register input-specific steps
        this.registerInputSteps();

        // Register output-specific steps
        this.registerOutputSteps();
    }

    /**
     * Register a flow step for each machine input
     */
    private registerInputSteps(): void {
        const machineData = MachineData.Instance;
        const inputs = machineData.machineInputs;

        for (const input of inputs) {
            // Skip inputs without a name
            if (!input.name) {
                continue;
            }

            // Create a unique type name based on input name
            const typeName = `CheckInput_${input.name.replace(/\s+/g, '_')}`;

            // Capture the input name in closure
            const inputName = input.name;

            // Create a class that creates CheckInputStep and sets the input name
            const InputStepClass = class extends CheckInputStep {
                constructor() {
                    super();
                    this.setInputName(inputName);
                }
            };

            // Register it with the library
            FlowStepLibrary.registerStepType(typeName, InputStepClass);
        }
    }

    /**
     * Register flow steps for each machine output (3 steps per output)
     */
    private registerOutputSteps(): void {
        const machineData = MachineData.Instance;
        const outputs = machineData.machineOutputs;

        for (const output of outputs) {
            // Skip outputs without a name
            if (!output.name) {
                continue;
            }

            // Capture the output name in closure
            const outputName = output.name;
            const safeName = output.name.replace(/\s+/g, '_');

            // 1. Check if output is on step
            const CheckOutputStepClass = class extends CheckOutputStep {
                constructor() {
                    super();
                    this.setOutputName(outputName);
                }
            };
            FlowStepLibrary.registerStepType(`CheckOutput_${safeName}_IsOn`, CheckOutputStepClass);

            // 2. Turn output on step
            const TurnOnStepClass = class extends TurnOutputOnStep {
                constructor() {
                    super();
                    this.setOutputName(outputName);
                }
            };
            FlowStepLibrary.registerStepType(`TurnOutput_${safeName}_On`, TurnOnStepClass);

            // 3. Turn output off step
            const TurnOffStepClass = class extends TurnOutputOffStep {
                constructor() {
                    super();
                    this.setOutputName(outputName);
                }
            };
            FlowStepLibrary.registerStepType(`TurnOutput_${safeName}_Off`, TurnOffStepClass);
        }
    }

    /**
     * Register flow steps for each callable flow/MDI program
     * Only registers flows/MDI programs that have canBeCalledAsStep = true
     */
    private async registerFlowSteps(): Promise<void> {
        try {
            // Unregister all previously registered flow steps
            this.registeredFlowStepTypes.forEach(typeName => {
                FlowStepLibrary.unregisterStepType(typeName);
            });
            this.registeredFlowStepTypes.clear();

            // Get all storage items from the machine
            const allStorages = await Machine.getInstance().storage.getAllStorageNames();

            for (const storageName of allStorages) {
                const storage = await Machine.getInstance().storage.getStorageData(storageName);

                // Skip if not found or not marked as callable
                if (!storage || !storage.canBeCalledAsStep) {
                    continue;
                }

                // Create a unique type name based on flow name
                const typeName = `CallFlow_${storage.name.replace(/\s+/g, '_')}`;

                // Capture the flow name in closure
                const flowName = storage.name;

                // Create a class that creates CallFlowStep and sets the flow name
                const CallFlowStepClass = class extends CallFlowStep {
                    constructor() {
                        super();
                        this.setFlowName(flowName);
                    }
                };

                // Register it with the library and track it
                FlowStepLibrary.registerStepType(typeName, CallFlowStepClass);
                this.registeredFlowStepTypes.add(typeName);
            }
        } catch (error) {
            // If storage access fails during initialization, just skip flow steps
            // This can happen during early initialization before storage is ready
        }
    }

    /**
     * Public method to refresh callable flow steps
     * Call this when flows are added, removed, or their canBeCalledAsStep flag changes
     */
    public async refreshFlowSteps(): Promise<void> {
        await this.registerFlowSteps();
        // Clear category cache to force recalculation
        this.categoryCache.clear();
    }

    /**
     * Get the root categories (top-level categories)
     */
    public getRootCategories(): FlowStepCategory[] {
        this.ensureInitialized();
        const tree = this.buildCategoryTree();
        return tree.subcategories;
    }

    /**
     * Get subcategories for a given category path
     */
    public getSubcategories(categoryPath: string[]): FlowStepCategory[] {
        this.ensureInitialized();
        const tree = this.buildCategoryTree();
        const category = this.findCategory(tree, categoryPath);
        return category ? category.subcategories : [];
    }

    /**
     * Get all step types in a specific category (not including subcategories)
     */
    public getStepsInCategory(categoryPath: string[]): string[] {
        this.ensureInitialized();
        const allStepTypes = FlowStepLibrary.getAllStepTypes();
        const stepsInCategory: string[] = [];

        for (const typeName of allStepTypes) {
            const step = this.getStepByType(typeName);
            if (step && this.categoryMatches(step.category, categoryPath)) {
                stepsInCategory.push(typeName);
            }
        }

        return stepsInCategory;
    }

    /**
     * Get a step instance by its type name
     */
    public getStepByType(typeName: string): FlowStep | undefined {
        this.ensureInitialized();
        try {
            return FlowStepLibrary.createStep(typeName);
        } catch (error) {
            return undefined;
        }
    }

    /**
     * Get all registered step type names
     */
    public getAllStepTypes(): string[] {
        this.ensureInitialized();
        return FlowStepLibrary.getAllStepTypes();
    }

    /**
     * Get the complete category tree structure
     */
    public getCategoryTree(): FlowStepCategory {
        this.ensureInitialized();
        return this.buildCategoryTree();
    }

    /**
     * Build the complete category tree from all registered steps
     */
    private buildCategoryTree(): FlowStepCategory {
        const root: FlowStepCategory = {
            name: 'Root',
            path: [],
            subcategories: [],
            stepTypes: []
        };

        const allStepTypes = FlowStepLibrary.getAllStepTypes();
        console.log(`[FlowStepFactory] buildCategoryTree: Processing ${allStepTypes.length} step types`);

        let addedCount = 0;
        let skippedCannotAdd = 0;
        let skippedNoInstance = 0;

        for (const typeName of allStepTypes) {
            const step = this.getStepByType(typeName);
            if (!step) {
                console.log(`[FlowStepFactory] buildCategoryTree: Could not create instance for ${typeName}`);
                skippedNoInstance++;
                continue;
            }

            // Don't include steps that can't be added (like StartStep)
            if (step.canAdd === false) {
                skippedCannotAdd++;
                continue;
            }

            this.addStepToTree(root, step.category, typeName);
            addedCount++;
        }

        console.log(`[FlowStepFactory] buildCategoryTree: Added ${addedCount} steps, skipped ${skippedCannotAdd} (canAdd=false), ${skippedNoInstance} (no instance)`);

        // Sort categories and steps alphabetically
        this.sortCategoryTree(root);

        return root;
    }

    /**
     * Add a step to the category tree
     */
    private addStepToTree(root: FlowStepCategory, categoryPath: string[], stepType: string): void {
        let current = root;

        // Log factory-generated steps specifically
        if (stepType.includes('CheckInput_') || stepType.includes('CheckOutput_') || stepType.includes('TurnOutput_')) {
            console.log(`[FlowStepFactory] addStepToTree: Adding ${stepType} to category [${categoryPath.join(' > ')}]`);
        }

        for (let i = 0; i < categoryPath.length; i++) {
            const categoryName = categoryPath[i];
            const currentPath = categoryPath.slice(0, i + 1);

            let subcategory = current.subcategories.find(cat => cat.name === categoryName);

            if (!subcategory) {
                subcategory = {
                    name: categoryName,
                    path: currentPath,
                    subcategories: [],
                    stepTypes: []
                };
                current.subcategories.push(subcategory);
            }

            current = subcategory;
        }

        // Add the step type to the leaf category
        if (!current.stepTypes.includes(stepType)) {
            current.stepTypes.push(stepType);
        }
    }

    /**
     * Sort category tree alphabetically
     */
    private sortCategoryTree(category: FlowStepCategory): void {
        category.subcategories.sort((a, b) => a.name.localeCompare(b.name));
        category.stepTypes.sort();

        for (const subcategory of category.subcategories) {
            this.sortCategoryTree(subcategory);
        }
    }

    /**
     * Find a category by its path
     */
    private findCategory(root: FlowStepCategory, path: string[]): FlowStepCategory | undefined {
        if (path.length === 0) return root;

        let current = root;
        for (const segment of path) {
            const subcategory = current.subcategories.find(cat => cat.name === segment);
            if (!subcategory) return undefined;
            current = subcategory;
        }

        return current;
    }

    /**
     * Check if a step's category matches the given path exactly
     */
    private categoryMatches(stepCategory: string[], filterPath: string[]): boolean {
        if (stepCategory.length !== filterPath.length) return false;

        for (let i = 0; i < filterPath.length; i++) {
            if (stepCategory[i] !== filterPath[i]) return false;
        }

        return true;
    }

    /**
     * Force re-initialization (useful for testing or when machine configuration changes)
     */
    public reinitialize(): void {
        this.initialized = false;
        this.categoryCache.clear();
        FlowStepRegistration.forceReinitialize();
        this.ensureInitialized();
    }
}
