import { ToggleOn as OutputIcon } from '@mui/icons-material';
import { Box, Checkbox, FormControlLabel, TextField, Typography } from '@mui/material';
import React, { useState } from 'react';
import { Machine } from '../../../../machine/Machine';
import { DataUtilities } from '../../../../utils/storage/DataUtilities';
import { FlowStep } from "../../../FlowStep";
import { FlowStepData } from "../../../FlowStepData";

export class SetOutputStateStep extends FlowStep {
    readonly __type = 'SetOutputStateStep';
    readonly category = ['Machine', 'IO'];
    readonly name = 'Set Output State';
    readonly description = 'Sets the state of a specific output pin';
    
    // Icon is created dynamically, not stored
    get icon(): React.ReactNode {
        return React.createElement(OutputIcon, { sx: { color: 'primary.main' } });
    }

    // Step parameters
    public outputNumber: number = 1;
    public state: boolean = false;

    static readonly DONE_PATH = 'done';

    async execute(data: FlowStepData, prototypeRun: boolean): Promise<string | null> {
        if (prototypeRun) {
            return SetOutputStateStep.DONE_PATH;
        }

        try {
            await Machine.getInstance().io.SetOutputState(this.outputNumber, this.state);
            return SetOutputStateStep.DONE_PATH;
        } catch (error) {
            console.error('SetOutputState failed:', error);
            return SetOutputStateStep.DONE_PATH; // Still done, just with error logged
        }
    }

    results(): string[] {
        return [SetOutputStateStep.DONE_PATH];
    }

    renderResultsUI(data: FlowStepData, result: string): React.ReactNode {
        const stateText = this.state ? 'ON' : 'OFF';
        return (
            <Typography variant="caption">
                Set output {this.outputNumber} to {stateText}: {result}
            </Typography>
        );
    }

    renderEditUI(props: { onClose: () => void }): React.ReactNode {
        const SetOutputStateEditUI: React.FC = () => {
            const [outputNumber, setOutputNumber] = useState(this.outputNumber.toString());
            const [state, setState] = useState(this.state);

            // Update the instance when the local state changes
            React.useEffect(() => {
                this.outputNumber = parseInt(outputNumber) || 1;
                this.state = state;
            }, [outputNumber, state]);

            return (
                <Box sx={{ p: 2, minWidth: 300 }}>
                    <Typography variant="h6" gutterBottom>Set Output State</Typography>
                    <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                        Control the state of a specific digital output pin.
                    </Typography>

                    <TextField
                        label="Output Number"
                        type="number"
                        value={outputNumber}
                        onChange={(e) => setOutputNumber(e.target.value)}
                        fullWidth
                        margin="normal"
                        inputProps={{ min: 1, max: 32 }}
                        helperText="Output pin number (typically 1-32)"
                    />

                    <FormControlLabel
                        control={
                            <Checkbox
                                checked={state}
                                onChange={(e) => setState(e.target.checked)}
                                color="primary"
                            />
                        }
                        label={`Set output ${parseInt(outputNumber) || 1} ${state ? 'ON (High)' : 'OFF (Low)'}`}
                        sx={{ mt: 2 }}
                    />

                    <Box sx={{ mt: 2 }}>
                        <Typography variant="subtitle2" gutterBottom>Current Configuration:</Typography>
                        <Typography variant="body2" color="primary.main">
                            Output {parseInt(outputNumber) || 1}: {state ? 'ON (High/True)' : 'OFF (Low/False)'}
                        </Typography>
                    </Box>
                </Box>
            );
        };

        return React.createElement(SetOutputStateEditUI);
    }

    public toJSON(): any {
        const data = DataUtilities.getStorageData(this, ['icon']) as any;
        data.__type = this.__type;
        return data;
    }

    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data);
    }
}