import { MachineData } from "../../../data/MachineData";
import { HomingWizard } from "./HomingWizard";
import { ManualHomingWizard } from "./ManualHomingWizard";

/**
 * Singleton manager for homing wizards
 * Determines which wizard to show based on machine configuration
 */
export class HomingWizardManager {
    private static _instance: HomingWizardManager;

    private constructor() {
        // Private constructor to enforce singleton
    }

    public static get Instance(): HomingWizardManager {
        if (!HomingWizardManager._instance) {
            HomingWizardManager._instance = new HomingWizardManager();
        }
        return HomingWizardManager._instance;
    }

    /**
     * Show the appropriate homing wizard based on machine configuration
     * If manuallyHomeMachine is enabled, shows manual homing wizard
     * Otherwise, shows automatic homing wizard
     */
    public show(): void {
        if (MachineData.Instance.manuallyHomeMachine) {
            ManualHomingWizard.show();
        } else {
            HomingWizard.show();
        }
    }
}
