import { CheckCircle, Close, PlayArrow, Refresh } from '@mui/icons-material';
import {
  Alert,
  Box,
  Button,
  CircularProgress,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  IconButton,
  Paper,
  TextField,
  Typography
} from '@mui/material';
import { useEffect, useState } from 'react';

interface ApiInputDialogProps {
  open: boolean;
  title: string;
  methodId: string;
  defaultInputs: any;
  loading: boolean;
  error: string | null;
  result: any;
  executionTime?: number;
  onClose: () => void;
  onExecute: (inputs: any) => Promise<void>;
  onResetStats?: (methodId: string) => void;
}

export function ApiInputDialog({
  open,
  title,
  methodId,
  defaultInputs,
  loading,
  error,
  result,
  executionTime,
  onClose,
  onExecute,
  onResetStats
}: ApiInputDialogProps) {
  const [inputJson, setInputJson] = useState('');
  const [jsonError, setJsonError] = useState<string | null>(null);

  useEffect(() => {
    if (open && defaultInputs) {
      setInputJson(JSON.stringify(defaultInputs, null, 2));
      setJsonError(null);
    }
  }, [open, defaultInputs]);

  const handleInputChange = (value: string) => {
    setInputJson(value);
    try {
      JSON.parse(value);
      setJsonError(null);
    } catch (err) {
      setJsonError('Invalid JSON syntax');
    }
  };

  const handleExecute = async () => {
    if (defaultInputs === null) {
      // No parameters required, execute with null
      await onExecute(null);
    } else {
      try {
        const parsedInputs = JSON.parse(inputJson);
        await onExecute(parsedInputs);
      } catch (err) {
        setJsonError('Invalid JSON format');
      }
    }
  };

  const handleClose = () => {
    setInputJson(JSON.stringify(defaultInputs, null, 2));
    setJsonError(null);
    onClose();
  };

  return (
    <Dialog
      open={open}
      onClose={handleClose}
      maxWidth="xl"
      fullWidth
      PaperProps={{
        sx: {
          height: '90vh',
          backgroundColor: '#fafafa'
        }
      }}
    >
      {/* Header */}
      <DialogTitle sx={{ 
        backgroundColor: '#ffffff',
        borderBottom: '2px solid #e0e0e0',
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center',
        pb: 2
      }}>
        <Box>
          <Typography variant="h5" sx={{ fontWeight: 600, color: '#1565c0', mb: 0.5 }}>
            🔧 {title}
          </Typography>
          <Typography variant="body2" color="text.secondary">
            Customize parameters and execute API calls with live response monitoring
          </Typography>
        </Box>
        <IconButton onClick={handleClose} size="large" sx={{ color: '#666' }}>
          <Close />
        </IconButton>
      </DialogTitle>

      {/* Content - Split Layout */}
      <DialogContent sx={{ p: 0, height: '100%' }}>
        <Box sx={{ display: 'flex', height: '100%' }}>
          
          {/* Left Side - Input Parameters */}
          <Paper sx={{ 
            width: '50%',
            display: 'flex',
            flexDirection: 'column',
            borderRadius: 0,
            boxShadow: 'none',
            borderRight: '2px solid #e0e0e0'
          }}>
            {/* Input Header */}
            <Box sx={{ 
              p: 3,
              backgroundColor: '#1565c0',
              color: 'white'
            }}>
              <Typography variant="h6" sx={{ fontWeight: 600, mb: 1, display: 'flex', alignItems: 'center' }}>
                📝 Input Parameters
              </Typography>
              <Typography variant="body2" sx={{ opacity: 0.9 }}>
                Edit the JSON below to customize your API call parameters
              </Typography>
            </Box>

            {/* JSON Input */}
            <Box sx={{ flex: 1, p: 3, backgroundColor: '#ffffff' }}>
              {defaultInputs === null ? (
                // Show "No parameters required" message
                <Box sx={{ 
                  display: 'flex', 
                  flexDirection: 'column',
                  justifyContent: 'center', 
                  alignItems: 'center',
                  height: '100%',
                  textAlign: 'center',
                  backgroundColor: '#f8f9fa',
                  borderRadius: 2,
                  border: '2px dashed #d0d0d0'
                }}>
                  <Box sx={{ fontSize: '3rem', mb: 2, opacity: 0.5 }}>⚙️</Box>
                  <Typography variant="h6" sx={{ mb: 1, color: '#666' }}>
                    No Parameters Required
                  </Typography>
                  <Typography variant="body2" color="text.secondary">
                    This API method does not require any input parameters.<br/>
                    Click "Execute API Call" to run the method directly.
                  </Typography>
                </Box>
              ) : (
                // Show JSON input field
                <TextField
                  fullWidth
                  multiline
                  value={inputJson}
                  onChange={(e) => handleInputChange(e.target.value)}
                  variant="outlined"
                  error={!!jsonError}
                  helperText={jsonError}
                  placeholder="Enter JSON parameters..."
                  sx={{
                    height: '100%',
                    '& .MuiOutlinedInput-root': {
                      height: '100%',
                      backgroundColor: '#ffffff',
                      '& textarea': {
                        height: '100% !important',
                        fontFamily: '"Courier New", monospace',
                        fontSize: '14px',
                        lineHeight: 1.5,
                        color: '#1a1a1a !important',
                        backgroundColor: '#ffffff !important',
                        padding: '16px !important'
                      },
                      '& fieldset': {
                        borderColor: '#d0d0d0',
                        borderWidth: '2px'
                      },
                      '&:hover fieldset': {
                        borderColor: '#1565c0'
                      },
                      '&.Mui-focused fieldset': {
                        borderColor: '#1565c0',
                        borderWidth: '2px'
                      },
                      '&.Mui-error fieldset': {
                        borderColor: '#d32f2f'
                      }
                    }
                  }}
                />
              )}
            </Box>

            {/* Execute Button */}
            <Box sx={{ p: 3, backgroundColor: '#f5f5f5', borderTop: '1px solid #e0e0e0' }}>
              <Button
                variant="contained"
                size="large"
                startIcon={loading ? <CircularProgress size={16} sx={{ color: 'white' }} /> : <PlayArrow />}
                onClick={handleExecute}
                disabled={(defaultInputs !== null && !!jsonError) || loading}
                fullWidth
                sx={{
                  backgroundColor: '#4caf50',
                  color: 'white',
                  fontWeight: 600,
                  py: 1.5,
                  fontSize: '16px',
                  '&:hover': {
                    backgroundColor: '#45a049'
                  },
                  '&:disabled': {
                    backgroundColor: '#bdbdbd',
                    color: '#ffffff'
                  }
                }}
              >
                {loading ? 'Executing API Call...' : 'Execute API Call'}
              </Button>
            </Box>
          </Paper>

          {/* Right Side - Response */}
          <Paper sx={{ 
            width: '50%',
            display: 'flex',
            flexDirection: 'column',
            borderRadius: 0,
            boxShadow: 'none'
          }}>
            {/* Response Header */}
            <Box sx={{ 
              p: 3,
              backgroundColor: '#2e7d32',
              color: 'white'
            }}>
              <Typography variant="h6" sx={{ fontWeight: 600, mb: 1, display: 'flex', alignItems: 'center' }}>
                📊 API Response
              </Typography>
              <Typography variant="body2" sx={{ opacity: 0.9 }}>
                Real-time response from your API call will appear here
              </Typography>
            </Box>

            {/* Response Content */}
            <Box sx={{ flex: 1, p: 3, backgroundColor: '#f8f9fa', overflow: 'auto' }}>
              {/* Loading State */}
              {loading && (
                <Box sx={{ 
                  display: 'flex', 
                  flexDirection: 'column',
                  justifyContent: 'center', 
                  alignItems: 'center',
                  height: '100%',
                  textAlign: 'center'
                }}>
                  <CircularProgress size={48} sx={{ mb: 3, color: '#1565c0' }} />
                  <Typography variant="h6" sx={{ mb: 1, color: '#333' }}>
                    Executing API Call...
                  </Typography>
                  <Typography variant="body2" color="text.secondary">
                    Please wait while we process your request
                  </Typography>
                </Box>
              )}

              {/* Error State */}
              {error && (
                <Alert 
                  severity="error" 
                  sx={{ 
                    mb: 2,
                    fontSize: '14px',
                    '& .MuiAlert-message': {
                      width: '100%'
                    }
                  }}
                >
                  <Typography variant="body2">
                    <strong>❌ Request Failed:</strong><br/>
                    {error}
                  </Typography>
                </Alert>
              )}

              {/* Success State */}
              {(result !== undefined || executionTime !== undefined) && !loading && !error && (
                <Box>
                  {/* Success Header */}
                  <Box sx={{ 
                    mb: 3, 
                    p: 2, 
                    backgroundColor: '#e8f5e8', 
                    borderRadius: 2,
                    border: '2px solid #4caf50',
                    display: 'flex',
                    alignItems: 'center'
                  }}>
                    <CheckCircle sx={{ color: '#4caf50', mr: 1 }} />
                    <Box>
                      <Typography variant="body1" sx={{ color: '#2e7d32', fontWeight: 600 }}>
                        ✅ API Call Successful!
                      </Typography>
                      <Typography variant="caption" sx={{ color: '#666' }}>
                        Response Type: {typeof result} • Size: {result !== undefined ? JSON.stringify(result).length : 0} characters
                        {executionTime && ` • Executed in ${executionTime}ms`}
                      </Typography>
                    </Box>
                  </Box>
                  
                  {/* Response Data */}
                  <TextField
                    fullWidth
                    multiline
                    value={result !== undefined ? JSON.stringify(result, null, 2) : 'void (no return value)'}
                    variant="outlined"
                    InputProps={{ readOnly: true }}
                    sx={{
                      '& .MuiOutlinedInput-root': {
                        backgroundColor: '#ffffff',
                        '& textarea': {
                          fontFamily: '"Courier New", monospace',
                          fontSize: '13px',
                          lineHeight: 1.5,
                          color: '#1a1a1a !important',
                          backgroundColor: '#ffffff !important',
                          minHeight: '300px !important'
                        },
                        '& fieldset': {
                          borderColor: '#d0d0d0',
                          borderWidth: '2px'
                        }
                      }
                    }}
                  />
                </Box>
              )}

              {/* Empty State */}
              {result === undefined && executionTime === undefined && !loading && !error && (
                <Box sx={{ 
                  display: 'flex', 
                  flexDirection: 'column',
                  justifyContent: 'center', 
                  alignItems: 'center',
                  height: '100%',
                  textAlign: 'center',
                  color: '#999'
                }}>
                  <Box sx={{ fontSize: '5rem', mb: 2, opacity: 0.3 }}>⏳</Box>
                  <Typography variant="h6" sx={{ mb: 1, color: '#666' }}>
                    Ready to Execute
                  </Typography>
                  <Typography variant="body2" color="text.secondary">
                    Click the "Execute API Call" button to run your API call<br/>
                    and see the response data here
                  </Typography>
                </Box>
              )}
            </Box>
          </Paper>
        </Box>
      </DialogContent>

      {/* Footer */}
      <DialogActions sx={{ 
        p: 3, 
        backgroundColor: '#ffffff',
        borderTop: '2px solid #e0e0e0',
        justifyContent: 'space-between'
      }}>
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
          <Typography variant="body2" color="text.secondary" sx={{ fontStyle: 'italic' }}>
            🛠️ API Testing Tool • Real-time parameter editing and response monitoring
          </Typography>
          {onResetStats && (
            <Button
              onClick={() => onResetStats(methodId)}
              variant="outlined"
              color="warning"
              size="small"
              startIcon={<Refresh />}
              sx={{ minWidth: 120 }}
            >
              Reset Stats
            </Button>
          )}
        </Box>
        <Button 
          onClick={handleClose} 
          variant="outlined"
          size="large"
          sx={{ 
            minWidth: 120,
            borderWidth: '2px',
            '&:hover': {
              borderWidth: '2px'
            }
          }}
        >
          Close
        </Button>
      </DialogActions>
    </Dialog>
  );
}