import {
  Terminal as CommandIcon,
  AccountTree as FlowIcon,
  Code as GCodeIcon,
  Handyman as HandymanIcon,
  Home as HomeIcon,
  FlashOn as LaserIcon,
  Layers as LayersIcon,
  Hardware as MachineIcon,
  Settings as MillIcon,
  Build as ToolIcon,
  RotateRight as TurnIcon,
  HomeWork as UnhomeIcon,
  Air as VacuumIcon
} from '@mui/icons-material';
import { HomingWizardManager } from '../../components/wizards/homing';
import { BedSetupWizard, SpoilboardSetupWizard, WorkHomeZSetupWizard } from '../../components/wizards/touchoff';
import { UserMessageQueue } from '../../data/UserMessageQueue';
import { Machine } from '../../machine/Machine';
import { ConfirmDialogManager } from '../ConfirmDialogManager';
import { UserActionRegistry } from './UserActionRegistry';

/**
 * Registers all default user actions for the ActionsPanel
 */
export class DefaultUserActions {
  private static _initialized = false;
  private static _onViewChange?: (view: string) => void;

  /**
   * Initialize and register all default actions
   * @param onViewChange Callback for view changes (optional on first call)
   */
  public static initialize(onViewChange?: (view: string) => void): void {
    // Store the callback for use in actions
    if (onViewChange) {
      DefaultUserActions._onViewChange = onViewChange;
    }

    if (DefaultUserActions._initialized) {
      return;
    }

    const registry = UserActionRegistry.Instance;

    // Run Job actions
    registry.registerAction({
      id: 'run_job_mill',
      name: 'Mill',
      category: 'Run Job',
      icon: MillIcon,
      variant: 'contained',
      color: 'primary',
      run: () => DefaultUserActions._onViewChange?.('milling')
    });

    registry.registerAction({
      id: 'run_job_turn',
      name: 'Turn',
      category: 'Run Job',
      icon: TurnIcon,
      variant: 'outlined',
      color: 'primary',
      run: () => DefaultUserActions._onViewChange?.('turning')
    });

    registry.registerAction({
      id: 'run_job_laser',
      name: 'Laser',
      category: 'Run Job',
      icon: LaserIcon,
      variant: 'outlined',
      color: 'secondary',
      run: () => DefaultUserActions._onViewChange?.('laser')
    });

    // Measure Z actions
    registry.registerAction({
      id: 'measure_z_material_top',
      name: 'Material Top',
      category: 'Measure Z',
      icon: LayersIcon,
      variant: 'contained',
      color: 'primary',
      run: () => WorkHomeZSetupWizard.show()
    });

    registry.registerAction({
      id: 'measure_z_spoilboard',
      name: 'Spoilboard',
      category: 'Measure Z',
      icon: LayersIcon,
      variant: 'outlined',
      color: 'primary',
      run: () => SpoilboardSetupWizard.show()
    });

    registry.registerAction({
      id: 'measure_z_machine_bed',
      name: 'Machine Bed',
      category: 'Measure Z',
      icon: MachineIcon,
      variant: 'outlined',
      color: 'secondary',
      run: () => BedSetupWizard.show()
    });

    // Machine Homing actions
    registry.registerAction({
      id: 'machine_homing_home',
      name: 'Home Machine',
      category: 'Machine Homing',
      icon: HomeIcon,
      variant: 'contained',
      color: 'primary',
      run: () => HomingWizardManager.Instance.show()
    });

    registry.registerAction({
      id: 'machine_homing_unhome',
      name: 'Unhome Machine',
      category: 'Machine Homing',
      icon: UnhomeIcon,
      variant: 'outlined',
      color: 'warning',
      run: async () => {
        const confirmed = await ConfirmDialogManager.Instance.showConfirm({
          title: 'Unhome Machine',
          message: 'Are you sure you want to unhome the machine?\n\nThis will disable position tracking and require you to home the machine again before running any jobs.',
          confirmText: 'Yes, Unhome',
          severity: 'warning'
        });

        if (confirmed) {
          try {
            await Machine.getInstance().system.UnhomeMachine();
            UserMessageQueue.Instance.addMessage('✓ Machine unhomed successfully');
          } catch (error) {
            console.error('Failed to unhome machine:', error);
            UserMessageQueue.Instance.addMessage('❌ Failed to unhome machine');
          }
        }
      }
    });

    // Machine Controls actions
    registry.registerAction({
      id: 'machine_controls_dust_boot',
      name: 'Dust Boot',
      category: 'Machine Controls',
      icon: VacuumIcon,
      variant: 'contained',
      color: 'primary',
      run: () => UserMessageQueue.Instance.addMessage('🔧 Dust boot controls coming soon')
    });

    registry.registerAction({
      id: 'machine_controls_vacuum',
      name: 'Vacuum',
      category: 'Machine Controls',
      icon: VacuumIcon,
      variant: 'outlined',
      color: 'primary',
      run: () => UserMessageQueue.Instance.addMessage('🔧 Vacuum controls coming soon')
    });

    registry.registerAction({
      id: 'machine_controls_dust_collector',
      name: 'Dust Collector',
      category: 'Machine Controls',
      icon: VacuumIcon,
      variant: 'outlined',
      color: 'secondary',
      run: () => UserMessageQueue.Instance.addMessage('🔧 Dust collector controls coming soon')
    });

    // Tool Management actions
    registry.registerAction({
      id: 'tool_management_measure_tool',
      name: 'Measure Tool',
      category: 'Tool Management',
      icon: HandymanIcon,
      variant: 'contained',
      color: 'secondary',
      run: () => UserMessageQueue.Instance.addMessage('🔧 Tool measurement coming soon')
    });

    registry.registerAction({
      id: 'tool_management_edit_tools',
      name: 'Edit Tools',
      category: 'Tool Management',
      icon: ToolIcon,
      variant: 'outlined',
      color: 'secondary',
      run: () => UserMessageQueue.Instance.addMessage('🔧 Tool editor coming soon')
    });

    // Custom Routines actions
    registry.registerAction({
      id: 'custom_routines_flow',
      name: 'Flow',
      category: 'Custom Routines',
      icon: FlowIcon,
      variant: 'contained',
      color: 'primary',
      run: () => DefaultUserActions._onViewChange?.('flow')
    });

    registry.registerAction({
      id: 'custom_routines_gcode',
      name: 'G-Code',
      category: 'Custom Routines',
      icon: GCodeIcon,
      variant: 'outlined',
      color: 'primary',
      run: () => UserMessageQueue.Instance.addMessage('🔧 G-Code editor coming soon')
    });

    registry.registerAction({
      id: 'custom_routines_commands',
      name: 'Commands',
      category: 'Custom Routines',
      icon: CommandIcon,
      variant: 'outlined',
      color: 'secondary',
      run: () => UserMessageQueue.Instance.addMessage('🔧 Command interface coming soon')
    });

    DefaultUserActions._initialized = true;
  }

  /**
   * Reset initialization state (useful for testing)
   */
  public static reset(): void {
    DefaultUserActions._initialized = false;
  }
}
