import React from 'react';
import { MachineStateData } from '../../../data/MachineStateData';
import { CoordinateUtil } from '../../../utils/CoordinateUtil';
import { ObserveMultiProperties } from '../../../utils/statemanager/ObserveMultiProperties';
import { Vector3, BufferGeometry, LineBasicMaterial, Line } from 'three';

export interface DragLineProps {
  machineState: MachineStateData;
}

export function DragLine({ machineState }: DragLineProps) {
  return (
    <ObserveMultiProperties
      listenTo={[
        { object: machineState, properties: ['currentMachinePoint', 'proposedSpindlePosition'] }
      ]}
      control={() => {
        // Only render if there's a proposed spindle position (drag in progress)
        if (!machineState.proposedSpindlePosition) {
          return null;
        }

        // Convert both positions to simulator coordinates
        const currentSimulatorPos = CoordinateUtil.toSimulator(machineState.currentMachinePoint);
        const proposedSimulatorPos = CoordinateUtil.toSimulator(machineState.proposedSpindlePosition);

        // Create points for the line
        const points = [
          new Vector3(currentSimulatorPos.x, currentSimulatorPos.y, currentSimulatorPos.z),
          new Vector3(proposedSimulatorPos.x, proposedSimulatorPos.y, proposedSimulatorPos.z)
        ];

        // Create buffer geometry from points
        const geometry = new BufferGeometry().setFromPoints(points);
        const material = new LineBasicMaterial({ color: 'black', linewidth: 6 });

        // Create the THREE.Line object
        const line = new Line(geometry, material);

        return (
          <primitive object={line} />
        );
      }}
    />
  );
}
