import { Build as ToolIcon } from '@mui/icons-material';
import { Typography } from '@mui/material';
import React from 'react';
import { Machine } from '../../../../machine/Machine';
import { LogCategory, Logger } from '../../../../utils/Logger';
import { DataUtilities } from '../../../../utils/storage/DataUtilities';
import { FlowStep } from "../../../FlowStep";
import { FlowStepData } from "../../../FlowStepData";

export class MeasureAllToolsStep extends FlowStep {
    readonly __type = 'MeasureAllToolsStep';
    readonly category = ['Machine', 'Features'];
    readonly name = 'Measure All Tools';
    readonly description = 'Measures the length of all tools in the tool library';
    
    // Icon is created dynamically, not stored
    get icon(): React.ReactNode {
        return React.createElement(ToolIcon, { sx: { color: 'warning.main' } });
    }

    static readonly DONE_PATH = 'done';

    async execute(data: FlowStepData, prototypeRun: boolean): Promise<string | null> {
        if (prototypeRun) {
            //Logger.Instance.log(LogCategory.System, 'Prototype: Measure all tools');
            return MeasureAllToolsStep.DONE_PATH;
        }

        try {
            await Machine.getInstance().features.MeasureAllTools();
            //Logger.Instance.log(LogCategory.System, 'All tools measured');
            return MeasureAllToolsStep.DONE_PATH;
        } catch (error) {
            Logger.Instance.logError(LogCategory.System, 'Measure all tools failed:', error);
            return MeasureAllToolsStep.DONE_PATH; // Still done, just with error logged
        }
    }

    results(): string[] {
        return [MeasureAllToolsStep.DONE_PATH];
    }

    renderResultsUI(data: FlowStepData, result: string): React.ReactNode {
        return (
            <Typography variant="caption">
                Measure all tools: {result}
            </Typography>
        );
    }

    public toJSON(): any {
        const data = DataUtilities.getStorageData(this, ['icon']) as any;
        data.__type = this.__type;
        return data;
    }

    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data);
    }
}





