import React, { useState } from 'react';
import { 
  Typography, 
  Box, 
  Button, 
  Stepper, 
  Step, 
  StepLabel, 
  StepButton,
  Paper
} from '@mui/material';
import { GCodeStage } from './Milling/GCodeStage';
import { MaterialStage } from './Milling/MaterialStage';
import { ClampsStage } from './Milling/ClampsStage';
import { ToolStage } from './Milling/ToolStage';
import { AnalyzeStage } from './Milling/AnalyzeStage';
import { RunStage } from './Milling/RunStage';
import { MachineStateData } from '../../data/MachineStateData';
import { ObserveState } from '../../utils/statemanager/ObserveState';

const stages = ['GCode', 'Material', 'Clamps', 'Tool', 'Analyze', 'Run'];

export const Milling: React.FC = () => {
  const [activeStep, setActiveStep] = useState(0);
  const [completedSteps, setCompletedSteps] = useState<Set<number>>(new Set());

  const handleStepClick = (step: number) => {
    // Can only go back to completed steps or current step
    if (step <= Math.max(...Array.from(completedSteps), -1) + 1) {
      setActiveStep(step);
      // Remove completion status from steps after the clicked step
      if (step < activeStep) {
        const newCompleted = new Set(Array.from(completedSteps).filter(s => s < step));
        setCompletedSteps(newCompleted);
      }
    }
  };

  const handleNext = () => {
    // Call the moving to next callback for the current step
    handleMovingToNext(activeStep);
    
    // Mark current step as completed and move to next
    const newCompleted = new Set(completedSteps);
    newCompleted.add(activeStep);
    setCompletedSteps(newCompleted);
    
    if (activeStep < stages.length - 1) {
      setActiveStep(activeStep + 1);
    }
  };

  const handleBack = () => {
    if (activeStep > 0) {
      const newStep = activeStep - 1;
      setActiveStep(newStep);
      // Remove completion status from steps after the new step
      const newCompleted = new Set(Array.from(completedSteps).filter(s => s < newStep));
      setCompletedSteps(newCompleted);
    }
  };

  const isStepCompleted = (step: number) => {
    return completedSteps.has(step);
  };

  const isStepClickable = (step: number) => {
    // Can click on completed steps or the next available step
    return step <= Math.max(...Array.from(completedSteps), -1) + 1;
  };

  // Callback for stages to customize the next step behavior
  const handleMovingToNext = (step: number) => {
    //console.log(`📝 Moving to next from step ${step}:`, stages[step]);
    
    // Handle specific step logic
    if (step === 0) { // GCode stage
      const machineState = MachineStateData.Instance;
      if (machineState.proposedJob) {
        //console.log(`📝 Committing proposed job: ${machineState.proposedJob.name}`);
        // Store current job as last job before replacing
        if (machineState.currentJob) {
          machineState.lastJob = machineState.currentJob;
        }
        
        // Set the proposed job as current
        machineState.currentJob = machineState.proposedJob;
        
        // Clear the proposed job since it's now current
        machineState.proposedJob = undefined;
      }
    }
  };

  // Callback for stages to customize the next button text
  const getNextStepName = (step: number) => {
    if (step === stages.length - 1) {
      return 'Finish';
    } else if (step === 0 && MachineStateData.Instance.proposedJob) {
      return 'Use This File';
    } else {
      return 'Next';
    }
  };

  const renderStageContent = () => {
    const stageProps = {
      onMovingToNext: () => handleMovingToNext(activeStep),
      getNextStepName: () => getNextStepName(activeStep)
    };
    
    switch (activeStep) {
      case 0:
        return <GCodeStage {...stageProps} />;
      case 1:
        return <MaterialStage {...stageProps} />;
      case 2:
        return <ClampsStage {...stageProps} />;
      case 3:
        return <ToolStage {...stageProps} />;
      case 4:
        return <AnalyzeStage {...stageProps} />;
      case 5:
        return <RunStage {...stageProps} />;
      default:
        return <GCodeStage {...stageProps} />;
    }
  };

  return (
    <Box sx={{ height: '100%', display: 'flex', flexDirection: 'column' }}>
      {/* Header with Stage Navigation */}
      <Paper sx={{ p: 3, mb: 2, borderRadius: 0, borderBottom: 1, borderColor: 'divider' }}>
        <Box sx={{ px: 3 }}>
          <Stepper activeStep={activeStep} alternativeLabel>
            {stages.map((label, index) => (
              <Step key={label} completed={isStepCompleted(index)}>
                <StepButton
                  onClick={() => handleStepClick(index)}
                  disabled={!isStepClickable(index)}
                  sx={{
                    '& .MuiStepLabel-root': {
                      cursor: isStepClickable(index) ? 'pointer' : 'default',
                    },
                    '& .MuiStepLabel-label': {
                      fontSize: '1rem',
                      fontWeight: activeStep === index ? 'bold' : 'normal',
                    }
                  }}
                >
                  <StepLabel>{label}</StepLabel>
                </StepButton>
              </Step>
            ))}
          </Stepper>
        </Box>
      </Paper>

      {/* Stage Content */}
      <Box sx={{ flex: 1, overflow: 'auto' }}>
        <Box sx={{ px: 3, py: 3, height: '100%' }}>
          {renderStageContent()}
        </Box>
      </Box>

      {/* Navigation Buttons */}
      <Paper sx={{ p: 2, borderRadius: 0, borderTop: 1, borderColor: 'divider' }}>
        <Box sx={{ px: 3 }}>
          <ObserveState
            listenTo={MachineStateData.Instance}
            properties={['proposedJob']}
            control={() => {
              return (
                <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <Button
                    variant="outlined"
                    onClick={handleBack}
                    disabled={activeStep === 0}
                  >
                    Back
                  </Button>
                  
                  <Typography variant="body2" color="text.secondary">
                    Step {activeStep + 1} of {stages.length}: {stages[activeStep]}
                  </Typography>
                  
                  <Button
                    variant="contained"
                    onClick={handleNext}
                    disabled={activeStep === stages.length - 1 && completedSteps.has(activeStep)}
                  >
                    {getNextStepName(activeStep)}
                  </Button>
                </Box>
              );
            }}
          />
        </Box>
      </Paper>
    </Box>
  );
};
