import { Search as SearchIcon } from '@mui/icons-material';
import { Typography } from '@mui/material';
import React from 'react';
import { Machine } from '../../../../machine/Machine';
import { DataUtilities } from '../../../../utils/storage/DataUtilities';
import { FlowStep } from "../../../FlowStep";
import { FlowStepData } from "../../../FlowStepData";

export class CheckToolStep extends FlowStep {
    readonly __type = 'CheckToolStep';
    readonly category = ['Machine', 'Features'];
    readonly name = 'Check Tool';
    readonly description = 'Checks if a tool is properly loaded';
    
    // Icon is created dynamically, not stored
    get icon(): React.ReactNode {
        return React.createElement(SearchIcon, { sx: { color: 'info.main' } });
    }

    static readonly DONE_PATH = 'done';

    async execute(data: FlowStepData, prototypeRun: boolean): Promise<string | null> {
        if (prototypeRun) {
            return CheckToolStep.DONE_PATH;
        }

        try {
            await Machine.getInstance().features.CheckTool();
            return CheckToolStep.DONE_PATH;
        } catch (error) {
            console.error('CheckTool failed:', error);
            return CheckToolStep.DONE_PATH;
        }
    }

    results(): string[] {
        return [CheckToolStep.DONE_PATH];
    }

    renderResultsUI(data: FlowStepData, result: string): React.ReactNode {
        return (
            <Typography variant="caption">
                Check tool: {result}
            </Typography>
        );
    }

    public toJSON(): any {
        const data = DataUtilities.getStorageData(this, ['icon']) as any;
        data.__type = this.__type;
        return data;
    }

    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data);
    }
}






