import {
    Box,
    CircularProgress,
    Paper,
    Typography
} from '@mui/material';
import React from 'react';
import { ConfigurationData } from '../data/ConfigurationData';
import { Machine } from '../machine/Machine';
import { LogCategory, Logger } from '../utils/Logger';

interface ConnectionSplashScreenProps {
    onConnected: () => void;
}

/**
 * ConnectionSplashScreen displays while waiting for server connection
 * Continuously polls IsConnectedToServer until connection is established
 */
export function ConnectionSplashScreen({ onConnected }: ConnectionSplashScreenProps) {
    const config = ConfigurationData.Instance;
    const [attempts, setAttempts] = React.useState(0);
    const checkIntervalRef = React.useRef<NodeJS.Timeout | null>(null);

    React.useEffect(() => {
        let isMounted = true;

        const checkConnection = async () => {
            try {
                const attemptNumber = attempts + 1;
                setAttempts(attemptNumber);
                
                console.log(`[ConnectionSplashScreen] Attempt #${attemptNumber} - Starting connection check...`);
                Logger.Instance.log(LogCategory.System, `Connection check attempt #${attemptNumber}`);
                
                const machine = Machine.getInstance();
                console.log('[ConnectionSplashScreen] Got machine instance:', machine);
                
                console.log('[ConnectionSplashScreen] Calling machine.system.IsConnectedToServer()...');
                const isConnected = await machine.system.IsConnectedToServer();
                console.log(`[ConnectionSplashScreen] IsConnectedToServer() returned:`, isConnected);
                Logger.Instance.log(LogCategory.System, `Connection status: ${isConnected}`);

                if (isConnected && isMounted) {
                    console.log('[ConnectionSplashScreen] ✅ Connection established! Calling onConnected()');
                    Logger.Instance.log(LogCategory.System, 'Server connection established');
                    // Clear interval and notify parent
                    if (checkIntervalRef.current) {
                        clearInterval(checkIntervalRef.current);
                        checkIntervalRef.current = null;
                    }
                    onConnected();
                } else {
                    console.log(`[ConnectionSplashScreen] ❌ Not connected yet (isConnected=${isConnected}, isMounted=${isMounted})`);
                }
            } catch (error) {
                console.error('[ConnectionSplashScreen] ❌ Error during connection check:', error);
                Logger.Instance.logError(LogCategory.System, 'Error checking server connection:', error);
            }
        };

        // Initial check
        checkConnection();

        // Set up polling interval (check every 2 seconds)
        checkIntervalRef.current = setInterval(checkConnection, 2000);

        // Cleanup
        return () => {
            isMounted = false;
            if (checkIntervalRef.current) {
                clearInterval(checkIntervalRef.current);
                checkIntervalRef.current = null;
            }
        };
    }, [onConnected]);

    return (
        <Box
            sx={{
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'center',
                justifyContent: 'center',
                height: '100vh',
                backgroundColor: config.lightBackgroundColor,
                padding: 3
            }}
        >
            <Paper
                elevation={8}
                sx={{
                    padding: 6,
                    borderRadius: 4,
                    textAlign: 'center',
                    maxWidth: 500,
                    width: '100%',
                    backgroundColor: config.darkBackgroundColor,
                    color: config.lightTextColor
                }}
            >
                {/* App Title */}
                <Typography
                    variant="h3"
                    component="h1"
                    gutterBottom
                    sx={{
                        color: config.primaryColor,
                        fontWeight: 'bold',
                        marginBottom: 3
                    }}
                >
                    HavenCNC
                </Typography>

                {/* Loading Spinner */}
                <CircularProgress
                    size={60}
                    sx={{
                        color: config.primaryColor,
                        marginBottom: 3
                    }}
                />

                {/* Connection Status */}
                <Typography
                    variant="h6"
                    sx={{
                        color: config.lightTextColor,
                        marginBottom: 1
                    }}
                >
                    Connecting to Server...
                </Typography>

                <Typography
                    variant="body2"
                    sx={{
                        color: config.mutedTextColor,
                        marginBottom: 2
                    }}
                >
                    Attempting to establish connection
                </Typography>

                {/* Attempt Counter */}
                {attempts > 5 && (
                    <Typography
                        variant="caption"
                        sx={{
                            color: config.mutedTextColor,
                            fontStyle: 'italic'
                        }}
                    >
                        Connection attempts: {attempts}
                    </Typography>
                )}
            </Paper>

            {/* Version Info */}
            <Typography
                variant="caption"
                sx={{
                    color: config.mutedTextColor,
                    marginTop: 3,
                    textAlign: 'center'
                }}
            >
                CNC Machine Control Interface
                <br />
                Waiting for server connection...
            </Typography>
        </Box>
    );
}
