import { IMachineInterface } from '../machine/Machine';
import { SimulatorCNCFeatures } from './SimulatorCNCFeatures';
import { SimulatorCNCIO } from './SimulatorCNCIO';
import { SimulatorCNCMovement } from './SimulatorCNCMovement';
import { SimulatorCNCProgram } from './SimulatorCNCProgram';
import { SimulatorCNCProgramStorage } from './SimulatorCNCProgramStorage';
import { SimulatorCNCSetup } from './SimulatorCNCSetup';
import { SimulatorCNCSpindle } from './SimulatorCNCSpindle';
import { SimulatorCNCSystem } from './SimulatorCNCSystem';

/**
 * Composite simulator machine interface that exposes specialized sub-interfaces
 * All method implementations are in the individual sub-interface classes
 */
export class SimulatorMachineInterface implements IMachineInterface {
  public readonly system: SimulatorCNCSystem;
  public readonly movement: SimulatorCNCMovement;
  public readonly spindle: SimulatorCNCSpindle;
  public readonly program: SimulatorCNCProgram;
  public readonly features: SimulatorCNCFeatures;
  public readonly io: SimulatorCNCIO;
  public readonly setup: SimulatorCNCSetup;
  public readonly storage: SimulatorCNCProgramStorage;

  constructor() {
    this.system = new SimulatorCNCSystem();
    this.movement = new SimulatorCNCMovement();
    this.spindle = new SimulatorCNCSpindle();
    this.program = new SimulatorCNCProgram();
    this.features = new SimulatorCNCFeatures();
    this.io = new SimulatorCNCIO();
    this.setup = new SimulatorCNCSetup();
    this.storage = new SimulatorCNCProgramStorage();
  }
}
