import {
    Box,
    Button,
    Dialog,
    DialogActions,
    DialogContent,
    DialogTitle,
    List,
    ListItemButton,
    ListItemText,
    TextField,
    Typography
} from '@mui/material';
import { useState } from 'react';
import { ConfigurationData } from '../../data/ConfigurationData';
import { Tool } from '../../data/Common/Tool';
import { ToolLibrary } from '../../data/Common/ToolLibrary';
import { MachineStateData } from '../../data/MachineStateData';
import { ObserveState } from '../../utils/statemanager/ObserveState';

interface ToolSelectionDialogProps {
    open: boolean;
    onClose: () => void;
}

export function ToolSelectionDialog({ open, onClose }: ToolSelectionDialogProps) {
    const [config] = useState(() => ConfigurationData.Instance);
    const [toolLibrary] = useState(() => ToolLibrary.Instance);
    const [machineState] = useState(() => MachineStateData.Instance);
    const [searchText, setSearchText] = useState('');
    const [selectedToolNumber, setSelectedToolNumber] = useState<number | null>(null);

    const handleSelectTool = () => {
        if (selectedToolNumber !== null) {
            machineState.currentToolNumber = selectedToolNumber;
            onClose();
        }
    };

    const handleClose = () => {
        setSearchText('');
        setSelectedToolNumber(null);
        onClose();
    };

    return (
        <Dialog
            open={open}
            onClose={handleClose}
            maxWidth="md"
            fullWidth
            PaperProps={{
                sx: {
                    backgroundColor: config.darkBackgroundColor,
                    color: config.lightTextColor
                }
            }}
        >
            <DialogTitle sx={{ borderBottom: `1px solid ${config.borderColor}` }}>
                <Typography variant="h6" sx={{ fontWeight: 'bold' }}>
                    Select Tool
                </Typography>
            </DialogTitle>

            <DialogContent sx={{ p: 2 }}>
                <ObserveState
                    key="tool-selection-dialog-content"
                    listenTo={machineState}
                    properties={['currentToolNumber']}
                    control={() => {
                        const currentToolNumber = machineState.currentToolNumber;
                        const availableTools: Tool[] = toolLibrary.tools;

                        // Filter tools based on search
                        const filteredTools = availableTools.filter(tool => {
                            if (!searchText) return true;
                            const searchLower = searchText.toLowerCase();
                            return (
                                tool.toolNumber.toString().includes(searchText) ||
                                tool.displayName.toLowerCase().includes(searchLower)
                            );
                        });

                        return (
                            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
                                {/* Search field */}
                                <TextField
                                    fullWidth
                                    label="Search Tools"
                                    value={searchText}
                                    onChange={(e) => setSearchText(e.target.value)}
                                    placeholder="Search by number, name, or description"
                                    autoFocus
                                    sx={{
                                        '& .MuiInputBase-root': {
                                            backgroundColor: config.lightBackgroundColor
                                        }
                                    }}
                                />

                                {/* Tool list */}
                                <Box
                                    sx={{
                                        border: `1px solid ${config.borderColor}`,
                                        borderRadius: 1,
                                        maxHeight: '400px',
                                        overflow: 'auto'
                                    }}
                                >
                                    <List sx={{ p: 0 }}>
                                        {filteredTools.length === 0 ? (
                                            <Box sx={{ p: 3, textAlign: 'center' }}>
                                                <Typography variant="body2" color="text.secondary">
                                                    No tools found
                                                </Typography>
                                            </Box>
                                        ) : (
                                            filteredTools.map((tool) => {
                                                const isSelected = selectedToolNumber === tool.toolNumber;
                                                const isCurrent = tool.toolNumber === currentToolNumber;

                                                return (
                                                    <ListItemButton
                                                        key={tool.toolNumber}
                                                        selected={isSelected}
                                                        onClick={() => setSelectedToolNumber(tool.toolNumber)}
                                                        sx={{
                                                            borderBottom: `1px solid ${config.borderColor}`,
                                                            backgroundColor: isCurrent
                                                                ? `${config.primaryColor}22`
                                                                : undefined,
                                                            '&.Mui-selected': {
                                                                backgroundColor: `${config.primaryColor}44`,
                                                                '&:hover': {
                                                                    backgroundColor: `${config.primaryColor}55`
                                                                }
                                                            }
                                                        }}
                                                    >
                                                        <ListItemText
                                                            primary={
                                                                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                                                                    <Typography
                                                                        variant="body1"
                                                                        sx={{
                                                                            fontWeight: 'bold',
                                                                            color: config.primaryColor
                                                                        }}
                                                                    >
                                                                        T{tool.toolNumber.toString().padStart(2, '0')}
                                                                    </Typography>
                                                                    <Typography variant="body1" sx={{ fontWeight: 'bold' }}>
                                                                        {tool.displayName}
                                                                    </Typography>
                                                                    {isCurrent && (
                                                                        <Typography
                                                                            variant="caption"
                                                                            sx={{
                                                                                color: config.successColor,
                                                                                fontWeight: 'bold',
                                                                                ml: 1
                                                                            }}
                                                                        >
                                                                            (Current)
                                                                        </Typography>
                                                                    )}
                                                                </Box>
                                                            }
                                                            secondary={
                                                                <Typography variant="body2" color="text.secondary">
                                                                    {tool.cuttingDiameter.toFixed(3)}" Ø - {tool.cutterType}
                                                                </Typography>
                                                            }
                                                        />
                                                    </ListItemButton>
                                                );
                                            })
                                        )}
                                    </List>
                                </Box>
                            </Box>
                        );
                    }}
                />
            </DialogContent>

            <DialogActions sx={{ borderTop: `1px solid ${config.borderColor}`, p: 2, gap: 1 }}>
                <Button
                    onClick={handleClose}
                    variant="outlined"
                >
                    Cancel
                </Button>
                <Button
                    onClick={handleSelectTool}
                    variant="contained"
                    disabled={selectedToolNumber === null}
                    sx={{ fontWeight: 'bold' }}
                >
                    Select Tool
                </Button>
            </DialogActions>
        </Dialog>
    );
}
