import {
  AccountTree as FlowIcon,
  Home as HomeIcon,
  FlashOn as LaserIcon,
  School as LearningIcon,
  Terminal as MDIIcon,
  Build as MillingIcon,
  Settings as SettingsIcon,
  AdminPanelSettings as SystemIcon,
  Rotate90DegreesCcw as TurningIcon,
  Visibility as ViewerIcon,
} from '@mui/icons-material';
import {
  Box,
  ListItemButton,
  Typography,
} from '@mui/material';
import React from 'react';

interface LeftNavigationProps {
  selectedView: string;
  onViewChange: (view: string) => void;
}

interface NavigationItem {
  id: string;
  label: string;
  icon: React.ComponentType;
}

const navigationItems: NavigationItem[] = [
  { id: 'home', label: 'Home', icon: HomeIcon },
  { id: 'viewer', label: 'Viewer', icon: ViewerIcon },
  { id: 'learning', label: 'Learning', icon: LearningIcon },
  { id: 'flow', label: 'Flow', icon: FlowIcon },
  { id: 'mdi', label: 'MDI', icon: MDIIcon },
  { id: 'milling', label: 'Milling', icon: MillingIcon },
  { id: 'turning', label: 'Turning', icon: TurningIcon },
  { id: 'laser', label: 'Laser', icon: LaserIcon },
  { id: 'settings', label: 'Settings', icon: SettingsIcon },
  { id: 'system', label: 'Config', icon: SystemIcon },
];

export function LeftNavigation({ selectedView, onViewChange }: LeftNavigationProps) {
  return (
    <Box sx={{ height: '100%', display: 'flex', flexDirection: 'column' }}>
      {/* Navigation Items */}
      <Box sx={{ flexGrow: 1, p: 1 }}>
        {navigationItems.map((item) => {
          const IconComponent = item.icon;
          const isSelected = selectedView === item.id;

          return (
            <Box key={item.id} sx={{ mb: 1 }}>
              <ListItemButton
                selected={isSelected}
                onClick={() => onViewChange(item.id)}
                sx={{
                  width: 75,
                  height: 75,
                  borderRadius: 1,
                  display: 'flex',
                  flexDirection: 'column',
                  alignItems: 'center',
                  justifyContent: 'center',
                  bgcolor: isSelected ? 'rgba(0, 0, 0, 0.02)' : 'transparent',
                  border: isSelected ? '1px solid' : '1px solid transparent',
                  borderColor: isSelected ? 'secondary.main' : 'transparent',
                  color: isSelected ? 'secondary.main' : 'text.primary',
                  '&:hover': {
                    bgcolor: isSelected ? 'rgba(0, 0, 0, 0.04)' : 'action.hover',
                    borderColor: isSelected ? 'secondary.dark' : 'transparent',
                  },
                  '&.Mui-selected': {
                    bgcolor: 'rgba(0, 0, 0, 0.02)',
                    border: '1px solid',
                    borderColor: 'secondary.main',
                    color: 'secondary.main',
                    '&:hover': {
                      bgcolor: 'rgba(0, 0, 0, 0.04)',
                      borderColor: 'secondary.dark',
                    },
                  },
                }}
              >
                <Box sx={{ fontSize: 28, mb: 0.5 }}>
                  <IconComponent />
                </Box>
                <Typography variant="caption" sx={{ fontSize: '0.65rem', textAlign: 'center' }}>
                  {item.label}
                </Typography>
              </ListItemButton>
            </Box>
          );
        })}\n      </Box>
    </Box>
  );
}